typedef struct {
    uint64_t ue_ci;
    tbb::concurrent_vector<uint32_t> pfis;
} notification;

typedef tbb::concurrent_vector<notification> notifications_list;

notifications_list* create_notifications_list() {
    return new notifications_list();
}

void destroy_notifications_list(notifications_list* list) {
    delete list;
}

bool add_notification(notifications_list* list, uint64_t ue_ci, const tbb::concurrent_vector<uint32_t>& pfis) {
    if (ue_ci == 0 || pfis.empty()) return false;

    notification n = {ue_ci, pfis};
    list->push_back(n);
    return true;
}

bool remove_notification(notifications_list* list, uint64_t ue_ci) {
    for (auto it = list->begin(); it != list->end(); ++it) {
        if (it->ue_ci == ue_ci) {
            list->erase(it);
            return true;
        }
    }
    return false;
}

tbb::concurrent_vector<notification> get_notifications(const notifications_list* list, uint64_t start_ue_ci, size_t max_results) {
    tbb::concurrent_vector<notification> results;

    for (auto it = list->begin(); it != list->end() && results.size() < max_results; ++it) {
        if (it->ue_ci >= start_ue_ci) {
            results.push_back(*it);
        }
    }

    return results;
}

