#include <stdio.h>
#include <stdlib.h>
#include <getopt.h>
#include <string.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>

#define BUFFER_SIZE 4096

struct Options {
    char *filename;
    char delimiter;
    char output_file[256];
    int count_char;
    bool help;
};

void* map_file(const char *path, size_t *size) {
    int fd = open(path, O_RDONLY);
    void *map = mmap(NULL, BUFFER_SIZE, PROT_READ, MAP_PRIVATE, fd, 0);
    if (map == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    off_t filesize = lseek(fd, 0, SEEK_END);
    *size = filesize;
    close(fd);
    return map;
}

void unmap_file(const char *path, void *map, size_t size) {
    if (munmap(map, size) == -1) {
        perror("munmap");
        exit(EXIT_FAILURE);
    }
}

int main(int argc, char **argv) {
    struct Options options;
    memset(&options, 0, sizeof(options));

    static const char short_opts[] = "hco:d:";
    static const char *long_opts[] = {"help", "count:", "output:", "delimiter:", NULL};
    int opt;

    while ((opt = getopt_long(argc, argv, short_opts, long_opts, NULL)) != -1) {
        switch (opt) {
            case 'h':
                options.help = true;
                break;
            case 'c':
                options.count_char = optarg[0];
                break;
            case 'o':
                strcpy(options.output_file, optarg);
                break;
            case 'd':
                options.delimiter = optarg[0];
                break;
        }
    }

    if (options.help) {
        printf("Usage: %s [OPTIONS] [INPUT]\n", argv[0]);
        printf("\t-h, --help\t\tDisplay this message and exit.\n");
        printf("\t-c, --count CHAR\tCount occurrences of specified character.\n");
        printf("\t-o, --output FILE\tSpecify output file for the result.\n");
        printf("\t-d, --delimiter DELIM\tCustom delimiter for counting.\n");
        return 0;
    }

    // Process input source and handle I/O
    size_t buffer_size = BUFFER_SIZE;
    void *input;
    int input_fd = 0;
    if (argc > optind) {
        input = map_file(argv[optind], &buffer_size);
        input_fd = -1;
    } else {
        input = stdin;
        input_fd = fileno(stdin);
    }

    // Initialize other variables and perform processing logic here.

    unmap_file((input_fd >= 0) ? "/dev/stdin" : argv[optind], input, buffer_size);
    return 0;
}
```
