// DNS resolution function
void* dns_resolve(void *arg) {
    char *hostname = arg;
    struct hostent *he;
    char ipaddr[INET6_ADDRSTRLEN];

    he = gethostbyname(hostname);
    if (he == NULL) return NULL; // Error: DNS resolution failed

