void* reallocate(void **ptr, size_t *size, size_t new_size) {
    if (new_size > *size) {
        void *new_ptr = mmap(NULL, new_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        memcpy(new_ptr, *ptr, *size);
        if (munmap(*ptr, *size) < 0) {
            perror("Error in munmapping old memory");
            exit(EXIT_FAILURE);
        }
        *ptr = new_ptr;
        *size = new_size;
    }
    return *ptr;
}

