        pthread_t thread;
        void *ipaddr;
        if (pthread_mutex_lock(&dns_mutex) != 0) {
            perror("Error locking the DNS mutex");
            free(parsed_line);
            continue;
        }

        if (pthread_create(&thread, NULL, dns_resolve, token) != 0) {
            pthread_mutex_unlock(&dns_mutex);
            perror("Error creating a DNS thread");
            free(parsed_line);
            continue;
        }

        while (true) {
            if (pthread_equal(thread, (pthread_t) -1)) break; // Thread not initialized yet
            if (pthread_join(thread, &ipaddr)) {
                pthread_mutex_unlock(&dns_mutex);
                perror("Error joining the DNS thread");
