        // Calculate average of the last two numerical fields
        if (sscanf((*((char**)reallocate(&parsed_line, &line_length, line_length + 1)), line_length), "%lu,%lu,%luf",
                   &last_two_averages, &last_two_averages, &token) == 3) {
            last_two_averages = (last_two_averages * 2 + atol(token)) / 3;
