#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <errno.h>

typedef struct Config_t {
    int id;
    void* params; // User-defined parameters
    pthread_mutex_t lock;
} Config;

static pthread_key_t thread_specific_config = PTHREAD_KEY_NULL;
static size_t num_allocated = 0;
static size_t num_freed = 0;

// Logging function for initialization attempts and failures
void log_init(const char* message) {
    printf("%s\n", message);
}

void* config_params_destroy(void* params) {
    if (params != NULL) {
        free(params);
        ++num_freed;
    }
    return NULL;
}

Config* create_config(int id, void* params, size_t param_size) {
    Config* config = malloc(sizeof(Config));
    if (!config) {
        log_init("Out of memory while creating configuration.");
        return NULL;
    }

    config->id = id;
    config->params = malloc(param_size);
    if (!config->params) {
        free(config);
        log_init("Out of memory while allocating parameters for configuration.");
        return NULL;
    }
    memcpy(config->params, params, param_size);

    pthread_mutex_init(&config->lock, NULL);
    ++num_allocated;
    return config;
}

Config* get_current_config() {
    void** thread_specific_data = pthread_getspecific(thread_specific_config);
    if (!thread_specific_data) {
        Config* default_config = create_config(-1, NULL, 0);
        if (default_config == NULL) {
            log_init("Failed to create default configuration.");
            return NULL;
        }
        pthread_setspecific(thread_specific_config, default_config);
    }
    return *((Config**)thread_specific_data);
}

void set_current_config(Config* config) {
    void** thread_specific_data = pthread_getspecific(thread_specific_config);
    if (thread_specific_data && *thread_specific_data != config) {
        pthread_mutex_lock(&((*thread_specific_data)->lock));
        pthread_mutex_unlock(&((*thread_specific_data)->lock));
    }
    pthread_setspecific(thread_specific_config, config);
}

void delete_current_config() {
    void** thread_specific_data = pthread_getspecific(thread_specific_config);
    if (thread_specific_data) {
        Config* current_config = *thread_specific_data;
        pthread_mutex_destroy(&current_config->lock);
        free(current_config->params);
        free(current_config);
        pthread_setspecific(thread_specific_config, NULL);
    }
}
```

