import os
import hashlib
import concurrent.futures
from time import sleep, time
from retrying import retry

class FileProcessor:
    def __init__(self, max_files, max_size, concurrency=10, retry_attempts=4, backoff_factor=2):
        self.max_files = max_files
        self.max_size = max_size
        self.concurrency = concurrency
        self.retry_attempts = retry_attempts
        self.backoff_factor = backoff_factor

    @retry(retry_on_exception=TypeError, wait_fixed=60 * 10, stop_max_delay=60 * 60)
    def _fetch_metadata(self, file_path):
        # Implement metadata retrieval logic here (e.g., using an external API or database)
        pass

    def process_file(self, file_path):
        try:
            if not os.path.isfile(file_path):
                return None

            file_size = os.path.getsize(file_path)
            if file_size > self.max_size:
                return None

            md5 = hashlib.md5()
            with open(file_path, 'rb') as f:
                while True:
                    data = f.read(65536)
                    if not data:
                        break
                    md5.update(data)

            metadata = self._fetch_metadata(file_path)
            return {file_path: (md5.hexdigest(), metadata)}
        except Exception as e:
            print(f"Error processing file {file_path}: {e}")
            return None

    def calculate_hashes(self, root_dir):
        processed = 0
        file_paths = [os.path.join(root_dir, f) for f in os.listdir(root_dir)]
        file_paths += [os.path.join(subdir, f) for subdir in os.walk(root_dir) for f in subdir[2]]

        with concurrent.futures.ThreadPoolExecutor(max_workers=self.concurrency) as executor:
            results = list(executor.map(self.process_file, file_paths))

            hashes_dict = {}
            for result in results:
                if result is not None:
                    hashes_dict.update(result)
                    processed += 1
                    if processed >= self.max_files:
                        break

        return hashes_dict
