#include <stdio.h>
#include <stdlib.h>

typedef struct {
    EVP_CIPHER_CTX *aes; // AES context
    RSA *rsa; // RSA key exchange context
    unsigned char *hmac_key; // HMAC key
    size_t hmac_key_len; // HMAC key length
} EncryptionContext;

EncryptionContext* create_encryption_context(int aes_bits, const EVP_CIPHER **aes_cipher, int rsa_bits, int hmac_len) {
    EncryptionContext *ctx = malloc(sizeof(EncryptionContext));

    // Initialize AES context based on selected key size and mode (ECB or CBC)
    ctx->aes = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx->aes, *aes_cipher, NULL, NULL, IV); // Initialize with NULL keys for now

    // Initialize RSA key exchange context
    ctx->rsa = RSA_new();
    RSA_generate_key(ctx->rsa, rsa_bits, NULL);

    // Allocate memory for HMAC key and set its length
    ctx->hmac_key = malloc(hmac_len);
    ctx->hmac_key_len = hmac_len;

    return ctx;
}

void destroy_encryption_context(EncryptionContext *ctx) {
    EVP_CIPHER_CTX_free(ctx->aes);
    RSA_free(ctx->rsa);
    free(ctx->hmac_key);
    free(ctx);
}

void configure_encryption_context(EncryptionContext *ctx, const EVP_CIPHER **aes_cipher, int aes_bits, int rsa_bits, int hmac_len) {
    // Update AES context with selected key size and mode (ECB or CBC)
    EVP_EncryptInit_ex(ctx->aes, *aes_cipher, NULL, NULL, IV); // Initialize with NULL keys for now

    // Update RSA key exchange context
    if (RSA_generate_key(ctx->rsa, rsa_bits, NULL) <= 0) {
        fprintf(stderr, "Error generating RSA key\n");
        exit(1);
    }
}

void encrypt_and_integrity_check(const EncryptionContext *ctx, const void *plaintext, size_t plaintext_len, void *ciphertext, unsigned char **tag) {
    // Perform AES encryption with padding
    EVP_CIPHER_CTX_set_padding(ctx->aes, 1);
    int ciphertext_len = plaintext_len;
    if (EVP_EncryptUpdate(ctx->aes, ctx->plaintext, &ciphertext_len, (const unsigned char*)plaintext, plaintext_len) <= 0 ||
        EVP_EncryptFinal_ex(ctx->aes, ctx->plaintext + ciphertext_len, &ciphertext_len) <= 0) {
        fprintf(stderr, "Error during AES encryption\n");
        exit(1);
    }

    // Perform HMAC integrity check and generate tag
    unsigned char hmac[EVP_MAX_MD_SIZE];
    HMAC(EVP_sha256(), ctx->hmac_key, ctx->hmac_key_len, (const unsigned char*)plaintext, plaintext_len, hmac, EVP_MAX_MD_SIZE);
    if (tag) *tag = malloc(EVP_SHA256_DIGEST_LENGTH);
    memcpy(*tag, hmac, EVP_SHA256_DIGEST_LENGTH);
}

void decrypt_and_integrity_check(const EncryptionContext *ctx, const void *ciphertext, size_t ciphertext_len, void *plaintext, unsigned char *tag) {
    // Perform AES decryption with padding and integrity check
    if (EVP_DecryptUpdate(ctx->aes, ctx->plaintext, &ciphertext_len, (const unsigned char*)ciphertext, ciphertext_len) <= 0 ||
        EVP_DecryptFinal_ex(ctx->aes, ctx->plaintext + ciphertext_len, &ciphertext_len) <= 0) {
        fprintf(stderr, "Error during AES decryption\n");
        exit(1);
    }

    // Compare the provided tag with the calculated HMAC
    unsigned char hmac[EVP_MAX_MD_SIZE];
    HMAC(EVP_sha256(), ctx->hmac_key, ctx->hmac_key_len, (const unsigned char*)plaintext, ciphertext_len, hmac, EVP_MAX_MD_SIZE);
    if (memcmp(tag, hmac, EVP_SHA256_DIGEST_LENGTH)) {
        fprintf(stderr, "Invalid message integrity\n");
        exit(1);
    }
}
```
