import os
import sys
import logging
from typing import Dict, Union
import time
import yaml
from concurrent.futures import ThreadPoolExecutor
from urllib.parse import urlparse
from collections import defaultdict

# Logging setup
logging.basicConfig(level=logging.WARNING)
logger = logging.getLogger(__name__)

class ConfigLoader:
    def __init__(self, primary_config: str, alt_configs: Dict[str, Union[str, None]]):
        self.primary_config = primary_config
        self.alt_configs = alt_configs
        self.config_data = {}

    def load(self):
        # Load primary configuration file if available and valid
        try:
            with open(self.primary_config, 'r') as f:
                self.config_data = yaml.safe_load(f)
        except (FileNotFoundError, PermissionError, yaml.YAMLError):
            pass

        # Load alternative configurations if needed
        for alt_name, alt_file in self.alt_configs.items():
            if alt_file is not None:
                try:
                    with open(alt_file, 'r') as f:
                        alt_data = yaml.safe_load(f)
                        self.config_data.update(alt_data)
                except (FileNotFoundError, PermissionError, yaml.YAMLError):
                    logger.warning(f'Unable to load alternative configuration {alt_name}')

        # Fill in placeholders with values from dynamic sources and templates
        self._fill_placeholders()

    def _fill_placeholders(self):
        placeholders = set(self.config_data.keys())

        def resolve_placeholder(key: str, sources: list) -> str:
            for source in sources:
                if key in source and isinstance(source[key], str):
                    return source[key]
            raise KeyError(f'Placeholder {key} not found in any source')

        # Define dynamic sources with connectivity handling
        data_sources = defaultdict(list)
        def register_data_source(name: str, url: str):
            parsed_url = urlparse(url)
            data_sources[name].append((parsed_url.netloc, parsed_url.path))

        def fetch_from_data_source(name: str, timeout: float = 5) -> Dict[str, str]:
            try:
                host, path = next(iter(data_sources[name]))
                response = requests.get(url=f'http://{host}:80{path}', timeout=timeout)
                if response.status_code == 200:
                    return yaml.safe_load(response.content)
            except (requests.exceptions.RequestException, KeyError):
                pass

            # Use fallback data source if available
            for backup_name, backup_url in data_sources[name]:
                try:
                    response = requests.get(url=f'http://{backup_host}:80{backup_path}', timeout=timeout)
                    if response.status_code == 200:
                        return yaml.safe_load(response.content)
                except (requests.exceptions.RequestException, KeyError):
                    pass

            raise FileNotFoundError(f'Unable to retrieve data from any configured source for {name}')

        # Register dynamic sources
        register_data_source('primary', self.primary_config)

        for alt_name, alt_file in self.alt_configs.items():
            if alt_file is not None:
                register_data_source(alt_name, alt_file)

        # Define placeholders and their corresponding sources
        placeholder_sources = {}
        for key in placeholders:
            template = self.config_data[key]
            if isinstance(template, str):
                placeholder_sources[key] = [{'source': 'primary'}]
            else:
                sources = []
                for source_name, source_url in template['urls']:
                    if source_name not in data_sources:
                        logger.warning(f'Ignoring placeholder {key} due to unregistered dynamic source {source_name}')
                    else:
                        sources.append({'source': source_name})
                placeholder_sources[key] = sources

        # Resolve placeholders using dynamic sources
        for key, sources in placeholder_sources.items():
            try:
                self.config_data[key] = resolve_placeholder(key, sources)
            except KeyError as e:
                logger.error(f'Failed to resolve placeholder {key}: {str(e)}')

        # Load and process templates for new configuration blocks
        template_blocks = {}
        for key in self.config_data:
            if isinstance(self.config_data[key], dict) and 'template' in self.config_data[key]:
                template_block = self.config_data.pop(key)
                template_blocks[key] = template_block

        with ThreadPoolExecutor() as executor:
            for block_name, template_block in template_blocks.items():
                try:
                    data = fetch_from_data_source(template_block['source'])
                    self.config_data[block_name] = {k: v for k, v in template_block.items() if k != 'template'} | data
                except Exception as e:
                    logger.error(f'Failed to load template for block {block_name}: {str(e)}')

    def save(self, output_file: str):
        with open(output_file, 'w') as f:
            yaml.dump(self.config_data, f)

def main():
    config = ConfigLoader('primary_config.yaml', {'maintenance': 'maintenance_config.yaml'})
    config.load()
    config.save('updated_config.yaml')

if __name__ == "__main__":
    main()
```
