void processFile(const char* file_path) {
    FILE *file = fopen(file_path, "r");
    if (!file) {
        log_message("Error opening file.");
        return;
    }

    // Read the file content into a buffer while respecting memory limits
    size_t buffer_size = 1024;
    char *buffer = malloc(buffer_size);
    size_t bytes_read = fread(buffer, sizeof(char), buffer_size, file);
    while (bytes_read == buffer_size) {
        buffer_size *= 2;
        buffer = realloc(buffer, buffer_size);
        bytes_read = fread(&buffer[bytes_read], sizeof(char), buffer_size - bytes_read, file);
    }
    fclose(file);

    // Perform the specified operation based on configuration
    EVP_PKEY *pkey;
    unsigned char *cipher_or_signature = NULL;
    int cipher_or_signature_len = 0;

    if (strcmp(config.operation, "encrypt") == 0) {
        pkey = PEM_read_PKEY(config.key_path, NULL, NULL, NULL);
        cipher_or_signature = AES_ EncryptUpdate(pkey, buffer, bytes_read, NULL, &cipher_or_signature_len);
    } else if (strcmp(config.operation, "decrypt") == 0) {
        pkey = PEM_read_PKEY(config.key_path, NULL, NULL, NULL);
        AES_DecryptUpdate(&pkey, buffer, bytes_read, cipher_or_signature, cipher_or_signature_len);
    } else if (strcmp(config.operation, "sign") == 0) {
        pkey = PEM_read_PKEY(config.key_path, NULL, NULL, NULL);
        cipher_or_signature = SHA256_SIG(*pkey, buffer, bytes_read, &cipher_or_signature_len);
    } else if (strcmp(config.operation, "verify") == 0) {
        pkey = PEM_read_PKEY(config.key_path, NULL, NULL, NULL);
        int is_verified = SHA256_Verify(*pkey, buffer, bytes_read, cipher_or_signature, cipher_or_signature_len);
        if (!is_verified) {
            log_message("Signature verification failed.");
        }
    }

    free(buffer);
    EVP_PKEY_free(pkey);
    if (cipher_or_signature) {
        log_message("Operation completed successfully.");
        // Return the cipher or signature object to the caller
