#include <pthread.h>
#include <semaphore.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/time.h>

typedef struct {
    size_t id;
    sem_t *semaphore;
    void (*function)(void*);
    void *dataset;
    double weight;
} WorkerThreadData;

sem_t master; // Semaphore to synchronize all threads
size_t num_threads, total_operations = 0;
pthread_attr_t attr;

// Initialize semaphores for each thread and dataset
void init(size_t num_threads) {
    this->num_threads = num_threads;
    pthread_attr_init(&attr);
    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_JOINABLE);

    sem_t *semaphores = malloc(num_threads * sizeof(sem_t));
    WorkerThreadData *data = malloc(num_threads * sizeof(WorkerThreadData));

    // Initialize master semaphore
    sem_init(&master, 0, num_threads);

    for (size_t i = 0; i < num_threads; ++i) {
        data[i].id = i;
        data[i].semaphore = &semaphores[i];
        sem_init(data[i].semaphore, 0, 1); // Each thread starts with a 1-count semaphore
    }
}

// Function for each worker thread to call when processing the dataset
void process_dataset(void *arg) {
    WorkerThreadData *data = arg;

    struct timeval start, end;
    gettimeofday(&start, NULL);

    data->function(data->dataset); // Process the dataset

    sem_post(data->semaphore); // Signal completion and increment total operations
    ++total_operations;

    if (total_operations == num_threads) {
        sem_post(&master); // Notify all threads to clean up resources
    }

    gettimeofday(&end, NULL);
    double elapsed = 1000.0 * (end.tv_sec - start.tv_sec) + (end.tv_usec - start.tv_usec) / 1000;
    printf("Thread %zu finished processing dataset in %f seconds\n", data->id, elapsed);

    pthread_exit(NULL);
}

// Start the specified number of threads, assigning each one a unique dataset and semaphore
void start_threads(WorkerThreadData *data) {
    for (size_t i = 0; i < num_threads; ++i) {
        pthread_create(&(data[i].thread), &attr, process_dataset, &(data[i]));
    }
}

// Wait for all threads to finish and clean up resources
void wait_for_all() {
    sem_wait(&master);

    for (size_t i = 0; i < num_threads; ++i) {
        pthread_join(data[i].thread, NULL);
    }

    free(data);
    free(semaphores);
    sem_destroy(&master);
}
```

To configure the function, pass in the number of threads and a structure for each worker thread containing the following:

- `id`: A unique identifier for the thread.
- `semaphore`: A semaphore associated with this thread.
- `function`: The function to call when processing the dataset.
- `dataset`: The dataset to process.
- `weight`: The complexity of the dataset, influencing the number of operations a thread can perform before signaling completion.

To handle errors gracefully and log detailed information about failed operations, you could modify the `process_dataset()` function to call any error handling code within the `function()` function and use a logging library for outputting errors.

To allow for the configuration of thread priorities based on dataset complexity, you can use the `pthread_setschedparam()` function with SCHED_FIFO or other scheduling policies. For more information, see the [POSIX Threads Programming Guide and API](https://man7.org/linux/man-pages/man3/pthread_setschedparam.3.html).']

