            const filePath = path.join(dirPath, file);
            const isValid = await validateFileSchema(filePath, config.schema[path.extname(file).toLowerCase()]);

            if (isValid) {
              processedFiles.push({ file, valid: true });
              logger('info', `Processed file ${file} successfully.`);
            } else {
              processedFiles.push({ file, valid: false });
              logger('error', `Validation failed for file ${file}. Error details: ${JSON.stringify(ajv.errorsText())}`);
            }
          } catch (err) {
            processedFiles.push({ file, error: err.message });
            logger('error', `Encountered an error processing file ${file}: ${err.message}`);
          }
        })
      );

      await new Promise(resolve => setTimeout(resolve, config.retries * config.timeout)); // Retry logic
    }

    const summary = {
      successCount: processedFiles.filter(file => file.valid).length,
      errorCount: processedFiles.filter(file => !file.valid && file.error).length,
      failedCount: processedFiles.filter(file => !file.valid && !file.error).length
    };

    if (externalServiceUrl) {
      await axios.post(externalServiceUrl, summary);
    }

    return summary;
  } catch (err) {
    logger('error', `An error occurred while processing directory ${dirPath}: ${err.message}`);
    throw err;
  }
}

module.exports = { processDirectory };
```

This code provides an asynchronous JavaScript function to process files from a specified directory, covering the given requirements. It uses external libraries like `fs-extra`, `ajv`, `async-local-storage`, `axios`, and `lodash`. The function returns a summary of processed files, including counts of successfully validated files and any encountered errors."]

