    double highest_priority = calculatePriority(current->packet);
    highest_priority_packet = current->packet;

    while (current && num_packets > 1) {
        QueueNode* next = current->next;
        double priority = calculatePriority(next->packet);

        if (priority > highest_priority) {
            highest_priority = priority;
            highest_priority_packet = next->packet;
            current = next;
        } else {
            current = next;
        }
        num_packets--;
    }

    packet_id = highest_priority_packet.id;
    head = current ? current->next : NULL;
    pthread_mutex_unlock(&queue_lock);

