    processPacket(highest_priority_packet);
    auto end = std::chrono::steady_clock::now();

    total_processing_time_ns += std::chrono::duration_cast<std::chrono::nanoseconds>(end - start).count();
    num_processed++;

    // Update average and max processing time, maintaining real-time constraints
