// Custom data structure for configuration file metadata
typedef struct ConfigMetadata {
    size_t max_path_len;
    char* allowed_file_types;
    size_t ext_length;
    size_t random_letters_limit;
} ConfigMetadata;

// Function to parse the configuration file and populate ConfigMetadata structure
void parse_config(const char* filename, ConfigMetadata* metadata) {
    // Implement configuration parsing logic here
