char* modify_filename(const char* original_filename, const ConfigMetadata* metadata) {
    size_t len = strlen(original_filename);
    if (len > metadata->max_path_len) {
        return NULL;  // Return NULL to indicate error due to path overflow
    }

    // Count digits in the original filename
    size_t digit_count = 0;
    for (size_t i = 0; i < len; ++i) {
        if (isdigit(original_filename[i])) {
            ++digit_count;
        }
    }

    // Ensure that the count of digits is within the allowed range
    if (digit_count > metadata->max_digits) {
        return NULL;  // Return NULL to indicate error due to digit overflow
    }

    // Generate a random string of uppercase letters
    char random_letters[metadata->random_letters_limit + 1];
    for (size_t i = 0; i < metadata->random_letters_limit; ++i) {
        random_letters[i] = 'A' + rand() % 26;
    }
    random_letters[metadata->random_letters_limit] = '\0';

    // Determine the original filename's extension
    size_t ext_start = len - metadata->ext_length;
    const char* ext = (ext_start < len) ? &original_filename[ext_start] : NULL;

    // Construct the new filename based on the rules
    size_t new_len = len + metadata->random_letters_limit + 15;  // Allow for the extension, digits, and modified suffix
    if (new_len > metadata->max_path_len) {
        return NULL;  // Return NULL to indicate error due to path overflow
    }

    char* new_filename = malloc(new_len);
    if (!new_filename) {
        return NULL;  // Return NULL to indicate memory allocation failure
    }

    strncpy(new_filename, original_filename, len);

    // Append random letters and the modified suffix
    snprintf(&new_filename[len], metadata->random_letters_limit + 1, "%s.modified.%zu.%s.%s", &digit_count, (int)rand_r(NULL), random_letters, ext);

    return new_filename;
}
```']

