    EVP_MD_CTX *hash_ctx;
    char *cache_root;
    char *default_theme_dir;
    PNG_struct *theme_png;
} Context;

Context* init_cipher(const char *password) {
    static Context cipher_context = {};
    unsigned char key[EVP_MAX_MD_SIZE];
    unsigned char iv[AES_BLOCK_SIZE];
    int key_len, iv_len;

    if (password && strlen(password) >= 32) {
        SHA256((unsigned char*)password, strlen(password), key, sizeof(key));
        key_len = EVP_sha256((EVP_MD_CTX*)&cipher_context.hash_ctx, key, sizeof(key), NULL);
    } else {
        RAND_bytes(key, sizeof(key));
        key_len = sizeof(key);
    }

    if (!cipher_context.aes_ctx.encrypt) {
        cipher_context.aes_ctx.encrypt = AES_set_encrypt_key(key, 256, &cipher_context.hash_ctx);
    }

    if (cipher_context.aes_ctx.iv && !memcmp(cipher_context.aes_ctx.iv, iv, AES_BLOCK_SIZE)) {
        return &cipher_context;
    }

    SHA256((unsigned char*)password, strlen(password), iv, sizeof(iv));
    iv_len = AES_block_size();

    if (cipher_context.aes_ctx.iv) {
        free(cipher_context.aes_ctx.iv);
    }
    cipher_context.aes_ctx.iv = malloc(iv_len);
    memcpy(cipher_context.aes_ctx.iv, iv, iv_len);

    cipher_context.key_len = key_len;
    cipher_context.iv_len = iv_len;

    if (!cipher_context.cache_root) {
        char cache_dir[256];
        snprintf(cache_dir, sizeof(cache_dir), "%s/themes", getenv("HOME"));
        struct stat st;
        if (stat(cache_dir, &st) != 0 || !S_ISDIR(st.st_mode)) {
            mkdir(cache_dir, 0755);
        }
        cipher_context.cache_root = strdup(cache_dir);
    }

    // Load theme from cache or set default if not found
    // ... (implement loading and parsing PNG file here)

    return &cipher_context;
}
