#include <sys/stat.h>
#include <err.h>
#include <pthread.h>

typedef struct cmd_s {
    char **args;
    pid_t pid;
} cmd_t;

int execute_commands(char *command_str) {
    char **commands = split(command_str, ';');
    int num_commands = 0;
    for (char **cmd = commands; *cmd != NULL; cmd++) {
        if (!*(*cmd)) continue; // skip empty commands
        num_commands++;
    }

    cmd_t *command_list = malloc(num_commands * sizeof(cmd_t));
    int i = 0;
    for (char **cmd = commands; *cmd != NULL; cmd++) {
        if (!*(*cmd)) continue; // skip empty commands

        char **args = split(*cmd, ' ');
        command_list[i].args = args;
        command_list[i].pid = -1;
        i++;
    }

    sigset_t sigint_mask, sigterm_mask, sigquit_mask;
    sigfillset(&sigint_mask);
    sigdelset(&sigint_mask, SIGCHLD); // exclude SIGCHLD from mask for waitpid
    sigfillset(&sigterm_mask);
    sigfillset(&sigquit_mask);

    pthread_t tid;
    for (int i = 0; i < num_commands; i++) {
        command_list[i].pid = fork();

        if (command_list[i].pid == 0) { // child process
            execv(command_list[i].args[0], command_list[i].args);
            err(EXIT_FAILURE, "Failed to execute command: %s", command_list[i].args[0]);
        } else if (command_list[i].pid > 0) { // parent process
            if (i == 0) { // only block for the first command in the sequence
                pid_t status;
                waitpid(command_list[i].pid, &status, WNOHANG);
            }
            continue;
        } else { // fork failed, return error
            warn("Fork failed. Exiting...");
            return 0;
        }
    }

    sigemptyset(&sigint_mask);
    sigprocmask(SIG_BLOCK, &sigint_mask, NULL);
    sigemptyset(&sigterm_mask);
    sigprocmask(SIG_BLOCK, &sigterm_mask, NULL);
    sigemptyset(&sigquit_mask);
    sigprocmask(SIG_BLOCK, &sigquit_mask, NULL);

    // signal handler to gracefully terminate child processes upon receiving signals
    void signal_handler(int signum) {
        sigprocmask(SIG_SETMASK, NULL, &sigint_mask);
        for (int i = 0; i < num_commands; i++) {
            if (command_list[i].pid > 0 && TERM == signum) {
                kill(command_list[i].pid, SIGTERM);
            } else if (command_list[i].pid > 0 && INT == signum) {
                kill(command_list[i].pid, SIGINT);
            } else if (command_list[i].pid > 0 && QUIT == signum) {
                kill(command_list[i].pid, SIGQUIT);
            }
        }
    }
    pthread_create(&tid, NULL, signal_handler, NULL);

    int exit_status = 1;
    for (int i = 0; i < num_commands; i++) {
        if (-1 == command_list[i].pid) continue; // skip uninitialized commands

        pid_t status;
        while (waitpid(command_list[i].pid, &status, WNOHANG) > 0);
        if (!WIFEXITED(status)) {
            warn("Command %d failed to terminate gracefully.", i+1);
            exit_status = 0;
        } else if (WEXITSTATUS(status) != 0) {
            warn("Command %d exited with error: %d.", i+1, WEXITSTATUS(status));
            exit_status = 0;
        }
    }

    pthread_join(tid, NULL); // ensure signal handler is cleaned up

    for (int i = 0; i < num_commands; i++) {
        free(command_list[i].args);
    }
    free(command_list);

    return exit_status;
}
```

Note that the `split` function is not included in this code snippet, but it should handle command and argument parsing, environment variable substitution, and memory management for the resulting arrays. The implementation of this function may depend on the preferred library or data structure used to store strings and character arrays.']

