    private readonly ConcurrentDictionary<string, Process> _runningApplications;
    private readonly int _maxConcurrency;
    private readonly IWebHostBuilder _hostBuilder;

    public ApplicationManager(ILogger<ApplicationManager> logger, int maxConcurrency)
    {
        _logger = logger;
        _runningApplications = new ConcurrentDictionary<string, Process>();
        _maxConcurrency = maxConcurrency;
        _hostBuilder = CreateWebHostBuilder();
    }

    private IWebHostBuilder CreateWebHostBuilder()
    {
        // Implement custom web host builder configuration for integrating authentication mechanisms or custom logging levels.
        return WebHost.CreateDefaultBuilder();
