    public void AddApplication(string directoryPath, string siteName, Uri baseAddress)
    {
        if (!Directory.Exists(directoryPath))
        {
            _logger.LogError("Invalid directory path: {Directory}", directoryPath);
            return;
        }

        var webConfigFile = Path.Combine(directoryPath, "web.config");
        if (!File.Exists(webConfigFile))
        {
            _logger.LogError("Missing web.config file in directory: {Directory}", directoryPath);
            return;
        }

        var processAttempts = 5;
        while (true)
        {
            try
            {
                if (_runningApplications.ContainsKey(siteName))
                {
                    _logger.LogWarning("Application already running: {SiteName}", siteName);
                    continue;
                }

                var availableConcurrency = Interlocked.Decrement(ref _maxConcurrency) > 0 ? 1 : 0;
                if (availableConcurrency == 0)
                {
                    _logger.LogWarning("Maximum concurrency limit reached, queueing application: {SiteName}", siteName);
                    return;
                }

                var process = StartApplication(directoryPath, siteName, baseAddress);
                _runningApplications[siteName] = process;
                MonitorApplication(process, siteName);
                break;
            }
            catch (Exception ex)
            {
                _logger.LogError("Failed to start application: {SiteName}. Error: {Ex}", siteName, ex);
                if (--processAttempts == 0)
                {
                    throw new ApplicationStartupException($"Application '{siteName}' failed to start.");
                }
            }
        }
    }

    private Process StartApplication(string directoryPath, string siteName, Uri baseAddress)
    {
        // Implement SSL certificate configuration for HTTPS applications.
        var processStartInfo = new ProcessStartInfo();
        processStartInfo.FileName = _hostBuilder.CreateHostBuilder().UseContentRoot(directoryPath).Build().ToString();
        processStartInfo.Arguments = $"--server.urls \"{baseAddress.Scheme}://localhost:{baseAddress.Port}\"";

        var process = new Process();
        process.StartInfo = processStartInfo;
        process.Start();
        return process;
    }

    private void MonitorApplication(Process process, string siteName)
    {
        // Implement health checks and notifications for each application.
