```java
import java.io.BufferedReader;
import java.io.File;
import java.io.IOException;
import java.io.InputStreamReader;
import java.nio.file.Paths;
import org.apache.commons.io.FileUtils;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class CommandExecutor {
    private static final Logger logger = LoggerFactory.getLogger(CommandExecutor.class);

    public void executeCommand(String command, String workingDirectory) throws IOException, InterruptedException {
        File dir = new File(workingDirectory);
        if (!dir.exists() || !dir.isDirectory()) {
            throw new IOException("Target directory does not exist or is not a directory.");
        }

        ProcessBuilder processBuilder = new ProcessBuilder(command.split(" "));
        processBuilder.directory(dir);

        Process process = processBuilder.start();

        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));

        Thread inputThread = new Thread(() -> {
            try {
                String line;
                while ((line = reader.readLine()) != null) {
                    logger.info("Standard Output: {}", line);
                }
            } catch (IOException e) {
                logger.error("Error reading standard output.", e);
            }
        });
        Thread errorThread = new Thread(() -> {
            try {
                String line;
                while ((line = errorReader.readLine()) != null) {
                    logger.error("Standard Error: {}", line);
                }
            } catch (IOException e) {
                logger.error("Error reading standard error.", e);
            }
        });

        inputThread.start();
        errorThread.start();

        process.waitFor();

        if (process.exitValue() != 0) {
            FileUtils.deleteRecursively(dir);
            throw new RuntimeException("Command execution failed.");
        }
    }
}
```

