using namespace std;
using namespace __gnu_pbds;

typedef tree<string, null_type, less<string>, rb_tree_tag, tree_order_statistics_node_update> StrSet;

// Predefined list of authorized roles.
vector<string> authorized_roles = {"role1", "role2", "role3"};

struct SessionData {
    string session_id;
    time_t expiration_time;
    string username;
    vector<string> roles;
    time_t last_login_time;
};

StrSet usernames;

// Function to validate the session data.
bool validateSession(const json_t *session) {
    SessionData sd;
    json_tokenizer t(session);
    if (!json_tokener_get_parse_error(&t)) {
        json_object *obj = json_tokener_get_object(&t);
        if (json_object_get_length(obj) >= 4) {
            json_object_foreach(obj, key, val) {
                string k(json_string_value(key));
                if (k == "session_id") {
                    sd.session_id = json_string_value(val);
                    if (sd.session_id.size() > 64) return false;
                } else if (k == "expiration_time") {
                    time_t exp_time = json_integer_value(val);
                    time_t current_time = time(NULL);
                    if (difftime(current_time, exp_time) > 604800 || difftime(exp_time, current_time) <= 0) return false;
                } else if (k == "username") {
                    sd.username = json_string_value(val);
                    if (sd.username.size() > 50 || usernames.find(sd.username) != usernames.end()) return false;
                } else if (k == "roles") {
                    json_array *arr = json_object_get_array(val);
                    for (json_t *role : *arr) {
                        string r(json_string_value(role));
                        if (r.size() > 128 || find(authorized_roles.begin(), authorized_roles.end(), r) == authorized_roles.end()) return false;
                    }
                } else if (k == "last_login_time") {
                    time_t last_login = json_integer_value(val);
                    time_t current_time = time(NULL);
                    if (current_time - last_login > 86400 || last_login > current_time) return false;
                } else return false;
            }
        }
    }

    // Verify uniqueness of username and add to the usernames set.
    unique_lock<pthread_mutex_t> lock(usernames_mutex);
    if (usernames.find(sd.username) != usernames.end()) return false;
    usernames.insert(sd.username);

    return true;
}

// Initialize the data structure to store unique usernames.
void init() {
    pthread_mutex_init(&usernames_mutex, NULL);
}

// Cleanup the data structure when done.
void cleanup() {
    pthread_mutex_destroy(&usernames_mutex);
}
