using System;
using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

namespace EncryptionModule
{
    public class EncryptionService
    {
        private readonly ConcurrentQueue<Task> _tasks = new ConcurrentQueue<Task>();
        private readonly Aes _aesCbc = AES.Create();
        private readonly Aes _aesGcm = AES.Create();

        public byte[] Encrypt(byte[] data, bool useGCM, byte[] associatedData)
        {
            using (var encryptor = UseAesMode(useGCM))
            {
                return encryptor.TransformFinalBlock(data, 0, data.Length);
            }
        }

        public byte[] Decrypt(byte[] ciphertext, bool useGCM, byte[] associatedData, byte[] additionalAuthenticationData)
        {
            using (var decryptor = UseAesMode(useGCM))
            {
                var decryptedData = decryptor.TransformFinalBlock(ciphertext, 0, ciphertext.Length);

                if (decryptedData == null || decryptedData.Length < 1)
                    throw new Exception("Decryption failed.");

                return decryptedData;
            }
        }

        private ICryptoTransform UseAesMode(bool useGCM)
        {
            var aes = _useAppropriateAlgorithm(useGCM);
            using (ICryptoTransform transform = aes.CreateEncryptor())
            {
                _tasks.Enqueue(Task.Run(() =>
                {
                    GC.Collect();
                    aes.Clear();
                }));

                return transform;
            }
        }

