#include <boost/lexical_cast.hpp>
#include <boost/functional/hash.hpp>
#include <boost/functional/hash_combine.hpp>
#include <boost/unordered_map.hpp>
#include <boost/thread/locks.hpp>
#include <boost/chrono.hpp>

using namespace boost;
using namespace std;

struct Vertex {
    property<vertex_property, int> id;
    property<vertex_property, string> metadata;
};

struct Edge {
    property<edge_property, int> weight;
};

typedef adjacency_list<vecS, vecS, directedS, Vertex, Edge> Graph;

class MetadataService {
public:
    virtual string getMetadata(int id) = 0;
};

class CachedMetadataService : public MetadataService {
private:
    unordered_map<int, string> cache_;
    mutex cacheMutex_;
    shared_ptr<MetadataService> delegate_;
    boost::circular_buffer<pair<int, string>> cacheQueue_;
    size_t maxCacheSize_;
public:
    explicit CachedMetadataService(shared_ptr<MetadataService> delegate, size_t maxCacheSize) :
        delegate_(delegate), maxCacheSize_(maxCacheSize) {}

    string getMetadata(int id) override {
        lock_guard<mutex> lock(cacheMutex_);
        if (cache_.count(id)) return cache_[id];

        auto it = find_if(cacheQueue_.begin(), cacheQueue_.end(),
                          [&](const pair<int, string>& p) { return p.first == id; });
        if (it != cacheQueue_.end()) {
            auto result = move(*it);
            cacheQueue_.erase(it);
            return result.second;
        }

        string metadata = delegate_->getMetadata(id);
        lock_guard<mutex> lock(cacheMutex_);
        cache_[id] = metadata;

        if (cacheQueue_.size() >= maxCacheSize_) {
            cacheQueue_.pop_front();
        }
        cacheQueue_.push_back({ id, metadata });
        return metadata;
    }
};

class NetworkConnection : public enable_shared_from_this<NetworkConnection> {
public:
    explicit NetworkConnection(boost::asio::io_service& ioService) : socket_(ioService) {}

