        if (!ec) {
            // handle network communication here
            auto metadata = metadataService->getMetadata(boost::lexical_cast<int>(hash<int>()(socket_.remote_endpoint().address())));
            // update vertex with fetched metadata and continue with further graph operations
        }
    }

private:
    boost::asio::ip::tcp::socket socket_;
};

void addVertexAndEdge(Graph& g, int id, shared_ptr<MetadataService> metadataService) {
    Vertex v;
    v.id = id;
    auto metadata = metadataService->getMetadata(id);
    v.metadata = metadata;
    add_vertex(g, v);

    for (int neighborId : generate_random(numVertices(g), randomGenerator)) {
        Edge e;
        e.weight = generate_random(100, randomGenerator);
        add_edge(g, id, neighborId, e);
    }
}

void run(Graph& g, int numVertices, shared_ptr<MetadataService> metadataService) {
    boost::asio::io_service ioService;
    for (int i = 0; i < numVertices; ++i) {
        auto sp = make_shared<NetworkConnection>(ioService);
