static TASKS: RwLock<HashMap<String, Box<dyn FnOnce() + Send + 'static>>> = RwLock::new(HashMap::new());

async fn run_task(name: &str) {
    let mut tasks = TASKS.write().await;
    if let Some(task) = tasks.remove(name) {
        task().await;
    } else {
        error!("Task '{}' not found.", name);
    }
}

fn main() {
    let args = Args::parse();

    for task_name in args.tasks {
        TASKS.write().await.insert(task_name, Box::new(|| {
