use std::collections::HashMap;
use std::env;
use std::fs::{self, File};
use std::io::{BufWriter, Write};
use std::path::Path;
use std::sync::{Arc, Mutex};
use tokio::sync::RwLock;
use tokio::task::spawn;
use tracing::*;
use tracing_subscriber::{filter, Registry, EnvFilter};

type ConfigDir = Arc<RwLock<Path>>;
type EnvVars = HashMap<String, String>;

async fn init_config_dir(config_dir: &ConfigDir) {
    let mut dir = config_dir.write().await;
    if !dir.exists() {
        fs::create_dir_all(dir).expect("Failed to create config directory");
    }
}

async fn update_env_vars(config_dir: &ConfigDir, vars: &EnvVars) {
    for (key, value) in vars {
        let file = config_dir.read().await.join(format!("{}.env", key));
        if file.exists() {
            std::fs::remove_file(file).expect("Failed to remove existing .env file");
        }
        let mut env_file = File::create(&file).expect("Failed to create .env file");
        writeln!(env_file, "{key}={value}").expect("Failed to write .env file");
    }

    for (key, _) in env::vars() {
        if !vars.contains_key(key) {
            env::remove_var(key);
        }
    }

    for (key, value) in vars {
        env::set_var(key, value);
    }
}

async fn load_env_vars(config_dir: &ConfigDir) -> Option<EnvVars> {
    let mut vars = HashMap::new();
    for entry in fs::read_dir(config_dir.read().await).expect("Failed to read config directory") {
        let entry = entry?;
        let file = entry.path().join(".env");
        if !file.exists() {
            continue;
        }

        let mut buffer = String::new();
        fs::File::open(file)
            .and_then(|mut f| std::io::BufReader::new(f).read_to_string(&mut buffer))
            .expect("Failed to read .env file");

        for line in buffer.lines() {
            let (key, value) = line.split_once('=').expect("Invalid .env format");
            vars.insert(key.into(), value.to_owned());
        }
    }

    if !vars.is_empty() {
        Some(vars)
    } else {
        None
    }
}

async fn main() {
    let config_dir = Arc::new(RwLock::new(Path::new("./config")));

    // Initialize logging subsystem with appropriate filters
    let filter = EnvFilter::from_default_env();
    Registry::default().init().expect("Failed to init logging");
    tracing_subscriber::registry().with(filter).try_init().unwrap();

    // Run initialization tasks in the background
    spawn(init_config_dir(&config_dir));

    let mut vars = load_env_vars(&config_dir).await;

    if let Some(mut vars) = vars.take() {
        // Load and apply any remaining environment variables
        for (key, value) in env::vars() {
            if !vars.contains_key(key) {
                vars.insert(key, value);
            }
        }

        update_env_vars(&config_dir, &vars).await;
    }

    // Perform the main application logic using updated environment variables
    // ...
}
