# DynamicJSONHandler.py
import json
from typing import Any, Callable, Dict, List, Type
import threading
import datetime
import dateutil.parser as dt_parser
import sys
import os

class CustomJSONEncoder(json.JSONEncoder):
    def __init__(self, custom_handlers: Dict[Type, Callable] = None):
        self.custom_handlers = custom_handlers or {}
        super().__init__(sort_keys=True)

    def default(self, obj: Any) -> Any:
        if isinstance(obj, type) and obj not in (str, int, float, bool):
            handler = self.custom_handlers.get(obj)
            return handler(obj) if callable(handler) else None
        return super().default(obj)

class CustomJSONDecoder:
    def __init__(self, date_format: str = "%Y-%m-%d %H:%M:%S"):
        self.date_format = date_format

    def __call__(self, json_data: str) -> Dict[str, Any]:
        try:
            data = json.loads(json_data, parse_float=lambda x: float(x))
            for key in data:
                if isinstance(data[key], str):
                    data[key] = dt_parser.parse(data[key], self.date_format)
            return data
        except json.JSONDecodeError as e:
            print(f"Error decoding JSON: {e}")
            raise e

class DynamicJSONHandler:
    _instance_lock = threading.Lock()
    __instance = None

    def __new__(cls, *args, **kwargs):
        if not cls.__instance:
            with cls._instance_lock:
                if not cls.__instance:
                    cls.__instance = super().__new__(cls)
                    cls.__instance.config = {
                        "date_format": "%Y-%m-%d %H:%M:%S",
                        # Add more configuration options here
                    }
                    cls.__instance.custom_handlers = {}

        return cls.__instance

    def register_custom_handler(self, class_type: Type, handler: Callable):
        self.custom_handlers[class_type] = handler

    def to_json(self, data: Any) -> str:
        encoder = CustomJSONEncoder(self.custom_handlers)
        return json.dumps(data, cls=encoder, indent=2, separators=(",", ":"))

    def from_json(self, json_data: str) -> Dict[str, Any]:
        decoder = CustomJSONDecoder()
        return decoder(json_data)

# Example usage:
dynamic_handler = DynamicJSONHandler()
class MyClass:
    def __init__(self, x, y):
        self.x = x
        self.y = y

custom_handler = dynamic_handler.register_custom_handler(MyClass, lambda obj: {"x": obj.x, "y": obj.y})
data = MyClass(1, 2)
json_data = dynamic_handler.to_json(data)
print(json_data) # {"x": 1, "y": 2}
new_data = dynamic_handler.from_json(json_data)
```
