['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 1000000
#define KEY_RANGE 1000000

typedef struct {
    int key;
    long value;
    char *message;
    pthread_mutex_t mutex;
} Record;

Record records[MAX_RECORDS];
long offsets[MAX_RECORDS];
int used = 0, free_index = 0;
pthread_mutex_t global_mutex = PTHREAD_MUTEX_INITIALIZER;

void init_record(Record *r) {
    r->key = -1;
    r->value = rand() % KEY_RANGE;
    r->message = strdup("Default Message");
    pthread_mutex_init(&r->mutex, NULL);
}

int add_record(int key, long value, char *message) {
    if (used == MAX_RECORDS) return -1; // No more space

    Record *r = &records[free_index];
    init_record(r);
    r->key = key;

    for (int i = free_index; i > 0 && offsets[i] != 0; --i) {
        offsets[i + 1] = offsets[i]; // Shift existing elements up
    }
    offsets[free_index] = used - free_index; // Set new offset

    ++used;
    return free_index--;
}

Record *get_record(int key) {
    for (size_t i = 0; i < used; ++i) {
        if (records[i].key == key) {
            pthread_mutex_lock(&records[i].mutex);
            return &records[i];
        }
    }
    return NULL;
}

void update_record(Record *r, long value, char *message) {
    r->value = value;
    free(r->message);
    r->message = strdup(message);
    pthread_mutex_unlock(&r->mutex);
}

int query(int *result, size_t max_results, int start_key, int end_key) {
    size_t count = 0;
    for (size_t i = 0; i < used; ++i) {
        Record *r = &records[i];
        pthread_mutex_lock(&r->mutex);
        if (r->key >= start_key && r->key <= end_key) {
            result[count++] = i;
            if (count == max_results) break;
        }
        pthread_mutex_unlock(&r->mutex);
    }
    return count;
}

void free_all() {
    for (size_t i = 0; i < used; ++i) {
        Record *r = &records[i];
        free(r->message);
    }
}
