#include <boost/asio/io_service.hpp>
#include <boost/asio/ip/tcp.hpp>

using namespace std;
using json = nlohmann::json;
namespace async = boost::asio;

class Semaphore {
public:
    Semaphore(int initialValue) : value_(initialValue) {}
    void wait() { --value_; }
    bool tryWait() { return !--value_ && ++value_; }
    void post(unsigned int count = 1) { value_+=count; }
private:
    atomic<int> value_;
};

class ThreadTask {
public:
    ThreadTask(Semaphore& sem, function<void()> task) : sem_(sem), task_(task) {}
    void operator()() {
        sem_.wait(); // acquire semaphore
        try {
            task_(); // execute the task
            sem_.post(); // signal completion
        } catch (const exception& e) {
            cerr << "Error in thread task: " << e.what() << endl;
        }
    }
private:
    Semaphore& sem_;
    function<void()> task_;
};

class ThreadManager {
public:
    ThreadManager(int numThreads, Semaphore& sem) : numThreads_(numThreads), threads_(numThreads, ThreadTask(sem, [](){})), sem_(sem) {}
    void addTask(function<void()> task) {
        auto f = async::make_ready_future<void>(task);
        threads_.emplace_back(ThreadTask(sem_, [f](){f();}));
    }

    void joinAll() {
        for (auto& thread : threads_) thread.get();
    }
private:
    int numThreads_;
    vector<ThreadTask> threads_;
    Semaphore& sem_;
};

class App {
public:
    App(int numThreads, const string& configFilePath) : numThreads_(numThreads), configFile_(configFilePath) {}
    void run() {
        // Initialize and start data source connection here

        // Load configuration parameters from the external data source
        loadConfig();

        // Create semaphore for thread synchronization
        sem_.reset(new Semaphore(numThreads_));

        // Manage threads using ThreadManager
        threadManager_.reset(new ThreadManager(numThreads_, *sem_));

        // Add tasks to the thread manager
        for (int i = 0; i < numTasks_; ++i) {
            auto task = [i]{computeTask(i);};
            threadManager_->addTask(task);
        }

        // Wait for all threads to complete their tasks
        threadManager_->joinAll();

        // Cleanup and finalize data source connection here
    }
private:
    int numThreads_;
    string configFile_;
    unique_ptr<Semaphore> sem_;
    unique_ptr<ThreadManager> threadManager_;

    void loadConfig() {
        ifstream configStream(configFile_);
        json configJson;
        configStream >> configJson;
        numTasks_ = configJson["numTasks"];
    }

    int numTasks_;
    void computeTask(int taskId) {
        // Implement the computational task here
    }
};

int main(int argc, char* argv[]) {
    if (argc < 3) {
        cerr << "Usage: app <numThreads> <configFilePath>" << endl;
        return -1;
    }
    int numThreads = stoi(argv[1]);
    string configFilePath = argv[2];
    App app(numThreads, configFilePath);
    app.run();
    return 0;
}
```
