std::vector<std::string> processLogs(const std::vector<std::string>& logs, const std::string& searchTerm, const std::string& replacement) {
    std::regex replaceRegex(std::regex_constants::format(R"(\b%1$s\b)", searchTerm));
    auto it = logs.begin();
    auto end = logs.end();

    for (; it != end; ++it) {
        // Trim leading and trailing whitespace from log entries
        std::string entry(*it);
        std::trim(entry);

        if (!entry.empty()) {
            // Replace all instances of the search term within the log entry
            std::replace(std::begin(entry), std::end(entry), searchTerm, replacement);
            *it = entry;
        } else {
            // If the search term is not found in any log entry, append the replacement string to the end of the last log entry
            if (it == end - 1) {
                (*it) += " " + replacement;
            }
        }
    }

    return logs;
}
