using System;
using System.Collections.Generic;
using System.Linq;
using System.Numerics;

public class CustomRandom
{
    private float minValue = 0.0f;
    private float maxValue = 1.0f;
    private float bias = 0.5f; // Default to unbiased (50/50 chance)

    public CustomRandom(float min, float max)
    {
        EnsureValidRange(min, max);
        minValue = min;
        maxValue = max;
    }

    private void EnsureValidRange(float min, float max)
    {
        if (max <= min)
            throw new ArgumentOutOfRangeException(nameof(max), $"Max value must be greater than min value: {min} > {max}");
    }

    public float GetRandomFloat()
    {
        return new Random().NextDouble() * (maxValue - minValue) + minValue;
    }

    public int GetRandomInt()
    {
        return (int)((GetRandomFloat() * (maxValue - minValue)) + minValue);
    }

    public float GetRandomValue(float bias)
    {
        if (bias < 0.0f || bias > 1.0f)
            throw new ArgumentOutOfRangeException(nameof(bias), $"Bias value must be between 0 and 1: {bias}");
        return GetRandomFloat() + bias - 0.5f;
    }

    public override string ToString()
    {
        return $"CustomRandom[{minValue}, {maxValue}: Bias={bias}]";
    }

    // Not implemented: Union-Find data structure for efficiently managing and checking disjoint pairs within the range.

    // Not implemented: Method to count disjoint pairs within an integer array using the Union-Find data structure.
}
