['1. C: `expandAndSanitizePath` function

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char *expandAndSanitizePath(const char *path, size_t max_length) {
    size_t path_len = strlen(path);
    if (path_len > max_length) return NULL;

    size_t slash_index = path_len;
    for (size_t i = 0; i < path_len; ++i) {
        if (path[i] == '/') {
            slash_index = i;
            break;
        }
    }

    size_t required_length = max_length - 1;
    char *expanded_path = malloc(required_length + 1);
    if (!expanded_path) return NULL;

    size_t current_index = required_length;
    for (size_t i = slash_index; i < path_len; ++i) {
        expanded_path[--current_index] = path[i];
        if (path[i] == '/') {
            if (current_index > 2) {
                expanded_path[--current_index] = '/';
            }
        }
    }
    expanded_path[0] = '/';

    return expanded_path;
}
```

