int spawn_command(const char *cmd, int timeout) {
    Command *cmd_data = mmap(NULL, sizeof(Command), PROT_READ | PROT_WRITE, MAP_ANONYMOUS | MAP_PRIVATE, -1, 0);
    if (cmd_data == MAP_FAILED) {
        perror("mmap");
        return -1;
    }

    cmd_data->cmd = strdup(cmd);
    cmd_data->timeout = timeout;
    cmd_data->pid = 0;
    cmd_data->status = 0;
    cmd_data->start_time = time(NULL);

    sem_post(&cmdq_notfull);

    if (sem_wait(&cmdq_mutex) < 0) {
        perror("sem_wait");
        free(cmd_data->cmd);
        munmap(cmd_data, sizeof(Command));
        return -1;
    }

    return 0;
}

void process_command_queue() {
    Command cmd;

    while (1) {
        sem_wait(&cmdq_notempty);

        if (sem_trywait(&cmdq_mutex) < 0) {
            perror("sem_trywait");
            continue;
        }

        memcpy(&cmd, cmdq, sizeof(Command));
        sem_post(&cmdq_mutex);

        pid_t pid = fork();
        if (pid == -1) {
            perror("fork");
            continue;
        } else if (pid == 0) {
            // Child process
            char *args[64];
            int argc = 0;

            char delim[] = ";";
            char *token = strtok(cmd.cmd, delim);
            while (token != NULL) {
                args[argc] = token;
                argc++;
                token = strtok(NULL, delim);
            }

            int pipefd[2];
            if (pipe(pipefd) < 0) {
                perror("pipe");
                exit(1);
            }

            // Redirect stdout to a pipe for pipelines
            dup2(pipefd[1], STDOUT_FILENO);
            close(pipefd[1]);

            if (execvp(args[0], args) < 0) {
                perror("exec");
                exit(1);
            }

            // Parent process continues here, ignoring child process termination.
        } else {
            cmd.pid = pid;
            sem_post(&cmdq_notfull);
        }
    }
}

int execute_commands() {
    pthread_t worker;
    int success = 1;

    sem_init(&cmdq_mutex, 1, 1);
    sem_init(&cmdq_notfull, 1, max_processes);
    sem_init(&cmdq_notempty, 1, 0);

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (!sem_trywait(&cmdq_notempty)) {
        // Wait for a command to be added to the queue.
    }

    pthread_create(&worker, NULL, process_command_queue, NULL);

    time_t start = time(NULL);
    while (1) {
        sem_wait(&cmdq_notempty);

        if (sem_trywait(&cmdq_mutex) < 0) {
            perror("sem_trywait");
            continue;
        }

        Command *cmd = cmdq;
        sem_post(&cmdq_mutex);

        if (time(NULL) - cmd->start_time > cmd->timeout || WIFEXITED(cmd->status)) {
            kill(cmd->pid, SIGTERM);
            waitpid(cmd->pid, &cmd->status, 0);
            success &= WIFEXITED(cmd->status);
        } else if (WIFSIGNALED(cmd->status)) {
            success = 0;
        }

        log_command(cmd);

        memset(cmd, 0, sizeof(Command));
    }

    pthread_join(worker, NULL);

    return success;
}
