using System;
using UnityEngine;

public class DataSimulator
{
    private Random _random;
    private float _minValue;
    private float _maxValue;
    private bool _isInclusive;

    public int Seed { get; set; }

    public Vector3 MinVector { get; set; }
    public Vector3 MaxVector { get; set; }

    public Quaternion MinQuaternion { get; set; }
    public Quaternion MaxQuaternion { get; set; }

    public DataSimulator(int seed)
    {
        _random = new Random(seed);
    }

    public void SetConstraints(float min, float max, bool isInclusive)
    {
        if (min > max || isInclusive && (min >= max - 1))
            throw new ArgumentException("Invalid constraints provided.");

        _minValue = min;
        _maxValue = max;
        _isInclusive = isInclusive;
    }

    public void SetVectorConstraints(Vector3 min, Vector3 max)
    {
        if (min > max)
            throw new ArgumentException("Invalid vector constraints provided.");
    }

    public void SetQuaternionConstraints(Quaternion min, Quaternion max)
    {
        ValidateQuaternion(min);
        ValidateQuaternion(max);
    }

    private void ValidateQuaternion(Quaternion quat)
    {
        if (quat.w < 0 || quat.sqrMagnitude > 1)
            throw new ArgumentException("Invalid quaternion provided.");
    }

    public float GetRandomFloat() => _random.NextDouble() * (_maxValue - _minValue) + _minValue;

    public float GetRandomFloat(float min, float max, bool isInclusive)
    {
        if (isInclusive)
            return _random.NextDouble() * (max - min) + min;
        else
            return _random.NextDouble() * (max - min) + Mathf.Min(min, max);
    }

    public Vector3 GetRandomVector3() => new Vector3(GetRandomFloat(), GetRandomFloat(), GetRandomFloat()) * (_MaxVector - _MinVector) + _MinVector;

    public Quaternion GetRandomQuaternion() => UnityEngine.Random.rotation * UnityEngine.Random.onUnitSphere();

    public override string ToString()
    {
        return $"DataSimulator: seed={Seed}, min={_minValue} max={_maxValue} inclusive={_isInclusive}, vectorMin={_MinVector}, vectorMax={_MaxVector}, quaternionMin={_MinQuaternion}, quaternionMax={_MaxQuaternion}";
    }
}
