using System;
using System.Collections.Concurrent;
using System.Diagnostics;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

namespace DynamicRangeGenerator
{
    public class DynamicRangeGenerator
    {
        private readonly SemaphoreSlim _semaphore;
        private readonly Random _random;
        private readonly Tuple<double, double> _range;
        private readonly ConcurrentDictionary<long, int> _usageCounts;

        public DynamicRangeGenerator(int initialSemaphoreValue = Environment.ProcessorCount * 2)
        {
            _semaphore = new SemaphoreSlim(initialSemaphoreValue);
            _random = new Random();
            _range = Tuple.Create(_rangeMin: double.MinValue, _rangeMax: double.MaxValue);
            _usageCounts = new ConcurrentDictionary<long, int>();
        }

        public DynamicRangeGenerator(double rangeMin, double rangeMax, int initialSemaphoreValue = Environment.ProcessorCount * 2) : this(initialSemaphoreValue)
        {
            _range = Tuple.Create(_rangeMin: rangeMin, _rangeMax: rangeMax);
        }

        public double NextDouble()
        {
            return Next(_random.NextDouble());
        }

        public int NextInt()
        {
            long hashCode = Interlocked.Increment(ref _usageCounts.GetOrAdd((_rangeMin + _rangeMax) / 2, 0)).GetHashCode();
            Debug.WriteLine($"Generated value: {(_rangeMin + _rangeMax) / 2}, hash code: {hashCode}");
            return (int)Next(hashCode % (_rangeMax - _rangeMin + 1) + _rangeMin);
        }

        private double Next(long index)
        {
            _semaphore.Wait();
            try
            {
                var fraction = _random.NextDouble();
                var rangeSize = _rangeMax - _rangeMin;
                return (_rangeMin + fraction * rangeSize + index * (fraction % (1 / (_rangeMax - _rangeMin))) * rangeSize) % rangeSize + _rangeMin;
            }
            finally
            {
                _semaphore.Release();
            }
        }
    }
}
```

