static long *offsets = NULL;
static int *keys = NULL;
static pthread_mutex_t hash_lock = PTHREAD_MUTEX_INITIALIZER;
static pthread_t thread_ids[THREAD_COUNT];
static pthread_attr_t attr[THREAD_COUNT];
static thread_data_t *threads = NULL; // Thread-specific data for logging and queue management

void* logger(void *arg) {
    // Log memory usage statistics here, ensure thread safety using locks/condition variables
    return NULL;
}

void* thread_func(void *arg) {
