    return NULL;
}

void init() {
    mmap = mmap(NULL, THREAD_COUNT * MEMORY_THRESHOLD, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (mmap == MAP_FAILED) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
