typedef struct {
    double *numbers;
    size_t capacity;
    size_t count;
} NumberList;

NumberList* create_number_list(size_t initial_capacity) {
    NumberList *list = malloc(sizeof(NumberList));
    if (!list) {
        syslog(LOG_ERR, "Failed to allocate memory for number list");
        return NULL;
    }

    list->numbers = malloc(initial_capacity * sizeof(double));
    if (!list->numbers) {
        free(list);
        syslog(LOG_ERR, "Failed to allocate memory for numbers array");
        return NULL;
    }

    list->capacity = initial_capacity;
    list->count = 0;
    return list;
}

void resize_number_list(NumberList *list, size_t new_capacity) {
    double *temp = realloc(list->numbers, new_capacity * sizeof(double));
    if (!temp) {
        syslog(LOG_ERR, "Failed to reallocate memory for numbers array");
        return;
    }

    list->numbers = temp;
    list->capacity = new_capacity;
}

void destroy_number_list(NumberList *list) {
    free(list->numbers);
    free(list);
}

bool is_numeric(const char *str) {
    if (!str || !*str) return false;

    size_t len = strlen(str);
    if (len > INT_MAX - 1 - 1) return false; // checks for integer overflow in atof()

    bool has_point = false;
    int i = 0;
    for (; str[i]; ++i) {
        if (str[i] == '.') {
            if (has_point || (i > len - 2)) return false; // checks for more than one decimal point
            has_point = true;
            continue;
        }

        if ('0' <= str[i] && str[i] <= '9') continue;

        return false;
    }

    return true;
}

void read_numbers(const char *filename, NumberList *list) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        syslog(LOG_ERR, "Failed to open input file: %s", strerror(errno));
        return;
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        if (!is_numeric(line)) continue; // skip non-numeric lines

        double number = atof(line);
        if (list->count == list->capacity) resize_number_list(list, list->capacity * 2); // grow array as needed

        list->numbers[list->count++] = number;
    }

    fclose(file);
}

void compute_average(const NumberList *list, double *average) {
    if (!list->count) {
        *average = 0.0; // handle empty list case
        return;
    }

    double sum = 0.0;
    for (size_t i = 0; i < list->count; ++i) {
        sum += list->numbers[i];
    }

    *average = sum / list->count; // compute average
}

void process_input(const char *filename) {
    NumberList *list = create_number_list(8);
    if (!list) return;

    read_numbers(filename, list);

    double average;
    compute_average(list, &average);

    printf("The average value is: %.16f\n", average);

    destroy_number_list(list);
}
```

