#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <hash_map.h> // External hash table library implementation

typedef struct Edge {
    int id;
    int to;
    struct Edge *next;
} Edge;

typedef struct Node {
    int id;
    int degree;
    HashMap_t metadata;
    Edge *edges;
    struct Node *next;
} Node;

Node* create_node(int id) {
    Node *new_node = (Node*) malloc(sizeof(Node));
    new_node->id = id;
    new_node->degree = 0;
    new_node->metadata = HashMap_init();
    new_node->edges = NULL;
    new_node->next = NULL;
    return new_node;
}

Edge* create_edge(int id, int to) {
    Edge *new_edge = (Edge*) malloc(sizeof(Edge));
    new_edge->id = id;
    new_edge->to = to;
    new_edge->next = NULL;
    return new_edge;
}

Graph* create_graph() {
    Graph *new_graph = (Graph*) malloc(sizeof(Graph));
    new_graph->nodes = NULL;
    return new_graph;
}

void insert_node(Graph *graph, int id) {
    Node *new_node = create_node(id);

    if (!graph->nodes) {
        graph->nodes = new_node;
        return;
    }

    Node *current = graph->nodes;
    while (current->next != NULL)
        current = current->next;

    current->next = new_node;
}

void insert_edge(Graph *graph, int id1, int id2, void* metadata) {
    Node *node1 = find_node(graph, id1);
    Node *node2 = find_node(graph, id2);

    if (!node1 || !node2)
        return;

    Edge *new_edge = create_edge(id1, id2);
    new_edge->next = node1->edges;
    node1->edges = new_edge;
    node1->degree++;

    if (!HashMap_contains(node2->metadata, &id1)) {
        HashMap_put(node2->metadata, &id1, metadata);
        node2->degree++;
    }
}

Node* find_node(Graph *graph, int id) {
    Node *current = graph->nodes;

    while (current != NULL) {
        if (current->id == id)
            return current;
        current = current->next;
    }

    return NULL;
}
```

