public class EmployeeDetails {
    private static final LoadingCache<String, String> EMPLOYEE_DETAILS_CACHE = CacheBuilder.newBuilder()
            .expireAfterAccess(10, TimeUnit.MINUTES)
            .build((key) -> retrieveEmployeeDetails(key));

    private static final OkHttpClient HTTP_CLIENT = new OkHttpClient();

    public static String retrieveEmployeeDetails(String supervisorId, DatabaseCredentials dbCredentials) {
        try (Connection connection = createConnection(dbCredentials)) {
            PreparedStatement statement = connection.prepareStatement("SELECT name, city, address FROM Employees WHERE SupervisorId = ?");
            statement.setString(1, supervisorId);
            ResultSet resultSet = statement.executeQuery();

            if (resultSet.next()) {
                String employeeDetails = String.format("Name: %s%nCity: %s%nAddress: %s",
                        resultSet.getString("name"),
                        resultSet.getString("city"),
                        resultSet.getString("address"));

                EMPLOYEE_DETAILS_CACHE.put(supervisorId, employeeDetails);

                // Fetch additional data from external API if available
                URL apiUrl = new URL("https://api.example.com/employee/" + supervisorId);
                Response apiResponse = HTTP_CLIENT.newCall(new Request.Builder().url(apiUrl).build()).execute();

                if (!apiResponse.isSuccessful()) {
                    // Handle API failure by returning limited information
                    return employeeDetails;
                }

                JSONObject apiData = new JSONObject(apiResponse.body().string());
                String department = apiData.getString("department");
                String jobTitle = apiData.optString("job_title", "Unknown Job Title");

                return String.format("%s%nDepartment: %s%nJob Title: %s", employeeDetails, department, jobTitle);
            } else {
                // Handle unsupported supervisor ID by providing a default response
                return "Unsupported Supervisor ID";
            }
        } catch (SQLException | InterruptedException | ExecutionException e) {
            // Handle database connectivity issues and errors during query execution
            e.printStackTrace();
            return "Database error: Check logs for details.";
        }
    }

