    public class UpdateElementController : ApiController
    {
        private readonly ICacheManager _cacheManager;
        private readonly IDbContextProvider _dbContextProvider;
        private readonly ILockManager _lockManager;
        private readonly IRetryPolicy _retryPolicy;
        private const string CacheKeyPrefix = "UpdateElement-";

        public UpdateElementController(ICacheManager cacheManager, IDbContextProvider dbContextProvider, ILockManager lockManager, IRetryPolicy retryPolicy)
        {
            _cacheManager = cacheManager;
            _dbContextProvider = dbContextProvider;
            _lockManager = lockManager;
            _retryPolicy = retryPolicy;
        }

        [HttpPost]
        public async Task<IHttpActionResult> UpdateElement(int pageSectionId, int elementId, string htmlContent)
        {
            var cacheKey = CreateCacheKey(pageSectionId, elementId);
            var cachedHtmlContent = _cacheManager.GetData(cacheKey);

            if (cachedHtmlContent != null)
            {
                return Json(new { Refresh = true });
            }

            using (var transactionScope = _dbContextProvider.GetTransaction())
            {
                var dbLockKey = CreateDbLockKey(pageSectionId, elementId);
                var redisLock = await _lockManager.AcquireLockAsync(dbLockKey);

                if (!redisLock)
                {
                    return StatusCode(HttpStatusCode.Conflict, "Unable to acquire lock");
                }

                try
                {
                    var service = new ContentService(_retryPolicy);
                    var updatedHtmlContent = await service.UpdateElementAsync(pageSectionId, elementId, htmlContent);

                    transactionScope.Complete();

                    _cacheManager.AddData(cacheKey, updatedHtmlContent, Cache.NoSlidingExpiration);

                    return Json(new { Refresh = true });
                }
                catch (Exception ex)
                {
                    // Log the exception here
                    // ...
                    transactionScope.Dispose();

                    return StatusCode(HttpStatusCode.InternalServerError, "An error occurred while updating the element");
                }
            }
        }

        private string CreateCacheKey(int pageSectionId, int elementId) => $"{CacheKeyPrefix}{pageSectionId}-{elementId}";

        private string CreateDbLockKey(int pageSectionId, int elementId) => $"UpdateElementLock-{pageSectionId}-{elementId}";
    }

    public class ContentService
    {
        private readonly IRetryPolicy _retryPolicy;
        private const int MaxRetries = 5;
        private const BackoffStrategy BackoffStrategy = BackoffStrategy.Exponential;

        public async Task<string> UpdateElementAsync(int pageSectionId, int elementId, string htmlContent)
        {
            var attempt = 0;

            do
            {
                try
                {
                    // Implement your database updates here

                    return htmlContent;
                }
                catch (Exception ex)
                {
                    if (attempt >= MaxRetries)
                    {
                        throw;
                    }

                    await Task.Delay((long)Math.Pow(2, attempt + 1), _retryPolicy.CurrentDelayProvider);
                }

                attempt++;
            } while (attempt < MaxRetries);
        }
