import os
import re
import json
from collections import defaultdict, Counter
from concurrent.futures import ThreadPoolExecutor
import nltk
from nltk.corpus import stopwords
from nltk.stem import PorterStemmer
from nltk.tokenize import word_tokenize, sent_tokenize
from gensim import corpora, models
from spacy import load
import requests
from functools import lru_cache
from time import time

# Set up logging and monitoring
import logging
logger = logging.getLogger(__name__)

nltk.download('punkt')
nltk.download('stopwords')
nltk.download('wordnet')

class CloudTermProcessor:
    def __init__(self, api_key, max_workers=10):
        self.api_key = api_key
        self.max_workers = max_workers
        self.stop_words = set(stopwords.words('english'))
        self.stemmer = PorterStemmer()
        self.id2word = corpora.Dictionary.load('./cloud_dict.txt') if os.path.exists('./cloud_dict.txt') else None
        self.corpus = []
        self.model = None
        self.synonym_api = requests.get('https://contextualwebapi.com/api/v1/search', params={'q': '', 'apikey': self.api_key}) if api_key else None
        self.context_extractor = load("en_core_web_sm")
        self.cache = {}
        self.rate_limit = 60 # requests per minute

    def process(self, text):
        tokens = self._tokenize(text)
        stemmed_tokens = [self.stemmer.stem(token) for token in tokens if token not in self.stop_words]
        self._add_to_corpus(stemmed_tokens)
        term_freqs, terms_contexts = self._get_term_info()
        report = self._generate_report(terms_contexts, term_freqs)
        return report

    @lru_cache(maxsize=None)
    def _tokenize(self, text):
        doc = self.context_extractor(text)
        return [token for token in doc if not token.is_stop and not token.is_punct]

    @lru_cache(maxsize=None)
    def _get_synonyms(self, term):
        if self.synonym_api:
            synonyms = set()
            for syn in self.synonym_api.json()['data']['items']:
                if re.search(term, syn['text']) and syn['relation'] == 'hyponym':
                    synonyms.add(syn['text'].replace("\n", ""))
            return synonyms
        else:
            return set()

    def _get_term_info(self):
        if not self.id2word:
            self._train_dict()
        term_freqs = defaultdict(Counter)
        terms_contexts = defaultdict(lambda: {'occurrences': 0, 'sections': {}})
        for token in self.corpus:
            term_freqs[token] += 1
            terms_contexts[token]['occurrences'] += 1
        for token, freqs in term_freqs.items():
            section_freq = defaultdict(int)
            for section, section_freqs in freqs.items():
                section_freq[section] = sum(section_freqs.values())
            terms_contexts[token]['sections'].update(section_freq)
        return term_freqs, terms_contexts

    def _add_to_corpus(self, tokens):
        for token in tokens:
            self.corpus.append(token)
        if len(self.corpus) > 1000000:
            self._update_dict()

    def _train_dict(self):
        self.id2word = corpora.Dictionary(self.corpus)
        self.corpus = list(self.id2word.doc2bow(self.corpus))
        self.model = models.LdaModel(corpus, num_topics=10, id2word=self.id2word, passes=15)

    def _update_dict(self):
        new_dict = corpora.Dictionary(self.corpus)
        if self.id2word:
            old_dict = self.id2word
            for token, freq in new_dict.dfs[0]:
                if token not in old_dict.token2id:
                    old_dict.add_token(token)
        else:
            old_dict = new_dict
        self.id2word = old_dict
        self.corpus = list(self.id2word.doc2bow(self.corpus))
        self._train_model()

    def _generate_report(self, terms_contexts, term_freqs):
        report = {}
        for term, freq in term_freqs.items():
            contexts = [self._get_synonyms(syn) for syn in terms_contexts[term]['synonyms']]
            contexts += terms_contexts[term]['contexts'].keys()
            report[term] = {'occurrences': freq, 'contexts': sorted(list(set(contexts)))}
        return report

    def _get_synonyms(self, term):
        if self.synonym_api:
            synonyms = set()
            for syn in self.synonym_api.json()['data']['items']:
                if re.search(term, syn['text']) and syn['relation'] == 'hyponym':
                    synonyms.add(syn['text'].replace("\n", ""))
            return synonyms
        else:
            return set()

    def _train_model(self):
        if self.corpus and self.id2word:
