    var lockFactory = $cacheFactory('lockCache');
    var retryConfig = { retries: 3, delay: 1000 }; // Customizable retry configuration

    function DialogService($scope) {
        this.$scope = $scope;
        this.resourceId = null;
        this.url = null;
        this.fieldsMapping = [];

        this.updateDialogFields = function(resourceId, url, fieldsMapping) {
            this.resourceId = resourceId;
            this.url = url;
            this.fieldsMapping = fieldsMapping;
            this.refreshFields();
        };
    }

    DialogService.prototype.refreshFields = function() {
        if (!this._lock) {
            this._lock = lockFactory.get(this.resourceId);
            if (!this._lock.isLocked()) {
                this._lock.put(true);

                this._loadData().then(function(data) {
                    data.forEach(field => {
                        var fieldName = this.fieldsMapping[field];
                        if (fieldName) {
                            this.$scope.$parent[fieldName] = data[field]; // Assuming the parent scope has properties with matching field names
                        }
                    });
                }).finally(function() {
                    this._lock.release();
                });
            } else {
                console.log('Dialog refresh locked'); // Log concurrency issues
            }
        }
    };

    DialogService.prototype._loadData = function() {
        var deferred = $q.defer();

        dialogCache.get(this.resourceId).then(function(cachedData) {
            if (cachedData) {
                deferred.resolve(cachedData);
            } else {
                $http({
                    method: 'GET',
                    url: this.url,
                    cache: false
                }).then(function(response) {
                    dialogCache.put(this.resourceId, response.data);
                    deferred.resolve(response.data);
                });
            }
        });

        return deferred.promise;
    };

    DialogService.prototype._retry = function(callback) {
        var deferred = $q.defer();

        if (this.retries > 0) {
            this.retries--;
            callback().then(function() {
                deferred.resolve();
            }).catch(function(error) {
                setTimeout(function() {
                    deferred = $q.defer();
                    this._retry(callback).then(function() {
                        deferred.resolve();
                    });
                }, retryConfig.delay);
            });
        } else {
            deferred.reject(new Error('Maximum retries exceeded'));
        }

        return deferred.promise;
    };

    DialogService.prototype._sendMessage = function(message) {
        this.$scope.$parent.$broadcast('dialog-update', message);
    };

    // For versioning and logging purposes, you can implement the following methods:
