  }

  startService() {
    if (this.serviceRunning) return;

    this.serviceRunning = true;
    setTimeout(() => {
      if (!this.pauseRequested) this.transmitData();
    }, Math.random(...this.delayRange));
  }

  stopService() {
    this.serviceRunning = false;
  }

  pause() {
    this.pauseRequested = true;
    this.stats.pauses++;
  }

  resume() {
    if (!this.serviceRunning) return;

    this.pauseRequested = false;
    this.resumeRequested = true;
    this.stats.resumes++;
  }

  collectData(data) {
    this.buffer.push(data);
  }

  transmitData() {
    try {
      if (this.buffer.length < this.batchSize) return;

      const dataBatch = this.buffer.splice(0, this.batchSize);
      this.stats.successfulTransmissions++;
      this.healthMonitor.reportSuccessfulTransmission();

      // Implement sending data to messaging system here
      sendToMessagingSystem(dataBatch);

      if (!this.pauseRequested) requestAnimationFrame(() => this.transmitData());
    } catch (error) {
      this.healthMonitor.reportError(error);
      console.error(`Error transmitting data: ${error}`);
    }
  }
}

class HealthMonitor {
  constructor(dataCollector) {
    this.dataCollector = dataCollector;
    this.threshold = 1000; // in milliseconds
  }

  reportSuccessfulTransmission() {
    if (this.dataCollector.buffer.length > this.threshold)
      this.alertAdministrator();
  }

  reportError(error) {
    if (this.dataCollector.buffer.length > this.threshold || error.type === 'PERSISTENT')
      this.alertAdministrator();
  }

  alertAdministrator() {
