let modules = [];
let executedModules = new Set();

function loadModule(filename) {
  try {
    const module = { filename };
    let src = fs.readFileSync(filename, 'utf8');
    eval(`module.exports = ${src}`);
    modules.push(module);
  } catch (error) {
    console.error(`Failed to load module: ${filename}:`, error);
  }
}

function executeModule(module) {
  if (!executedModules.has(module.filename)) {
    const timestamp = Date.now();
    const extension = '.js';
    const executableName = `${module.filename.replace(extension, '_loaded${timestamp}${extension}`;

    try {
      const exportedModule = require(executableName);
      const result = exportedModule.default || exportedModule;
      console.log(`Successfully executed module: ${module.filename}`);
      executedModules.add(module.filename);
      return result;
    } catch (error) {
      console.error(`Failed to execute module: ${module.filename}:`, error);
    }
  }
}

function loadAndExecute() {
  modules.forEach((module) => {
    executeModule(module);
  });
}

loadAndExecute();
