```java
import org.apache.http.*;
import org.apache.http.client.config.RequestConfig;
import org.apache.http.impl.nio.client.CloseableHttpAsyncClient;
import org.apache.http.impl.nio.conn.PoolingNHttpClientConnectionManager;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.integration.http.dsl.Http;
import org.springframework.messaging.Message;
import org.springframework.messaging.support.MessageBuilder;
import reactor.core.publisher.Mono;

@Configuration
public class ServerConnectionService {
    private static final Logger log = LoggerFactory.getLogger(ServerConnectionService.class);

    @Bean
    public CloseableHttpAsyncClient httpClient() {
        HttpParams params = HttpUtils.getDefaultParameters();
        RequestConfig config = RequestConfig.custom()
                .setConnectTimeout(3000)
                .setSocketTimeout(3000)
                .build();
        PoolingNHttpClientConnectionManager connMgr = new PoolingNHttpClientConnectionManager();
        connMgr.setMaxTotal(200);
        return HttpAsyncClients.custom()
                .setDefaultRequestConfig(config)
                .setConnectionManager(connMgr)
                .build();
    }

    @Bean
    public HttpMessageHandlerSpec httpRequestHandlerSpec(CloseableHttpAsyncClient client) {
        return Http.inboundGateway("/api/remote")
                .poller(Pollers.fixedDelay(100))
                .requestFactory(() -> client.executeRequest(HttpRequestBuilder.create()))
                .transformSendAndReceive((request, sendReply) -> {
                    log.debug("Sending request: {}", request);
                    return Mono.fromCallable(() -> sendReply(request));
                })
                .handle(this::processMessage);
    }

    private void processMessage(Message<?> message) {
        // Process the incoming message and send it to RabbitMQ for asynchronous processing
    }
}
```

3. Configure RabbitMQ as needed and create a Publisher bean for sending messages:

