```java
@Service
public class MessageSender {

    private final AmqpTemplate ampTemplate;

    public MessageSender(AmqpTemplate ampTemplate) {
        this.ampTemplate = ampTemplate;
    }

    public void sendMessageToQueue(String queueName, String message) {
        ampTemplate.convertAndSend(queueName, MessageBuilder.createMessage(message));
    }
}
```

5. Finally, wire up the service and message sender:

```java
@SpringBootApplication
public class Application {

    public static void main(String[] args) {
        SpringApplication.run(Application.class, args);
    }

    @Autowired
    private ServerConnectionService serverConnectionService;

    @Autowired
    private MessageSender messageSender;

    @PostConstruct
    public void init() {
        // Load configuration via environment variables and adjust the service accordingly
        // For example, set maximum message size and configure connection pool parameters
        // ...
        serverConnectionService.processMessage((message) -> {
            String payload = String.valueOf(message.getPayload());
            if (payload.length() > 1_000_000) {
                log.error("Message size exceeds limit: {}", payload.length());
                return Mono.empty();
            }
            messageSender.sendMessageToQueue("remote-queue", payload);
            return Mono.just(payload);
        });
    }
}
