[" Here's a simplified version of the requested JavaScript function using Streams API, Promises, and some logging using `winston` library. This example assumes that the private key and certificate are in separate files and located within the OAuth request object.

```javascript
const fs = require('fs');
const stream = require('stream');
const { createWriteStream } = require('fs-extra');
const { v4: uuidv4 } = require('uuid');
const winston = require('winston');

async function generatePEMCertificate(oauthRequest) {
  const { privateKeyPath, certificatePath } = oauthRequest;

  if (!privateKeyPath || !certificatePath) {
    throw new Error('Private key and certificate paths are required.');
  }

  let privateKeyStream = fs.createReadStream(privateKeyPath);
  let certificateStream = fs.createReadStream(certificatePath);

  const pemFileStream = new stream.Transform({
    transform(chunk, encoding, callback) {
      this.push(`${chunk}\n`);
      callback();
    },
    objectMode: true
  });

  let pemFilePath = `certificates/${uuidv4()}.pem`;
  const outputStream = createWriteStream(pemFilePath);

  privateKeyStream.pipe(pemFileStream).pipe(outputStream);
  certificateStream.pipe(pemFileStream);

  return new Promise((resolve, reject) => {
    outputStream.on('finish', () => resolve(pemFilePath));
    outputStream.on('error', (err) => reject(err));
  });
}

generatePEMCertificate({ privateKeyPath: '/path/to/private_key', certificatePath: '/path/to/certificate' })
  .then((pemFilePath) => {
    winston.info(`Generated PEM certificate at ${pemFilePath}`);
  })
  .catch((err) => {
    winston.error(err);
  });
```

This example demonstrates a basic implementation of the given task, but it does not cover all the points mentioned in your request due to their complexity and scope. It provides an asynchronous function using Promises that generates a PEM-formatted certificate from specified private key and certificate files. The function logs the status of each certificate generation process and supports integration into larger applications.

