#[derive(Default)]
struct Config {
    filter: Regex,
    db_url: String,
}

async fn process_file(path: Path, sender: Sender<LogEntry>, config: &Config) {
    let mut file = File::open(path).await.expect("Failed to open file");
    let reader = TokioBufReader::new(&mut file);
    let re = config.filter.as_str();
    for line in reader.lines().filter_map(|line| async move { line.ok() }).buffer_unordered(1024) {
        if let Some(line) = line {
            if re.find(&line).is_some() {
                sender.send(LogEntry::new(line, Instant::now())).await.expect("Failed to send log entry");
            }
        }
    }
}

async fn process_directory(path: Path, config: &Config) {
    let dir_stream = ReadDirStream::new(path);
    while let SomeOk(entry) = dir_stream.read().await {
        if entry.file_type().is_file() {
            let path = entry.into_path();
            if let Err(e) = spawn(|| process_file(path, config.db_sender.clone(), config)).await {
                eprintln!("Error processing file: {}", e);
            }
        }
    }
}

