#include <type_traits>

template<typename DataType, typename Allocator = std::allocator<DataType>>
class Octree final {
public:
    using node_t = std::unique_ptr<Octree>;
    using value_type = DataType;
    using allocator_type = Allocator;
    using node_allocator_type = typename allocator_type::template rebind<node_t>::other;
    using size_type = std::size_t;
    using index_type = std::uint32_t;
    using mutex_type = std::mutex;

private:
    static constexpr index_type bit(index_type i) noexcept { return 1 << i; }
    static constexpr index_type max_bits() noexcept { return sizeof(index_type) * 8 - 3; }

    index_type feature_size_;
    size_type num_leaf_nodes_;
    size_type data_capacity_;
    node_allocator_type node_alloc_;
    mutex_type nodes_mutex_;
    std::vector<node_t> roots_;
    std::atomic<bool> resizing_;

public:
    Octree(index_type feature_size, size_type num_leaf_nodes, size_type data_capacity) noexcept
        : feature_size_(feature_size), num_leaf_nodes_(num_leaf_nodes), data_capacity_(data_capacity),
          resizing_(false), roots_() {
        if (num_leaf_nodes_ > std::pow(8, max_bits()))
            throw std::runtime_error("Number of leaf nodes exceeds the maximum capacity.");
    }

    template<typename Function>
    void construct(Function func) noexcept {
        std::vector<std::future<void>> futures;
        auto num_threads = std::thread::hardware_concurrency();

        for (size_type i = 0; i < num_threads; ++i) {
            futures.emplace_back(std::async(std::launch::async, [this, func]() mutex_type* lock, index_type node_index) mutable {
                auto root_it = roots_.begin();
                std::advance(root_it, node_index / 8);

                lock->lock();
                auto node = (*root_it).get();
                lock->unlock();

                if (!node) {
                    if (node_index == 0)
                        node.reset(new Octree(feature_size_, num_leaf_nodes_, data_capacity_));
                    else
                        node.reset(new Octree(feature_size_, num_leaf_nodes_, data_capacity_).split());
                }

                if (!node->isLeaf()) {
                    func([this, lock, node_index]() mutex_type* lock, index_type child_node_index) mutable {
                        this->construct(std::bind(func, std::ref(*lock), child_node_index));
                    }, node_index);
                }
            }, &nodes_mutex_, node_index_);
        }

        for (auto& future : futures) future.wait();
    }

    // Other member functions for insertion, retrieval, resizing, and destruction...
};
```
