    char *theme_bitmap;
    size_t cache_size;
} ThemeCache;

ThemeCache theme_cache;

void recycle_theme_bitmap(char **bitmap) {
    if (*bitmap != NULL) {
        free(*bitmap);
        *bitmap = NULL;
    }
}

int initialize_default_theme_directory() {
    char *default_dir = configuration_manager_get_default_theme_directory();
    if (default_dir == NULL) {
        mkdir(CONFIGURATION_MANAGER_DEFAULT_THEME_DIRECTORY, 0755);
        return 1;
    }
    return 0;
}

int load_image_into_cache(const char *filepath, char **bitmap) {
    int fd = open(filepath, O_RDONLY);
    if (fd == -1) {
        return 0;
    }

    struct stat file_stats;
    fstat(fd, &file_stats);
    void *image_data = mmap(NULL, file_stats.st_size, PROT_READ, MAP_PRIVATE, fd, 0);
    close(fd);

    if (image_data == MAP_FAILED) {
        return 0;
    }

    *bitmap = malloc(file_stats.st_size);
    memcpy(*bitmap, image_data, file_stats.st_size);
    munmap(image_data, file_stats.st_size);

    return 1;
}

void process_entry(char *line, Entry **entry) {
    char *fields[4];
    int num_fields = tokenize(line, fields);

    Entry *new_entry = malloc(sizeof(Entry));
    new_entry->timestamp = strdup(fields[0]);
    new_entry->error_code1 = atoi(fields[1]);
    new_entry->error_code2 = atoi(fields[2]);
    new_entry->metadata = strdup(fields[3]);

    if (theme_cache.cache_size + sizeof(*new_entry) > theme_cache.cache_size_limit) {
        recycle_theme_bitmap(&theme_cache.theme_bitmap);
        free(*entry);
        *entry = new_entry;
        theme_cache.cache_size -= sizeof(*entry);
    } else {
        theme_cache.cache_size += sizeof(*new_entry);
        theme_cache.theme_bitmap = realloc(theme_cache.theme_bitmap, theme_cache.cache_size);
        *entry = new_entry;
    }
}

