typedef struct {
    int value;
} Record;

void init_graph_data(int *offsets, int *keys, Record **records, int capacity, int *config) {
    offsets[0] = 0;
    keys[0] = 0;

    *records = malloc(capacity * RECORD_SIZE);
    for (int i = 1; i <= capacity; ++i) {
        offsets[i] = offsets[i - 1] + 1;
        keys[i] = i;
        ((Record *)*records)[offsets[i] - 1].value = config[RANDOM_SEED] * (i + config[MAX_VALUE]); // Generates random values within a specified range
        config[RANDOM_SEED] = (config[RANDOM_SEED] * config[MULTIPLIER]) % config[MAX_VALUE];
    }
}

