class DynamicRangeValueGenerator {
private:
    double minValue = 0.0;
    double maxValue = 1.0;
    double bias = 0.5;
    std::unordered_map<int, int> unionFind;

    void EnsureValidRange() {
        if (minValue >= maxValue) {
            throw std::invalid_argument("Invalid range: Minimum value must be less than maximum value.");
        }
    }

    int Find(int x) {
        if (unionFind.find(x) == unionFind.end()) {
            unionFind[x] = x;
            return x;
        }
        auto parent = unionFind[x];
        while (parent != unionFind[parent]) {
            unionFind[parent] = unionFind[unionFind[parent]];
            parent = unionFind[parent];
        }
        return parent;
    }

    void Union(int x, int y) {
        auto rootX = Find(x);
        auto rootY = Find(y);
        if (rootX != rootY) {
            unionFind[rootY] = rootX;
        }
    }

    int CountDisjointPairs(const std::vector<int>& values) {
        for (size_t i = 0; i < values.size(); ++i) {
            auto x = Find(values[i]);
            for (size_t j = i + 1; j < values.size(); ++j) {
                std::chrono::steady_clock::time_point begin = std::chrono::steady_clock::now();
                auto y = Find(values[j]);
                std::chrono::steady_clock::time_point end = std::chrono::steady_clock::now();
                auto duration = std::chrono::duration_cast<std::chrono::milliseconds>(end - begin).count();
                if (x != y) {
                    std::cout << "Pair (" << values[i] << ", " << values[j] << ") is disjoint, took " << duration << " ms.\n";
                    Union(values[i], values[j]);
                }
            }
        }
        return unionFind.size();
    }

public:
    DynamicRangeValueGenerator() {}
    DynamicRangeValueGenerator(double min, double max) {
        EnsureValidRange();
        minValue = min;
        maxValue = max;
    }

    double GetRandomFloat() const {
        std::uniform_real_distribution<> distrib(minValue, maxValue);
        return distrib(std::random_device{}());
    }

    int GetRandomInt() const {
        std::uniform_int_distribution<> distrib((int)minValue, (int)maxValue);
        return distrib(std::random_device{});
    }

    double GetRandomValue(double bias) const {
        if (bias < 0.0 || bias > 1.0) {
            throw std::invalid_argument("Invalid bias: Bias must be between 0 and 1.");
        }
        return minValue + (maxValue - minValue) * bias;
    }

    std::string ToString() const {
        std::stringstream ss;
        ss << "DynamicRangeValueGenerator [Min: " << minValue << ", Max: " << maxValue << ", Bias: " << bias << ']';
        return ss.str();
    }
};
