```javascript
async function collectMatchingElements(selector, callback, rootElement, batchSize = 10) {
    const queue = [rootElement];
    const results = [];

    while (queue.length > 0) {
        const currentElement = queue.shift();

        if (currentElement instanceof HTMLElement && !currentElement.isConnected || currentElement === document.body) continue;

        let matches = Array.from(document.querySelectorAll(selector, currentElement));

        if (matches.length > 0) {
            results.push(...matches);
            queue.push(...matches);
        }

        for (let i = 0; i < matches.length && i + batchSize < results.length; ++i) {
            const element = matches[i];
            if (!callback(element)) break;
        }
    }

    return results;
}
