public async Task<List<Dictionary<string, object>>> ProcessMessagesAsync(byte[] key, byte[] iv, bool synchronous, List<(string base64Message, string signature, bool executionMode)> messages)
{
    var userInfoCache = new MemoryCache("UserInfoCache");
    var accessToken = GetAccessToken(); // Implement OAuth 2.0 authentication and obtain access token

    var decryptedMessages = new List<Dictionary<string, object>>();

    var tripleDes = TripleDES.Create();
    tripleDes.Key = key;
    tripleDes.IV = iv;

    var hmacSHA256 = new HMACSHA256(key);

    var tasks = messages.Select(t =>
    {
        return Task.Run(() =>
        {
            try
            {
                var messageBytes = Convert.FromBase64String(t.base64Message);

                if (messageBytes.Length % TripleDes.BlockSize >= 1)
                    throw new ArgumentException("Invalid Base64-encoded string length");

                var decryptedMessage = Decrypt(tripleDes, messageBytes, iv);
                var computedSignature = ComputeHMACSHA256(hmacSHA256, decryptedMessage);
                var isValidSignature = t.signature == ComputedBase64String(computedSignature);

                return new Dictionary<string, object>
                {
                    {"Decrypted Message", decryptedMessage},
                    {"Signature", t.signature},
                    {"Is Valid Signature", isValidSignature}
                };
            }
            catch (Exception ex)
            {
                return new Dictionary<string, object>
                {
                    {"Decrypted Message", ""},
                    {"Signature", ""},
                    {"Is Valid Signature", false},
                    {"Error", ex.Message}
                };
            }
        });
    });

    if (synchronous) await Task.WhenAll(tasks);
    else tasks.ForEach(t => t.Start());

    var results = tasks.Select(t => t.Result).ToList();

    // Implement caching strategies for frequently accessed user data
    var userInfo = userInfoCache.Get(accessToken) as UserInfo;
    if (userInfo == null)
    {
        using (var httpClient = new HttpClient())
        {
            httpClient.DefaultRequestHeaders.Authorization = new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", accessToken);
            var userResponse = await httpClient.GetAsync("https://api.example.com/user");
            userResponse.EnsureSuccessStatusCode();
            userInfo = JsonConvert.DeserializeObject<UserInfo>(await userResponse.Content.ReadAsStringAsync());
            userInfoCache.Set(accessToken, userInfo, new MemoryCacheEntryOptions().SetSlidingExpiration(new TimeSpan(0, 1, 0)));
        }
    }

    results.ForEach(r => r["User Information"] = userInfo);

    return results;
}

private byte[] GetAccessToken()
{
    // Implement OAuth2 token storage and management here
}

private static byte[] Decrypt(TripleDESCryptoServiceProvider tripleDes, byte[] cipherText, byte[] iv)
{
    using (var ms = new MemoryStream(cipherText))
    {
        using (var cs = new CryptoStream(ms, tripleDes.CreateDecryptor(), CryptoStreamMode.Read))
        {
            using (var reader = new BinaryReader(cs))
                return reader.ReadBytes((int)ms.Length);
        }
    }
}

private static byte[] ComputeHMACSHA256(HMACSHA256 hash, byte[] message)
{
    using (var ms = new MemoryStream())
    {
        hash.ComputeHash(message, 0, message.Length, ms, null);
        return ms.ToArray();
    }
}

private static string ComputedBase64String(byte[] data) => Convert.ToBase64String(data);
