using System;
using System.Collections.Generic;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using UnityEngine;

public class FileHashAndRandomGenerator
{
    private string _filePath;
    private long _minValue;
    private long _maxValue;
    private SHA256 _hashAlgorithm;
    private Dictionary<string, byte[]> _hashedLines;
    private Dictionary<ulong, float> _cachedRandFloats;
    private Dictionary<ulong, int> _cachedRandInts;

    public FileHashAndRandomGenerator(string filePath, long minValue, long maxValue)
    {
        _filePath = filePath;
        _minValue = Math.Min(minValue, maxValue);
        _maxValue = Math.Max(minValue, maxValue);
        _hashedLines = new Dictionary<string, byte[]>();
        _cachedRandFloats = new Dictionary<ulong, float>();
        _cachedRandInts = new Dictionary<ulong, int>();
        _hashAlgorithm = SHA256.Create();
    }

    public IEnumerable<KeyValuePair<string, byte[]>> GetHashedLines()
    {
        FileStream fileStream;
        StreamReader streamReader;
        try
        {
            fileStream = new FileStream(_filePath, FileMode.Open, FileAccess.Read, FileShare.ReadWrite);
            streamReader = new StreamReader(fileStream);

            string line;
            while ((line = streamReader.ReadLine()) != null)
            {
                byte[] hashBytes = _hashAlgorithm.ComputeHash(Encoding.UTF8.GetBytes(line));
                _hashedLines[line] = hashBytes;
                yield return new KeyValuePair<string, byte[]>(line, hashBytes);
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error reading file: {ex.Message}");
        }
    }

    public float GetRandomFloat(bool inclusiveMin = true, bool inclusiveMax = true)
    {
        ulong key = (_minValue + _maxValue - 1) * (_maxValue - _minValue) + (_inclusiveMin ? 0 : 1) * (_inclusiveMax ? 0 : 1);
        if (_cachedRandFloats.TryGetValue(key, out float cached)) return cached;

        float randFloat = UnityEngine.Random.Range(_minValue / (float)_maxValue, _maxValue / (float)_minValue);
        _cachedRandFloats[key] = randFloat;
        return randFloat;
    }

    public int GetRandomInt(bool inclusiveMin = true, bool inclusiveMax = true)
    {
        ulong key = (_minValue + _maxValue - 1) * (_maxValue - _minValue) + (_inclusiveMin ? 0 : 1) * (_inclusiveMax ? 0 : 1);
        if (_cachedRandInts.TryGetValue(key, out int cached)) return cached;

