using System;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Text;
using Microsoft.Extensions.Configuration;

namespace DecryptionService
{
    public class Decrypter
    {
        private readonly IConfiguration _configuration;
        private readonly ICryptoProvider _cryptoProvider;

        public Decrypter(IConfiguration configuration, ICryptoProvider cryptoProvider)
        {
            _configuration = configuration;
            _cryptoProvider = cryptoProvider;
        }

        public string Decrypt(string cipherText, bool useVaultService)
        {
            var keySource = useVaultService ? _configuration["AesKeyVaultUri"] : _configuration["AesEnvironmentVariableName"];
            var ivSource = useVaultService ? _configuration["IvVaultUri"] : _configuration["IvEnvironmentVariableName"];

            var key = GetEncryptionKey(keySource);
            var iv = GetInitializationVector(ivSource);

            byte[] decryptedData;

            try
            {
                using (var aes = Aes.Create())
                {
                    aes.Key = key;
                    aes.IV = iv;

                    var macTagProvider = useVaultService ? _configuration["MacTagVaultUri"] : _configuration["MacTagEnvironmentVariableName"];

                    var hmac = new HMACSHA256(key);
                    var computedMacTag = hmac.ComputeHash(Encoding.UTF8.GetBytes(cipherText));

                    var combinedDataAndTag = Encoding.UTF8.GetBytes(cipherText + computedMacTag.ToHexString());
                    var tagOnly = combinedDataAndTag.TakeLast(32).ToArray();

                    if (IsInvalidPadding(combinedDataAndTag) || !Array.Equals(tagOnly, GetTagFromSource(macTagProvider)))
                        throw new InvalidOperationException("MAC verification failed or invalid padding detected.");

                    using (var decryptor = aes.CreateDecryptor())
                    {
                        var cryptoTransform = new CryptoStream(new MemoryStream(Convert.FromBase64String(cipherText)), decryptor, CryptoStreamMode.Read);
                        decryptedData = new byte[cryptoTransform.ReadAllBytes()];
                    }
                }
            }
            catch (Exception ex)
            {
                // Handle potential issues with network latency and service unavailability here.
                throw new AggregateException("Error decrypting data.", ex);
            }

            return Encoding.UTF8.GetString(decryptedData);
        }

        private byte[] GetEncryptionKey(string source) => _cryptoProvider.GetKeyFromSource(source);
        private byte[] GetInitializationVector(string source) => _cryptoProvider.GetIVFromSource(source);
        private string GetTagFromSource(string source) => _cryptoProvider.GetMacTagFromSource(source);

        private static bool IsInvalidPadding(byte[] buffer)
        {
            // Implement a mechanism to detect invalid padding without leaking information through exceptions.
            if (buffer.Length < 16 || (buffer.Length % 16 != 0)) return true;

            var lastByte = buffer[^1];
            for (int i = buffer.Length - 2; i >= 0; i -= 16)
            {
                if (buffer[i] != lastByte) return false;
            }

            return true;
        }
    }
}
```

