    {
        private readonly ConcurrentDictionary<string, Func<Stream, object>> _deserializers = new ConcurrentDictionary<string, Func<Stream, object>>();
        private readonly RateLimiter _rateLimiter;
        private readonly ILogger _logger;

        public FileProcessor(ILogger logger, int maxConcurrentTasks, double requestsPerSecond)
        {
            _logger = logger;
            _rateLimiter = new RateLimiter(maxConcurrentTasks, requestsPerSecond);

            // Register deserializers based on file extensions
            _deserializers[".bin"] = LoadFromBin;
            _deserializers[".zip"] = ExtractAndLoadZip;
            _deserializers[".gz"] = DecompressGzAndLoad;
        }

        public async Task ProcessDirectoryAsync(string directoryPath, Action<ProcessedFileInfo> onProcessed)
        {
            await Task.Run(() =>
            {
                foreach (var file in Directory.EnumerateFiles(directoryPath, "*.*", SearchOption.AllDirectories))
                {
                    if (_rateLimiter.ShouldProcess())
                    {
                        _ = ProcessFileAsync(file, onProcessed);
                    }
                }
            });
        }

        private async Task ProcessFileAsync(string filePath, Action<ProcessedFileInfo> onProcessed)
        {
            try
            {
                using (var fileStream = File.OpenRead(filePath))
                {
                    var extension = Path.GetExtension(filePath).ToLower();

                    if (_deserializers.TryGetValue(extension, out var deserializeFunc))
                    {
                        var data = await Task.Run(() => deserializeFunc(fileStream));

                        ChecksumValidation(data);

                        onProcessed?.Invoke(new ProcessedFileInfo
                        {
                            FilePath = filePath,
                            CompressionMethod = extension switch { ".zip" | ".gz" => "Compressed", _ => "None" },
                            Size = fileStream.Length,
                            Data = data
                        });
                    }
                }
            }
            catch (Exception ex)
            {
                _logger.Error($"Error processing file: {filePath}. Error details: {ex}");
            }
        }

        private object LoadFromBin(Stream stream) => // Deserialize binary data here

        private object ExtractAndLoadZip(Stream stream)
        {
            using (var archive = new Archive(stream))
            {
                var extractedFiles = archive.ExtractToDirectory(@"temp_zip");

                foreach (var file in extractedFiles)
                {
                    if (Path.GetExtension(file).ToLower() == ".bin")
                    {
                        using (var stream2 = File.OpenRead(file))
                        {
                            return LoadFromBin(stream2);
                        }
                    }
                }

                throw new InvalidDataException($"No .bin file found in extracted ZIP archive: {Path.GetFileName(archive.FileName)}");
            }
        }

        private object DecompressGzAndLoad(Stream stream)
        {
            using (var decompressionStream = new GZipInputStream(stream))
            {
                return LoadFromBin(decompressionStream);
            }
        }

        private void ChecksumValidation(object data) => // Validate checksum here and log any errors

        public class ProcessedFileInfo
        {
            public string FilePath { get; set; }
            public string CompressionMethod { get; set; }
            public long Size { get; set; }
            public object Data { get; set; }
        }
    }
}
