        return NULL;
    }

    pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
    int log_enabled = 1; // Set to 0 to disable logging

    for (size_t i = 0; i < num_records + 1; ++i) {
        offsets[i] = min_offset + i;
    }

