    for (size_t i = 0; i < num_records; ++i) {
        int key = rand() % (max_key - min_key + 1) + min_key;
        pthread_mutex_lock(&log_mutex);
        if (log_enabled) printf("Key: %d\n", key);
        pthread_mutex_unlock(&log_mutex);

        keys[i] = key;
        Record *current_record = &records[i];
        current_record->value = rand() % (max_key - min_key + 1) + min_key;
        for (size_t j = 0; j < 16; ++j) {
            current_record->str[j] = rand() % 128; // Use rand() % 128 to get ASCII characters
        }
        current_record->small_int = rand() % (small_max - small_min + 1) + small_min;
    }

    // Handle partial data availability if needed

    long total_memory = (num_records * record_size) + (num_records * sizeof(int)) + ((num_records + 1) * sizeof(long));
    if (total_memory > predefined_limit) {
        fprintf(stderr, "Memory usage exceeded the predefined limit\n");
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    pthread_mutex_destroy(&log_mutex);
    return records;
}
