    public string ErrorMessage { get; set; }
}

public class DirectoryManager
{
    private readonly ConcurrentDictionary<string, object> _websites = new ConcurrentDictionary<string, object>();
    private readonly object _lock = new object();

    public async Task<WebsiteRegistrationResult> RegisterWebsiteInDirectory(string directoryPath)
    {
        if (!Directory.Exists(directoryPath))
            return new WebsiteRegistrationResult { Success = false, ErrorMessage = "Invalid directory path." };

        var websiteDirs = Directory.EnumerateDirectories(directoryPath).Where(d => d.Contains("website"));

        if (!websiteDirs.Any())
            return new WebsiteRegistrationResult { Success = false, ErrorMessage = "No valid website directory found." };

        var websiteDirectory = websiteDirs.First();
        var webConfigPath = Path.Combine(websiteDirectory, "web.config");
        var serverXmlPath = Path.Combine(websiteDirectory, "server.xml");

        if (!File.Exists(webConfigPath) || !File.Exists(serverXmlPath))
            return new WebsiteRegistrationResult { Success = false, ErrorMessage = "Missing required configuration files." };

        lock (_lock)
        {
            if (_websites.ContainsKey(websiteDirectory))
                return new WebsiteRegistrationResult { Success = false, ErrorMessage = "Duplicate website directory found." };

            _websites[websiteDirectory] = null; // Placeholder for future integration with external pipeline
        }

        // Implement data processing pipeline integration here

        return new WebsiteRegistrationResult { Success = true };
    }
}
