#include <cassert>
#include <limits>
#include <numeric>
#include <algorithm>
#include <stdexcept>

constexpr int MAX_INPUT_SIZE = 10_000_000;

class LargeIntReader {
public:
    void reset() {
        data.clear();
    }

    int read(int maxInput) {
        int inputCount = 0;
        int num;

        while (inputCount < maxInput) {
            if (!(std::cin >> num)) {
                std::cerr << "Invalid input format. Please enter an integer or terminate the input." << std::endl;
                return -1;
            }

            if (!std::numeric_limits<int>::has_quiet_NaN(num) && !(num > std::numeric_limits<int>::max() || num < std::numeric_limits<int>::min())) {
                data.push_back(num);
                inputCount++;
            } else {
                std::cerr << "Error: Non-integer value or excessively large number detected." << std::endl;
                return -1;
            }
        }

        if (inputCount == 0) {
            std::cerr << "Empty input provided. Please enter at least one integer." << std::endl;
            return -1;
        }

        std::sort(data.begin(), data.end());
        largest = *std::max_element(data.begin(), data.end());
        return 0;
    }

    int getLargest() const {
        return largest;
    }

private:
    std::vector<int> data;
    int largest = std::numeric_limits<int>::min();
};

int main(int argc, char* argv[]) {
    LargeIntReader reader;

    if (argc > 1) {
        int maxInput = std::atoi(argv[1]);
        if (maxInput <= 0 || maxInput > MAX_INPUT_SIZE) {
            throw std::invalid_argument("Invalid maximum input size. Must be greater than zero and less than or equal to " + std::to_string(MAX_INPUT_SIZE));
        }
        reader.read(maxInput);
    } else {
        reader.read(MAX_INPUT_SIZE);
    }

    if (reader.getLargest() == std::numeric_limits<int>::min()) {
        return 1; // Return error code if an error occurred
    }

    std::cout << "The largest integer is: " << reader.getLargest() << std::endl;
    return 0;
}
```

