struct Transaction {
  uint64_t tid;
};

using SessionId = uint64_t;
using Sessions = std::unordered_map<SessionId, std::vector<Transaction>>;
using Config = std::function<Sessions()>; // Dynamic configuration function

class SessionManager {
 public:
