    mutex mtx;
    atomic<bool> initialized;
};

thread_local std::mt19937 ThreadSafeRandom::generator{std::random_device{}()};
ThreadSafeRandom::ThreadSafeRandom(unsigned long seed)
    : initialized(false) {
    std::unique_lock<mutex> lock(mtx);
    if (!initialized.exchange(true)) {
        generator.seed(seed);
    }
}

ThreadSafeRandom::~ThreadSafeRandom() {}

int ThreadSafeRandom::getRandomNumber() {
    std::unique_lock<mutex> lock(mtx);
    return generator();
}

