typedef struct {
    int value;
    char status;
    char* str;
} record;

typedef struct node {
    record* data;
    struct node* next;
} node;

typedef struct hash_table {
    node** table;
    unsigned long size;
    unsigned long num_entries;
} hash_table;

unsigned long hash(unsigned long key, unsigned long table_size) {
    return key % table_size;
}

void resize_hash_table(hash_table* table) {
    hash_table new_table = {.table = malloc(INITIAL_CAPACITY * sizeof(node*)),
                            .size = INITIAL_CAPACITY,
                            .num_entries = 0};

    for (unsigned long i = 0; i < table->size; ++i) {
        node* current = table->table[i];
        while (current != NULL) {
            record* data = current->data;
            unsigned long hash_key = hash(data->value, new_table.size);

            node** slot = &new_table.table[hash_key];
            node* temp = *slot;
            *slot = malloc(sizeof(node));
            (*slot)->data = data;
            (*slot)->next = temp;

            ++new_table.num_entries;
            current = current->next;
        }
    }
    table->size *= 2;
    table->table = realloc(table->table, table->size * sizeof(node*));
}

