    pthread_mutex_lock(&db.lock);
    record->offset = db.offsets[db.length];
    db.keys[db.length] = record->key;
    db.offsets[db.length] = record->offset + sizeof(Record);
    memcpy((void *)&db.records[record->offset], (const void *)record, sizeof(Record));
    randomize_record(&db.records[record->offset], 0, INT_MAX / 2);
    db.length++;
    pthread_mutex_unlock(&db.lock);
    return 0;
}

