    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;
    node->data = data;
    node->next = NULL;
    return node;
}

void insert_node(Node** head, Node* new_node) {
    if (*head == NULL) {
        *head = new_node;
    } else {
        Node* temp = *head;
        while (temp->next != NULL) temp = temp->next;
        temp->next = new_node;
    }
}

Record read_integer() {
    Record data;
    scanf("%d", &data.value);
    return data;
}

int find_empty_key(int* keys, int size) {
    for (int i = 0; i < size; ++i) {
        if (!keys[i]) return i;
    }
    return -1;
}

// Main function
Record* create_record(void) {
    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) return NULL;
    record->value = rand() % 100 + 1;
    record->status = 'N';
    record->string = malloc(sizeof(char) * 256);
    if (!record->string) {
        free(record);
        return NULL;
    }
    strcpy(record->string, "");
    return record;
}

void validate_and_store(Node** records, int* offsets, char* keys, int* size) {
    Record data = read_integer();

    if (data.value < 1 || data.value > 100) return;

    int key_index = find_empty_key(keys, *size);
    if (key_index == -1) {
        // Handle memory allocation failure gracefully
        if ((*size + 1) * sizeof(int) >= 1 << 30) return;
        keys = realloc(keys, (*size + 1) * sizeof(int));
        offsets = realloc(offsets, (*size + 1) * sizeof(int));
    }
    keys[*size] = data.value;
    offsets[*size] = *records ? offsets[*size - 1] + 1 : 0;
    insert_node(records, create_node({data, 'N', NULL}));
    (*size)++;
}

void find_largest(Node* records, int size) {
    Record* largest = records->next;
    for (int i = 1; i < size; ++i) {
        if (records->next[i].value > largest->value)
            largest = &records->next[i];
    }
    printf("Largest integer: %d\n", largest->value);
}

