```cpp
#include <iostream>
#include <random>
#include <string>
#include <unordered_map>
#include <vector>
#include <atomic>
#include <thread>
#include <mutex>

struct Record {
    int value;
    std::atomic<char> statusFlag; // Atomic for thread safety
    std::string data;
};

class DynamicList {
public:
    explicit DynamicList(size_t initialCapacity) : records_(initialCapacity), keys_(initialCapacity), offsets_(initialCapacity + 1) {}

    void processInput() {
        int value;
        while (std::cin >> value) {
            insertRecord(value);
        }
    }

    void insertRecord(int value) {
        std::unique_lock<std::mutex> lock(mtx_);
        auto it = hash_.find(value);
        if (it != hash_.end()) {
            ++it->second.statusFlag; // Mark as used
            lock.unlock();
            continue;
        }

        Record newRecord{ value, std::atomic<char>(1), "" }; // Create new record with initial values

        lock.unlock();
        auto insertedIndex = findEmptySlot(offsets_);
        offsets_[insertedIndex] = records_.size();
        keys_[insertedIndex] = value;
        records_.emplace_back(newRecord);
        hash_[value] = &records_.back(); // Insert into hash table using pointer to new record
    }

private:
    size_t findEmptySlot(std::vector<long>& slots) {
        for (size_t i = 0; i < slots.size(); ++i) {
            if (!slots[i]) {
                return i;
            }
        }
        // If no empty slot found, dynamically resize offsets and repeat the search
        auto newSize = static_cast<long>(slots.size()) * 2 + 1;
        slots.resize(newSize);
        return findEmptySlot(slots);
    }

    std::vector<Record> records_; // The dynamic record array
    std::unordered_map<int, Record*> hash_; // Custom hash table for efficient lookups and deletions
    std::vector<long> offsets_; // Offset array to maintain contiguousness of data in the dynamic record array
    std::mutex mtx_; // Mutex for synchronizing access to the data structures during concurrent operations
};
```

