char* trimWhitespace(const char *str) {
    size_t length = strlen(str);
    char *result = malloc(length);
    size_t destIndex = 0;

    for (size_t i = 0; i < length; ++i) {
        if (isspace(str[i])) continue;

        result[destIndex++] = str[i];
    }

    result[destIndex] = '\0';
    return result;
}

char* appendSuffix(const char *str, const char *suffix) {
    size_t strLen = strlen(str);
    size_t suffixLen = strlen(suffix);
    char *result = malloc(strLen + suffixLen + 1);

    if (strLen + suffixLen > config->max_size_limit) return NULL;

    memcpy(result, str, strLen);
    memcpy(result + strLen, suffix, suffixLen + 1);

    return result;
}
```

JavaScript Function (collectMatchingElements):

```javascript
function collectMatchingElements(selector, callback) {
    let nodes = document.querySelectorAll(selector);
    let queue = [];

    function traverse(node) {
        if (!node || node.nodeType !== Node.ELEMENT_NODE) return;

        if (callback(node)) queue.push(node);

        Array.from(node.children).forEach(traverse);
    }

    nodes.forEach(traverse);

    return queue;
}
```"]

