[' Here's a skeleton implementation in C using a dynamic array (linked list) with reallocation and compacting mechanisms, thread safety, and memory management. The code does not include the generation of random int values, as it was not specified how to do so.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct record {
    long offset;
    int key;
    int value;
} Record;

typedef struct record_set {
    Record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} RecordSet;

// Generate a new random record with given key and initial value 0.
Record generate_record(int key) {
    Record record = { .key = key };
    return record;
}

// Helper function to find the next empty slot in the dynamic array.
size_t find_empty_slot(RecordSet* set) {
    for (size_t i = 0; i < set->capacity; ++i) {
        if (!set->records[i].key) return i;
    }

    // If no empty slots found, grow the array.
    size_t new_cap = set->capacity * 2;
    Record* new_array = realloc(set->records, new_cap * sizeof(Record));
    if (!new_array) {
        fprintf(stderr, "Failed to allocate memory for dynamic array.\n");
        exit(EXIT_FAILURE);
    }

    set->records = new_array;
    set->capacity = new_cap;
    return find_empty_slot(set);
}

// Helper function to move elements from the end of the array to fill empty slots.
void move_to_empty_slots(RecordSet* set) {
    size_t start = set->size - 1;
    for (size_t i = start; i > 0; --i) {
        if (set->records[i].key && set->records[i - 1].key == 0) {
            Record tmp = set->records[i];
            set->records[i] = set->records[i - 1];
            set->records[i - 1] = tmp;
        }
    }
}

// Function to add a new record with the given key and value.
void add_record(RecordSet* set, int key, int value) {
    pthread_mutex_lock(&set->lock);

    Record record = generate_record(key);
    record.value = value;

    size_t slot = find_empty_slot(set);
    if (slot < set->size) move_to_empty_slots(set); // Compact the array if necessary.

    set->records[slot] = record;
    set->size++;

    // Check if memory usage exceeds 75%. If so, compact the storage.
    if (static_cast<float>(set->size) / static_cast<float>(set->capacity) > 0.75f) {
        size_t new_cap = set->capacity / 2;
        Record* new_array = realloc(set->records, new_cap * sizeof(Record));
        if (!new_array) {
            fprintf(stderr, "Failed to allocate memory for compacting.\n");
            exit(EXIT_FAILURE);
        }

        set->records = new_array;
        set->capacity = new_cap;
    }

    pthread_mutex_unlock(&set->lock);
}

// Function to update an existing record with the given key and value.
void update_record(RecordSet* set, int key, int value) {
    pthread_mutex_lock(&set->lock);

    for (size_t i = 0; i < set->size; ++i) {
        if (set->records[i].key == key) {
            set->records[i].value = value;
            break;
        }
    }

    pthread_mutex_unlock(&set->lock);
}

// Function to find a record by its key and return its value if found.
int get_record(const RecordSet* set, int key) {
    pthread_mutex_lock(&set->lock);

    for (size_t i = 0; i < set->size; ++i) {
        if (set->records[i].key == key) {
            pthread_mutex_unlock(&set->lock);
            return set->records[i].value;
        }
    }

    pthread_mutex_unlock(&set->lock);
    return -1; // Return an error code or throw an exception if not found.
}
```

