        fprintf(stderr, "Invalid array size: %d\n", N);
        return;
    }

    pthread_mutex_lock(&mutex);

    if (array_size > 0 && data != NULL) {
        free(data);
        num_deallocations++;
    }

    array_size = N;
    data = calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (data == NULL) {
        fprintf(stderr, "Memory allocation failure\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    num_allocations++;

    for (int i = 0; i < array_size; ++i) {
        data[i].RX_UE_INFORMATION_TAG = i;
        data[i].RNTI = i * 10 + getpid();
        data[i].CRC_INDICATION_REL8_TAG[3] = rand() & 0x0F; // Set CRCFLAG bit
    }

    pthread_mutex_unlock(&mutex);
}

void free_data_array() {
    if (array_size <= 0 || data == NULL) {
        return;
    }

    pthread_mutex_lock(&mutex);

    num_deallocations++;

    free(data);
    array_size = 0;
    data = NULL;

    pthread_mutex_unlock(&mutex);
}
```

