static inline record *find_record(const record_set *rs, int key) {
    for (size_t i = 0; i < rs->num_records; ++i) {
        if (rs->records[i].key == key) return &rs->records[i];
    }
    return NULL;
}

static void resize(record_set *rs, size_t new_capacity) {
    record *new_records = realloc(rs->records, new_capacity * sizeof(record));
    if (!new_records) {
        perror("reallocation failed");
        return;
    }
    rs->capacity = new_capacity;
    rs->records = new_records;
}

static void compact(record_set *rs) {
    size_t free_slots = rs->capacity - rs->num_records;
    if (free_slots < rs->capacity / 4) resize(rs, 2 * rs->capacity);
    memmove(rs->records, rs->records + rs->num_records, free_slots * sizeof(record));
}

static void log(const char *message, ...) {
