void record_set_init(record_set *rs, size_t capacity, void (*serialize)(const struct record_set *, FILE*), void (*deserialize)(struct record_set*, FILE*)) {
    rs->capacity = capacity;
    rs->num_records = 0;
    rs->records = mmap(NULL, capacity * sizeof(record), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0);
    if (rs->records == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }
    rs->lock = PTHREAD_MUTEX_INITIALIZER;
    rs->serialize = serialize;
    rs->deserialize = deserialize;
}

void record_set_destroy(record_set *rs) {
    if (rs->records) munmap(rs->records, rs->capacity * sizeof(record));
}

int record_set_add(record_set *rs, int key) {
    pthread_mutex_lock(&rs->lock);
    record *found = find_record(rs, key);
    if (found) {
        found->value++;
        pthread_mutex_unlock(&rs->lock);
        return found->value;
    }

    if (rs->num_records >= rs->capacity * 0.75) compact(rs);
    record *new_record = &rs->records[rs->num_records++];
    new_record->key = key;
    new_record->value = 1 + rand() % (RAND_MAX / 2); // Random value within range [1, RAND_MAX/2]
    pthread_mutex_unlock(&rs->lock);
    return new_record->value;
}

int record_set_get(const record_set *rs, int key) {
    if (find_record(rs, key)) return find_record(rs, key)->value;
    return -1;
}
