#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct Record {
    int value;
} Record;

struct MemoryManager {
    size_t offsetCount;
    long *offsets;
    size_t keyCount;
    int *keys;
    size_t recordCount;
    Record **records;
    size_t maxOffsets;
    size_t maxKeys;
    size_t maxRecords;
    pthread_mutex_t lock;
    size_t loggingInterval;
};

void log_memory(struct MemoryManager *manager) {
    printf("Memory Usage:\n");
    printf("\toffsets: %zu bytes\n", sizeof(*manager->offsets) * manager->offsetCount);
    printf("\tkeys: %zu bytes\n", sizeof(*manager->keys) * manager->keyCount);
    printf("\trecords: %zu bytes\n", sizeof(**manager->records) * manager->recordCount);
}

void* reallocate(void **ptr, size_t currentSize, size_t newSize) {
    void *newPtr = realloc(*ptr, newSize);
    if (!newPtr) {
        perror("Reallocation failed");
        exit(EXIT_FAILURE);
    }
    return newPtr;
}

struct MemoryManager* create_memory_manager(size_t offsetLimit, size_t keyLimit, size_t recordLimit, size_t loggingInterval) {
    struct MemoryManager *manager = malloc(sizeof(*manager));
    if (!manager) {
        perror("Memory allocation for manager failed");
        exit(EXIT_FAILURE);
    }

    manager->offsetCount = 0;
    manager->keyCount = 0;
    manager->recordCount = 0;
    manager->maxOffsets = offsetLimit;
    manager->maxKeys = keyLimit;
    manager->maxRecords = recordLimit;
    manager->loggingInterval = loggingInterval;

    manager->offsets = malloc(sizeof(*manager->offsets) * offsetLimit);
    if (!manager->offsets) {
        perror("Memory allocation for offsets failed");
        exit(EXIT_FAILURE);
    }

    manager->keys = malloc(sizeof(*manager->keys) * keyLimit);
    if (!manager->keys) {
        perror("Memory allocation for keys failed");
        exit(EXIT_FAILURE);
    }

    manager->records = malloc(sizeof(Record*) * recordLimit);
    if (!manager->records) {
        perror("Memory allocation for records failed");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_memory_manager(struct MemoryManager *manager) {
    free(manager->offsets);
    free(manager->keys);
    for (size_t i = 0; i < manager->recordCount; ++i) {
        free(manager->records[i]);
    }
    free(manager->records);
    free(manager);
}

void update_offset(struct MemoryManager *manager, long offset) {
    pthread_mutex_lock(&manager->lock);

    if (manager->offsetCount >= manager->maxOffsets) {
        log_memory(manager);
        printf("Offset limit exceeded\n");
    } else {
        manager->offsets[manager->offsetCount++] = offset;
    }

    pthread_mutex_unlock(&manager->lock);
}

void update_key(struct MemoryManager *manager, size_t key) {
    pthread_mutex_lock(&manager->lock);

    if (manager->keyCount >= manager->maxKeys) {
        log_memory(manager);
        printf("Key limit exceeded\n");
    } else {
        manager->keys[manager->keyCount++] = key;
    }

    pthread_mutex_unlock(&manager->lock);
}

void update_record(struct MemoryManager *manager, size_t key, int value) {
    size_t index = find_index_for_key(manager, key);
    if (index == SIZE_MAX) {
        log_memory(manager);
        printf("No record found for key %zu\n", key);
    } else {
        pthread_mutex_lock(&manager->lock);

        Record *record = manager->records[index];
        if (!record) {
            // Resize records array and allocate new memory for the record
            resize_and_allocate(manager, recordCount + 1);
            record = &manager->records[index];
        }
        record->value = value;

        pthread_mutex_unlock(&manager->lock);
    }
}

size_t find_index_for_key(struct MemoryManager *manager, size_t key) {
    for (size_t i = 0; i < manager->keyCount; ++i) {
        if (manager->keys[i] == key) {
            return i;
        }
    }

    return SIZE_MAX;
}

void resize_and_allocate(struct MemoryManager *manager, size_t newSize) {
    void **ptr = manager->records;
    size_t currentSize = manager->recordCount;
    manager->records = reallocate(&manager->records, currentSize * sizeof(*manager->records), (newSize + 1) * sizeof(*manager->records));
    for (size_t i = currentSize; i < newSize; ++i) {
        ptr[i] = malloc(sizeof(Record));
    }
}
```

