['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct Transaction {
    int id;
    double amount;
    time_t timestamp;
};

struct TransactionNode {
    struct Transaction transaction;
    struct TransactionNode* next;
};

struct TransactionList {
    struct TransactionNode* head;
    struct TransactionNode* tail;
    size_t count;
    pthread_mutex_t lock;
};

// Initialize transaction list
void initTransactionList(struct TransactionList* list) {
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

// Allocate and initialize a new transaction node
struct TransactionNode* createTransactionNode(const struct Transaction* transaction) {
    struct TransactionNode* node = (struct TransactionNode*)malloc(sizeof(struct TransactionNode));
    if (!node) {
        perror("Failed to allocate memory for transaction node");
        exit(1);
    }
    node->transaction = *transaction;
    node->next = NULL;
    return node;
}

// Add a transaction to the list, locked
void addTransaction(struct TransactionList* list, const struct Transaction* transaction) {
    pthread_mutex_lock(&list->lock);
    struct TransactionNode* newNode = createTransactionNode(transaction);
    if (list->head == NULL) {
        list->head = newNode;
        list->tail = newNode;
    } else {
        list->tail->next = newNode;
        list->tail = newNode;
    }
    ++list->count;
    pthread_mutex_unlock(&list->lock);
}

// Update a transaction by ID, locked
void updateTransaction(struct TransactionList* list, int id, const struct Transaction* newTransaction) {
    pthread_mutex_lock(&list->lock);
    struct TransactionNode* current = list->head;
    while (current != NULL) {
        if (current->transaction.id == id) {
            current->transaction = *newTransaction;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

// Calculate the total transaction amount within a date range, locked
double calculateTotalAmount(const struct TransactionList* list, time_t start, time_t end) {
    double total = 0.0;
    pthread_mutex_lock(&list->lock);
    struct TransactionNode* current = list->head;
    while (current != NULL) {
        if (current->transaction.timestamp >= start && current->transaction.timestamp <= end) {
            total += current->transaction.amount;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return total;
}

// Free memory for a transaction node and the entire list, locked
void freeTransactionList(struct TransactionList* list) {
    pthread_mutex_lock(&list->lock);
    struct TransactionNode* current = list->head;
    struct TransactionNode* next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    pthread_mutex_destroy(&list->lock);
}
```

