#include <time.h>

typedef struct Record {
    int value;
    char status;
    char* str;
} Record;

typedef struct Node {
    Record data;
    struct Node* next;
} Node;

typedef struct HashTable {
    unsigned long capacity;
    unsigned long size;
    Node** table;
} HashTable;

void initHashTable(HashTable* ht, unsigned long capacity) {
    ht->capacity = capacity;
    ht->size = 0;
    ht->table = calloc(capacity, sizeof(Node*));
}

unsigned long hashFunction(const char* key, unsigned long capacity) {
    unsigned long hash = 5381;
    int c;

    while ((c = *key++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

    return hash % capacity;
}

void resizeHashTable(HashTable* ht, unsigned long newCapacity) {
    // Implement resizing here (not shown in this example)
}

Node* createNode(Record data) {
    Node* node = malloc(sizeof(Node));
    if (!node) {
        fprintf(stderr, "Out of memory!\n");
        exit(EXIT_FAILURE);
    }
    node->data = data;
    node->next = NULL;
    return node;
}

Record* createRecord() {
    Record* record = malloc(sizeof(Record));
    if (!record) {
        fprintf(stderr, "Out of memory!\n");
        exit(EXIT_FAILURE);
    }
    record->value = rand() % 100; // Adjust range as needed
    record->status = 'A'; // Set status flag
    record->str = strdup(""); // Initialize string pointer
    return record;
}

void insertRecord(HashTable* ht, Record* record) {
    Node** slot = &ht->table[hashFunction(record->str, ht->capacity)];
    Node* newNode = createNode(*record);

    if (!*slot) {
        *slot = newNode;
    } else {
        Node* current = *slot;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }
}

Record* searchRecord(HashTable* ht, const char* key) {
    Node** slot = &ht->table[hashFunction(key, ht->capacity)];
    Node* current = *slot;

    while (current != NULL) {
        if (strcmp(current->data.str, key) == 0) {
            return &current->data;
        }
        current = current->next;
    }

    return NULL;
}

void removeRecord(HashTable* ht, const char* key) {
    Node** slot = &ht->table[hashFunction(key, ht->capacity)];
    Node* current = *slot;
    Node** previous = slot;

    while (current != NULL) {
        if (strcmp(current->data.str, key) == 0) {
            if (*previous == current) {
                *previous = current->next;
            } else {
                *previous->next = current->next;
            }
            free(current->str);
            free(current);
            break;
        }
        previous = &current->next;
        current = current->next;
    }
}

void processInput() {
    // Implement input processing here (not shown in this example)
}
```

