#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <string.h>
#include <zlib.h>

typedef struct {
    int key;
    int value;
    char status;
    gzFile compressed_str; // zlib-compressed string
    float timestamp;
    struct Node *prev, *next;
} Record;

typedef struct {
    long offset[1024];
    Record* records;
    size_t capacity;
    size_t length;
    pthread_mutex_t mutex;
} DataStructure;

void init(DataStructure *ds, size_t capacity) {
    ds->records = malloc(capacity * sizeof(Record));
    ds->capacity = capacity;
    ds->length = 0;
    pthread_mutex_init(&ds->mutex, NULL);
}

void destroy(DataStructure *ds) {
    for (size_t i = 0; i < ds->length; ++i) gzclose(ds->records[i].compressed_str);
    free(ds->records);
    pthread_mutex_destroy(&ds->mutex);
}

void compress(char *src, char **dest) {
    gzFile dest_file = gzopen("temp.gz", "wb");
    gzip(dest_file, Z_DEFLATED, 9);
    gzprintf(dest_file, "%s", src);
    gzclose(dest_file);
    *dest = malloc((1 + gzeof(dest_file)) * sizeof(char));
    fseek(gzopen("temp.gz", "rb"), 0L, SEEK_SET);
    fread(*dest, sizeof(char), 1 + gzeof(dest_file), gzopen("temp.gz", "rb"));
}

void decompress(char *src, char **dest) {
    gzFile src_file = gzopen(src, "rb");
    *dest = malloc((1 + gzinflate(src_file, 0, NULL, Z_FINISH) - 4) * sizeof(char));
    gzread(src_file, *dest, 1 + gzinflate(src_file, 0, NULL, Z_FINISH) - 4);
}

