// External library interface for CRC computation
typedef uint32_t (*crc_compute)(const uint8_t* data, size_t len);
extern crc_compute my_crc_compute; // Define in another source file

static pthread_mutex_t array_lock = PTHREAD_MUTEX_INITIALIZER;
static size_t peak_memory_usage = 0;
static size_t current_memory_usage = 0;

NFAPI_CRC_INDICATION_PDU_T* create_array(size_t N) {
    if (N <= 0) return NULL;

    // Allocate memory for the array and structs using memory pooling or another efficient method
    NFAPI_CRC_INDICATION_PDU_T *arr = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);
    if (!arr) return NULL;

    pthread_mutex_lock(&array_lock);
    current_memory_usage += sizeof(NFAPI_CRC_INDICATION_PDU_T) * N;
    peak_memory_usage = max(peak_memory_usage, current_memory_usage);
    pthread_mutex_unlock(&array_lock);

    if (N > 0) { // Initialize the first 'N' entries with random CRCFLAG values
        for (size_t i = 0; i < N; ++i) {
            arr[i].CRCFLAG = rand_r(time(NULL) % UINT8_MAX);
            arr[i].RX_UE_INFORMATION_TAG = i;
            arr[i].RNTI = i * 10 + getpid(); // Replace this with your specific initialization logic
            arr[i].CRC_INDICATION_REL8_TAG = my_crc_compute((const uint8_t*)&arr[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
        }
    }

    return arr;
}

void destroy_array(NFAPI_CRC_INDICATION_PDU_T *arr, size_t N) {
    if (!arr || !N) return;

    pthread_mutex_lock(&array_lock);
    current_memory_usage -= sizeof(NFAPI_CRC_INDICATION_PDU_T) * N;
    pthread_mutex_unlock(&array_lock);

    free(arr);
}
