#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

typedef struct Record {
    int value;
    char status;
    char* string;
} Record;

typedef struct Node {
    Record data;
    struct Node* next;
} Node;

struct HashTable {
    unsigned int size;
    Node** table;
};

void initHashTable(struct HashTable* hashTable, unsigned int size) {
    hashTable->size = size;
    hashTable->table = calloc(size, sizeof(Node*));
}

unsigned int hashFunction(int key, unsigned int size) {
    return key % size;
}

void insertRecord(struct HashTable* hashTable, Record data) {
    unsigned int index = hashFunction(data.value, hashTable->size);
    Node* node = malloc(sizeof(Node));
    memcpy(&node->data, &data, sizeof(Record));
    node->next = hashTable->table[index];
    hashTable->table[index] = node;
}

Record* findRecord(struct HashTable* hashTable, int key) {
    unsigned int index = hashFunction(key, hashTable->size);
    Node* current = hashTable->table[index];

    while (current != NULL) {
        if (current->data.value == key)
            return &current->data;
        current = current->next;
    }

    return NULL;
}

void deleteRecord(struct HashTable* hashTable, int key) {
    Record* recordToDelete = findRecord(hashTable, key);
    if (recordToDelete != NULL) {
        unsigned int index = hashFunction(key, hashTable->size);
        Node** current = &hashTable->table[index];

        while (*current != NULL && ((*current)->data.value == key)) {
            Node* temp = *current;
            *current = temp->next;
