// Function to concatenate a variable number of strings using locale-specific delimiters
char* concat_strings(const char * const *strings, size_t count) {
    if (count == 0 || !strings) return NULL;

    // Calculate total length and allocate memory
    size_t len = 0;
    for (size_t i = 0; i < count; ++i) len += strlen(strings[i]);
    if (len > 1024) return NULL;
    char *result = malloc(len + count * sizeof(char));
    if (!result) return NULL;

    // Concatenate strings and null-terminate result
    size_t pos = 0;
    for (size_t i = 0; i < count; ++i) {
        strcpy(&result[pos], strings[i]);
        pos += strlen(strings[i]) + 1;
    }
    result[pos] = '\0';

    return result;
}

// Function to compute MD5 hash of a given string
uint8_t* md5(const char *str) {
    // Initialize MD5 context and digest
    const unsigned int digestSize = 16;
    unsigned char digest[digestSize];
    MD5_CTX ctx;
    MD5_Init(&ctx);

    // Hash the input string in chunks
    size_t len = strlen(str);
    for (size_t i = 0; i < len; i += BUFSIZ) {
        size_t bufLen = (i + BUFSIZ > len) ? (len - i) : BUFSIZ;
        MD5_Update(&ctx, str + i, bufLen);
    }

    // Finalize the hash and copy it to the output buffer
    MD5_Final(digest, &ctx);
    return digest;
}

// Thread-safe version of free function using pthread_key_t and pthread_getspecific
void tfree(void *ptr) {
    if (ptr) {
        pthread_key_t key;
        if ((key = pthread_self()) == 0) key = pthread_create_key(&key, free);
        pthread_setspecific(key, ptr);
    }
}
