#include <time.h>

// Define record structure
typedef struct Record {
    int key;
    int value;
    long offset;
} Record;

// Function to dynamically allocate and initialize memory for a dataset of records
Record* init_dataset(size_t size, size_t threshold, int min_value, int max_value, long seed) {
    // Initialize random number generator
    srand(seed);

    Record *records = (Record*) malloc(sizeof(Record) * size);
    if (!records) return NULL;

    size_t allocated_size = size;
    size_t current_size = size;

    // Handle dynamic memory allocation
    while (current_size < allocated_size) {
        records = realloc(records, sizeof(Record) * (allocated_size * 2));
        if (!records) {
            free(records);
            return NULL;
        }
        allocated_size *= 2;
    }

    // Initialize the 'value' field with a random integer within the specified range
    for (size_t i = 0; i < current_size; ++i) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
        records[i].key = i;
        records[i].offset = 0;
    }

    // Expose the current size to users of this function
    records->size = current_size;

    // Ensure memory usage remains below the specified threshold
    if (current_size > threshold) {
        free(records + current_size);
        records->size = threshold;
    }

    return records;
}

// Function to free allocated memory for a dataset of records
void free_dataset(Record *records) {
    free(records);
}
```

