void adjustOffsets(long* offsets, size_t n, double factor) {
    if (!factor) return;

    for (size_t i = 0; i < n; ++i)
        offsets[i] *= factor;
}

void initDataStructures(size_t n, size_t m, record** records, long* offsets, int* keys) {
    *records = malloc(n * sizeof(*records));
