    char ids[MAX_ID_LEN][MAX_ID_LEN];
    sensor_data* data;
    int numSensors, samples, duration, limit;
} config;

int initSensorData(config *cfg) {
    int i, j;

    // Validate configuration parameters
    if (cfg->duration <= 0 || cfg->samples <= 0 || cfg->limit <= 0)
        return -1;

    double interval = cfg->duration / cfg->samples;
    time_t timestamp = time(NULL);

    // Allocate memory for temperature readings
    cfg->temperature = (double*) malloc(cfg->samples * sizeof(double));
    if (!cfg->temperature) {
        freeMemory(cfg);
        return -1;
    }

    // Initialize temperature readings with minimal floating-point precision errors
    for (i = 0; i < cfg->samples; ++i) {
        cfg->temperature[i] = MIN_TEMP + (MAX_TEMP - MIN_TEMP) * ((double)i / cfg->samples);
    }

    // Allocate memory for sensor IDs
    cfg->numSensors = 0;
    for (i = 0; i < cfg->limit; ++i) {
        if (!cfg->ids[i][0]) break;

        int isValidID = 1;
        for (j = 0; j < strlen(cfg->ids[i]); ++j) {
            // Add ID validation here
            if (isalpha(cfg->ids[i][j]) || isdigit(cfg->ids[i][j])) continue;
            else {
                isValidID = 0;
                break;
            }
        }

        if (strlen(cfg->ids[i]) > MAX_ID_LEN) {
            isValidID = 0;
        }

        if (isValidID && cfg->numSensors == 0) {
            strcpy(cfg->ids[cfg->numSensors], cfg->ids[i]);
            ++cfg->numSensors;
        } else if (isValidID && cfg->numSensors < cfg->limit) {
            int found = 0;
            for (j = 0; j < cfg->numSensors; ++j) {
                if (!strcmp(cfg->ids[i], cfg->ids[j])) {
                    found = 1;
                    break;
                }
            }

            if (!found) {
                strcpy(cfg->ids[cfg->numSensors], cfg->ids[i]);
                ++cfg->numSensors;
            }
        }
    }

    // Allocate memory for sensor_data structures
    cfg->data = (sensor_data*) malloc(cfg->numSensors * sizeof(sensor_data));
    if (!cfg->data) {
        freeMemory(cfg);
        return -1;
    }

    // Initialize sensor data structures with random temperature values and timestamps
    for (i = 0; i < cfg->numSensors; ++i) {
        sensor_data* sd = &cfg->data[i];
        sd->temperature = &cfg->temperature[(timestamp + ((double)rand() / RAND_MAX) * interval) % cfg->samples];
        sd->timestamp = (int)(timestamp + ((double)rand() / RAND_MAX * interval));
        sd->isValid = rand() > RAND_MAX / 2;
    }

    return 0;
}

void freeMemory(config *cfg) {
    if (cfg->temperature) free(cfg->temperature);
    if (cfg->data) free(cfg->data);
}
