void init_collections(size_t *records, size_t *offsets, size_t *keys, size_t capacity) {
    *records = malloc(capacity * sizeof(Record));
    *offsets = calloc(capacity, sizeof(long));
    *keys = calloc(capacity + 1, sizeof(size_t)); // additional slot for sentinel value
}

void populate_records(size_t capacity, size_t *records, size_t min_int, size_t max_int, size_t min_long, size_t max_long) {
    for (size_t i = 0; i < capacity; ++i) {
        records[i].value = rand() % (max_int - min_int + 1) + min_int;
        records[i].offset = (rand() % (max_long - min_long + 1)) + min_long;
        records[i].key_index = i; // for simplicity, using index as key in this example
    }
}

void sort_records(size_t capacity, size_t *records) {
    qsort(records, capacity, sizeof(Record), compare_ints);
}

int compare_ints(const void *a, const void *b) {
    return (*(const Record *)a).value - (*(const Record *)b).value;
}

void print_record_details(const size_t index, const Record *records) {
    printf("Record %zu: int value=%d, long offset=%ld, key index=%zu\n", index, records[index].value, records[index].offset, records[index].key_index);
}

void cleanup(size_t *records, size_t *offsets, size_t *keys) {
    free(records);
    free(offsets);
    free(keys);
}

// Function to iterate over sorted records and print their details
void print_sorted_records(size_t capacity, size_t *records) {
