// Function to manage the data processing pipeline
void manageData(const std::string &inputFileName, const std::string &outputFileName, int arraySize, int minKey, int maxKey, std::list<std::string> &strings) {
    // Initialize dynamic memory for offset values and record keys
    std::vector<long> offsets;
    std::vector<Record> records(arraySize);

    // Generate random integer keys within the specified range and store them in the records vector
    std::random_device rd;  //Will be used to obtain a seed for the random number generator
    std::mt19937 gen(rd()); //Mersenne Twister pseudo-random number engine
    std::uniform_int_distribution<> dis(minKey, maxKey); //Uniform int distribution between minKey and maxKey (inclusive)

    for (auto &rec : records) {
        rec.key = dis(gen);
        offsets.push_back(records.size());
    }

