// Define struct record and its member function to print itself
typedef struct {
    int value;
    long offset;
    int key;
} Record;

void printRecord(const Record* record) {
    printf("Value: %d, Offset: %ld, Key: %d\n", record->value, record->offset, record->key);
}

// Function to validate user-defined size and return a suitable fallback value if necessary
size_t validateSize(size_t size) {
    if (size < 10 || size > 1000) {
        printf("Invalid input. Using default size of 50 for offsets, keys, and records.\n");
        return 50;
    }
    return size;
}

// Function to generate processRecords
void processRecords(size_t size) {
    // Validate user-defined size and adjust as necessary
    size_t adjustedSize = validateSize(size);

    // Allocate memory for offsets, keys, and records arrays
    long* offsets = malloc(adjustedSize * sizeof(long));
    int* keys = malloc(adjustedSize * sizeof(int));
    Record** records = malloc((adjustedSize / 2) * sizeof(Record*));

    // Initialize random seed for reproducibility and seed the random number generator
    srand(1);

    // Initialize offsets and keys arrays
    for (size_t i = 0; i < adjustedSize; ++i) {
        offsets[i] = i * 2 + 1;
        keys[i] = i;
    }

    // Shuffle the offsets array to ensure no two consecutive elements have the same value
    for (size_t i = adjustedSize - 1; i > 0; --i) {
        size_t j = rand() % (i + 1);
        long temp = offsets[i];
        offsets[i] = offsets[j];
        offsets[j] = temp;
    }

    // Adjust the records array size and initialize its elements
    size_t recordsSize = adjustedSize / 2;
    for (size_t i = 0; i < recordsSize; ++i) {
        records[i] = malloc(sizeof(Record));
        records[i]->value = rand() % 1000 + 1;
        records[i]->offset = offsets[i * 2];
        records[i]->key = keys[i * 2];
    }

    // Shuffle the records array to ensure no two consecutive elements have the same value
    for (size_t i = recordsSize - 1; i > 0; --i) {
        size_t j = rand() % (i + 1);
        Record* temp = records[i];
        records[i] = records[j];
        records[j] = temp;
    }

    // Iterate over the records array and print each record
    for (size_t i = 0; i < recordsSize; ++i) {
        printRecord(records[i]);
    }

    // Free allocated memory before function exit
    free(offsets);
    free(keys);
    for (size_t i = 0; i < recordsSize; ++i) {
        free(records[i]);
    }
    free(records);
}
```

