typedef struct {
    long offset;
    int key;
    int value;
} record;

struct worker_args {
    DIR *dir;
    size_t max_file_size;
    record* records;
    long* offsets;
    int* keys;
    pthread_mutex_t* mutexes;
    int num_workers;
};

void worker(struct worker_args* args) {
    struct dirent *entry;
    while ((entry = readdir(args->dir)) != NULL) {
        if (strchr(entry->d_name, '.') && strlen(entry->d_name) > args->max_file_size) continue;
        // Process file...
    }
}

void process_directory(const char *path, size_t max_file_size, int num_workers, record** records, long** offsets, int** keys, pthread_mutex_t** mutexes) {
    DIR *dir = opendir(path);
    if (!dir) {
        log_error("Failed to open directory: %s", path);
        return;
    }

    struct worker_args args[num_workers];
    for (int i = 0; i < num_workers; ++i) {
        args[i].dir = dir;
        args[i].max_file_size = max_file_size;
        args[i].records = records + i;
        args[i].offsets = offsets + i;
        args[i].keys = keys + i;
        args[i].mutexes = mutexes + i;
    }

    pthread_t threads[num_workers];
    for (int i = 0; i < num_workers; ++i) {
        if (pthread_create(&threads[i], NULL, worker, &args[i])) {
            log_error("Failed to create thread: %s", strerror(errno));
        }
    }

    for (int i = 0; i < num_workers; ++i) {
        if (pthread_join(threads[i], NULL)) {
            log_error("Failed to join thread: %s", strerror(errno));
        }
    }

    closedir(dir);
}

void initialize_arrays(long* offsets, int* keys, record** records, size_t num_elements) {
    for (size_t i = 0; i < num_elements; ++i) {
        offsets[i] = -1;
        keys[i] = -1;
        records[i]->value = rand() % 100 + 1;
    }
}

