['```java
import java.io.File;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.security.MessageDigest;
import java.util.ArrayDeque;
import java.util.ConcurrentLinkedQueue;
import java.util.HashSet;
import java.util.Random;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicLong;
import java.util.zip.Checksum;

import com.google.common.base.Function;
import com.google.common.collect.Lists;
import com.google.common.io.Files;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class FileProcessor {
    private static final Logger LOGGER = LoggerFactory.getLogger(FileProcessor.class);
    private static final int MAX_CONNECTIONS = 10;
    private static final int MIN_CONNECTION_RETRY_DELAY = 500;
    private static final int MAX_CONNECTION_RETRY_DELAY = 3000;
    private static final long BYTE_THRESHOLD = 10485760; // 10MB
    private static final Random RANDOM = new Random();

    public MoSTState processAndLoadStateFromBinaryFiles(String directoryPath) {
        File directory = new File(directoryPath);
        if (!directory.exists() || !directory.isDirectory()) {
            throw new IllegalArgumentException("Invalid directory path: " + directoryPath);
        }

        long[] offsets = null;
        int[] keys = null;
        AtomicLong recordIndex = new AtomicLong(0);

        ExecutorService executor = Executors.newCachedThreadPool();
        ConcurrentLinkedQueue<File> fileQueue = new ConcurrentLinkedQueue<>();
        ArrayDeque<Future<Void>> pendingTasks = new ArrayDeque<>();
        HashSet<String> hashedFiles = new HashSet<>();

        addSubdirectoriesToQueue(fileQueue, directory);

        while (!fileQueue.isEmpty() || !pendingTasks.isEmpty()) {
            File currentFile = fileQueue.poll();
            if (currentFile.isDirectory()) {
                addSubdirectoriesToQueue(fileQueue, currentFile);
            } else {
                pendingTasks.add(executor.submit(() -> processAndLoadRecordFromFile(currentFile, recordIndex, offsets, keys)));
            }
        }

        executor.shutdown();
        try {
            executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
        } catch (InterruptedException e) {
            LOGGER.error("File processing interrupted", e);
            Thread.currentThread().interrupt();
        }

        MoSTState state;
        if (offsets != null && keys != null) {
            state = new MoSTState(offsets, keys, recordIndex.get());
        } else {
            state = null;
        }

        closeExecutedTasks(executor, pendingTasks);

        return state;
    }

    private void addSubdirectoriesToQueue(ConcurrentLinkedQueue<File> queue, File directory) {
        for (File file : directory.listFiles()) {
            if (file != null && file.isDirectory()) {
                queue.add(file);
            }
        }
    }

    private void processAndLoadRecordFromFile(File file, AtomicLong recordIndex, long[] offsets, int[] keys) {
        try {
            if (Files.size(Paths.get(file.getPath())) > BYTE_THRESHOLD) {
                LOGGER.debug("Skipping large file: {}", file.getPath());
                return;
            }

            Checksum checksum = Files.checksum(Paths.get(file.getPath()), MessageDigest.getInstance("MD5"));
            String hashValue = new String(Hex.encode(checksum.getValue()));
            if (hashedFiles.contains(hashValue)) {
                LOGGER.debug("Skipping duplicate file: {}", file.getPath());
                return;
            }
            hashedFiles.add(hashValue);

            ObjectInputStream objectInputStream = null;
            try {
                objectInputStream = new ObjectInputStream(Files.newInputStream(Paths.get(file.getPath())));
                Object readObject = objectInputStream.readObject();
                if (readObject instanceof Record) {
                    Record record = (Record) readObject;
                    int key = Math.abs(RANDOM.nextInt()) % Integer.MAX_VALUE;
                    while (keys != null && keys[keys.length - 1] == key) {
                        key = Math.abs(RANDOM.nextInt()) % Integer.MAX_VALUE;
                    }
                    if (keys == null) {
                        keys = new int[recordIndex.get() + 1];
                    } else {
                        int[] newKeys = new int[keys.length + 1];
                        System.arraycopy(keys, 0, newKeys, 0, keys.length);
                        newKeys[newKeys.length - 1] = key;
                        keys = newKeys;
                    }
                    long offset = file.getAbsoluteFile().getAbsolutePath().length();
                    if (offsets != null) {
                        System.arraycopy(offsets, 0, new long[offsets.length + 1], 0, offsets.length);
                    } else {
                        offsets = new long[recordIndex.get() + 1];
                    }
                    offsets[offsets.length - 1] = offset;
                    recordIndex.incrementAndGet();
                }
            } catch (IOException | ClassNotFoundException e) {
                LOGGER.error("Error processing file: {}", file.getPath(), e);
            } finally {
                if (objectInputStream != null) {
                    try {
                        objectInputStream.close();
                    } catch (IOException ignored) {
                    }
                }
            }
        } catch (Exception e) {
            LOGGER.error("Error while adding subdirectories to queue: {}", file.getPath(), e);
        }
    }

    private void closeExecutedTasks(ExecutorService executor, ArrayDeque<Future<Void>> pendingTasks) {
        List<Future<Void>> completedTasks = Lists.newArrayList(pendingTasks);
        completedTasks.addAll(executor.shutdownNow());
        for (Future<Void> future : completedTasks) {
            try {
                future.get();
            } catch (Exception e) {
                LOGGER.error("Error while closing tasks", e);
            }
        }
    }
}

class Record implements Serializable {
    private static final long serialVersionUID = 1L;
    private int value;

    public Record(int value) {
        this.value = value;
    }

    public int getValue() {
        return value;
    }

    public void setValue(int value) {
        this.value = value;
    }
}

class MoSTState implements Serializable {
    private static final long serialVersionUID = 1L;
    private long[] offsets;
    private int[] keys;
    private int recordCount;

    public MoSTState(long[] offsets, int[] keys, int recordCount) {
        this.offsets = offsets;
        this.keys = keys;
        this.recordCount = recordCount;
    }

    // Getters and Setters for offsets, keys, and recordCount
}
