const fs = require('fs');
const path = require('path');
let uniqueId = 0;

function loadScript(filePath) {
    const scriptTag = document.createElement('script');
    scriptTag.src = filePath;
    scriptTag.onerror = () => console.error(`Failed to load ${filePath}`);
    scriptTag.onload = () => {
        const newName = path.basename(filePath, '.js') + '_' + uniqueId++ + '.processed.js';
        const head = document.head || document.getElementsByTagName('head')[0];
        const existingScripts = Array.from(head.getElementsByTagName('script'));
        let scriptIndex;

        // Find the position of the new script among existing scripts with the same file path (if any)
        for (let i = 0; i < existingScripts.length; i++) {
            if (existingScripts[i].src === filePath) {
                scriptIndex = i;
                break;
            }
        }

        // Insert the modified script at the end of all existing scripts or directly into the head, depending on whether a matching script was found.
        if (scriptIndex === undefined || scriptIndex === existingScripts.length) {
            head.appendChild(scriptTag);
        } else {
            head.insertBefore(scriptTag, existingScripts[scriptIndex + 1]);
        }
    };
    document.head.appendChild(scriptTag);
}
