    private $hostnames;
    private $cache;
    private $config;
    private $timeout;
    private $capacity;

    public function __construct(array $config) {
        $this->hostnames = $config['hostnames'];
        $this->cache = new \SplObjectStorage();
        $this->timeout = $config['timeout'];
        $this->capacity = $config['capacity'];
    }

    public function processTransaction(string $orderId, array $customerDetails, float $amount) {
        $gatewayIp = $this->resolveDNS($this->getPrimaryHostname());

        if (!$gatewayIp) {
            return ['status' => 'failure', 'message' => 'Payment gateway unavailable'];
        }

        // Use Guzzle HTTP client for API requests
        require 'vendor/autoload.php';
        use GuzzleHttp\Client;

        $client = new Client([
            'base_uri' => "http://{$gatewayIp}",
            'timeout' => $this->timeout,
        ]);

        try {
            $response = $client->post('/transactions', [
                'form_params' => [
                    'orderId' => $orderId,
                    'customerDetails' => json_encode($customerDetails),
                    'amount' => $amount,
                ],
            ]);

            $responseBody = json_decode($response->getBody(), true);

            if ($responseBody['status'] === 'success') {
                return $this->createTransactionRecord($responseBody['transactionId']);
            } else {
                // Handle failed transaction with backoff logic
                usleep($this->backoff());
                return $this->processTransaction($orderId, $customerDetails, $amount);
            }
        } catch (\Exception $e) {
            // Handle exceptions and network failures gracefully
            if (strpos($e->getMessage(), 'Failed to connect') !== false) {
                return $this->fallback();
            } else {
                return ['status' => 'failure', 'message' => $e->getMessage()];
            }
        }
    }

    private function resolveDNS(string $hostname): ?string {
        if (!$this->cache->contains($hostname)) {
            $ip = gethostbyname($hostname);

            if ($ip) {
                $this->cache->attach($hostname, $ip);
            }
        }

        return $this->cache->offsetExists($hostname) ? $this->cache[$hostname] : null;
    }

    private function backoff(): int {
        static $backoffMultiplier = 2;
        static $initialBackoffTime = 100000; // 100 ms

        if ($backoffMultiplier > 3) {
            $backoffMultiplier = 2;
        }

        return min($this->timeout / 2, $initialBackoffTime * pow($backoffMultiplier, $backoffMultiplier++));
    }

    private function fallback(): array {
        // Implement a simple fallback mechanism, e.g., using a secondary DNS service or alternative payment gateway API
        // ...
        return ['status' => 'failure', 'message' => 'Payment gateway unavailable'];
    }

    private function createTransactionRecord(string $transactionId): array {
        // Create and populate a transaction record using standard PHP functions
        // ...
        return ['status' => 'success', 'transaction' => $transaction];
    }

    private function getPrimaryHostname(): string {
        // Rotate through hostnames provided in the constructor, prioritizing available ones
        foreach ($this->hostnames as $index => $hostname) {
            if (!$this->resolveDNS($hostname)) {
                continue;
            }

            array_unshift($this->hostnames, $hostname);
            return $hostname;
        }

        throw new \RuntimeException('All provided hostnames are unavailable');
    }
}
```

