};

class ImageParser {
private:
    std::mutex mtx;
    int bitsPerSample;
    int samplePerPixel;
    int extraSamples;
    std::string compressionMethod;
    std::string md5Hash;

public:
    ImageParser(TestDouble& table) : table(table) {}

    void parseTIFF(const std::string& filePath) {
        TIFF* tif = TIFFOpen(filePath.c_str(), "r");

        if (!tif) {
            std::cerr << "Error: Invalid TIFF file." << std::endl;
            return;
        }

        uint16_t photometricInterpretation = 0;
        tiffGetField(tif, TIFFTAG_PHOTOMETRIC, &photometricInterpretation);

        if (TIFFGetBitDepth(tif) != 1 && TIFFGetBitDepth(tif) != 2 &&
            TIFFGetBitDepth(tif) != 4 && TIFFGetBitDepth(tif) != 8 &&
            TIFFGetBitDepth(tif) != 16) {
            std::cerr << "Error: Unsupported number of bits per sample." << std::endl;
            TIFClose(tif);
            return;
        }

        tiffGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &samplePerPixel);
        tiffGetField(tif, TIFFTAG_EXTRASAMPLES, &extraSamples);

        if (TIFFGetField(tif, TIFFTAG_COMPRESSION) != COMPRESSION_NONE) {
            tiffGetField(tif, TIFFTAG_COMPRESSION, &compressionMethod[0]);
            compressionMethod.resize(strlen(TIFFGetName(tif)));
        }

        uint8_t buffer[512];
        boost::iostreams::stream<boost::iostreams::mapped_file> fileStream(
                boost::filesystem::wpath(filePath).filename().string(), false);
        boost::iostreams::filtering_stream<boost::iostreams::input> inputFilter;
        inputFilter.push(boost::iostreams::gzip_decompressor());
        inputFilter.push(fileStream);

        TIFFReadScanline(tif, buffer, 0);
        md5Hash = std::string((const char*)SHA1((const unsigned char*)buffer, sizeof(buffer), &md5Hash[0]), &md5Hash[0] + SHA1_DIGEST_LENGTH);

        TIFClose(tif);
    }

    int getBitsPerSample() const { return bitsPerSample; }
    int getSamplePerPixel() const { return samplePerPixel; }
    int getExtraSamples() const { return extraSamples; }
    const std::string& getCompressionMethod() const { return compressionMethod; }
    const std::string& getMD5Hash() const { return md5Hash; }

private:
    TestDouble& table;
};

class SandeshClient {
