LOG4CXX_INITIALIZE()
static log4cxx::LoggerPtr logger(log4cxx::Logger::getLogger("ImageParser"));

int main() {
    TestDouble test; // Use the test double for network communication
    ImageParser parser(test);

    std::string filePath = "path/to/your/tiff_image.tif";
    parser.parseTIFF(filePath);

    int requests = 0, proxySessions = 0, internalErrors = 0;
    {
        std::lock_guard<std::mutex> lock(parser.mtx);
        requests = parser.getMD5Hash().length();
        proxySessions = parser.getBitsPerSample() + parser.getSamplePerPixel() + parser.getExtraSamples() + 1; // +1 for compression method
        internalErrors += !parser.getCompressionMethod().empty();
    }

    std::cout << "Number of requests: " << requests << std::endl;
    std::cout << "Number of proxy sessions: " << proxySessions << std::endl;
    std::cout << "Number of internal errors: " << internalErrors << std::endl;

