2. JavaScript Helper Function: `collectMatchingElements`

```javascript
function collectMatchingElements(selector, callback, parentElement = document) {
  let elements = [];

  function traverse(node) {
    if (node === null) return;

    const matchesSelector = node.matches ? node.matches(selector) : node.matchesSelector(selector);
    if (matchesSelector && callback(node)) elements.push(node);

    Array.from(node.children).forEach((child) => traverse(child));
    Array.from(node.querySelectorAll(selector)).forEach((child) => traverse(child));
  }

  traverse(parentElement);
  return elements;
}
