void initializeDataStructures(size_t *offsetSize, size_t *keySize, size_t *recordCount, size_t *timestampSize) {
    long *offsets = malloc(*offsetSize * sizeof(long));
    int *keys = malloc(*keySize * sizeof(int));
    Record *records = malloc((*recordCount) * sizeof(Record));
    time_t *timestamps = malloc(*timestampSize * sizeof(time_t));
    enum Status *statuses = calloc((*recordCount), sizeof(enum Status));

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Seed random number generator with current time
    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < *recordCount; ++i) {
        pthread_mutex_lock(&mutex);

        // Generate unique keys within given range
        keys[i] = rand() % (*keySize);

        // Ensure temporal consistency between timestamps
        if (i == 0)
            timestamps[i] = time(NULL);
        else
            timestamps[i] = timestamps[i - 1] + 60; // Increment by a minute to simulate temporal consistency

        pthread_mutex_unlock(&mutex);

        size_t j;
        for (j = 0; j < i; ++j) {
            // Ensure uniqueness of keys across records
            if (keys[i] == keys[j]) {
                // If key collision, find a new key within the range
                keys[i] = rand() % (*keySize);
                break;
            }
        }

        // Initialize offset and status values
