Below is a code snippet demonstrating part of the custom data structure for `ArrayNode` and its associated functions:

```c
typedef struct {
    void* data; // pointer to actual array data (either offsets or keys)
    size_t capacity; // current capacity of the array
    size_t length;   // number of elements currently occupied in the array
    size_t item_size; // size of each element in bytes
} ArrayNode;

ArrayNode* array_grow(ArrayNode* node, size_t new_capacity) {
    if (new_capacity <= node->capacity) return node;

    void* new_data = realloc(node->data, new_capacity * node->item_size);
    if (!new_data) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    node->data = new_data;
    node->capacity = new_capacity;
    return node;
}
```

