#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <sys/mman.h> // For posix_memalign

typedef struct Record {
    int value;
} Record;

// Allocate memory for long offsets and int keys, validated for correctness
long* allocate_long(size_t size) {
    void *ptr = malloc(size * sizeof(long));
    if (!ptr) {
        // Handle allocation failure
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    return (long*) ptr;
}

int* allocate_int(size_t size) {
    void *ptr = malloc(size * sizeof(int));
    if (!ptr) {
        // Handle allocation failure
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    return (int*) ptr;
}

// Allocate memory for record structures on the heap, ensuring minimal memory overhead
Record* allocate_records(size_t count) {
    size_t alignment = sizeof(max_align_t); // Get maximum supported alignment from system
    void *ptr = malloc(count * sizeof(Record));
    if (!ptr) {
        // Handle allocation failure
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    if (posix_memalign(ptr, alignment, count * sizeof(Record))) {
        // Handle memory alignment failure
        free(ptr);
        perror("posix_memalign");
        exit(EXIT_FAILURE);
    }
    return (Record*) ptr;
}

// Set each record's int field to a random value within a given range
void initialize_records(Record* records, size_t count, int min, int max) {
    static thread_local struct {
        pthread_mutex_t mutex;
        int cached[RAND_MAX];
    } prng = { PTHREAD_MUTEX_INITIALIZER };

    for (size_t i = 0; i < count; ++i) {
        records[i].value = rand_r(&prng.cached[pthread_mutex_lock(&prng.mutex)] % (max - min + 1)) + min;
        pthread_mutex_unlock(&prng.mutex);
    }
