// Memory-efficient linked list implementation of DataRecord
class DataRecordList {
public:
    DataRecordList() : head_(nullptr), tail_(nullptr), size_(0) {}

    ~DataRecordList() {
        while (head_) {
            auto temp = head_;
            head_ = head_->next;
            delete temp;
        }
    }

    void push_back(DataRecord* record) {
        if (!tail_) {
            tail_ = head_ = record;
        } else {
            tail_->next = record;
            tail_ = record;
        }
        ++size_;
    }

    DataRecord* pop_front() {
        auto temp = head_;
        if (head_) {
            head_ = head_->next;
            --size_;
        }
        return temp;
    }

    size_t size() const { return size_; }

private:
    DataRecord* head_, *tail_;
    mutable std::mutex mtx;
    size_t size_;
};

