#define RECORD_THRESHOLD 1000

typedef struct {
    int value;
    char status;
    char *string;
} Record;

struct Node {
    int key;
    Record record;
    struct Node *next;
};

void initDataStructures(struct Node **head, int *offsets, int *keys) {
    *head = NULL;
    offsets[0] = 0;
    keys[0] = 1;
}

Record createRecord(int value, char status, char *string) {
    Record record;
    record.value = value;
    record.status = status;
    record.string = strdup(string);
    return record;
}

struct Node* createNode(int key, Record record) {
    struct Node *node = (struct Node*) malloc(sizeof(struct Node));
    node->key = key;
    node->record = record;
    node->next = NULL;
    return node;
}

void insertRecord(struct Node **head, int *offsets, int *keys, int value) {
    if (*head == NULL) {
        initDataStructures(head, offsets, keys);
        (*head) = createNode(keys[0], createRecord(value, 'A', ""));
        offsets[1] = sizeof(**head);
        keys[0] += KEY_INCREMENT;
    } else {
        struct Node *current = *head;
        int currentOffset = offsets[1];
        while (current->key <= keys[*offsets / sizeof(**head)]) {
            currentOffset += sizeof(**current);
            if (!current->next) break;
            current = current->next;
        }
        current->next = createNode(keys[*offsets / sizeof(**head)], createRecord(value, 'A', ""));
        offsets[1] += sizeof(**current);
        keys[*offsets / sizeof(**head)]++;
    }
}

void removeRecordByKey(struct Node **head, int *offsets, int key) {
    if (*head == NULL) return;

    struct Node *current = *head;
    struct Node *prev = NULL;
    while (current && current->key <= key) {
        prev = current;
        current = current->next;
    }

    if (!current) return;

    if (prev == NULL) {
        *head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current->record.string);
    free(current);
}

