struct Node {
    int key;
    long offset;
    Record record;
    struct Node* next;
};

struct HashTable {
    int size;
    struct Node** nodes;
    pthread_mutex_t mutex;
};

void initHashTable(struct HashTable* table, int size) {
    table->size = size;
    table->nodes = calloc(size, sizeof(struct Node*));
    if (!table->nodes) {
        perror("Error allocating memory for hash table");
        exit(EXIT_FAILURE);
    }
    table->mutex = PTHREAD_MUTEX_INITIALIZER;
}

int hashFunction(const int key, const int size) {
    return key % size;
}

void resizeHashTable(struct HashTable* table) {
    // Implement a strategy to resize the hash table
    // ...
}

int addRecord(struct HashTable* table, Record record, long offset, int key) {
    struct Node* newNode = malloc(sizeof(struct Node));
    if (!newNode) {
        perror("Error allocating memory for new node");
        exit(EXIT_FAILURE);
    }

    newNode->key = key;
    newNode->offset = offset;
    newNode->record = record;
    newNode->next = NULL;

    pthread_mutex_lock(&table->mutex);
    int index = hashFunction(key, table->size);
    if (!table->nodes[index]) {
        table->nodes[index] = newNode;
    } else {
        struct Node* current = table->nodes[index];
        while (current->next) {
            current = current->next;
        }
        current->next = newNode;
    }
    pthread_mutex_unlock(&table->mutex);

    return 0;
}

Record* getRecordByKey(struct HashTable* table, int key) {
    struct Node* node;
    pthread_mutex_lock(&table->mutex);
    int index = hashFunction(key, table->size);
    node = table->nodes[index];
    while (node) {
        if (node->key == key) {
            break;
        }
        node = node->next;
    }
    pthread_mutex_unlock(&table->mutex);

    return &node->record;
}

void removeRecordByKey(struct HashTable* table, int key) {
    struct Node** current, *tmpNode;
    pthread_mutex_lock(&table->mutex);
    int index = hashFunction(key, table->size);
    current = &table->nodes[index];

    while (*current && (*current)->key != key) {
        current = &((*current)->next);
    }

    if (!(*current)) {
        goto exit;
    }

    tmpNode = *current;
    *current = tmpNode->next;
    free(tmpNode->str);
    free(tmpNode);

exit:
    pthread_mutex_unlock(&table->mutex);
}

