        std::unique_ptr<Node> next;

        Node(long o, int k, const Record& r) : offset(o), key(k), record(r), next(nullptr) {}
    };

    struct HashNode {
        int key;
        Node* node;
    };

    std::atomic<int> memUsage{ 0 };
    std::atomic<size_t> numNodes{ 0 };
    std::vector<Node*> nodes;
    std::list<HashNode> hashTable;
    mutex mtx;
    int maxMemUsage;

    void resize() {
        // Implement your resizing strategy here
    }

public:
    DynamicRecordCollection(int maxMem) : maxMemUsage(maxMem) {}

    Record* get(int key) {
        std::unique_lock<mutex> lk(mtx);
        auto it = hashTable.begin();
        while (it != hashTable.end()) {
            if (it->key == key) {
                lk.unlock();
                return it->node;
            }
            it++;
        }
        return nullptr;
    }

    void insert(const Record& r) {
        std::unique_lock<mutex> lk(mtx);
        if (memUsage + sizeof(Record) > maxMemUsage) resize();
        numNodes++;
        memUsage += sizeof(Record);

        auto newNode = std::make_unique<Node>(numNodes, r.key, r);
        nodes.push_back(newNode.get());
        if (hashTable.empty()) {
            hashTable.emplace_back(r.key, newNode.get());
        } else {
            auto it = hashTable.begin();
            while (it != hashTable.end() && it->key < r.key) it++;
            if (it == hashTable.begin()) {
                hashTable.push_front({r.key, newNode.get()});
            } else {
                it--;
                it->next.swap(HashNode({r.key, newNode.get()}));
            }
        }
    }

    void remove(int key) {
        std::unique_lock<mutex> lk(mtx);
        auto it = hashTable.begin();
        while (it != hashTable.end() && it->key != key) it++;
        if (it == hashTable.end()) return;

        Node* toDelete = it->node;
        numNodes--;
        memUsage -= sizeof(Record);
        hashTable.erase(it);

        if (toDelete->next) {
            auto nextIt = toDelete->next.get();
            size_t index = std::distance(nodes.cbegin(), toDelete);
            nodes[index] = nextIt;
            for (size_t i = index + 1, j = index + 2; i < numNodes; ++i, ++j) {
                nodes[j] = nodes[i];
            }
        } else {
            auto index = std::distance(nodes.cbegin(), toDelete);
            nodes.erase(nodes.begin() + index);
        }
    }
};
```

