import java.io.*;
import java.nio.file.*;
import java.security.MessageDigest;
import java.math.BigInteger;
import java.nio.charset.StandardCharsets;
import java.util.ConcurrentLinkedQueue;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class FileHashUtil {
    private static final long MAX_DATA_SIZE = 8 * (1024L * 1024L);

    public String calculateSHA256(String... filePaths) throws IOException {
        var dataQueue = new ConcurrentLinkedQueue<>();
        var executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

        try {
            for (String filePath : filePaths) {
                if (filePath == null || !Files.exists(Paths.get(filePath)) || !Files.isReadable(Paths.get(filePath))) {
                    throw new IllegalArgumentException("Invalid file path: " + filePath);
                }

                Runnable reader = () -> {
                    try (BufferedReader reader = new BufferedReader(new FileReader(filePath))) {
                        char[] buffer = new char[1024];
                        int read;
                        while ((read = reader.read(buffer)) != -1) {
                            dataQueue.add(buffer, 0, read);
                            if (dataQueue.size() > MAX_DATA_SIZE / Long.BYTES) {
                                break;
                            }
                        }
                    } catch (IOException e) {
                        // Handle exceptions here if needed
                    }
                };

                executorService.submit(reader);
            }

            executorService.shutdown();

            byte[] data = new byte[dataQueue.size()];
            int index = 0;
            for (char c : dataQueue) {
                System.arraycopy(c, 0, data, index, c.length);
                index += c.length;
            }

            MessageDigest sha256 = MessageDigest.getInstance("SHA-256");
            sha256.update(data);
            BigInteger bigHash = new BigInteger(1, sha256.digest());
            return String.format("%064x", bigHash);
        } finally {
            executorService.shutdownNow();
        }
    }
}
```
