#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef enum { IDLE, PROCESSING, COMPLETED } Status;
typedef struct Data {
    void *blob;
    size_t size;
} Data;

typedef struct Task {
    time_t timestamp;
    int priority;
    char description[256];
    Status status;
    Data data;
} Task;

typedef struct QueueNode {
    Task task;
    struct QueueNode *next;
} QueueNode;

struct JobQueue {
    QueueNode *head, *tail;
    size_t size;
    pthread_mutex_t mutex;
};

void job_queue_init(JobQueue *q) {
    q->head = q->tail = NULL;
    q->size = 0;
    pthread_mutex_init(&q->mutex, NULL);
}

void job_queue_destroy(JobQueue *q) {
    QueueNode *node = q->head;
    while (node != NULL) {
        QueueNode *temp = node;
        node = node->next;
        free(temp->task.data.blob);
        free(temp);
    }
    pthread_mutex_destroy(&q->mutex);
}

void job_queue_add(JobQueue *q, const char *description, void *data, size_t data_size) {
    Task task;
    memcpy(task.description, description, strlen(description)+1);
    task.timestamp = time(NULL);
    task.priority = rand() % 10 + 1; // Random priority within the range [1, 10]
    task.status = IDLE;
    task.data.blob = malloc(data_size);
    memcpy(task.data.blob, data, data_size);
    task.data.size = data_size;

    pthread_mutex_lock(&q->mutex);

    if (q->head == NULL) {
        q->head = q->tail = &task;
    } else {
        q->tail->next = &task;
        q->tail = &task;
    }
    q->size++;

    pthread_mutex_unlock(&q->mutex);
}

Task* job_queue_remove_by_timestamp(JobQueue *q, time_t timestamp) {
    Task *result = NULL;
    QueueNode *node = q->head;

    while (node != NULL) {
        if (node->task.timestamp <= timestamp) {
            result = &node->task;
            if (node == q->head) {
                q->head = node->next;
            }
            if (node->next == NULL) {
                q->tail = q->head;
            } else {
                QueueNode *temp = node->next;
                node->next = NULL;
                q->tail = temp;
            }
            q->size--;
            break;
        }
        node = node->next;
    }

    return result;
}

Task* job_queue_search_by_priority(JobQueue *q, int priority) {
    Task *result = NULL;
    QueueNode *node = q->head;

    while (node != NULL) {
        if (node->task.priority == priority) {
            result = &node->task;
            break;
        }
        node = node->next;
    }

    return result;
}
```

