struct MemoryBlock {
    void *memory;
    size_t size;
    struct MemoryBlock *next;
};

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file;

void log_operation(const char *operation, Record r) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(log_file, "%s - %s: (offset=%ld, key=%d, value=%d, status=%c, str=\"%s\")\n", timestamp, operation, r.data.offset, r.data.key, r.data.value, r.data.status, r.data.str);
}

void *memory_pool_alloc(size_t size) {
    struct MemoryBlock *mem_block = (struct MemoryBlock *) mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (mem_block == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    struct MemoryBlock *head = NULL;
    struct MemoryBlock *current = head;

    while (current != NULL && current->size < size) {
        current = current->next;
    }

    if (current == NULL || current->size >= size + sizeof(struct MemoryBlock)) {
        mem_block->size = size;
        mem_block->next = head;
        head = mem_block;
    } else {
        void *ptr = ((char *) current + current->size - sizeof(struct MemoryBlock));
        struct MemoryBlock *new_mem_block = (struct MemoryBlock *) ptr;
        new_mem_block->size = size;
        new_mem_block->next = current->next;
        current->next = new_mem_block;
    }

    return (void *) ((char *) head + sizeof(struct MemoryBlock));
}

