using System;
using System.Collections.Generic;
using System.Linq;
using System.Numerics;

public class ResourceScheduler
{
    private BigInteger _availableResources;
    private BigInteger _maxResourceLimit;
    private PriorityQueue<Task> _tasks;

    public ResourceScheduler(BigInteger maxResources = 0)
    {
        _maxResourceLimit = maxResources > 0 ? maxResources : BigInteger.MaxValue;
        _availableResources = 0;
        _tasks = new PriorityQueue<Task>();
    }

    public void RequestResource(BigInteger quantity)
    {
        if (_availableResources + quantity < _maxResourceLimit && _availableResources + quantity > BigInteger.Zero)
            _availableResources += quantity;
    }

    public void ReleaseResource(BigInteger quantity)
    {
        if (_availableResources - quantity >= BigInteger.Zero && _availableResources - quantity <= _maxResourceLimit)
            _availableResources -= quantity;
    }

    public BigInteger GetAvailableResources() => _availableResources;

    public void ScheduleTask(Task task)
    {
        if (task == null) throw new ArgumentNullException(nameof(task));
        _tasks.Enqueue(task);
    }

    public override string ToString()
    {
        var availableResources = _availableResources;
        var tasksAsString = string.Join("\n", _tasks.Select(t => t.ToString()));

        return $"Resource Availability: {availableResources}\nScheduled Tasks:\n{tasksAsString}";
    }

    private void EnsureValidLimits()
    {
        if (_availableResources < BigInteger.Zero || _availableResources > _maxResourceLimit)
            throw new InvalidOperationException("Resource limits are invalid.");
    }

    // Add CalculateTaskExecutionStats and ModifyFileName methods here...
}
