```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Memory pool structure
struct MemPool {
    void* blocks[NUM_BLOCKS];
    size_t used;
    pthread_mutex_t lock;
};

void init_mempool(struct MemPool *mp) {
    memset(mp->blocks, 0, sizeof(mp->blocks));
    mp->used = 0;
    pthread_mutex_init(&mp->lock, NULL);
}

// Allocate memory from the pool or malloc if empty
void* get_mem(struct MemPool *mp) {
    pthread_mutex_lock(&mp->lock);
    if (mp->used < NUM_BLOCKS) {
        void* mem = mp->blocks[mp->used];
        mp->used++;
        pthread_mutex_unlock(&mp->lock);
        return mem;
    } else {
        pthread_mutex_unlock(&mp->lock);
        return malloc(BLOCK_SIZE);
    }
}

// Free memory back to the pool or free if already in the pool
void free_mem(struct MemPool *mp, void* mem) {
    pthread_mutex_lock(&mp->lock);
    if (mem != mp->blocks[mp->used - 1]) {
        free(mem);
    } else {
        mp->used--;
    }
    pthread_mutex_unlock(&mp->lock);
}
```

