#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>
#include <sys/types.h>
#include <semaphore.h>
#include <arpa/inet.h>

typedef struct {
    int key;
    int value;
    char status;
    char *str;
    float timestamp;
} Record;

typedef struct Node {
    Record data;
    struct Node *left, *right;
    sem_t sem;
} Node;

Node *root = NULL;
pthread_mutex_t global_mutex;
int total_records = 0;

void initBST() {
    root = malloc(sizeof(Node));
    root->left = root->right = NULL;
    sem_init(&root->sem, 0, 1);
}

void insertRecord(Node *node, Record new_record) {
    pthread_mutex_lock(&global_mutex);
    total_records++;

    if (node == NULL) {
        node = malloc(sizeof(Node));
        node->data = new_record;
        node->left = node->right = NULL;
        sem_init(&node->sem, 0, 1);
        return;
    }

    if (new_record.key < node->data.key) {
        if (!node->left) insertRecord(node->left, new_record);
        else pthread_mutex_unlock(&global_mutex);
        pthread_mutex_lock(&node->left->sem);
        insertRecord(node->left, new_record);
        pthread_mutex_unlock(&node->left->sem);
    } else {
        if (!node->right) insertRecord(node->right, new_record);
        else pthread_mutex_unlock(&global_mutex);
        pthread_mutex_lock(&node->right->sem);
        insertRecord(node->right, new_record);
        pthread_mutex_unlock(&node->right->sem);
    }

    pthread_mutex_unlock(&global_mutex);
}

void deleteRecord(Node *node, int key) {
    pthread_mutex_lock(&global_mutex);
    total_records--;

    if (node == NULL) return;

    if (key < node->data.key) {
        if (!node->left) return;
        deleteRecord(node->left, key);
    } else if (key > node->data.key) {
        if (!node->right) return;
        deleteRecord(node->right, key);
    } else {
        Node *temp = node;

        if (!temp->left) node = temp->right;
        else if (!temp->right) node = temp->left;
        else {
            Node *successor = temp->right;
            while (successor->left) successor = successor->left;
            temp->data = successor->data;
            deleteRecord(temp->right, successor->key);
        }

        free(temp);
    }

    pthread_mutex_unlock(&global_mutex);
}

Record searchRecord(Node *node, int key) {
    if (node == NULL) return (Record){0};

    if (node->data.key < key) return searchRecord(node->right, key);
    else if (node->data.key > key) return searchRecord(node->left, key);
    else return node->data;
}

