use std::env;
use std::fs::{create_dir, create_dir_all, remove_dir_all};
use std::path::PathBuf;
use std::io::{ErrorKind, Result};

pub fn create_and_manage_directory(dir: &str) -> Result<PathBuf> {
    let directory_path = env::var("DIRECTORY_PATH")?;

    let mut path = PathBuf::from(directory_path);
    path.push(dir);

    if !path.exists() {
        create_dir_all(&path)?;
        env::set_var("DIRECTORY_PATH", path.to_str());
    } else if !path.is_dir() || !path.can_write() {
        remove_dir_all(path)?;
        create_dir_all(&path)?;
        env::set_var("DIRECTORY_PATH", path.to_str());
    }

    Ok(path)
}
