#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <sys/mman.h>

// Thread-safe cache structure
typedef struct {
    void** cache;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} Cache;

Cache* create_cache(size_t initial_capacity) {
    Cache* cache = malloc(sizeof(Cache));
    if (!cache) return NULL;
    cache->cache = malloc(initial_capacity * sizeof(void*));
    if (!cache->cache) {
        free(cache);
        return NULL;
    }
    cache->capacity = initial_capacity;
    cache->count = 0;
    pthread_mutex_init(&cache->lock, NULL);
    return cache;
}

void destroy_cache(Cache* cache) {
    if (cache && cache->cache) {
        free(cache->cache);
        free(cache);
    }
}

// Function to modify filename based on given criteria
char* modify_filename(const char* filename) {
    // Check for edge cases
    if (!filename || !*filename || strlen(filename) > 255) return NULL;

    Cache* cache = create_cache(10); // Initialize cache with a small capacity
    pthread_mutex_lock(&cache->lock);

    int index, digits = -1, random_length = 7;
    char* start, *ext, *file_type, *new_filename;
    for (index = strlen(filename) - 1; index >= 0 && digits == -1; index--) {
        if (isdigit(filename[index])) digits++;
    }

    ext = strchr(filename, '.');
    file_type = ext ? ext : filename;
    file_type = strlen(file_type) < 4 ? file_type : file_type + strlen(file_type) - 3;

    if (ext) {
        start = realloc(filename, strlen(filename) + random_length + digits + strlen(file_type) + 5);
        if (!start) goto cleanup;
        filename = start;
    } else {
        start = realloc(filename, strlen(filename) + random_length + digits + strlen(file_type) + 6);
        if (!start) goto cleanup;
        strcat(filename, ".modified.");
        filename = start;
    }

    time_t now = time(NULL);
    struct tm* local = localtime(&now);
    char random[7];
    for (int i = 0; i < 7; i++) {
        random[i] = 'A' + rand() % 26;
    }
    snprintf(filename + strlen(filename) - digits - random_length, random_length, "%s", random);

    snprintf(filename + strlen(filename) - digits - random_length - 4, 5, ".%0*d.", digits, digits);
    snprintf(filename + strlen(filename) - digits - random_length - 9, 12, "%04d", (int)(now - local->tm_year * 365 * 24 * 60 * 60 + local->tm_yday));
    snprintf(filename + strlen(filename) - digits - random_length - 19, 4, ".%s", file_type);

cleanup:
    pthread_mutex_unlock(&cache->lock);

    // Cache the result if not already in cache and adjust cache size based on memory availability
    pthread_mutex_lock(&cache->lock);
    for (index = 0; index < cache->count; index++) {
        if (cache->cache[index] == filename) goto exit;
    }
    if (cache->count >= cache->capacity && mallctl("system.memory.info", NULL, NULL, NULL, NULL) > 1024 * 1024 * 1024) { // Adjust capacity based on memory usage and max limit
        size_t new_capacity = (cache->capacity * 3 / 2);
        Cache* new_cache = realloc(cache, sizeof(Cache) + new_capacity * sizeof(void*));
        if (!new_cache) {
            free(filename);
            goto exit;
        }
        cache = new_cache;
        cache->cache = realloc(cache->cache, new_capacity * sizeof(void*));
    }
    cache->cache[cache->count++] = filename;

exit:
    return filename;
}
