DataContainer* createDataContainer(size_t size, long min_offset, long max_offset, int min_key, int max_key, double min_value, double max_value, unsigned int seed) {
    DataContainer *container = malloc(sizeof(DataContainer));
    if (!container) {
        perror("Memory allocation failed");
        return NULL;
    }

    container->size = size;
    container->records = calloc(size, sizeof(Record));
    if (!container->records) {
        perror("Memory allocation failed");
        free(container);
        return NULL;
    }

    srand(seed);
    for (size_t i = 0; i < size; ++i) {
        container->records[i].offset = min_offset + rand() % ((max_offset - min_offset) + 1);
        container->records[i].key = rand() % ((max_key - min_key) + 1) + min_key;
        container->records[i].value = min_value + (rand() % ((max_value - min_value) + 1)) * 0.01;
    }

    return container;
}

Record getRecordByIndex(const DataContainer* container, size_t index) {
    if (index >= container->size || index < 0) {
        Record default_record = {0, -1, 0.0};
        return default_record;
    }
    return container->records[index];
}

void setRecordValue(DataContainer* container, size_t index, double value) {
    if (index >= container->size || index < 0) {
        fprintf(stderr, "Invalid index\n");
        return;
    }
    container->records[index].value = value;
}

void freeDataContainer(DataContainer* container) {
    if (!container) return;
    free(container->records);
    free(container);
