void log(const char* message) {
    pthread_mutex_lock(&log_mutex);
    printf("[LOG] %s\n", message);
    pthread_mutex_unlock(&log_mutex);
}

Record* create_record() {
    Record* record = (Record*)memory_pool.pool;
    memory_pool.count--;
    return record;
}

void destroy_record(Record* record) {
    free(record->data);
    memory_pool.count++;
}

void initialize_collection(size_t size) {
    memory_pool.pool = malloc(sizeof(Record) * size);
    memory_pool.size = size;
    memory_pool.count = size;
}

Record* get_record(size_t index) {
    if (index >= memory_pool.size || index < 0) {
        log("Error: Invalid index.");
        return NULL;
    }
    return create_record() + index;
}

void set_record_value(Record* record, long offset, int key, double value, const char* data) {
    if (offset < 0 || offset >= RAND_MAX || key < 0 || key > INT_MAX || value < -DBL_MAX || DBL_MAX < value) {
        log("Error: Value out of range.");
        return;
    }

    record->offset = offset;
    record->key = key;
    record->value = value;
    if (data != NULL) {
        size_t length = strlen(data) + 1;
        record->data = malloc(length);
        memcpy(record->data, data, length);
    } else {
        record->data = NULL;
    }
}

void add_record(Record* record) {
    if (memory_pool.count >= memory_pool.size) {
        log("Error: Memory pool is full.");
        return;
    }

    set_record_value(record, rand(), rand(), rand(), NULL);
}

