    const size_t chunk_size = memory_pool.size / 4;

    for (size_t i = 0; i < 4; ++i) {
        size_t start = i * chunk_size;
        size_t end = (i == 3) ? memory_pool.size : start + chunk_size;
        pthread_create(&threads[i], NULL, process_records, (void*)(start));
