void gc(struct cache* cache) {
    if (cache->size / (double) cache->capacity > cache->max_cache_size / 100.0) {
        size_t new_size = (cache->size * 3) / 4;
        resize_cache(cache);
        for (size_t i = cache->size; i < cache->capacity; ++i) {
            free((cache->records[i]));
        }
        cache->size = new_size;
    }
}

int find_record(struct cache* cache, const long offset, record** out_record) {
    pthread_mutex_lock(&cache->lock);
    int index = (offset % cache->capacity);
