#include <sys/mman.h> // For sharing memory with an external data source

// Shared memory segment for storing size limit
void* shared_memory;
size_t size_limit;

int init_shared_memory() {
    int shmid = shmget(IPC_PRIVATE, sizeof(size_t), IPC_CREAT | 0666);
    if (shmid == -1) {
        perror("shmget");
        return -1;
    }
    shared_memory = shmat(shmid, NULL, 0);
    if (shared_memory == (void*)-1) {
        perror("shmat");
        shmctl(shmid, IPC_RMID, NULL);
        return -1;
    }
    size_limit = 0;
    return 0;
}

char* process_string(const char* input) {
    if (!input || (size_t)(-1) == init_shared_memory()) {
        return NULL;
    }

    // Trim leading whitespace and count the remaining characters
    size_t trimmed_len = 0;
    const char* trimmed = input;
    for (; *trimmed && isspace(*trimmed); ++trimmed) {
        ++trimmed_len;
    }

    // Calculate the new string size, considering the potential semicolon appending
    size_t required_size = trimmed_len + 1;
    if (trimmed_len >= *((size_t*)shared_memory)) {
        required_size += 1;
    }

    // Allocate memory for the new string, considering the dynamically determined size limit
    char* processed_str = malloc(required_size);
    if (!processed_str) {
        return NULL;
    }

    // Copy the trimmed string and append a semicolon if necessary
    strncpy(processed_str, trimmed, trimmed_len + 1);

    // Fetch the size limit from the shared memory and update the processed string if it meets the criteria
    if (trimmed_len >= *((size_t*)shared_memory)) {
        processed_str[trimmed_len] = ';';
        ++processed_str[trimmed_len + 1]; // Ensure a null terminator is present at the end of the string
    }

    return processed_str;
}
