import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.Arrays;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.logging.Logger;
import java.util.logging.LogManager;
import javax.servlet.http.HttpServletRequest;

public class HashUtil {
    private static final Logger LOGGER = LogManager.getLogManager().getLogger(HashUtil.class.getName());

    private static ConcurrentLinkedQueue<String> queue = new ConcurrentLinkedQueue<>();
    private static int maxLength = 1024;
    private static MessageDigest SHA_256;

    static {
        try {
            SHA_256 = MessageDigest.getInstance("SHA-256");
        } catch (Exception e) {
            LOGGER.severe("Failed to initialize SHA-256 digest.");
        }
    }

    public static String concatenateAndHash(HttpServletRequest request, String... strings) {
        if (strings == null || strings.length == 0) {
            throw new IllegalArgumentException("Strings array cannot be null or empty.");
        }

        Arrays.stream(strings).forEach(s -> {
            if (s == null || s.isEmpty()) {
                LOGGER.warning("Skipping null or empty string.");
                return;
            }
            queue.add(s);
        });

        StringBuilder sb = new StringBuilder();
        while (queue.size() > 0 && sb.length() + queue.peek().length() <= maxLength) {
            sb.append(queue.poll());
        }

        if (sb.length() > 0) {
            byte[] hashData = SHA_256.digest(sb.toString().getBytes(StandardCharsets.UTF_8));
            StringBuilder hexString = new StringBuilder();
            for (byte b : hashData) {
                hexString.append(String.format("%02x", b));
            }
            return hexString.toString();
        }

        return null;
    }

    public static void addProcessingRule(Rule rule) {
        // Implement a mechanism to dynamically add and remove processing rules for different data types
    }
}

interface Rule {
    void apply(String input);
}
