char *base_dir = ".";
char *output_dir = NULL;
int verbose = 0;
int quiet = 0;

typedef struct {
    char *input_file;
    FILE *input_fp;
    size_t lines;
    unsigned char digest[MD5_DIGEST_LENGTH];
} ProcessData;

void* hash_file(void *data) {
    ProcessData *pd = (ProcessData*)data;

    if (!fseeko(pd->input_fp, 0, SEEK_SET)) {
        char buffer[BUFFER_SIZE];
        size_t bytes_read;
        MD5_CTX ctx;
        memset(&ctx, 0, sizeof(ctx));

        while ((bytes_read = fread(buffer, 1, BUFFER_SIZE, pd->input_fp)) > 0) {
            MD5_Update(&ctx, buffer, bytes_read);
        }

        fclose(pd->input_fp);
        free(pd->input_file);

        FILE *output_fp = fopen((quiet ? pd->input_file : output_dir)/pd->input_file, "w");
        if (!output_fp) {
            fprintf(stderr, "Error: Could not open file for writing.\n");
            return NULL;
        }

        char hash_str[33];
        base64encode((unsigned char*)&pd->digest, sizeof(pd->digest), (unsigned char*)hash_str);
        fprintf(output_fp, "%s %lld\n", hash_str, pd->lines);
        fclose(output_fp);
    } else {
        fprintf(stderr, "Error: Could not seek to the start of the file.\n");
    }

    free(pd);
    return NULL;
}

void base64encode(const unsigned char *in, size_t in_len, unsigned char *out) {
    // Base64 encoding implementation omitted for brevity
}

void process_file(char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error: Could not open file '%s'.\n", filename);
        return;
    }

    struct stat sb;
    if (stat(filename, &sb) == -1) {
        fprintf(stderr, "Error: Could not stat file '%s'.\n", filename);
        fclose(fp);
        return;
    }

    char *abspath = realpath(filename, NULL);
    if (!abspath) {
        fprintf(stderr, "Error: Could not determine absolute path of file '%s'.\n", filename);
        fclose(fp);
        return;
    }

    size_t lines = 0;
    char buffer[LINES_BUFFER_SIZE];
    while (fgets(buffer, sizeof(buffer), fp)) {
        ++lines;
    }

    ProcessData *pd = malloc(sizeof(ProcessData));
    pd->input_file = abspath;
    pd->input_fp = fp;
    pd->lines = lines;

    pthread_t thread_id;
    pthread_create(&thread_id, NULL, &hash_file, pd);
}

int main(int argc, char *argv[]) {
    int c;
    while ((c = getopt(argc, argv, "b:o:vqh")) != -1) {
        switch (c) {
            case 'b':
                base_dir = optarg;
                break;
            case 'o':
                output_dir = optarg;
                break;
            case 'v':
                verbose++;
                break;
            case 'q':
                quiet++;
                break;
            case 'h':
                printf("Usage: %s [options] \n"
                       "Options:\n"
                       "   -b, --base-dir <directory>      Base directory for relative paths\n"
                       "   -o, --output-dir <directory>    Output directory for storing results\n"
                       "   -v, --verbose                  Increase verbosity of output\n"
                       "   -q, --quiet                    Decrease verbosity of output\n", argv[0]);
                return 0;
            default:
                return 1;
        }
    }

    DIR *dir = opendir(base_dir);
    if (!dir) {
        fprintf(stderr, "Error: Could not open directory '%s'.\n", base_dir);
        return 1;
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        char filepath[1024];
        snprintf(filepath, sizeof(filepath), "%s/%s", base_dir, entry->d_name);

        if (strchr(entry->d_name, '.') == NULL || strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        process_file(filepath);
    }

    closedir(dir);
    return 0;
}
