#define MAX_CACHE 0.5
#define THREAD_POOL_SIZE 16

typedef struct {
    int value;
} Record;

struct CacheNode {
    Record* record;
    struct CacheNode* next;
};

// Global variables for cache and thread pool management
pthread_mutex_t cache_lock;
pthread_cond_t cache_not_full;
struct CacheNode *cache_head = NULL, *cache_tail = NULL;
size_t cache_capacity = 0;
size_t cache_num_elements = 0;
pthread_t thread_pool[THREAD_POOL_SIZE];
bool thread_pool_busy[THREAD_POOL_SIZE] = {false};

void* worker(void *arg) {
    // Implement thread-function logic here
}

Record* create_record() {
    Record* new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) return NULL;
    new_record->value = rand() % 100 + 1;
    return new_record;
}

void* initialize_arrays(long* offsets, int* keys, Record** records, size_t size) {
    long* offset_array = malloc(sizeof(long) * size);
    if (!offset_array) return NULL;
    int* key_array = malloc(sizeof(int) * size);
    if (!key_array) return NULL;
    Record** record_array = malloc(sizeof(Record*) * size);
    if (!record_array) return NULL;

    for (size_t i = 0; i < size; ++i) {
        offset_array[i] = i;
        key_array[i] = rand() % 100 + 1;
        record_array[i] = create_record();
        if (!record_array[i]) return NULL;
    }
    return (void*){offset_array, key_array, record_array};
}

Record* get_or_add(long offset) {
    pthread_mutex_lock(&cache_lock);
    struct CacheNode *iter = cache_head;

    while (iter != NULL) {
        if (iter->record->offset == offset) {
            pthread_mutex_unlock(&cache_lock);
            return iter->record;
        }
        iter = iter->next;
    }

    Record* new_record = create_record();
    if (!new_record) {
        pthread_mutex_unlock(&cache_lock);
        return NULL;
    }
    new_record->offset = offset;

    if (cache_num_elements + 1 > cache_capacity * MAX_CACHE) {
        struct CacheNode* least_recently_used = cache_head;
        size_t remove_index = 0;

        while (least_recently_used != NULL && cache_num_elements > 0) {
            if (cache_num_elements <= 1 || rand() % (least_recently_used->offset - remove_index) < (cache_head->offset - remove_index)) {
                least_recently_used = least_recently_used->next;
                remove_index++;
            } else {
                Record* record_to_remove = least_recently_used->record;
                free(record_to_remove);
                cache_num_elements--;
                free(least_recently_used);
            }
        }
    }

    Record* new_cache_node = (Record*)malloc(sizeof(Record));
    if (!new_cache_node) {
        pthread_mutex_unlock(&cache_lock);
        return NULL;
    }
    new_cache_node->offset = offset;
    new_cache_node->record = new_record;

    if (cache_num_elements == 0) {
        cache_head = cache_tail = new_cache_node;
    } else {
        cache_tail->next = new_cache_node;
        cache_tail = new_cache_node;
    }
    cache_num_elements++;

    pthread_mutex_unlock(&cache_lock);
    return new_record;
}

void cleanup() {
    pthread_mutex_destroy(&cache_lock);
    pthread_cond_destroy(&cache_not_full);

    Record* iter = cache_head;
    while (iter != NULL) {
        Record* temp = iter;
        iter = iter->next;
        free(temp->record);
        free(temp);
    }

    for (size_t i = 0; i < THREAD_POOL_SIZE; ++i) {
        pthread_join(thread_pool[i], NULL);
    }
}
