#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdbool.h>

typedef struct Record {
    long offset;
    int key;
    double value;
} Record;

typedef struct Collection {
    size_t size;
    Record* data;
    double min_value, max_value;
    long default_offset, default_key;
} Collection;

void print_error(const char* message) {
    fprintf(stderr, "[ERROR] %s\n", message);
}

Collection* create_collection(size_t size, double min_value, double max_value, long default_offset, int default_key) {
    Collection* collection = malloc(sizeof(Collection));
    if (!collection) print_error("Out of memory");
    collection->size = size;
    collection->min_value = min_value;
    collection->max_value = max_value;
    collection->default_offset = default_offset;
    collection->default_key = default_key;
    if (!populate(collection)) {
        free(collection);
        print_error("Memory allocation failure");
        return NULL;
    }
    return collection;
}

bool populate(Collection* collection) {
    collection->data = calloc(collection->size, sizeof(Record));
    if (!collection->data) {
        print_error("Memory allocation failure");
        return false;
    }
    srand(time(NULL));
    for (size_t i = 0; i < collection->size; ++i) {
        collection->data[i].offset = collection->default_offset + i;
        collection->data[i].key = rand() % ((int)(collection->max_value - collection->min_value)) + (int)collection->min_value;
        collection->data[i].value = (double)((rand() % 100) / 100.0) * (collection->max_value - collection->min_value) + collection->min_value;
    }
    return true;
}

Record* get_record(Collection* collection, size_t index) {
    if (index >= collection->size) {
        Record default_record = { .offset = collection->default_offset, .key = collection->default_key, .value = 0.0 };
        return &default_record;
    }
    return &collection->data[index];
}

void set_record(Collection* collection, size_t index, double new_value) {
    if (index >= collection->size) print_error("Index out of bounds");

    Record* record = get_record(collection, index);
    if (new_value < collection->min_value || new_value > collection->max_value) {
        print_error("Value out of range");
        return;
    }
    record->value = new_value;
}

void destroy_collection(Collection* collection) {
    free(collection->data);
    free(collection);
