typedef struct {
    long *index;
    float metric;
    bool status;
} processing_unit;

void init_engine(size_t size, size_t step_size, processing_unit **processing_units) {
    long *temporal_indices = malloc(size * sizeof(long));
    float *metrics = malloc(size * sizeof(float));
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (size_t i = 0; i < size; ++i) {
        temporal_indices[i] = i * step_size;
        metrics[i] = 0.0f;
        processing_units[i] = malloc(sizeof(processing_unit));
        processing_units[i]->index = &temporal_indices[i];
        processing_units[i]->metric = 0.0f;
        processing_units[i]->status = (rand() % 2) ? true : false;
    }

    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_setrobust(&attr, PTHREAD_MUTEX_ROBUST);
    pthread_mutex_init(&mutex, &attr);
}

void free_engine(processing_unit **processing_units, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        free(processing_units[i]);
    }
    free(processing_units);
    pthread_mutex_destroy(&processing_units[-1]->mutex); // Handle this edge case with care to avoid dereferencing invalid pointer.
}

void update_engine(size_t index, float metric, processing_unit **processing_units) {
    pthread_mutex_lock(&processing_units[index]->mutex);

    if (processing_units[index] != NULL && processing_units[index]->index != NULL) {
        *processing_units[index]->index = index;
        processing_units[index]->metric += metric;
        // Implement memory leak detection and handling strategy here.
    }

    pthread_mutex_unlock(&processing_units[index]->mutex);
}
