// Cache data structure and LRU policy (adapted for thread-safety)
typedef struct _cache_entry {
    char *key;
    char *value;
    time_t last_access;
} cache_entry;

typedef struct _lru_cache {
    size_t capacity;
    size_t size;
    cache_entry *entries;
    pthread_mutex_t mutex;
    pthread_rwlock_t rw_lock; // Read-write lock for concurrent access
} lru_cache;

void lru_cache_init(lru_cache *cache, size_t capacity) {
    cache->capacity = capacity;
    cache->size = 0;
    cache->entries = calloc(capacity, sizeof(cache_entry));
    if (!cache->entries) {
        fprintf(stderr, "Failed to allocate cache entries\n");
        exit(1);
    }
    cache->mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_rwlock_init(&cache->rw_lock, NULL);
}

void lru_cache_free(lru_cache *cache) {
    size_t i;
    for (i = 0; i < cache->capacity; ++i) {
        if (cache->entries[i].key)
            free(cache->entries[i].key);
        if (cache->entries[i].value)
            free(cache->entries[i].value);
    }
    free(cache->entries);
}

