typedef struct DecryptParams {
    char *password;
    void *config_settings;
    void (*callback)(char*);
    int timeout;
} DecryptParams;

// Constant-time comparison function
int ctcmp(const char *a, const char *b) {
    int alen = strlen(a);
    int blen = strlen(b);
    if (alen != blen) return alen < blen;
    int i;
    for (i = 0; i < alen; ++i) {
        if (a[i] < b[i]) return -1;
        if (a[i] > b[i]) return 1;
    }
    return 0;
}

sem_t sem_decryption_limit; // Semaphore for limiting concurrent decryption operations

void log_event(const char *message) {
    openlog("decrypt", LOG_PID, LOG_DAEMON);
    syslog(LOG_INFO, message);
    closelog();
}

// Decryption function
int decrypt(DecryptParams *params) {
    if (!params || !params->password || strlen(params->password) == 0 ||
        !params->config_settings || !params->callback || params->timeout <= 0) {
        log_event("Invalid parameters");
        return -1;
    }

    int sockfd = connect_and_validate_connection(params->config_settings);
    if (sockfd < 0) {
        log_event("Connection failed");
        return -2;
