#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <sys/mman.h>

typedef struct Record {
    int value;
    char status_flag;
    char* keyword;
    time_t timestamp;
} Record;

const char* keywords[] = {"apple", "banana", "cherry", "date", "elderberry"};
const int MAX_CACHE_SIZE = 10000;
const int RECORD_ALIGNMENT = 64;
const int KEY_OFFSET_STRIDE = sizeof(int) * 2;
const int VALUE_OFFSET_STRIDE = sizeof(Record);

struct CacheNode {
    Record* record;
    struct CacheNode* prev, * next;
};

struct Cache {
    struct CacheNode** head;
    struct CacheNode** tail;
    int* key_offsets;
    int size, capacity;
    pthread_mutex_t lock;
};

void cache_init(struct Cache* cache) {
    cache->head = calloc((cache->capacity = 2 * MAX_CACHE_SIZE), sizeof(struct CacheNode*));
    cache->tail = cache->head + cache->capacity;
    cache->key_offsets = mmap(NULL, KEY_OFFSET_STRIDE * cache->capacity, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0);
    if (cache->key_offsets == MAP_FAILED) {
        fprintf(stderr, "Memory allocation failure\n");
        exit(EXIT_FAILURE);
    }

    cache->size = 0;
    pthread_mutex_init(&cache->lock, NULL);
}

void cache_destroy(struct Cache* cache) {
    munmap(cache->key_offsets, KEY_OFFSET_STRIDE * cache->capacity);
    free(cache->head);
    pthread_mutex_destroy(&cache->lock);
}

int get_key_offset(const struct Cache* cache, int key) {
    int offset = (key % cache->capacity) * KEY_OFFSET_STRIDE;
    return *(cache->key_offsets + offset);
}

void set_key_offset(struct Cache* cache, int key, int offset) {
    int offset2 = get_key_offset(cache, key);
    if (offset2 != offset) {
        *(cache->key_offsets + offset2) = offset;
        *(cache->key_offsets + offset) = offset2;
    }
}

void add_record(struct Cache* cache, Record* record) {
    pthread_mutex_lock(&cache->lock);

    struct CacheNode* node = (struct CacheNode*)malloc(sizeof(struct CacheNode));
    if (!node) {
        fprintf(stderr, "Memory allocation failure\n");
        pthread_mutex_unlock(&cache->lock);
        return;
    }

    node->record = record;
    node->prev = node->next = NULL;

    int key_offset = get_key_offset(cache, record->value);
    struct CacheNode* list_head = cache->head[key_offset];
    if (list_head) {
        list_head->prev->next = node;
        node->prev = list_head->prev;
        list_head->prev = node;
        node->next = list_head;
    } else {
        cache->head[key_offset] = cache->tail[key_offset] = node;
    }

    cache->size++;

    pthread_mutex_unlock(&cache->lock);
}

Record* get_record(const struct Cache* cache, int key) {
    pthread_mutex_lock(&cache->lock);

    int key_offset = get_key_offset(cache, key);
    struct CacheNode* list_head = cache->head[key_offset];
    Record* record;

    if (list_head) {
        for (struct CacheNode* node = list_head; node != NULL; node = node->next) {
            if (node->record->value == key) {
                record = node->record;
                break;
            }
        }
    }

    pthread_mutex_unlock(&cache->lock);
    return record;
}

void remove_record(struct Cache* cache, int key) {
    pthread_mutex_lock(&cache->lock);

    int key_offset = get_key_offset(cache, key);
    struct CacheNode* list_head = cache->head[key_offset];

    if (list_head) {
        for (struct CacheNode* node = list_head; node != NULL; node = node->next) {
            if (node->record->value == key) {
                if (node == list_head)
                    list_head = list_head->next;
                if (node->next)
                    node->next->prev = node->prev;
                if (node->prev)
                    node->prev->next = node->next;

                free(node->record);
                free(node);

                cache->size--;
                break;
            }
        }
    }

    pthread_mutex_unlock(&cache->lock);
}
```

This code provides a basic implementation of the requested cache in C. It uses a doubly linked list to manage records based on unique keys, supports addition, removal, and retrieval of records, and allocates memory for an array of record structures and arrays for storing long offsets and integer keys. Error handling is included for memory allocation failures.

The function `cache_init` initializes the cache data structures, while `cache_destroy` frees allocated resources. The functions `get_key_offset`, `set_key_offset`, `add_record`, `get_record`, and `remove_record` manage adding, retrieving, and removing records from the cache.']

