```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct Entry {
    double* value;
    char label[64];
    time_t timestamp;
} entry;

entry** data = NULL;
size_t capacity = 0, size = 0;
entry** cache = NULL;
size_t cache_capacity = 0, cache_size = 0;

void validate_timestamp(time_t* t) {
    time_t now = time(NULL);
    if (*t < now - 3600 || *t > now + 3600) {
        *t = now;
    }
}

size_t find_entry(const char* label) {
    for (size_t i = 0; i < size; ++i) {
        if (!strcmp(data[i]->label, label)) {
            return i;
        }
    }
    return SIZE_MAX;
}

entry* get_or_create_entry(const char* label) {
    size_t index = find_entry(label);
    if (index != SIZE_MAX && data[index]->value) {
        return data[index];
    }

    if (size == capacity) {
        reallocate();
    }

    entry* new_entry = data[size];
    strcpy(new_entry->label, label);
    new_entry->timestamp = time(NULL);
    validate_timestamp(&new_entry->timestamp);
    return new_entry;
}

void reallocate() {
    entry** tmp = (entry**)realloc(data, capacity * 2 * sizeof(entry*));
    if (!tmp) {
        fprintf(stderr, "Out of memory error\n");
        exit(EXIT_FAILURE);
    }
    data = tmp;
    capacity *= 2;
}

void update_cache(size_t index) {
    if (cache_size == cache_capacity) {
        reallocate_cache();
    }
    cache[cache_size++] = data[index];
}

void reallocate_cache() {
    entry** tmp = (entry**)realloc(cache, cache_capacity * 2 * sizeof(entry*));
    if (!tmp) {
        fprintf(stderr, "Out of memory error\n");
        exit(EXIT_FAILURE);
    }
    cache = tmp;
    cache_capacity *= 2;
}

entry* get_cached_entry(size_t index) {
    if (index >= cache_size || !cache[index]) return NULL;
    return cache[index];
}

double* get_value(const char* label, bool update) {
    size_t index = find_entry(label);
    entry* e = index != SIZE_MAX ? data[index] : NULL;

    if (!e || !e->value && update) {
        e = get_or_create_entry(label);
    }

    if (e && e->value) {
        if (!update || get_cached_entry(index)) return e->value;
        update_cache(index);
        return e->value;
    }

    return NULL;
}

void free_data() {
    for (size_t i = 0; i < size; ++i) {
        free(data[i]->label);
        if (data[i]->value) free(data[i]->value);
        free(data[i]);
    }
    free(data);
}
```

