typedef struct UserProfile {
    int id;
    char name[256];
    int age;
    char email[256];
    struct UserProfile* next;
    struct UserProfile* prev;
} UserProfile;

typedef struct HashTableNode {
    UserProfile* data;
    struct HashTableNode* next;
} HashTableNode;

typedef struct {
    pthread_mutex_t lock;
    unsigned long capacity;
    HashTableNode** table;
    UserProfile* head;
    UserProfile* tail;
    size_t count;
    pthread_cond_t cond_not_empty;
} ProfileCollection;

void init_profile_collection(ProfileCollection* collection, unsigned long capacity) {
    collection->capacity = capacity;
    collection->table = calloc(capacity, sizeof(HashTableNode*));
    if (!collection->table) {
        fprintf(stderr, "Memory allocation error\n");
        exit(1);
    }
}

unsigned long hash_function(const char* key, unsigned long capacity) {
    unsigned long hash = 5381;
    int c;
    while ((c = *key++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    return hash % capacity;
}

UserProfile* create_user_profile(const char* name, int age, const char* email) {
    UserProfile* profile = (UserProfile*) malloc(sizeof(UserProfile));
    if (!profile) {
        fprintf(stderr, "Memory allocation error\n");
        return NULL;
    }
    strcpy(profile->name, name);
    profile->age = rand() % 100 + 18; // random age within [18, 108]
    strcpy(profile->email, email);
    return profile;
}

void add_to_list(ProfileCollection* collection, UserProfile* profile) {
    pthread_mutex_lock(&collection->lock);
    if (!collection->head) {
        collection->head = profile;
        collection->tail = profile;
    } else {
        collection->tail->next = profile;
        profile->prev = collection->tail;
        collection->tail = profile;
    }
    ++collection->count;
    pthread_cond_signal(&collection->cond_not_empty);
    pthread_mutex_unlock(&collection->lock);
}

HashTableNode* get_hash_table_node(ProfileCollection* collection, unsigned long hash) {
    if (collection->table[hash] == NULL) {
        HashTableNode* node = (HashTableNode*) malloc(sizeof(HashTableNode));
        if (!node) {
            fprintf(stderr, "Memory allocation error\n");
            return NULL;
        }
        node->data = NULL;
        node->next = collection->table[hash];
        collection->table[hash] = node;
    }
    return collection->table[hash];
}

void add_to_hash_table(ProfileCollection* collection, UserProfile* profile) {
    unsigned long hash = hash_function(profile->name, collection->capacity);
    HashTableNode* current = get_hash_table_node(collection, hash);
    while (current->data != NULL) {
        if (current->data->id == profile->id) {
            free(profile);
            return;
        }
        current = current->next;
    }
    current->data = profile;
}

int find_by_id(ProfileCollection* collection, int id) {
    pthread_mutex_lock(&collection->lock);
    UserProfile* current = collection->head;
    while (current != NULL) {
        if (current->id == id) {
            break;
        }
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&collection->lock);
        return -1; // profile not found
    }

    UserProfile* temp = current;
    pthread_mutex_unlock(&collection->lock);

    // remove from list and hash table
    if (current == collection->head) {
        collection->head = current->next;
    }
    if (current->next != NULL) {
        current->next->prev = current->prev;
    }
    if (current->prev != NULL) {
        current->prev->next = current->next;
    }
    if (collection->tail == current) {
        collection->tail = current->prev;
    }
    --collection->count;

    HashTableNode* hash_node = get_hash_table_node(collection, hash);
    while (hash_node->data != NULL && hash_node->data->id != id) {
        hash_node = hash_node->next;
    }
    if (hash_node->data == NULL) {
        fprintf(stderr, "Internal inconsistency\n");
        return -1; // should never happen
    }
    HashTableNode* to_free = hash_node;
    hash_node = hash_node->next;
    free(to_free);

    return 0; // profile found and removed
}

