#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <stdbool.h>

typedef struct Module {
    int id;
    char version[20];
    time_t release_date;
    struct Dependency *dependencies;
    size_t num_dependencies;
} Module;

typedef struct Dependency {
    int id;
    struct Module *module;
} Dependency;

struct HashTable {
    size_t capacity;
    struct Module **table;
    pthread_mutex_t lock;
};

struct ListNode {
    struct Module module;
    struct ListNode *next;
};

void hash_table_init(struct HashTable *hash_table, size_t capacity) {
    hash_table->capacity = capacity;
    hash_table->table = calloc(capacity, sizeof(Module*));
    if (!hash_table->table) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    pthread_mutex_init(&hash_table->lock, NULL);
}

size_t hash(int id) {
    return id % hash_table->capacity;
}

void list_insert(struct ListNode **head, struct Module module) {
    struct ListNode *new_node = malloc(sizeof(struct ListNode));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    new_node->module = module;
    new_node->next = *head;
    *head = new_node;
}

struct ListNode* list_remove(struct ListNode **head, int id) {
    struct ListNode *current = *head;
    struct ListNode *prev = NULL;

    while (current != NULL && current->module.id != id) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        return NULL;
    }

    if (prev == NULL) {
        *head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    return current;
}

Module* hash_table_get(struct HashTable *hash_table, int id) {
    pthread_mutex_lock(&hash_table->lock);
    size_t index = hash(id);
    Module *module = hash_table->table[index];

    while (module != NULL && module->id != id) {
        module = module->next;
    }

    pthread_mutex_unlock(&hash_table->lock);
    return module;
}

int is_valid(struct Module *module, struct HashTable *hash_table) {
    for (size_t i = 0; i < module->num_dependencies; ++i) {
        Dependency dependency = module->dependencies[i];
        struct Module *dependent = hash_table_get(hash_table, dependency.id);

        if (!dependent) {
            return false;
        }

        for (size_t j = 0; j < dependent->num_dependencies; ++j) {
            Dependency dep = dependent->dependencies[j];
            if (dep.id == module->id) {
                return false; // Circular dependency detected
            }
        }
    }

    return true;
}

void cleanup(struct HashTable *hash_table) {
    pthread_mutex_lock(&hash_table->lock);
    for (size_t i = 0; i < hash_table->capacity; ++i) {
        Module *module = hash_table->table[i];
        while (module != NULL) {
            struct ListNode *next = module->next;
            free(module);
            module = next;
        }
    }
    pthread_mutex_unlock(&hash_table->lock);
}
