class RandomValueGenerator {
private:
    int minValue;
    int maxValue;

public:
    explicit RandomValueGenerator(int min, int max) : minValue(min), maxValue(max) {}

    int getRandomInt() const { return rand() % (maxValue - minValue + 1) + minValue; }
    float getRandomFloat() const { return static_cast<float>(getRandomInt()) / (static_cast<float>(maxValue - minValue + 1)); }
    std::string ToString() const { return std::to_string(minValue) + " - " + std::to_string(maxValue); }
};

struct Record {
    int value;
    char status;
    std::unique_ptr<char[]> name;
};

std::vector<long> offsets;
std::vector<int> keys;
std::vector<Record> records;
std::list<Record*> linkedList;

void manageRecords(RandomValueGenerator& generator, int numRecords) {
    srand(time(0)); // Initialize random seed

    // Initialize offsets and keys with specific patterns
    long currentOffset = 0;
    for (int i = 0; i < numRecords; ++i) {
        offsets.push_back(currentOffset);
        currentOffset += sizeof(Record);
        keys.push_back(i);
    }

    // Initialize records with random values and dynamically allocated names
    for (auto& record : records) {
        record.value = generator.getRandomInt();
        record.status = 'A'; // Set status to 'A' by default
        size_t nameLength = static_cast<size_t>(generator.getRandomInt(20)); // Generate random string length up to 20 characters
        std::unique_ptr<char[]> name(new char[nameLength + 1]);
        for (size_t i = 0; i < nameLength; ++i) {
            name[i] = static_cast<char>(generator.getRandomInt('z' - 'a') + 'a');
        }
        name[nameLength] = '\0'; // Null terminate the string
        record.name = std::move(name);
    }

    // Connect records in the linked list
    for (size_t i = 0; i < records.size(); ++i) {
        Record* currentRecord = &records[i];
        linkedList.push_back(currentRecord);
        if (i + 1 < records.size()) {
            Record* nextRecord = &records[i + 1];
            currentRecord->name.reset(static_cast<char*>(std::realloc(currentRecord->name.get(), sizeof(long) + sizeof(Record))));
            std::copy(reinterpret_cast<const char*>(&offsets[i]), reinterpret_cast<const char*>(&offsets[i + 1]), currentRecord->name.get() + sizeof(long));
            linkedList.back()->name.reset(currentRecord->name.release());
        }
    }
}
