use std::env;
use std::fs::{self, File};
use std::io::{BufWriter, Write};
use std::path::{Path, PathBuf};
use std::sync::Mutex;

static MUTEX: Mutex<()> = Mutex::new(());

fn create_directory(dir: &Path) {
    let mut path = dir.to_owned();
    if path.is_file() {
        panic!("Directory already exists as a file");
    }
    if !path.exists() {
        fs::create_dir_all(&path).unwrap();
    }
}

fn get_env_var(key: &str) -> PathBuf {
    let path = env::var(key).expect("Environment variable not found");
    let resolved_path = Path::new(&path);

    if !resolved_path.is_dir() {
        panic!("Path from environment variable is not a directory");
    }

    resolved_path.canonicalize().unwrap()
}

fn generate_default_path(prefix: &str) -> PathBuf {
    let mut path = get_env_var("TEMP").into_owned();
    path.push(prefix);
