["Here's a simple implementation using an AVL tree (self-balancing binary search tree) for efficient key lookup, updates, and additions, along with a custom `record_set` structure that manages memory allocation and compaction. I've used pthreads for concurrent access and locking:

```c
#include <pthread.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/mman.h>

typedef struct record {
    long offset;
    int key;
    int value;
} record;

typedef struct avl_node {
    record data;
    struct avl_node *left, *right;
    int height;
} avl_node;

typedef struct avl_tree {
    avl_node *root;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} avl_tree;

int get_height(avl_node *n) {
    return n ? n->height : 0;
}

int balance_factor(avl_node *n) {
    return get_height(n->right) - get_height(n->left);
}

void rotate_right(avl_tree *t, avl_node **node) {
    avl_node *parent = (*node)->left;
    (*node)->left = parent->right;
    parent->right = *node;
    if ((*node)->left)
        (*node)->left->parent = *node;
    *node = parent;
}

void rotate_left(avl_tree *t, avl_node **node) {
    avl_node *parent = (*node)->right;
    (*node)->right = parent->left;
    parent->left = *node;
    if ((*node)->right)
        (*node)->right->parent = *node;
    *node = parent;
}

void rebalance(avl_tree *t, avl_node **n) {
    if (balance_factor(*n) == 2) {
        if (balance_factor((*n)->right) < 0)
            rotate_left(t, n);
        rotate_right(t, n);
    } else if (balance_factor(*n) == -2) {
        if (balance_factor((*n)->left) > 0)
            rotate_right(t, n);
        rotate_left(t, n);
    }
}

void update_height(avl_tree *t, avl_node *n) {
    int h1 = get_height(n->left);
    int h2 = get_height(n->right);
    n->height = (h1 > h2 ? h1 : h2) + 1;
}

void insert(avl_tree *t, record data) {
    avl_node **n = &t->root;
    avl_node **parent = &t->root;

    while (*n) {
        parent = n;
        if (data.key < ((*n)->data.key))
            n = &((*n)->left);
        else
            n = &((*n)->right);
    }

    avl_node *newNode = malloc(sizeof(avl_node));
    newNode->data = data;
    newNode->parent = *parent;
    newNode->left = NULL;
    newNode->right = NULL;
    newNode->height = 1;

    if (!*parent)
        t->root = newNode;
    else if (data.key < ((*parent)->data.key))
        (*parent)->left = newNode;
    else
        (*parent)->right = newNode;

    rebalance(t, parent);
    update_height(t, t->root);
}

void remove(avl_tree *t, avl_node **n) {
    if (!(*n)) return;

    if (!((*n)->left) && !((*n)->right)) {
        free(*n);
        (*n) = NULL;
    } else if (!((*n)->right)) {
        avl_node *temp = (*n)->left;
        free(*n);
        *n = temp;
    } else if (!((*n)->left)) {
        avl_node *temp = (*n)->right;
        free(*n);
        *n = temp;
    } else {
        avl_node *minRight = find_min(t, &(*n)->right);
        minRight->parent->left = NULL;
        *n = minRight;
        (*n)->parent = NULL;
    }
}

avl_node *find_min(avl_tree *t, avl_node **n) {
    while ((*n)->left) n = &(*n)->left;
    return *n;
}

record find(avl_tree *t, int key) {
    avl_node *n = t->root;

    while (n) {
        if (key == n->data.key) return n->data;
        n = key < n->data.key ? n->left : n->right;
    }

    return (record){0};
}

void compact(avl_tree *t) {
    // Implement memory compaction logic, e.g., by reallocating storage and moving active records to new positions
}

void record_set_init(record_set *rs, size_t capacity) {
    rs->capacity = capacity;
    rs->size = 0;
    pthread_mutex_init(&rs->lock, NULL);

    rs->avl = mmap(NULL, sizeof(avl_tree), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    avl_tree *avltree = (avl_tree *)rs->avl;
    avltree->root = NULL;
}

void record_set_destroy(record_set *rs) {
    munmap(rs->avl, sizeof(avl_tree));
    pthread_mutex_destroy(&rs->lock);
}

void add_record(record_set *rs, long offset, int key, int value) {
    record r = {offset, key, value};
    pthread_mutex_lock(&rs->lock);
    insert((avl_tree *)rs->avl, r);
    if (rs->size >= 0.6 * rs->capacity) compact((avl_tree *)rs->avl);
    pthread_mutex_unlock(&rs->lock);
}

record get_record(record_set *rs, int key) {
    pthread_mutex_lock(&rs->lock);
    record r = find((avl_tree *)rs->avl, key);
    pthread_mutex_unlock(&rs->lock);
    return r;
}
```

