#include <adbtree.h> // Balanced Adaptive Hash Table (balanced tree implementation)

typedef struct _file_metadata {
    int status;
    char* path;
    struct stat st;
    void* perm; // File permissions structure
} file_metadata;

pthread_mutex_t metadata_lock = PTHREAD_MUTEX_INITIALIZER;
adbtree* metadata_tree = NULL;

int add_file(const char* path) {
    pthread_mutex_lock(&metadata_lock);
    struct stat st;
    if (stat(path, &st) == -1) return -1; // Error handling

    file_metadata* metadata = malloc(sizeof(file_metadata));
    if (!metadata) {
        pthread_mutex_unlock(&metadata_lock);
        return -1; // Memory allocation failure
    }

    metadata->status = 0; // Assuming files are valid by default (modify as needed)
    metadata->path = strdup(path);
    if (!metadata->path) {
        free(metadata);
        pthread_mutex_unlock(&metadata_lock);
        return -1; // Memory allocation failure
    }

    memcpy(&metadata->st, &st, sizeof(st));
    metadata->perm = calloc(1, 4 * sizeof(int)); // Assuming file permissions are represented as 4 ints
    if (!metadata->perm) {
        free(metadata->path);
        free(metadata);
        pthread_mutex_unlock(&metadata_lock);
        return -1; // Memory allocation failure
    }

    adbtree_insert(metadata_tree, &metadata->st.st_mtime, metadata);
    pthread_mutex_unlock(&metadata_lock);

    return 0;
}

int remove_file(const char* path) {
    pthread_mutex_lock(&metadata_lock);
    file_metadata* metadata = adbtree_find(metadata_tree, &((struct stat*)&path)->st_mtime);
    if (!metadata) {
        pthread_mutex_unlock(&metadata_lock);
        return -1; // File not found
    }

    adbtree_remove(metadata_tree, &metadata->st.st_mtime);
    free(metadata->path);
    free(metadata->perm);
    free(metadata);
    pthread_mutex_unlock(&metadata_lock);

    return 0;
}

file_metadata* get_file_by_mtime(time_t mtime) {
    pthread_mutex_lock(&metadata_lock);
    file_metadata* metadata = adbtree_find(metadata_tree, &mtime);
    pthread_mutex_unlock(&metadata_lock);

    return metadata;
}
