        pthread_create(init_threads + i, NULL, service_initialization, &services[i]);
    }

    for (size_t i = 0; i < 3; ++i) {
        pthread_join(init_threads[i], NULL);
    }

    for (size_t i = 0; i < config->services_count; ++i) {
        if (!config->services[i]->initialized) {
            fprintf(stderr, "Service %zu initialization failed\n", i);
            return -3;
        }
