    time_t timestamp;
} Record;

typedef struct CacheNode {
    Record record;
    struct CacheNode* prev;
    struct CacheNode* next;
} CacheNode;

const int MAX_CACHE_SIZE = 1000000;
const int KEYWORDS_COUNT = 1000;
const int KEYWORDS_ARRAY_SIZE = KEYWORDS_COUNT * sizeof(char*);
const int LONG_OFFSETS_ARRAY_SIZE = MAX_CACHE_SIZE * sizeof(int);

CacheNode* cache_head = NULL;
CacheNode* cache_tail = NULL;
CacheNode** long_offsets = malloc(LONG_OFFSETS_ARRAY_SIZE);
int* keys = calloc(MAX_CACHE_SIZE, sizeof(int));

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void generate_keywords() {
    // Populate keywords array with unique random strings
}

Record create_record(char* keyword) {
    Record record;
    record.value = rand();
    record.status_flag = 'A';
    record.key = strdup(keyword);
    record.timestamp = time(NULL);
    return record;
}

void add_to_cache(Record* record) {
    pthread_mutex_lock(&mutex);
    CacheNode* new_node = malloc(sizeof(CacheNode));
    if (!new_node) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    new_node->record = *record;
    new_node->prev = NULL;
    new_node->next = NULL;

    if (!cache_head) {
        cache_head = new_node;
        cache_tail = new_node;
    } else {
        cache_tail->next = new_node;
        new_node->prev = cache_tail;
        cache_tail = new_node;
    }

    int index = hash(record->key);
    long_offsets[index] = (long)cache_head - sizeof(CacheNode);
    keys[index] = record->key;

    pthread_mutex_unlock(&mutex);
}

void remove_from_cache(int key) {
    pthread_mutex_lock(&mutex);

    int index = hash(keys[key]);
    CacheNode* node = (CacheNode*)long_offsets[index];

    while (node) {
        if (node->record.key == keys[key]) {
            if (node == cache_head) {
                cache_head = node->next;
            } else if (node == cache_tail) {
                cache_tail = node->prev;
            }

            if (node->prev) {
                node->prev->next = node->next;
            }
            if (node->next) {
                node->next->prev = node->prev;
            }

            free(node->record.key);
            free(node);

            pthread_mutex_unlock(&mutex);
            return;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&mutex);
}

Record get_from_cache(int key) {
    pthread_mutex_lock(&mutex);

    int index = hash(keys[key]);
    CacheNode* node = (CacheNode*)long_offsets[index];

    Record result;
    memcpy(&result, &node->record, sizeof(Record));

    pthread_mutex_unlock(&mutex);
    return result;
}

int hash(char* key) {
    uint32_t hash = 5381;
    int c;

    while ((c = *key++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

    return hash % MAX_CACHE_SIZE;
}

