static pthread_mutex_t rand_mutex;
static pthread_once_t once_control = PTHREAD_ONCE_INIT;
static unsigned long seed;

void init_random() {
    pthread_mutex_lock(&rand_mutex);
    srand(seed);
    pthread_mutex_unlock(&rand_mutex);
}

int DynamicRecordSerializer(size_t max_records, size_t max_memory) {
    if (max_records * sizeof(Record) + num_records * sizeof(struct record) > max_memory) {
        fprintf(stderr, "Memory limit exceeded\n");
        return -1;
    }

    sem_init(&mutex, 0, 1);

    size_t record_size = sizeof(Record) + num_records * sizeof(struct record);
    void *memory_pool = mmap(NULL, max_records * record_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (memory_pool == MAP_FAILED) {
        perror("mmap");
        return -1;
    }

    Record *records = memory_pool;
    struct record *data = (struct record *)((char *)records + sizeof(Record) * max_records);

    for (size_t i = 0; i < max_records; ++i) {
        records[i].data = data + i;
    }

    pthread_mutex_init(&rand_mutex, NULL);
    seed = time(NULL);

    num_records = max_records;
    this_max_memory = max_memory;

    return 0;
}

void log(enum LOG_LEVEL level, const char *message) {
    if (strcmp(LOG_TARGET, "console") == 0) {
        printf("[%s] %s\n", get_log_level_name(level), message);
    } else if (strcmp(LOG_TARGET, "file") == 0) {
        FILE *log_file = fopen("logs.txt", "a");
        fprintf(log_file, "[%s] %s\n", get_log_level_name(level), message);
        fclose(log_file);
    } else if (strcmp(LOG_TARGET, "syslog") == 0) {
        openlog("DynamicRecordSerializer", LOG_NDELAY | LOG_PID, LOG_LOCAL0);
        syslog(level, "%s", message);
        closelog();
    }
}

char *get_log_level_name(enum LOG_LEVEL level) {
