using System.Threading.Tasks;

public class ResourceScheduler
{
    private int _maxResources = int.MaxValue;
    private int _availableResources;

    private readonly PriorityQueue<Task> _tasks;

    public ResourceScheduler(int maxResources = int.MaxValue)
    {
        EnsureValidLimits(maxResources);
        _availableResources = maxResources;
        _tasks = new PriorityQueue<Task>();
    }

    private void EnsureValidLimits(int maxResources)
    {
        if (maxResources <= 0)
            throw new ArgumentOutOfRangeException(nameof(maxResources), "Maximum resources must be greater than zero.");
    }

    public int RequestResource(int quantity)
    {
        var requestQuantity = Math.Min(quantity, _availableResources);
        if (requestQuantity > 0)
            Interlocked.Add(ref _availableResources, -requestQuantity);
        return requestQuantity;
    }

    public void ReleaseResource(int quantity)
    {
        var releaseQuantity = Math.Min(quantity, _availableResources);
        if (releaseQuantity > 0)
            Interlocked.Add(ref _availableResources, releaseQuantity);
    }

    public int GetAvailableResources()
    {
        return Math.Min(_availableResources, _maxResources);
    }

    public void ScheduleTask(Task task)
    {
        task.UrgencyLevel = task.UrgencyLevel ?? 0;
        _tasks.Enqueue(task);
    }

    public override string ToString()
    {
        var tasksList = string.Join("\n", _tasks.OrderByDescending(t => t.UrgencyLevel).Select(t => t.ToString()));
        return $"ResourceScheduler:\nAvailable Resources: {GetAvailableResources()} \nTasks ({_tasks.Count} total):\n{tasksList}";
    }

    private class Task
    {
