typedef struct Node {
    int key;
    int value;
    char status;
    size_t len;
    char *str;
    struct Node *next;
} Node;

typedef struct HashTable {
    int size;
    Node **table;
} HashTable;

void init_hash_table(HashTable *ht, int size) {
    ht->size = size;
    ht->table = calloc(size, sizeof(Node*));
}

int hash(int key, int table_size) {
    return key % table_size;
}

void insert_record(HashTable *ht, Node **table, Node *node) {
    int h = hash(node->key, ht->size);

    if (!*table[h]) {
        *table[h] = node;
    } else {
        Node *curr = *table[h];
        while (curr->next) {
            curr = curr->next;
        }
        curr->next = node;
    }
}

void free_record(Node *node) {
    if (node) {
        free(node->str);
        free(node);
    }
}

void free_list(Node **head) {
    Node *temp;
    while (*head) {
        temp = *head;
        *head = (*head)->next;
        free_record(temp);
    }
}

Node* create_node(int key, int value, char status, size_t len, char *str) {
    Node *node = malloc(sizeof(Node));
    node->key = key;
    node->value = value;
    node->status = status;
    node->len = len;
    node->str = strdup(str);
    node->next = NULL;
    return node;
}

void process_stream(FILE *in, HashTable *ht) {
