['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sys/mman.h>

typedef struct {
    int value;
    int status;
    char *key;
} Record;

typedef struct HashTableNode {
    Record *record;
    struct HashTableNode *next;
} HashTableNode;

const unsigned long HASH_SIZE = 1024; // Initial hash table size
unsigned long hash(const char *key) {
    unsigned long hash = 5381;
    int c;

    while ((c = *key++))
        hash = (hash << 5) + hash + c; /* hash * 33 + c */

    return hash % HASH_SIZE;
}

HashTableNode **create_hash_table() {
    HashTableNode **table = mmap(NULL, sizeof(HashTableNode *) * HASH_SIZE, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (table == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    memset(table, 0, sizeof(HashTableNode *) * HASH_SIZE);
    return table;
}

Record *allocate_record(const char *key) {
    Record *record = malloc(sizeof(Record) + strlen(key) + 1);
    if (!record) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    record->value = 0;
    record->status = 0;
    strcpy(record->key, key);
    return record;
}

void insert(HashTableNode **table, const char *key, Record *record) {
    unsigned long hash_index = hash(key);

    HashTableNode *node = table[hash_index];
    if (!node) {
        table[hash_index] = malloc(sizeof(HashTableNode));
        node = table[hash_index];
        node->record = record;
        node->next = NULL;
        return;
    }

    while (node->next) {
        node = node->next;
    }

    node->next = malloc(sizeof(HashTableNode));
    node = node->next;
    node->record = record;
    node->next = NULL;
}

Record *find(HashTableNode **table, const char *key) {
    unsigned long hash_index = hash(key);

    HashTableNode *node = table[hash_index];
    while (node) {
        if (!strcmp(node->record->key, key))
            return node->record;

        node = node->next;
    }

    return NULL;
}

void delete(HashTableNode **table, const char *key) {
    unsigned long hash_index = hash(key);

    HashTableNode *node = table[hash_index];
    HashTableNode *prev_node = NULL;

    while (node) {
        if (!strcmp(node->record->key, key)) {
            if (prev_node) {
                prev_node->next = node->next;
            } else {
                table[hash_index] = node->next;
            }

            free(node->record);
            free(node);
            return;
        }

        prev_node = node;
        node = node->next;
    }
}

