Node* fibonacci_sequence(int n) {
    if (n <= 0) return NULL;
    Node *head = NULL, *prev = NULL, *curr = NULL;

    int f1 = 0, f2 = 1;
    for (int i = 0; i < n; ++i) {
        curr = malloc(sizeof(Node));
        if (!curr) return NULL;

        curr->data.offset = f1;
        curr->data.key = next_prime(f2);
        curr->data.value = rand() % 100 + 1;
        curr->next = NULL;

        if (i == 0) {
            head = curr;
            prev = curr;
        } else {
            prev->next = curr;
            prev = curr;
        }

        Node *temp = curr;
        curr = malloc(sizeof(Node));
        if (!curr) return NULL;

        curr->data.offset = f2;
        curr->data.key = next_prime(f1 + f2);
        curr->data.value = rand() % 100 + 1;
        curr->next = NULL;

        temp->next = curr;
        prev = curr;

        f1 = f2;
        f2 += f1;
    }

    return head;
}

int next_prime(int number) {
    if (number <= 2) return 3;

    bool is_prime = true;
    for (int i = 2; i * i <= number; ++i) {
        if (number % i == 0) {
            is_prime = false;
            break;
        }
    }

    if (!is_prime) return next_prime(number + 2);
    else return number;
}

