```cpp
#include <iostream>
#include <list>
#include <memory>
#include <string>
#include <thread>
#include <mutex>
#include <queue>

struct Record {
    long offset;
    int key;
    int value;
    char status;
    std::string data;
};

class RecordList {
private:
    std::list<std::unique_ptr<Record>> records;
    std::mutex listMutex;
    std::queue<std::unique_ptr<Record>> pendingRecords; // for handling delays/interruptions in data flow

public:
    void insert(const Record& record) {
        std::lock_guard<std::mutex> lock(listMutex);
        pendingRecords.push(std::unique_ptr<Record>(new Record(record)));
    }

    void processPending() {
        std::lock_guard<std::mutex> lock(listMutex);
        while (!pendingRecords.empty()) {
            records.push_back(std::move(pendingRecords.front()));
            pendingRecords.pop();
        }
    }

    Record* find(int key) const {
        auto it = std::find_if(records.begin(), records.end(), [&](const auto& rec) { return rec->key == key; });
        if (it != records.end()) return it->get();
        return nullptr;
    }

    Record* remove(int key) {
        auto it = std::find_if(records.begin(), records.end(), [&](const auto& rec) { return rec->key == key; });
        if (it != records.end()) {
            records.erase(it);
            return it->release();
        }
        return nullptr;
    }

    void print() const {
        std::lock_guard<std::mutex> lock(listMutex);
        for (const auto& record : records) {
            std::cout << "Offset: " << record->offset << ", Key: " << record->key << ", Value: " << record->value
                      << ", Status: " << static_cast<char>(record->status) << ", Data: " << record->data << "\n";
        }
    }
