struct Record {
    int value;
};

std::mutex mtx;
std::condition_variable cv;
unsigned long maxMemoryUsage;
std::vector<long> offsets;
std::vector<int> keys;
std::vector<Record> records;
std::map<int, size_t> keyToIndex;

void init() {
    // Initialize arrays with default values
    offsets.resize(1);
    keys.resize(1);
    records.emplace_back(Record{});

    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, maxMemoryUsage - 1);

    // Initialize record values with random unique numbers
    while (records.size() < maxMemoryUsage) {
        int randomValue = dis(gen);
        if (std::find_if(records.begin(), records.end(), [&](const Record& r) { return r.value == randomValue; }) == records.end()) {
            records.emplace_back(Record{randomValue});
            keyToIndex[randomValue] = records.size() - 1;
        }
    }
}

size_t findKeyIndex(int key) {
    std::unique_lock<std::mutex> lock(mtx);
    cv.wait(lock, [&](){ return keyToIndex.find(key) != keyToIndex.end(); });
    size_t index = keyToIndex[key];
    return index;
}

void cleanup() {
    // Implement compaction algorithm here
}

size_t getMemoryUsage() {
    return records.size();
}
