Record* create_record_array(size_t size, size_t min_key, size_t max_key, double min_value, double max_value, callback_func cb, bool use_external_data, const char* data_source, ...) {
    Record *records = NULL;
    size_t unique_keys = 0;
    pthread_mutex_t keys_mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_t threads[size];
    bool *keys_taken = calloc(max_key - min_key + 1, sizeof(bool));

    // Initialize record array with zeros
    records = malloc(size * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for record array.\n");
        exit(EXIT_FAILURE);
    }

    // Randomize seed
    srand(time(NULL));

    // Create and start threads for initializing records concurrently
    for (size_t i = 0; i < size; ++i) {
        pthread_create(&threads[i], NULL, initialize_record, &i);
    }

    // Wait for all threads to finish
    for (size_t i = 0; i < size; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Free keys array and thread-related data structures
    free(keys_taken);

    // Filter records based on external data (if provided)
    if (use_external_data && data_source) {
        filter_records(records, size, data_source, ...);
    }

    // Apply callback to each successfully initialized record
    for (size_t i = 0; i < unique_keys; ++i) {
        if (cb) cb(records[i].key, records[i].value);
    }

    return records;
}

void* initialize_record(void *index) {
    size_t idx = *(size_t*) index;
    Record *record = &((Record *)calloc(1, sizeof(Record)))[idx];
    long offset = 0;
    int key = 0;
    double value = 0.0;

    // Generate unique key and record offset
    while (true) {
        key = rand() % (MAX_KEY - MIN_KEY) + MIN_KEY;
        if (!keys_taken[key]) {
            keys_taken[key] = true;
            break;
        }
    }

    record->key = key;
    record->offset = offset;

    // Generate random value within specified range (ensuring no duplicates)
    do {
        record->value = (double)(rand() / RAND_MAX) * (max_value - min_value) + min_value;
    } while (key_has_same_value(record, unique_keys));

    return NULL;
}

// Helper function to check if a record with the same key and value already exists in the array
bool key_has_same_value(Record* record, size_t unique_keys) {
    for (size_t i = 0; i < unique_keys; ++i) {
        if (record->key == ((Record *)records)[i].key && record->value == ((Record *)records)[i].value) {
            return true;
        }
    }

    return false;
}
