#include <cstdint>

class DataRecordGenerator {
private:
    std::vector<std::unique_ptr<DataRecord>> records;
    std::mt19937 rng;
    int minValue, maxValue, key, recordCount, offsetStep;

public:
    DataRecordGenerator(int seed, int recordCount, int minValue, int maxValue, int key, int offsetStep) :
        rng(seed), minValue(minValue), maxValue(maxValue), key(key), recordCount(recordCount), offsetStep(offsetStep) {}

    void generateRecords() {
        std::uniform_int_distribution<int> distrib(minValue, maxValue);
        for (size_t i = 0; i < recordCount; ++i) {
            long offset = static_cast<long>(i * offsetStep);
            records.emplace_back(std::make_unique<DataRecord>(offset, key, distrib(rng)));
        }
    }

    void resizeRecords(int newSize) {
        if (newSize > recordCount) {
            for (size_t i = recordCount; i < newSize; ++i) {
                long offset = static_cast<long>(i * offsetStep);
                records.emplace_back(std::make_unique<DataRecord>(offset, key, minValue + (rand() % (maxValue - minValue + 1))));
            }
        } else {
            records.erase(records.begin(), records.begin() + newSize);
        }
        recordCount = newSize;
    }

    const DataRecord& getRecord(size_t index) const {
        if (index >= recordCount) {
            throw std::out_of_range("Index out of range.");
        }
        return *records[index];
    }

    ~DataRecordGenerator() {
        records.clear();
    }
};

class DataRecord {
public:
    long offset, key;
    int value;

    DataRecord(long offset, int key, int value) : offset(offset), key(key), value(value) {}
};
