#include <string.h>

typedef struct {
    long offset;
    int key;
    double value;
} record;

typedef void (*callback)(int, double);

record* structuredDataProcessor(long size, long minOffset, long maxOffset, int minKey, int maxKey, callback cb, char *suffix, int stringLimit, const char *input) {
    srand(time(NULL));

    if (size <= 0 || minOffset < minOffset || maxOffset > LONG_MAX - minOffset || minKey < minKey || maxKey > INT_MAX || input == NULL || strlen(input) > stringLimit) {
        return NULL;
    }

    record *records = malloc(size * sizeof(record));
    if (!records) {
        perror("Memory allocation error");
        return NULL;
    }

    for (long i = 0; i < size && maxKey - minKey > 0; ++i) {
        int key = minKey + rand() % (maxKey - minKey);
        bool keyExists = false;
        for (long j = 0; j < i && !keyExists; ++j) {
            if (records[j].key == key) {
                keyExists = true;
            }
        }

        if (!keyExists) {
            records[i].offset = minOffset + i;
            records[i].key = key;
            records[i].value = (double)(rand() % 100) / 10.0 + 5.0; // Random value between 5 and 55, adjust as needed
            if (cb) {
                cb(records[i].key, records[i].value);
            }
        } else {
            --size;
        }
    }

    record *result = malloc((size > 0 ? size : 1) * sizeof(record));
    if (!result) {
        perror("Memory allocation error");
        free(records);
        return NULL;
    }

    memcpy(result, records, size * sizeof(record));
    free(records);

    char *str = (strlen(input) <= stringLimit) ? strdup(input) : NULL;
    if (str) {
        strcat(str, suffix);
    }

    return result;
}
