function collectMatchingElements(callback, selector, root = document) {
    const cache = new Map();
    const queue = [root];

    let foundElement = null;

    function traverse(node) {
        if (node.matches && node.matches(selector)) {
            foundElement = node;
            callback(node);
        }

        for (let i = 0; i < node.children.length; ++i) {
            traverse(node.children[i]);
        }
    }

    function cacheElement(node, cacheKey) {
        if (!cache.has(cacheKey)) {
            cache.set(cacheKey, node);
        } else {
            foundElement = cache.get(cacheKey);
        }
    }

    while (queue.length > 0) {
        const currentNode = queue.pop();

        if (!currentNode.matches && currentNode.nodeType === Node.ELEMENT_NODE) {
            for (let i = 0; i < currentNode.childNodes.length; ++i) {
                cacheElement(currentNode.childNodes[i], currentNode);
                queue.push(currentNode.childNodes[i]);
            }
        } else if (currentNode.matches && !foundElement) {
            foundElement = currentNode;
            callback(currentNode);
        }
    }

    return foundElement;
}
