using Org.BouncyCastle;
using Org.BouncyCastle.Crypto.Parameters;
using Org.BouncyCastle.OpenSsl;
using log4net;

public class PayloadDecipherer
{
    private static readonly ILog Logger = LogManager.GetLogger(typeof(PayloadDecipherer));

    private AesEngine _aesCbc;
    private AesGcmEngine _aesGcm;

    public PayloadDecipherer()
    {
        _aesCbc = new AesEngine();
        _aesGcm = new AesGcmEngine();
    }

    public async Task DecryptPayloads(Stream[] payloadStreams)
    {
        var decryptedData = new List<byte[]>();

        ParallelOptions options = new ParallelOptions { MaxDegreeOfParallelism = Environment.ProcessorCount };

        Parallel.ForEach(payloadStreams, options, payload =>
        {
            try
            {
                using var ms = new MemoryStream();
                ReadPayloadHeader(payload, ms);
                byte[] header = ms.ToArray();

                // Determine encryption mode based on metadata within the payload header
                EncryptionMode encryptionMode;
                if (IsAesGcmSupported(header))
                {
                    encryptionMode = EncryptionMode.AES_GCM;
                }
                else
                {
                    encryptionMode = EncryptionMode.AES_CBC;
                }

                using var decryptor = GetDecryptor(encryptionMode);
                await decryptor.DecryptPayload(payload, ms);

                decryptedData.Add(ms.ToArray());
            }
            catch (Exception ex)
            {
                Logger.Error($"Failed to decrypt payload: {ex}");
            }
        });

        LogDecryptionResults(decryptedData);
    }

    private void ReadPayloadHeader(Stream input, Stream output)
    {
        // Implement reading the metadata (e.g., encryption mode, IV, etc.) from the payload header and writing it to the output stream
        // For simplicity, we'll just copy the entire payload header to the output stream for this example

        const int BufferSize = 4096;
        byte[] buffer = new byte[BufferSize];
        int bytesRead;

        while ((bytesRead = input.Read(buffer, 0, buffer.Length)) > 0)
        {
            output.Write(buffer, 0, bytesRead);
        }
    }

    private ICryptoTransform GetDecryptor(EncryptionMode encryptionMode)
    {
        switch (encryptionMode)
        {
            case EncryptionMode.AES_CBC:
                return _aesCbc.CreateDecryptor();
            case EncryptionMode.AES_GCM:
                return _aesGcm.CreateDecryptor();
            default:
                throw new NotSupportedException($"Unsupported encryption mode: {encryptionMode}");
        }
    }

    private bool IsAesGcmSupported(byte[] header)
    {
        // Implement checking for the presence of metadata indicating AES-GCM support within the payload header
        // For simplicity, we'll assume that the first 4 bytes of the header contain a magic value that identifies AES-GCM
        const byte AesGcmMagic = 0xAB;

        return Array.TrueForAll(header.Take(4), b => b == AesGcmMagic);
    }

    private void LogDecryptionResults(List<byte[]> decryptedData)
    {
        // Implement logging of the decrypted payloads, including metadata validation and any other relevant information
        // For simplicity, we'll just log each decrypted payload as a hexadecimal string for this example

        foreach (var data in decryptedData)
        {
            Logger.Info($"Decrypted payload: {BitConverter.ToString(data).Replace("-", " ") }");
        }
    }
}

public enum EncryptionMode
{
    AES_CBC,
    AES_GCM
}
