using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

public class ResourceScheduler
{
    private int _availableResources;
    private int _maxResourceLimit;
    private PriorityQueue<Task> _taskQueue;
    private readonly object _lock = new object();

    public ResourceScheduler() : this(0, int.MaxValue) { }

    public ResourceScheduler(int availableResources, int maxResourceLimit)
    {
        EnsureValidLimits(availableResources, maxResourceLimit);
        _availableResources = availableResources;
        _maxResourceLimit = maxResourceLimit;
        _taskQueue = new PriorityQueue<Task>();
    }

    private void EnsureValidLimits(int availableResources, int maxResourceLimit)
    {
        if (availableResources < 0 || maxResourceLimit <= 0)
            throw new ArgumentOutOfRangeException("Invalid resource limits.");
    }

    public int RequestResource(int quantity)
    {
        lock (_lock)
        {
            if (_availableResources + quantity > _maxResourceLimit)
                return -1; // Resource limit exceeded

            int resourcesToGrant = Math.Min(_availableResources, quantity);
            _availableResources -= resourcesToGrant;
            return resourcesToGrant;
        }
    }

    public int ReleaseResource(int quantity)
    {
        lock (_lock)
        {
            if (_availableResources + quantity < 0)
                throw new InvalidOperationException("Insufficient resources for release.");

            _availableResources += quantity;
            return quantity;
        }
    }

    public int GetAvailableResources() => _availableResources;

    public void ScheduleTask(Task task)
    {
        lock (_lock)
        {
            _taskQueue.Enqueue(task);
        }
    }

    public override string ToString()
    {
        StringBuilder sb = new StringBuilder();
        sb.AppendLine($"Resource Availability: {_availableResources}");
        sb.AppendLine("Scheduled Tasks:");
        foreach (var task in _taskQueue)
            sb.AppendLine($"{task.UrgencyLevel}: {task.TaskName}");

        return sb.ToString();
    }

    // Implement the remaining methods as per the task description...

    private static string ModifyFileName(string originalName, int numDigits, string fileType)
    {
        int index = originalName.LastIndexOf('.');
        string extension = index < 0 ? "" : originalName.Substring(index);
        string baseName = index < 0 ? originalName : originalName.Substring(0, index);

        StringBuilder newFileName = new StringBuilder();
        if (numDigits > 0 && !baseName.Any(char.IsDigit))
            newFileName.Append(baseName).AppendFormat("_{0:D{1}}", DateTime.Now.Ticks % Math.Pow(10, numDigits), numDigits);
        else
            newFileName.Append(baseName);

        if (!string.IsNullOrEmpty(extension))
            newFileName.Append(extension);

        return newFileName.ToString();
    }
}
