#include <sys/mman.h>

typedef struct Record {
    long offset;
    int key;
    int value;
    char status;
    char* content;
    struct Record *next;
} Record;

int init_record(Record **head, const long offset, const int key) {
    Record *new_record = (Record*) malloc(sizeof(Record));
    if (!new_record) return -1;

    new_record->offset = offset;
    new_record->key = key;
    new_record->value = rand() % 100 + 1;
    new_record->status = 'I'; // I = Init, U = Updated, D = Deleted
    new_record->next = *head;
    *head = new_record;

    return 0;
}

int remove_record(Record **head, int key) {
    Record *current = *head;
    Record *previous;

    if (!*head || (current->key != key)) return -1; // Not found

    previous = NULL;
    current = *head;
    *head = current->next;
    free(current);

    return 0;
}

Record* find_record(Record **head, int key) {
    Record *current = *head;

    while (current != NULL) {
        if (current->key == key) return current;
        current = current->next;
    }

    return NULL;
}

void print_records(Record **head) {
    Record *current = *head;

    while (current != NULL) {
        printf("Offset: %ld, Key: %d, Value: %d, Status: %c\n", current->offset, current->key, current->value, current->status);
        printf("Content: %s\n", current->content);
        current = current->next;
    }
}

char* read_file(const char *path) {
    int fd = open(path, O_RDONLY);
    if (fd == -1) return NULL;

    struct stat st;
    fstat(fd, &st);
    char *data = mmap(NULL, st.st_size, PROT_READ, MAP_PRIVATE, fd, 0);
    close(fd);

    if (data == MAP_FAILED) {
        free(data);
        return NULL;
    }

    return data;
}

void FileRecordManager() {
    Record *head = NULL;

    // Initialize linked list with records
    for (int i = 0; i < 10; ++i) {
        init_record(&head, i*i, i);
    }

    // Read file content and create new record
    char *file_content = read_file("/path/to/yourfile.txt");
    if (file_content != NULL) {
        Record *new_record = malloc(sizeof(Record));
        if (!new_record) goto cleanup;

        new_record->offset = ftell(NULL); // Use current file position
        new_record->key = rand() % 100 + 1;
        new_record->value = rand() % 100 + 1;
        new_record->status = 'I';
        new_record->content = strdup(file_content);
        new_record->next = head;
        head = new_record;
    }

    // Perform operations on the linked list
    print_records(&head);
    Record *found = find_record(&head, 1);
    if (found != NULL) {
        printf("Found record with key %d\n", found->key);
    }

    remove_record(&head, 2);
    print_records(&head);

cleanup:
    // Free resources and handle errors gracefully
    while (head != NULL) {
        Record *temp = head;
        head = head->next;
        free(temp->content);
        free(temp);
    }
}
```
