#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <stdbool.h>
#include <sys/mman.h>
#include <unistd.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/syscall.h>

#define GETDENTS64 syscall(SYS_getdents64)
typedef struct {
    unsigned long id;
    time_t timestamp;
    char *source;
    EventType type;
    SeverityLevel severity;
    EventMetadata metadata;
} LogEntry;

typedef enum { READ, WRITE } AccessType;
struct CacheNode {
    LogEntry entry;
    struct CacheNode *next;
};

struct Cache {
    size_t capacity;
    size_t currentSize;
    struct CacheNode *head;
    pthread_mutex_t lock;
};

void cacheInit(struct Cache* cache, size_t capacity) {
    cache->capacity = capacity;
    cache->currentSize = 0;
    cache->head = NULL;
    pthread_mutex_init(&cache->lock, NULL);
}

void enqueueCache(struct Cache *cache, LogEntry entry) {
    struct CacheNode* node = (struct CacheNode*) malloc(sizeof(struct CacheNode));
    if (!node) return;

    node->entry = entry;
    node->next = NULL;

    pthread_mutex_lock(&cache->lock);
    if (cache->currentSize < cache->capacity) {
        if (cache->head == NULL)
            cache->head = node;
        else {
            struct CacheNode *last = cache->head;
            while (last->next != NULL) last = last->next;
            last->next = node;
        }
        cache->currentSize++;
    }
    pthread_mutex_unlock(&cache->lock);
}

LogEntry dequeueCache(struct Cache *cache, bool isRead) {
    LogEntry ret;
    struct CacheNode *node;

    if (cache->currentSize == 0 || !isRead) return ret;

    pthread_mutex_lock(&cache->lock);
    node = cache->head;
    if (node != NULL) {
        cache->head = node->next;
        ret = node->entry;
        free(node);
        cache->currentSize--;
    }
    pthread_mutex_unlock(&cache->lock);

    return ret;
}

