void process_json(json_t *root, LogEntry *entry) {
    time_t start, end;
    json_t *session_duration_obj;

    if (json_unref(json_object_get(root, "error"))) {
        // Handle error cases here
        return;
    }

    session_duration_obj = json_object_get(root, "sessionDuration");
    if (!json_is_number(session_duration_obj)) {
        // Handle invalid JSON structure cases here
        return;
    }

    start = json_integer_value(json_object_get(root, "start"));
    end = start + json_integer_value(session_duration_obj);

    entry->session.start = start;
    entry->session.end = end;
}

void process_data_source(const char *data_source) {
    FILE *file;
    size_t len, read;
    char buffer[buffer_size];
    json_error_t error;
    json_t *root;
    LogEntry entry;

    if (!(file = fopen(data_source, "r"))) {
        // Handle I/O errors here
        return;
    }

    while ((read = fread(buffer, sizeof(char), buffer_size - 1, file)) > 0) {
        buffer[read] = '\0';
        root = json_loads(buffer, 0, &error);
        if (!root) {
            // Handle JSON parsing errors here
            continue;
