        pthread_mutex_lock(&log_entries_mutex);
        log_entries = realloc(log_entries, sizeof(LogEntry) * (num_log_entries + 1));
        entry.json = root;
        process_json(root, &entry);
        num_log_entries++;
        pthread_mutex_unlock(&log_entries_mutex);
    }

    fclose(file);
}

