        if (log_entries[i].session.end > log_entries[num_log_entries - 1].session.start) {
            // Handle edge case of overlapping sessions here
            continue;
        }
        total_duration += difftime(log_entries[i].session.end, log_entries[i].session.start);
    }
    pthread_mutex_unlock(&log_entries_mutex);

    printf("Average session duration: %.2f seconds\n", total_duration / num_log_entries);
}

