    off_t size;
    time_t mtime;
    uid_t uid;
    gid_t gid;
} FileMetadata;

struct map_node {
    const char *key;
    FileMetadata *value;
    struct map_node *next;
};

struct map {
    struct map_node **table;
    unsigned int size;
    unsigned int capacity;
};

FileMetadata **metadata;
uid_t *uids;
gid_t *gids;
off_t *sizes;
int num_files = 0;
int max_files = 16;
