void validate_path(const char *path) {
    struct stat buf;
    if (lstat(path, &buf) != 0) return; // Handle errors here
    if (S_ISDIR(buf.st_mode)) return; // Disallow directories as inputs
}

void add_metadata(FileMetadata *meta) {
    unsigned long hash = hash((const unsigned char *) meta->path);
    unsigned int index = hash % file_map.capacity;

    if (file_map.table[index] == NULL)
        file_map.table[index] = malloc(sizeof(struct map_node));

    struct map_node *node = file_map.table[index];
    while (node != NULL && strcmp(node->key, meta->path) < 0) node = node->next;

    if (node == NULL) {
        node = malloc(sizeof(struct map_node));
        node->key = meta->path;
        node->value = meta;
        node->next = file_map.table[index];
        file_map.table[index] = node;
    } else {
        free(meta); // If a key already exists, free the duplicated metadata
    }
}

int read_and_process_file(const char *path) {
    validate_path(path);

    int fd = open(path, O_RDONLY);
    if (fd == -1) return -1; // Handle errors here

    struct stat buf;
    fstat(fd, &buf);
    close(fd);

    FileMetadata *meta = malloc(sizeof(FileMetadata));
    meta->path = strdup(path);
    meta->size = buf.st_size;
    meta->mtime = buf.st_mtime;
    meta->uid = buf.st_uid;
    meta->gid = buf.st_gid;

    add_metadata(meta);

    return 0;
}

void* process_files() {
    char line[1024];
    while (fgets(line, sizeof(line), stdin)) {
        const char *path = strtok(line, "\n");
        if (!path || read_and_process_file(path) == -1) continue; // Handle errors here

        num_files++;
        if (num_files >= max_files) resize_arrays();
    }
}

void resize_arrays() {
    FileMetadata **new_metadata = realloc(metadata, sizeof(FileMetadata *) * file_map.capacity * 2);
    if (!new_metadata) return; // Handle memory allocation errors here
    metadata = new_metadata;

    uids = realloc(uids, num_files * sizeof(uid_t));
    gids = realloc(gids, num_files * sizeof(gid_t));
    sizes = realloc(sizes, num_files * sizeof(off_t));

    file_map.capacity *= 2;
}

int main() {
    pthread_t threads[4]; // Adjust the number of threads based on your system and use case

    for (int i = 0; i < arraysize(threads); ++i) {
        if (pthread_create(&threads[i], NULL, process_files, NULL)) return -1; // Handle errors here
    }

    for (int i = 0; i < arraysize(threads); ++i) pthread_join(threads[i], NULL);

    // Implement sorting and filtering functions here
    // ...

    return 0;
}
