void initCustomAllocator(struct CustomAllocator *allocator, size_t blockSize) {
    allocator->blockSize = blockSize;
    allocator->start = mmap(NULL, 1 << 20, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (allocator->start == MAP_FAILED) {
        fprintf(stderr, "Failed to initialize custom allocator\n");
        exit(EXIT_FAILURE);
    }
    allocator->current = allocator->start;
    allocator->end = allocator->start + (1 << 20);
}

void *customMalloc(struct CustomAllocator *allocator, size_t size) {
    if ((allocator->current + size > allocator->end)) {
        allocator->current = sbrk(sysconf(_SC_PAGESIZE));
        if (allocator->current == (char *)-1) {
            fprintf(stderr, "Failed to allocate memory for custom allocator\n");
            exit(EXIT_FAILURE);
