['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <semaphore.h>
#include <sys/mman.h>

typedef struct {
    time_t timestamp;
    int priority;
    int status;
    char *description;
    pthread_mutex_t lock;
} Task;

typedef struct QueueNode {
    Task task;
    struct QueueNode *next;
} QueueNode;

struct TaskQueue {
    Semaphore head; // points to the first non-empty node in the queue
    Semaphore tail; // points to the last non-empty node in the queue
    QueueNode *queue;
    size_t size;
};

void task_init(Task *task, time_t start) {
    task->timestamp = start + (start % TASK_GAP);
    task->priority = rand() % TASK_PRIORITY_RANGE;
    task->status = 0;
}

Task *task_alloc() {
    Task *task = mmap(NULL, sizeof(Task), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (!task) return NULL;
    task_init(task, time(NULL));
    return task;
}

void task_free(Task *task) {
    munmap((void *)task, sizeof(Task));
}

struct TaskQueue *queue_init(size_t size) {
    struct TaskQueue *queue = malloc(sizeof(struct TaskQueue));
    if (!queue) return NULL;

    queue->head = sem_init(0, 1, 0);
    queue->tail = sem_init(0, 1, 0);
    queue->size = size;
    queue->queue = malloc(sizeof(QueueNode) * size);
    if (!queue->queue) {
        free(queue);
        return NULL;
    }

    for (size_t i = 0; i < size; ++i) {
        queue->queue[i].next = &queue->queue[(i + 1) % size];
    }

    return queue;
}

void queue_free(struct TaskQueue *queue) {
    free(queue->queue);
    sem_destroy(queue->head);
    sem_destroy(queue->tail);
    free(queue);
}

void enqueue(struct TaskQueue *queue, Task *task) {
    pthread_mutex_lock(&task->lock);
    QueueNode *node = (QueueNode *)malloc(sizeof(QueueNode));
    if (!node) {
        fprintf(stderr, "Memory allocation failure\n");
        task_free(task);
        pthread_mutex_unlock(&task->lock);
        return;
    }

    node->task = *task;
    node->next = NULL;

    sem_wait(queue->tail);
    queue->queue[(queue->head + 1) % queue->size] = node;
    sem_post(queue->head);
    pthread_mutex_unlock(&node->task.lock);
}

Task *dequeue(struct TaskQueue *queue) {
    QueueNode *node;

    sem_wait(queue->head);
    node = queue->queue[queue->head];
    queue->head = (queue->head + 1) % queue->size;
    sem_post(queue->tail);

    pthread_mutex_lock(&node->task.lock);
    Task *task = &node->task;
    node->next = NULL;
    pthread_mutex_unlock(&node->task.lock);

    free(node);
    return task;
}

Task *find_by_priority(struct TaskQueue *queue, int priority) {
    for (QueueNode *node = queue->queue[queue->head]; node != NULL; node = node->next) {
        if (node->task.priority == priority) {
            pthread_mutex_lock(&node->task.lock);
            Task *task = &node->task;
            pthread_mutex_unlock(&node->task.lock);
            return task;
        }
    }
    return NULL;
}
```

