typedef struct {
    int value;
    char status;
    char* id;
} record;

typedef struct hash_node {
    record* data;
    size_t hash;
    struct hash_node *next;
} hash_node;

struct custom_allocator {
    void* base;
    size_t total, allocated, chunk_size;
};

hash_node* create_node(record* data, size_t hash) {
    hash_node* node = malloc(sizeof(hash_node));
    if (!node) return NULL;
    node->data = data;
    node->hash = hash;
    node->next = NULL;
    return node;
}

record* create_record(int value, char status, const char* id) {
    size_t len = strlen(id);
    record* rec = malloc(sizeof(record) + len);
    if (!rec) return NULL;
    memcpy(rec + sizeof(record), id, len + 1);
    rec->value = value;
    rec->status = status;
    return rec;
}

int hash_func(const char* key, size_t table_size) {
    unsigned int hash = 0;
    while (*key++) hash = (hash << 5) + hash + *key;
    return hash % table_size;
}

void custom_allocator_init(struct custom_allocator* alloc, size_t chunk_size) {
    alloc->base = mmap(NULL, chunk_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (!alloc->base) return;
    alloc->total = alloc->chunk_size = chunk_size;
    alloc->allocated = 0;
}

void* custom_allocator_malloc(struct custom_allocator* alloc, size_t size) {
    void* ptr = NULL;
    if (size + sizeof(record) > alloc->total - alloc->allocated) {
        if (!extend_memory(alloc)) return NULL;
    }
    ptr = alloc->base + alloc->allocated;
    alloc->allocated += size;
    return ptr;
}

void extend_memory(struct custom_allocator* alloc) {
    void *new_base = mmap(NULL, 2 * alloc->total, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (new_base == MAP_FAILED) return;
    memmove(new_base, alloc->base, alloc->total);
    munmap(alloc->base, alloc->total);
    alloc->base = new_base;
    alloc->total *= 2;
}

