#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Record {
    int key;
    int value;
    char* str;
} Record;

typedef struct DataStore {
    Record* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
    void* (*alloc)(size_t);
    void(*dealloc)(void*) ;
} DataStore;

DataStore* create_data_store(size_t initial_capacity, void* (*alloc)(size_t), void(*dealloc)(void*)) {
    DataStore* store = malloc(sizeof(DataStore));
    if (!store) return NULL;

    store->capacity = initial_capacity;
    store->size = 0;
    store->data = alloc(initial_capacity * sizeof(Record));
    if (!store->data) {
        free(store);
        return NULL;
    }

    pthread_mutex_init(&store->mutex, NULL);
    store->alloc = alloc;
    store->dealloc = dealloc;

    return store;
}

void destroy_data_store(DataStore* store) {
    if (!store) return;

    for (size_t i = 0; i < store->size; ++i) {
        free(store->data[i].str);
    }
    free(store->data);
    pthread_mutex_destroy(&store->mutex);
    free(store);
}

Record* find_record(DataStore* store, int key) {
    for (size_t i = 0; i < store->size; ++i) {
        if (store->data[i].key == key) return &store->data[i];
    }
    return NULL;
}

void insert(DataStore* store, Record record) {
    pthread_mutex_lock(&store->mutex);
    for (size_t i = 0; i < store->size; ++i) {
        if (store->data[i].key == record.key) {
            store->data[i] = record;
            break;
        }
    }

    if (store->size == store->capacity) {
        Record* new_data = store->alloc((store->capacity + 1) * sizeof(Record));
        if (!new_data) {
            pthread_mutex_unlock(&store->mutex);
            return;
        }
        memcpy(new_data, store->data, store->size * sizeof(Record));
        free(store->data);
        store->data = new_data;
        store->capacity *= 2;
    }

    store->data[store->size] = record;
    ++store->size;
    pthread_mutex_unlock(&store->mutex);
}

void remove(DataStore* store, int key) {
    Record* target = find_record(store, key);
    if (!target) return;

    pthread_mutex_lock(&store->mutex);

    memmove(target, &store->data[store->size - 1], sizeof(Record));
    --store->size;

    for (size_t i = store->size; i < store->capacity; ++i) {
        if (!store->data[i].key) {
            free(store->data[i].str);
            break;
        }
    }
    pthread_mutex_unlock(&store->mutex);
}

void update(DataStore* store, Record record) {
    Record* target = find_record(store, record.key);
    if (!target) return;

    pthread_mutex_lock(&store->mutex);

    target->value = record.value;
    free(target->str);
    target->str = store->alloc(strlen(record.str) + 1);
    strcpy(target->str, record.str);

    pthread_mutex_unlock(&store->mutex);
}
```

