    while (*current && ((*current)->key < key))
        current = &(*current)->next;

    if (!*current || (*current)->key > key) {
        *current = create_node(offsets[1000 - (1000 - (*current ? (*current)->offset : 0) + 1)], key, record);
        offsets[1000 - (1000 - (*current ? (*current)->offset : 0))] = -1;
    } else {
        Node* new_node = create_node(offsets[1000 - (1000 - (*current)->offset)], key, record);
        new_node->next = (*current)->next;
        (*current)->next = new_node;
    }
}

void remove_record(int key) {
    Node** current = &head;
    while (*current && (*current)->key != key)
        current = &(*current)->next;

    if (!*current) {
        perror("Error: Key not found.");
        exit(EXIT_FAILURE);
    }

    Node* temp = *current;
    *current = (*current)->next;
    free(temp->record->str);
    free(temp->record);
    offsets[1000 - (*current ? (*current)->offset : 0)] = temp->offset;
    free(temp);
}

