    free(xml_content);

    // Sort the records based on keys for easy access and handle overlapping keys gracefully
    qsort(*records, *num_records, sizeof(void*), compare_ints);

    *num_records = i;
    return SUCCESS;
}

// Custom comparison function for qsort() to sort the record pointers based on their associated int keys
int compare_ints(const void *a, const void *b) {
    const custom_record *rec_a = *(custom_record**) a;
    const custom_record *rec_b = *(custom_record**) b;
    return rec_a->key - rec_b->key;
}
```

