    bool active;
};

void handle_file_operations(const char* path, size_t float_size, size_t node_size) {
    FILE* file = fopen(path, "r"); // Open the file for reading
    if (!file) return; // Exit if the file cannot be opened

    // Allocate memory for floats and nodes
    float* floats = malloc(float_size * sizeof(float));
    struct node* nodes = malloc(node_size * sizeof(struct node));

    if (!floats || !nodes) { // Exit if memory allocation fails
        fclose(file);
        return;
    }

    // Initialize indices and set node indices
    for (size_t i = 0; i < node_size; ++i) {
        nodes[i].index = i;
        nodes[i].value = floats + (rand() % float_size); // Assign random valid floats to nodes
        nodes[i].active = rand() > RAND_MAX / 2; // Determine node activity randomly
    }

    // Buffer for reading file chunks and calculating MD5 hash
    unsigned char digest[MD5_DIGEST_LENGTH];
    char buffer[4096];
    size_t offset = 0;
    size_t bytes_read;

    while ((bytes_read = fread(buffer, sizeof(char), sizeof(buffer), file)) > 0) {
        // Hash the chunk and update the digest in chunks
        hashlib_md5(buffer, bytes_read, digest + offset);
        offset += bytes_read;
    }

    free(file); // Close the file and free associated resources

    // Free allocated memory upon exit
    free(floats);
    free(nodes);
}
