['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <sys/mman.h>

// Customizable memory management flags
#define ALLOC_CLEAR 1
#define MMAP_SHARED  (MAP_PRIVATE | MAP_ANONYMOUS)

typedef struct Record {
    int key;
    long offset;
} Record;

// Function prototype for error logging
void log_error(const char* message, FILE* log_file);

void* memory_manager(size_t size, int flags, void* arg) {
    // Implement dynamic memory allocation using mmap
    void *ptr = mmap(NULL, size, (flags & ALLOC_CLEAR) ? PROT_READ | PROT_WRITE : PROT_READ, MMAP_SHARED, -1, 0);

    if (ptr == MAP_FAILED) {
        log_error("Memory allocation failure", arg);
        return NULL;
    }

    return ptr;
}

void dynamic_memory_allocation(size_t offset_count, size_t key_count, size_t record_count,
                               size_t offset_start, size_t offset_end, int key_start, int key_end, FILE* log_file) {
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    void *offsets = memory_manager((offset_end - offset_start + 1) * sizeof(long), ALLOC_CLEAR, &lock);
    if (!offsets) {
        return;
    }

    long *offset_arr = (long*) offsets;
    for (size_t i = 0; i < offset_count; ++i) {
        offset_arr[i] = offset_start + i;
    }

    void *keys = memory_manager((key_end - key_start + 1) * sizeof(int), ALLOC_CLEAR, &lock);
    if (!keys) {
        return;
    }

    int *key_arr = (int*) keys;
    for (size_t i = 0; i < key_count; ++i) {
        key_arr[i] = key_start + i;
    }

    void *records = memory_manager(record_count * sizeof(Record), ALLOC_CLEAR, &lock);
    if (!records) {
        return;
    }

    Record *record_arr = (Record*) records;
    for (size_t i = 0; i < record_count; ++i) {
        record_arr[i].key = key_start + (i % key_count);
        record_arr[i].offset = offset_start + (i % offset_count);
    }

    pthread_mutex_destroy(&lock);
}

void log_error(const char* message, FILE* log_file) {
    if (!log_file) return;

    fprintf(log_file, "[Error] %s\n", message);
}
