use std::collections::HashMap;
use std::sync::Mutex;
use std::env;
use std::fs::{self, create_dir_all};
use std::io::{BufRead, BufReader};
use rayon::prelude::*;
use num::WrappingInt;

const MAX_PAIRS: usize = 10_000;
type Long = WrappingInt<u64>;

// Thread-safe offset vector
static OFFSETS: Mutex<Vec<Long>> = Mutex::new(vec![]);

// Thread-safe key-value map
static KV_MAP: Mutex<HashMap<i32, Long>> = Mutex::new(HashMap::new());

fn init_from_file(path: &str) {
    let file = match fs::File::open(path) {
        Ok(f) => f,
        Err(_) => return,
    };

    let reader = BufReader::new(file);
    let mut offsets = OFFSETS.lock().unwrap();
    let mut map = KV_MAP.lock().unwrap();

    reader.lines()
         .par_bridge()
         .filter_map(|line| line.ok())
         .map(|line| {
             let parts: Vec<&str> = line.split_whitespace().collect();
             if parts.len() != 2 {
                 return None;
             }
             let key: i32 = parts[0].parse::<i32>().unwrap();
             let offset: Long = parts[1].parse::<u64>().map(|v| WrappingInt(v)).unwrap();
             Some((key, offset))
         })
         .for_each(|(k, v)| {
             *map.entry(k).or_insert(Long::zero()) += v;
             offsets.push(v);
         });
}

fn set_env_and_create_dir(dir_name: &str) {
    if env::var("CURRENT_DIR").is_ok() {
        let path = env::var("CURRENT_DIR").unwrap();
        fs::create_dir_all(path.join(dir_name)).unwrap();
        env::set_var("CURRENT_DIR", path.join(dir_name).to_str().unwrap());
    } else {
        create_dir_all(dir_name).unwrap();
        env::set_var("CURRENT_DIR", dir_name);
    }
}
