[' here is a C++11 solution using `std::vector` and `std::unique_ptr` for dynamic memory management, providing thread safety with `std::mutex`. The class also includes validation checks, support for adding new tasks, retrieving existing ones by index, and error handling in case of out-of-memory conditions.

```cpp
#include <vector>
#include <unique_ptr>
#include <mutex>
#include <exception>
#include <stdexcept>

struct Task {
    std::string name;
    int priority = 0;
    double executionTime = 0.0;
};

class TaskCollection {
private:
    static constexpr size_t MAX_PRIORITY = 100;

    std::vector<std::unique_ptr<Task>> tasks;
    std::mutex mtx;

public:
    bool addTask(const Task& task) {
        if (task.executionTime <= 0 || static_cast<unsigned>(task.priority) > MAX_PRIORITY) {
            return false;
        }

        std::unique_lock<std::mutex> lock(mtx);
        tasks.emplace_back(std::make_unique<Task>(task));
        return true;
    }

    Task& getTask(size_t index) {
        if (index >= tasks.size()) {
            throw std::out_of_range("Index out of bounds");
        }

        std::unique_lock<std::mutex> lock(mtx);
        auto it = tasks.begin();
        std::advance(it, index);
        return **it;
    }

    void clear() {
        std::unique_lock<std::mutex> lock(mtx);
        for (auto& task : tasks) {
            task.reset();
        }
        tasks.clear();
    }
};
