#include <unordered_map>
#include <mutex>
#include <boost/thread/locks.hpp>
#include <future>

class RecordManager {
private:
    std::unordered_map<int, std::unique_ptr<Record>> records; // thread-safe map
    boost::mutex mutex;
    RecordMemPool memPool;
    int capacity = 100000;
    int numRecords = 0;
    std::future<void> asyncInit; // asynchronous initialization future
    bool isInitialized = false;

public:
    void init(std::function<Record()> dataLoader) {
        asyncInit = std::async(std::launch::async, [dataLoader]() mutable {
            for (int i = 0; i < capacity && numRecords < capacity; ++i) {
                Record newRec = dataLoader(); // load data asynchronously
                std::unique_lock<boost::mutex> lock(mutex);
                records[newRec.key] = std::move(newRec); // insert record into map, with locking for safety
                ++numRecords;
            }
            isInitialized = true;
        });
    }

    Record* getRecord(int key) {
        if (!isInitialized) {
            asyncInit.wait();
        }
        std::unique_lock<boost::mutex> lock(mutex);
        auto it = records.find(key);
        if (it != records.end()) {
            return &it->second; // return pointer to record
        } else {
            return nullptr; // record not found
        }
    }
};
