class RecordCache {
public:
    void put(const Record& record) {
        std::unique_lock<std::mutex> lock(m);
        cache.emplace(record.key, record);
        while (cache.size() > CACHE_SIZE) {
            auto it = --cache.end();
            it->second.status = 'E'; // Evicted
            it = cache.erase(it);
        }
        m.unlock();
