        // Find the record in the cache (use a hash table for efficient lookup)
        auto it = recordCache.get(key, lock);
        if (!it) return; // Not found in cache, no need to remove from list

        // Remove from the thread-safe linked list
        auto pos = std::find_if(records.begin(), records.end(), [&](const Record& r) { return r.key == key; });
        if (pos != records.end()) {
            records.erase(pos);
        }
