typedef struct {
    int value;
    char status;
    char* string;
} Record;

typedef struct {
    pthread_mutex_t mutex;
    int max_len;
    int capacity;
    Record* records;
} RecordSet;

RecordSet* create_recordset(int max_len) {
    RecordSet* set = malloc(sizeof(RecordSet));
    set->max_len = max_len;
    set->capacity = 1024;
    set->records = calloc(set->capacity, sizeof(Record));
    pthread_mutex_init(&set->mutex, NULL);
    return set;
}

int add_record(RecordSet* set, int value, char status, const char* string) {
    // Ensure capacity and allocate new memory if needed
    if (pthread_mutex_lock(&set->mutex) != 0) {
        fprintf(stderr, "Error: Mutex lock failed\n");
        return -1;
    }

    int len = strlen(string);
    if (len > set->max_len) {
        fprintf(stderr, "Error: String too long for max length (%d)\n", set->max_len);
        pthread_mutex_unlock(&set->mutex);
        return -2;
    }

    Record* records = set->records;
    if (set->capacity <= set->count + 1) {
        // Reallocate memory and update capacity
        Record* new_records = realloc(records, sizeof(Record) * (set->capacity *= 2));
        if (!new_records) {
            fprintf(stderr, "Error: Memory allocation failed\n");
            pthread_mutex_unlock(&set->mutex);
            return -3;
        }
        set->records = new_records;
    }

    // Set record fields and increment count
    records[set->count].value = value;
    records[set->count].status = status;
    records[set->count].string = strdup(string);
    set->count++;

    pthread_mutex_unlock(&set->mutex);
    return 0;
}

int remove_record(RecordSet* set, int key) {
    // Ensure mutex is locked before manipulating data
    if (pthread_mutex_lock(&set->mutex) != 0) {
        fprintf(stderr, "Error: Mutex lock failed\n");
        return -1;
    }

    int i;
    for (i = 0; i < set->count; i++) {
        if (set->records[i].value == key) {
            // Shift all remaining records to fill the gap
            memmove(&(set->records[i]), &(set->records[i + 1]), sizeof(Record) * (set->count - (i + 1)));
            set->count--;
            break;
        }
    }

    if (i == set->count) {
        fprintf(stderr, "Error: Key not found\n");
        pthread_mutex_unlock(&set->mutex);
        return -2;
    }

    pthread_mutex_unlock(&set->mutex);
    free(set->records[i].string); // Free the string after shifting is complete

    return 0;
}

int find_record(RecordSet* set, int key) {
    // Ensure mutex is locked before manipulating data
    if (pthread_mutex_lock(&set->mutex) != 0) {
        fprintf(stderr, "Error: Mutex lock failed\n");
        return -1;
    }

    int i;
    for (i = 0; i < set->count; i++) {
        if (set->records[i].value == key) {
            break;
        }
    }

    if (i == set->count) {
        fprintf(stderr, "Error: Key not found\n");
        pthread_mutex_unlock(&set->mutex);
        return -2;
    }

    pthread_mutex_unlock(&set->mutex);
    return i;
}

