import os
import sys
import hashlib
import platform
from shutil import ignore_patterns
from functools import lru_cache
import logging
import errno

# Set up logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(message)s')

def read_config(file_path):
    with open(file_path, 'r') as f:
        config = {line.split()[0]: (line.split()[1], int(line.split()[2])) for line in f}
    return config

@lru_cache(maxsize=None)
def getattr(obj, attr, default=None):
    try:
        return getattr(obj, attr)
    except AttributeError:
        return default

def islink(path):
    try:
        return os.lstat(path).st_mode & 0x40000
    except FileNotFoundError:
        return False

def read_chunk(file, chunk_size=65536):
    while True:
        data = file.read(chunk_size)
        if not data:
            break
        yield data

def process_directory(root_dir, config, md5_hasher, chunk_size=65536):
    results = {}
    for root, dirs, files in os.walk(root_dir, topdown=True, onerr=ignore_patterns('.*', '.DS_Store')):
        if platform.system() == 'Darwin':
            # Ignore .DS_Store on macOS
            continue

        for file in files:
            file_path = os.path.join(root, file)
            expected_size, expected_hash = config[file]

            try:
                if islink(file_path):
                    # Follow symbolic links
                    linked_path = os.readlink(file_path)
                    if not os.path.exists(linked_path):
                        logging.warning(f'Skipping {file_path}: Symbolic link points to non-existent file')
                        continue
                    file_path = linked_path
                file_stats = os.stat(file_path)

                if file_stats.st_size != expected_size:
                    logging.warning(f'{file_path}: Incorrect size ({file_stats.st_size} bytes, expected {expected_size} bytes)')

                hash_calculated = False
                md5_object = hashlib.md5()
                for chunk in read_chunk(open(file_path, 'rb'), chunk_size):
                    md5_object.update(chunk)
                calculated_hash = md5_object.hexdigest()

                if calculated_hash != expected_hash:
                    logging.warning(f'{file_path}: Incorrect hash ({calculated_hash} vs. {expected_hash})')
                else:
                    hash_calculated = True

                results[file_path] = (calculated_hash, hash_calculated, '')
            except PermissionError as e:
                results[file_path] = ('', False, f'Permission error: {e}')
            except Exception as e:
                results[file_path] = ('', False, f'{file_path}: {str(e)}')

    return results

