// Memory tracking functions (for debugging and leak detection)
void* malloc_tracked(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Error: Out of memory\n");
        exit(EXIT_FAILURE);
    }
    // Add tracking code here for leak detection and fragmentation management
    return ptr;
}

void free_tracked(void *ptr) {
    if (ptr != NULL) {
        free(ptr);
        // Remove tracking code here for leak detection and fragmentation management
    }
}

// Configuration manager functions
struct ConfigManager {
    struct HashTable *hash;
    int num_configs;
};

void config_manager_init(struct ConfigManager *cm, unsigned long hash_size) {
    cm->hash = malloc_tracked(sizeof(*cm->hash));
    cm->hash->size = hash_size;
    cm->hash->table = malloc_tracked(hash_size * sizeof(void*));
    pthread_mutex_init(&cm->hash->lock, NULL);
    memset(cm->hash->table, 0, hash_size * sizeof(void*));
}

void config_manager_destroy(struct ConfigManager *cm) {
    unsigned long i;
    for (i = 0; i < cm->hash->size; ++i) {
        struct HashNode *node = cm->hash->table[i];
        while (node != NULL) {
            struct HashNode *next = node->next;
            free_tracked(node->key);
            free_tracked(node->value);
            free_tracked(node);
            node = next;
        }
    }
    free_tracked(cm->hash->table);
    free_tracked(cm->hash);
}

struct HashNode* hash_lookup(const char *key, struct ConfigManager *cm) {
    unsigned long hash = hash_function(key, cm->hash->size);
    pthread_mutex_lock(&cm->hash->lock);

    struct HashNode *node = cm->hash->table[hash];
    while (node != NULL && strcmp(node->key, key) != 0) {
        node = node->next;
    }

    pthread_mutex_unlock(&cm->hash->lock);

    return node;
}

void hash_add(const char *key, void *value, struct ConfigManager *cm) {
    unsigned long hash = hash_function(key, cm->hash->size);
    pthread_mutex_lock(&cm->hash->lock);

    struct HashNode *node = malloc_tracked(sizeof(*node));
    node->key = strdup_tracked(key);
    node->value = value;
    node->next = cm->hash->table[hash];
    cm->hash->table[hash] = node;

    pthread_mutex_unlock(&cm->hash->lock);
}

void hash_remove(const char *key, struct ConfigManager *cm) {
    unsigned long hash = hash_function(key, cm->hash->size);
    pthread_mutex_lock(&cm->hash->lock);

    struct HashNode **prev = &cm->hash->table[hash];
    struct HashNode *node = cm->hash->table[hash];

    while (node != NULL && strcmp(node->key, key) != 0) {
        prev = &(*node->next);
        node = (*prev)->next;
    }

    if (node == NULL) {
        fprintf(stderr, "Error: Configuration not found\n");
        exit(EXIT_FAILURE);
    }

    *prev = node->next;
    free_tracked(node->key);
    free_tracked(node->value);
    free_tracked(node);

    pthread_mutex_unlock(&cm->hash->lock);
}

