typedef struct Event {
    double value;
    char id[201];
    char status;
    time_t timestamp;
    double mean;
    struct Event *next;
} Event;

Event *head = NULL;
double range_min, range_max, memory_threshold, fragmentation_limit;
pthread_mutex_t list_lock;

void init() {
    // Initialize variables and locks
    range_min = log(10) / 1000; // base 10 logarithmic scale, with minimum value of 1e-3
    range_max = log(1000000) / 1000; // base 10 logarithmic scale, with maximum value of 1e6
    memory_threshold = 1024 * 1024 * 1024; // 1GB as a rough estimate for large-scale data
    fragmentation_limit = 0.08;

    pthread_mutex_init(&list_lock, NULL);
}

Event* create_event() {
    Event *new_event = (Event*) malloc(sizeof(Event));
    if (!new_event) return NULL;

    new_event->value = pow(10, (rand() / (RAND_MAX + 1.0) * (range_max - range_min)) + range_min);
    snprintf(new_event->id, sizeof(new_event->id), "%c%06d", 'A' + rand() % 26, rand() % 1000000);
    new_event->status = rand() % 2;
    new_event->timestamp = time(NULL) + rand() % 501;
    new_event->mean = 0.0;
    new_event->next = head;
    head = new_event;

    return new_event;
}

Event* find_event(const char *id) {
    Event *current = head;
    while (current != NULL) {
        if (strcmp(current->id, id) == 0)
            break;
        current = current->next;
    }
    return current;
}

void delete_event(const char *id) {
    Event *prev, *current = head;

    pthread_mutex_lock(&list_lock);
    while (current != NULL) {
        if (strcmp(current->id, id) == 0) {
            prev->next = current->next;
            free(current->id);
            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list_lock);
}

void update_event(const char *id, double new_value) {
    Event *event = find_event(id);
    if (event == NULL) return;

    event->value = new_value;
}

double average_deviation() {
    double sum_of_squares = 0.0, mean = 0.0;
    Event *current = head;

    pthread_mutex_lock(&list_lock);
    while (current != NULL) {
        mean += current->value;
        sum_of_squares += pow(current->value - mean, 2);
        current = current->next;
    }
    mean /= head->next == NULL ? 1 : head->next->timestamp - head->timestamp; // Adjust for the number of events processed
    sum_of_squares /= (head->next == NULL ? 1 : head->next->timestamp - head->timestamp);
    pthread_mutex_unlock(&list_lock);

    return sqrt(sum_of_squares);
}

void check_memory() {
    void *memory_map = mmap(NULL, sysconf(_SC_PAGE_SIZE), PROT_READ, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    size_t used_memory = malloc_usable_space() / (1024 * 1024);
    size_t fragmentation = used_memory / memory_threshold;

    if (fragmentation > fragmentation_limit || used_memory > memory_threshold) {
        printf("Memory usage exceeded. Fragmentation: %.2f%%, Used memory: %.2fGB\n", fragmentation * 100, used_memory);
    }
}
