#include <gsl/gsl_hash_table.h>
#include <stdbool.h>

typedef struct {
    int value;
    bool status;
    char *id;
} record;

struct node {
    record *data;
    struct node *next;
};

struct my_list {
    struct node *head;
    gsl_hash_table *ht;
    pthread_mutex_t lock;
    size_t capacity;
    size_t count;
};

void insert(struct my_list *list, record *record) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) resize(list);

    record->id = strdup(list->ht->get(list->ht, record->id));
    if (list->ht->get(list->ht, record->id)) {
        free(record->id);
        // Update existing record's value and status
    } else {
        list->ht->set(list->ht, record->id, record);
        add_node(list, record);
    }
    pthread_mutex_unlock(&list->lock);
}

void delete(struct my_list *list, const char *id) {
    pthread_mutex_lock(&list->lock);
    if (char *data = list->ht->get(list->ht, id)) {
        record *record = (record *) data;
        remove_node(list, record);
        free(record->id);
        free(record);
        list->ht->remove(list->ht, id);
    }
    pthread_mutex_unlock(&list->lock);
}

void *search(struct my_list *list, const char *id) {
    pthread_mutex_lock(&list->lock);
    if (char *data = list->ht->get(list->ht, id)) {
        record *record = (record *) data;
        void *result = malloc(sizeof(record));
        memcpy(result, record, sizeof(record));
        pthread_mutex_unlock(&list->lock);
        return result;
    }
    pthread_mutex_unlock(&list->lock);
    return NULL;
}

