/* Custom macro for checking allocation errors */
#define ALLOCATE(ptr, type, n)                               \
    do {                                                     \
        void *__ptr = malloc(n * sizeof(type));              \
        if (!(__ptr)) {                                      \
            fprintf(stderr, "Error: Failed to allocate memory\n"); \
            return NULL;                                    \
        }                                                     \
        (ptr) = (__ptr);                                     \
    } while(0)

/* Custom macro for checking alignment errors */
#define ALIGN_PTR(ptr, alignment) ((char*)((uintptr_t)(ptr) & ~((sizeof(alignment) - 1))))

/**
 * @brief Manages memory allocation and initialization of a dynamically sized data structure composed of records.
 * Each `record` consists of a `long` offset and an `int` key.
 *
 * @param n Number of records to initialize.
 * @return A pointer to the initialized data structure, or NULL in case of error.
 */
struct record* init_data_structure(size_t n) {
    /* Allocate memory for n records, aligned to the size of a long (for offset field) */
    struct record *records = NULL;
    ALLOCATE(records, struct record, n);
    records = ALIGN_PTR(records, sizeof(long));

    /* Initialize keys and offsets, optimizing for cache efficiency and minimizing memory fragmentation */
    size_t key = 0;
    size_t *offsets = (size_t*)ALIGN_PTR(records, sizeof(long));
    for (size_t i = 0; i < n; ++i) {
        records[i].key = key++;
        offsets[i] = offsets[i - 1] + 1;
    }

    /* Cleanup on exit using RAII pattern */
    struct scoped_free {
        void *ptr;
        size_t refcount;
    public:
        explicit scoped_free(void* p) : ptr(p), refcount(1) {}
        ~scoped_free() { if (--refcount == 0) free(ptr); }
    };
    scoped_free data_struct_deleter(records);

    return records;
}
