// Function to generate Fibonacci sequence up to a given index
void fibonacci(size_t n, std::vector<long>& seq) {
    if (n <= 1) {
        seq.push_back(n);
        return;
    }
    long prev2 = 0, prev1 = 1;
    for (size_t i = 2; i < n; ++i) {
        seq.push_back(prev2 + prev1);
        std::swap(prev2, prev1);
    }
}

// Function to generate prime numbers up to a given index
void primes(size_t n, std::vector<int>& primes) {
    bool* isPrime = new bool[n + 1];
    std::fill(isPrime, isPrime + n + 1, true);

    for (long p = 2; p * p <= n; ++p) {
        if (isPrime[p]) {
            for (long i = p * p; i <= n; i += p << 1) {
                isPrime[i] = false;
            }
        }
    }

    for (size_t i = 2; i < n; ++i) {
        if (isPrime[i]) {
            primes.push_back(i);
        }
    }
    delete[] isPrime;
}

