    if (!outfile) {
        std::cerr << "Could not open file for writing!" << std::endl;
        return;
    }
    for (size_t i = 0; i < size; ++i) {
        std::stringstream ss;
        ss << records[i].offset << ',' << records[i].key << ',' << records[i].item.id << ','
          << records[i].item.value << records[i].item.description << ',' << records[i].str;
        outfile << ss.str() << std::endl;
    }
}

Record* deserialize(const char* filename) {
    std::ifstream infile(filename);
    if (!infile) {
        std::cerr << "Could not open file for reading!" << std::endl;
        return nullptr;
    }
    Record* records = nullptr;
    size_t size = 0;
    Record record;
    while (std::getline(infile, record.str)) {
        std::stringstream ss(record.str);
        ss >> record.offset >> record.key >> record.item.id >> record.item.value
          >> record.item.description >> record.str;
        if (records) {
            records[size] = record;
        } else {
            size_t numRecords = record.offset + 1;
            records = new Record[numRecords];
            std::copy_n(std::istream_iterator<Record>(infile), numRecords, records);
        }
        ++size;
    }
    return records;
}
