[' ```rust
use std::collections::HashMap;
use std::rc::Rc;
use std::sync::{Arc, Mutex};
use rand::{thread_rng, RngCore, SeedableRng};
use sha2::Sha256;
use tokio::sync::watch;
use tokio::runtime::Runtime;

mod structs {
    pub struct Item {
        id: i32,
        value: f64,
        description: char,
    }
}

pub struct MemoryManager {
    array_map: Arc<Mutex<HashMap<String, Rc<Vec<*mut double>>>>,
    item_array_map: Arc<Mutex<HashMap<String, Rc<Vec<Box<structs::Item>>>>>,
    rng: thread_rng::ThreadRng,
}

impl MemoryManager {
    pub async fn new() -> Self {
        let seed = Sha256::new();
        seed.update(chrono::Utc::now().to_string().as_bytes());
        let rng = thread_rng::from_seed(seed.finalize());
        MemoryManager {
            array_map: Arc::new(Mutex::new(HashMap::new())),
            item_array_map: Arc::new(Mutex::new(HashMap::new())),
            rng,
        }
    }

    pub async fn allocate_double(&self, name: String, capacity: usize) -> *mut double {
        let mut data = self.array_map.lock().await.entry(name.clone()).or_insert_with(|| Rc::new(Vec::with_capacity(capacity)));
        let ptr = data.get_mut(capacity - 1).unwrap();
        unsafe { std::ptr::write(ptr, self.rng.gen()); }
        ptr
    }

    pub async fn allocate_item(&self, name: String, capacity: usize) -> *mut structs::Item {
        let mut data = self.item_array_map.lock().await.entry(name.clone()).or_insert_with(|| Rc::new(Vec::with_capacity(capacity)));
        let ptr = data.get_mut(capacity - 1).unwrap();
        unsafe {
            let item = Box::new(structs::Item {
                id: self.rng.gen(),
                value: self.rng.gen(),
                description: self.rng.choice(b'a'..=b'z') as char,
            });
            ptr.write(item);
        }
        ptr
    }

    pub async fn resize_array(&self, name: String, new_capacity: usize) {
        if let Some(ref mut data) = self.array_map.lock().await.get_mut(&name) {
            let old_capacity = data.len();
            data.resize(new_capacity, std::mem::zeroed());
            for i in old_capacity..new_capacity {
                unsafe {
                    let ptr = data[i];
                    if !ptr.is_null() {
                        self.array_mut(name.clone(), i).unwrap().write(self.rng.gen());
                    }
                }
            }
        }
    }

    pub async fn resize_item_array(&self, name: String, new_capacity: usize) {
        if let Some(ref mut data) = self.item_array_map.lock().await.get_mut(&name) {
            let old_capacity = data.len();
            data.resize(new_capacity, Box::new(structs::Item {
                id: 0,
                value: 0.0,
                description: '\0',
            }));
            for i in old_capacity..new_capacity {
                unsafe {
                    let ptr = data[i];
                    if !ptr.is_null() {
                        let item = ptr.as_ref().unwrap();
                        item.id = self.rng.gen();
                        item.value = self.rng.gen();
                        item.description = self.rng.choice(b'a'..=b'z') as char;
                    }
                }
            }
        }
    }

    pub async fn array_mut(&self, name: String, index: usize) -> Option<&mut Vec<*mut double>> {
        self.array_map.lock().await.get_mut(&name).and_then(|data| data.get_mut(index))
    }

    pub async fn item_mut(&self, name: String, index: usize) -> Option<&mut Box<structs::Item>> {
        self.item_array_map.lock().await.get_mut(&name).and_then(|data| data.get_mut(index))
    }
}

pub async fn run(args: Vec<String>) {
    let mm = MemoryManager::new().await;
    let (tx, rx) = watch::channel::<usize>(0);
    let rt = Runtime::new().unwrap();
    let task = rt.spawn(async move {
        for arg in args {
            if arg == "double" {
                let name = format!("d_array_{}", tx.send(1).unwrap());
                let cap = 5;
                let ptr = mm.allocate_double(name, cap).await;
                println!("Allocated double array with {} elements at: {:p}", cap, ptr);
            } else if arg == "item" {
                let name = format!("i_array_{}", tx.send(2).unwrap());
                let cap = 3;
                let ptr = mm.allocate_item(name, cap).await;
                println!("Allocated item array with {} elements at: {:p}", cap, ptr);
            } else if arg == "resize" {
                let name = format!("d_array_{}", tx.send(3).unwrap());
                let new_cap = 10;
                mm.resize_array(name, new_cap).await;
                println!("Resized double array '{}' to capacity: {}", name, new_cap);
            } else if arg == "resize_item" {
                let name = format!("i_array_{}", tx.send(4).unwrap());
                let new_cap = 7;
                mm.resize_item_array(name, new_cap).await;
                println!("Resized item array '{}' to capacity: {}", name, new_cap);
            } else {
                eprintln!("Unknown command: {}", arg);
            }
        }
    });
    task.await.unwrap();
}
```

