} HashTable;

static HashTable *ht = NULL;
static Node **nodes = NULL;
static pthread_barrier_t bar;

void init_data_structures(unsigned long capacity) {
    ht = calloc(1, sizeof(*ht));
    nodes = calloc(capacity, sizeof(Node*));
    ht->size = capacity;
    ht->mask = ht->size - 1;
    pthread_mutex_init(&ht->mutex, NULL);
    pthread_barrier_init(&bar, NULL, MAX_THREADS + 1);
}

Record *create_record(int value) {
    Record *r = mmap(NULL, sizeof(*r), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    r->value = value;
    r->status = '\0';
    r->string = NULL;
    return r;
}

void insert(int key, Record *record) {
    unsigned long index = key & ht->mask;
    pthread_mutex_lock(&ht->mutex);
    Node **node_ptr = &nodes[index];
    while (*node_ptr != NULL) node_ptr = &(*node_ptr)->next;
    *node_ptr = malloc(sizeof(Node));
    (**node_ptr) = *record;
    pthread_mutex_unlock(&ht->mutex);
}

Record* search(int key) {
    unsigned long index = key & ht->mask;
    Record *record;
    pthread_mutex_lock(&ht->mutex);
    Node **node_ptr = &nodes[index];
    while (*node_ptr != NULL && (**node_ptr).key != key) node_ptr = &(*node_ptr)->next;
    if (*node_ptr == NULL) {
        pthread_mutex_unlock(&ht->mutex);
        return NULL;
    }
    record = &((*node_ptr)->record);
    pthread_mutex_unlock(&ht->mutex);
    return record;
}

void delete(int key, Record *record) {
    unsigned long index = key & ht->mask;
    pthread_mutex_lock(&ht->mutex);
    Node **node_ptr = &nodes[index];
    while (*node_ptr != NULL && (**node_ptr).key != key) node_ptr = &(*node_ptr)->next;
    if (*node_ptr == NULL) {
        pthread_mutex_unlock(&ht->mutex);
        return;
    }
    Record *temp = *node_ptr;
    *node_ptr = temp->next;
    free(temp->string);
    free(temp);
    pthread_mutex_unlock(&ht->mutex);
}

