void insert_node(Node** head, Node* node) {
    if (*head == NULL) {
        *head = node;
    } else {
        Node* current = *head;
        while (current->key < node->key) {
            if (!current->next) {
                current->next = node;
                break;
            }
            current = current->next;
        }
        node->next = current->next;
        current->next = node;
    }
}

