    Node* current = *head;
    while (current != NULL) {
        if (current->key == key) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

StringData* find_string(StringArray* array, size_t length) {
    for (size_t i = 0; i < array->size; ++i) {
        if (array->data[i]->length == length) {
            return array->data[i];
        }
    }
    return NULL;
}

void delete_node(Node** head, int key) {
    Node* current = *head;
    Node* previous = NULL;
    while (current != NULL) {
        if (current->key == key) {
            if (previous == NULL) {
                *head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            break;
        }
        previous = current;
        current = current->next;
    }
}
