type RequestNode = (RequestBuilder, String, HeaderMap);
type UrlQueue = VecDequue<RequestNode>;

struct UrlHashMap {
    inner: RwLock<HashMap<String, UrlQueue>>,
}

impl UrlHashMap {
    fn new(capacity: usize) -> Self {
        Self {
            inner: RwLock::new(HashMap::with_capacity(capacity)),
        }
    }

    fn get(&self, key: &str) -> Option<&UrlQueue> {
        self.inner.read().get(key)
    }

    fn insert(&self, key: String, value: UrlQueue) {
        self.inner.write().insert(key, value);
    }
}

