// Write a Python function to compute and store MD5 hashes for files in a large directory structure

import os
import hashlib
import concurrent.futures
from urllib.error import URLError
import requests

def compute_md5(filepath):
    with open(filepath, 'rb') as f:
        md5 = hashlib.md5()
        while True:
            data = f.read(65536)
            if not data:
                break
            md5.update(data)
        return md5.hexdigest()

def md5_files(directory, size_threshold, workers=10):
    results = {}
    file_queue = [os.path.join(directory, fname) for fname in os.listdir(directory) if os.path.isfile(os.path.join(directory, fname))]

    with concurrent.futures.ThreadPoolExecutor(max_workers=workers) as executor:
        for future in executor.map(lambda filepath: (filepath, compute_md5(filepath)), file_queue):
            filepath, md5 = future
            if os.path.getsize(filepath) <= size_threshold:
                results[filepath] = md5

    return results
