['```php
<?php

class UserPasswordService {
    private $authService;
    private $passwordPolicy;
    private $rateLimiter;
    private $database;
    private $logService;

    public function __construct(AuthService $authService, PasswordPolicy $passwordPolicy, RateLimiter $rateLimiter, Database $database, LogService $logService) {
        $this->authService = $authService;
        $this->passwordPolicy = $passwordPolicy;
        $this->rateLimiter = $rateLimiter;
        $this->database = $database;
        $this->logService = $logService;
    }

    public function updatePassword($userId, string $newPassword) {
        try {
            // Start transaction
            $this->database->beginTransaction();

            // Validate current password with challenge-response mechanism and external authentication service
            if (!$this->authService->validatePassword($userId, $newPassword)) {
                throw new Exception("Current password mismatch");
            }

            // Enforce complex password policies
            if (!$this->passwordPolicy->isValid($newPassword)) {
                throw new Exception("Invalid password policy");
            }

            // Check for rate limiting and lockout management
            $this->rateLimiter->checkAndUpdateLockout($userId);

            // Implement uniqueness check for the new password efficiently, minimizing latency during peak hours
            if (!$this->passwordPolicy->isUnique($newPassword)) {
                throw new Exception("New password is not unique");
            }

            // Batch operations to minimize transaction lock duration
            $this->database->updateUserSaltAndHash($userId, $newPassword);
            $this->database->saveLog($userId, 'password change', $newPassword, time());

            // Commit the transaction and finalize the operation
            $this->database->commit();
        } catch (Exception $e) {
            // Rollback the transaction on failure
            $this->database->rollBack();
            $this->logService->logError($e->getMessage());
            throw $e;
        }
    }
}
```

