    public class XmlProcessor
    {
        private readonly Dictionary<string, XElement> _cache = new Dictionary<string, XElement>();
        private XmlReaderSettings _settings = new XmlReaderSettings();

        public async Task<XElement> ProcessDocument(string xmlString, string xPathQuery, IDictionary<string, string> attributesFilter = null)
        {
            // 1. Element Retrieval, Performance Optimization, Validation
            var document = LoadFromCache(xmlString);

            if (document == null)
            {
                document = XElement.Parse(xmlString);

                if (!IsWellFormed(document))
                {
                    return new XElement();
                }

                // Validate XML using external service
                var validationResult = await ValidateXmlAsync(document);

                if (!validationResult.Success)
                {
                    LogValidationError(validationResult.Message);
                    return new XElement();
                }
            }

            // 2. Filtering based on attribute values
            if (attributesFilter != null)
            {
                var elements = document.XPathSelectElements(xPathQuery).Where(e => attributesFilter.All(f => e.Attribute(f.Key)?.Value == f.Value));

                return elements.Count() > 1 ? new XElement(elements.ToList()) : elements.FirstOrDefault();
            }

            // 3. Return the first matching element or an empty XElement
            return document.XPathSelectElement(xPathQuery) ?? new XElement();
        }

        private XElement LoadFromCache(string xmlString)
        {
            if (_cache.TryGetValue(xmlString, out var cachedDocument))
                return cachedDocument;
            return null;
        }

        private bool IsWellFormed(XElement element)
        {
            try
            {
                using (var writer = XmlWriter.Create(new StringWriter()))
