class Session {
public:
    int id;
    struct sockaddr_in clientAddr;
    std::string token;
    std::chrono::system_clock::time_point lastActivity;

    Session(struct sockaddr_in addr) : id(1 + sessions.size()), lastActivity(std::chrono::system_clock::now()) {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, 255);
        for (size_t i = 0; i < token.length(); ++i) {
            token[i] = static_cast<char>(dis(gen));
        }
    }
};

std::vector<Session> sessions;
std::mutex sessionsMutex;
constexpr int maxIdleTimeSeconds = 60; // Configurable idle period

void expireInactiveSessions() {
    std::unique_lock<std::mutex> lock(sessionsMutex);
    auto now = std::chrono::system_clock::now();
    auto it = sessions.begin();
    while (it != sessions.end()) {
        if ((now - it->lastActivity) > std::chrono::seconds(maxIdleTimeSeconds)) {
            it = sessions.erase(it);
        } else {
            ++it;
        }
    }
}

void addSession(const struct sockaddr_in& addr) {
    Session session(addr);
    std::unique_lock<std::mutex> lock(sessionsMutex);
    sessions.push_back(session);
}

Session* getSession(const struct sockaddr_in& addr) {
    std::unique_lock<std::mutex> lock(sessionsMutex);
    for (auto& session : sessions) {
        if (session.clientAddr == addr) {
            return &session;
        }
    }
    return nullptr;
}
