} Record;

typedef struct Node {
    Record *data;
    struct Node *prev, *next;
} Node;

Node *head = NULL, *tail = NULL;
int cache_size = 100;
pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

void init_offsets(Node **node) {
    *node = malloc(sizeof(Node));
    (*node)->data = malloc(sizeof(Record));
    (*node)->data->offset = 0;
    (*node)->prev = NULL;
    (*node)->next = tail;
    if (tail != NULL)
        tail->next = *node;
    else
        head = *node;
    tail = *node;
}

void init_keys(Node **node, int start, int step) {
    *node = malloc(sizeof(Node));
    (*node)->data = malloc(sizeof(Record));
    (*node)->data->key = start;
    (*node)->prev = NULL;
    (*node)->next = tail;
    if (tail != NULL)
        tail->next = *node;
    else
        head = *node;
    tail = *node;
    while ((*node)->data->key < INT_MAX / step) {
        Node *new_node = malloc(sizeof(Node));
        new_node->data = malloc(sizeof(Record));
        new_node->data->key = (*node)->data->key + step;
        new_node->prev = *node;
        new_node->next = NULL;
        tail->next = new_node;
        tail = new_node;
        *node = new_node;
    }
}

Record* create_record() {
    Record *new_rec = malloc(sizeof(Record));
    new_rec->offset = 0;
    new_rec->key = -1;
    new_rec->value = rand() % 100 + 1;
    new_rec->status = 'N';
    new_rec->str = NULL;
    return new_rec;
}

void add_record(Record *rec) {
    pthread_mutex_lock(&list_lock);
    Record *node = create_record();
    node->offset = ftell(head);
    rec->offset = ftell(head);
    node->data = rec;
    if (head == tail) {
        head->next = node;
        tail = node;
    } else {
        tail->next = node;
        tail = node;
    }
    pthread_mutex_unlock(&list_lock);
}

Record* get_record(long offset) {
    Record *current = head;
    while (current != NULL) {
        if (ftell(current) == offset)
            return current->data;
        current = current->next;
    }
    return NULL;
}

void remove_record(long offset) {
    pthread_mutex_lock(&list_lock);
    Record *current = head;
    while (current != NULL) {
        if (ftell(current) == offset) {
            if (current == head)
                head = current->next;
            else if (current == tail)
                tail = current->prev;

            if (current->prev != NULL)
                current->prev->next = current->next;
            if (current->next != NULL)
                current->next->prev = current->prev;

            free(current);
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list_lock);
}

