    Product product;
    struct Node *next;
} Node;

// Hash table implementation using open addressing (linear probing)
#define TABLE_SIZE 1024
Node **products = NULL;

void init_hash_table() {
    products = calloc(TABLE_SIZE, sizeof(Node*));
    if (!products) {
        fprintf(stderr, "Error: Failed to allocate memory for hash table\n");
        exit(1);
    }
}

long hash(long id) {
    return id % TABLE_SIZE;
}

int find_product(long id) {
    int index = hash(id);
    Node *current = products[index];
    do {
        if (current->product.id == id && current != NULL)
            return 1; // Product found
        current = current->next;
    } while (current != products[index]);
    return 0; // Product not found
}

void insert_product(Product product) {
    long index = hash(product.id);
    Node *new_node = malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Error: Failed to allocate memory for new node\n");
        exit(1);
    }
    memcpy(&(new_node->product), &product, sizeof(Product));
    new_node->next = products[index];
    products[index] = new_node;
}

void delete_product(long id) {
    long index = hash(id);
    Node *current = products[index];
    if (!current) return; // Product not found in the hash table

    if (current->product.id == id) {
        products[index] = current->next;
        free(current);
        return;
    }

    while (current != NULL && current->next != NULL && current->next->product.id != id) {
        current = current->next;
    }

    if (current->next == NULL) return; // Product not found in the list

    Node *temp = current->next;
    current->next = temp->next;
    free(temp);
}

