#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <semaphore.h>
#include <sys/mman.h>

typedef struct {
    double value;
    char* string;
} DataElement;

struct Cache {
    void* data;
    size_t size;
    pthread_mutex_t lock;
    sem_t sem;
};

DataElement* create_array(size_t size, int source1, double min1, double max1, int source2, double min2, double max2) {
    DataElement* array = (DataElement*) malloc(size * sizeof(DataElement));
    if (!array) return NULL;

    struct Cache caches[2] = {{0}};
    pthread_mutex_init(&caches[0].lock, NULL);
    sem_init(&caches[0].sem, 0, 1);
    caches[1] = (struct Cache) {0};
    pthread_mutex_init(&caches[1].lock, NULL);
    sem_init(&caches[1].sem, 0, 1);

    for (size_t i = 0; i < size; ++i) {
        DataElement* current = &array[i];
        current->value = get_double(source1, source2, &caches);
        current->string = malloc(128 * sizeof(char));
        if (!current->string) return NULL;
        memset(current->string, 0, 128 * sizeof(char));
    }

    return array;
}

double get_double(int source, int other_source, struct Cache* caches) {
    double value = -1;

    if (source == other_source) {
        pthread_mutex_lock(&caches[source].lock);
        sem_wait(&caches[source].sem);

        // Read from the cache if it exists, otherwise read from the source
        if (caches[source].data) {
            value = *(double*) caches[source].data;
        } else {
            int fd = open(FILE_PATH_SOURCE, O_RDONLY);
            if (fd < 0) goto error;

            off_t size = lseek(fd, 0, SEEK_END);
            if (size <= 0) goto error;

            mmap(NULL, size, PROT_READ, MAP_PRIVATE, fd, 0);
            value = *(double*) caches[source].data = mmap(NULL, sizeof(double), PROT_WRITE, MAP_SHARED, fd, 0);

            close(fd);
        }

        sem_post(&caches[source].sem);
        pthread_mutex_unlock(&caches[source].lock);
    } else {
        // Use a thread to read from the other source if necessary
        pthread_t thread;
        int err = pthread_create(&thread, NULL, fetch_double, (void*) &caches[other_source]);
        if (err != 0) goto error;

        void* result;
        pthread_join(thread, &result);
        value = *(double*) result;
    }

    return value;

error:
    fprintf(stderr, "Error while accessing data source\n");
    // Handle the error appropriately, such as returning a default value or terminating the program

    return -1;
}

void* fetch_double(void* arg) {
    struct Cache* caches = arg;

    int fd = open(FILE_PATH_OTHER_SOURCE, O_RDONLY);
    if (fd < 0) goto error;

    off_t size = lseek(fd, 0, SEEK_END);
    if (size <= 0) goto error;

    mmap(NULL, size, PROT_READ, MAP_PRIVATE, fd, 0);
    double value = *(double*) caches->data = mmap(NULL, sizeof(double), PROT_WRITE, MAP_SHARED, fd, 0);

    close(fd);

    pthread_mutex_lock(&caches->lock);
    sem_wait(&caches->sem);

    caches->data = mmap(NULL, sizeof(double), PROT_WRITE | PROT_EXEC, MAP_SHARED, fd, 0);
    if (caches->data == MAP_FAILED) goto error;

    sem_post(&caches->sem);
    pthread_mutex_unlock(&caches->lock);

    return &value;

error:
    // Handle the error appropriately, such as returning an error code or terminating the thread
}
```

