    dc->records = calloc(initialCapacity, sizeof(Record));
    if (!dc->records) {
        perror("calloc");
        free(dc);
        return NULL;
    }
    dc->capacity = initialCapacity;
    dc->size = 0;
    return dc;
}

void destroyDynamicCollection(struct DynamicCollection* dc) {
    free(dc->records);
    sem_destroy(&dc->lock);
    free(dc);
}

int findRecordById(const struct DynamicCollection* dc, int id) {
    for (size_t i = 0; i < dc->size; ++i) {
        if (dc->records[i].id == id) {
            return i;
        }
    }
    return -1;
}

int insertRecord(struct DynamicCollection* dc, const Record* record) {
    sem_wait(&dc->lock);

    for (size_t i = 0; i < dc->size; ++i) {
        if (dc->records[i].id == record->id) {
            dc->records[i] = *record;
            sem_post(&dc->lock);
            return i;
        }
    }

    if (dc->size >= dc->capacity) {
        Record* newRecords = realloc(dc->records, (dc->capacity + 10) * sizeof(Record));
        if (!newRecords) {
            perror("realloc");
            sem_post(&dc->lock);
            return -1;
        }
        dc->records = newRecords;
        dc->capacity += 10;
    }

    dc->records[dc->size] = *record;
    ++dc->size;

    sem_post(&dc->lock);
    return dc->size - 1;
}

void printRecord(const Record* record) {
    printf("{ id: %d, offset: %ld, key: %d, value: %.2f }\n", record->id, record->offset, record->key, record->value);
}

void iterateOverRecordsAndPrint(const struct DynamicCollection* dc) {
    sem_wait(&dc->lock);
    for (size_t i = 0; i < dc->size; ++i) {
        printRecord(&dc->records[i]);
    }
    sem_post(&dc->lock);
}

void resetRecord(struct DynamicCollection* dc, int index) {
    if (index >= dc->size || index < 0) {
        fprintf(stderr, "Invalid index: %d\n", index);
        return;
    }

    sem_wait(&dc->lock);
    memset(&dc->records[index], 0, sizeof(Record));
    dc->records[index].id = -1; // Mark as empty
    sem_post(&dc->lock);
}

int getValueByIndex(const struct DynamicCollection* dc, int index) {
    if (index >= dc->size || index < 0) {
        fprintf(stderr, "Invalid index: %d\n", index);
        return -1;
    }

    sem_wait(&dc->lock);
    const Record* record = &dc->records[index];
    sem_post(&dc->lock);
    return record->value;
}
