```cpp
#include <iostream>
#include <vector>
#include <memory>
#include <random>
#include <boost/asio/thread_pool.hpp>
#include <cstdlib>

using namespace std;

struct Record {
    int value;
};

class IndexingSystem {
public:
    explicit IndexingSystem(unsigned long seed) : _seed(seed), _keys(), _offsets(), _records() {}

    void initialize(size_t offsetSize, size_t keySize, size_t recordSize);
    vector<Record>* getRecords();
    size_t findKeyIndex(int key);

private:
    unsigned long _seed;
    vector<long> _keys;
    vector<long> _offsets;
    unique_ptr<vector<Record>> _records;
};

void IndexingSystem::initialize(size_t offsetSize, size_t keySize, size_t recordSize) {
    if (offsetSize > 1000000 || keySize > 1000000 || recordSize > 1000000)
        throw invalid_argument("Array size must not exceed 1 million elements.");

    _keys.resize(offsetSize);
    _offsets.resize(offsetSize + 1);
    _records = make_unique<vector<Record>>(keySize);
}

vector<Record>* IndexingSystem::getRecords() {
    if (!_records) {
        try {
            auto newRecords = make_unique<vector<Record>>((*_records).size() * 2);
            move(*_records, newRecords.get());
            _records.reset(newRecords.release());
        } catch (...) {
            cerr << "Failed to allocate memory for record array." << endl;
            freeMemory();
            return nullptr;
        }
    }
    return _records.get();
}

size_t IndexingSystem::findKeyIndex(int key) {
    auto it = lower_bound(_keys.begin(), _keys.end(), key);
    if (it == _keys.end() || *it != key)
        return _offsets[_keys.size()];
    return *--it - _offsets.begin();
}

void IndexingSystem::freeMemory() {
    _records.reset();
    _keys.clear();
    _offsets.clear();
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        cerr << "Usage: " << argv[0] << " <seed>" << endl;
        return -1;
    }

    unsigned long seed = strtoul(argv[1], nullptr, 10);
    IndexingSystem system(seed);
    system.initialize(_offsets.size(), _records->size(), sizeof(Record));

    boost::asio::thread_pool pool(4); // Number of threads based on system resources and required concurrency level

    for (auto& record : *system.getRecords()) {
        record.value = rand_r(_seed) % 10000 + 1;
        pool.post([&]() { system.setKeyAndOffset(record.value); });
    }

    pool.join();

    return 0;
}

void IndexingSystem::setKeyAndOffset(int key) {
    auto index = findKeyIndex(key);
    if (index == _offsets.size()) {
        _keys.push_back(key);
        _offsets.push_back(_offsets.back() + 1);
    } else {
        _offsets[index+1] = _offsets[index] + 1;
    }
}
```

This implementation uses a simple growth strategy for the `record` array, reusing previously allocated memory when possible, and handles thread safety with Boost.Asio's thread pool. It also includes error handling mechanisms to prevent leaks in case of allocation failures, and a random number generator using Mersenne Twister that can generate unique keys efficiently without worrying about race conditions.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <sys/mman.h>

#define N 1000
#define M 10000
#define GROW_FACTOR 2

typedef struct Record {
    int value;
} Record;

typedef struct DynamicCollection {
    long *offsets;
    int *keys;
    Record *records;
    size_t offsetsSize, keysSize, recordsCount, maxRecords;
    pthread_mutex_t mutex;
    FILE *persistentFile;
} DynamicCollection;

DynamicCollection* createDynamicCollection() {
    DynamicCollection *dc = malloc(sizeof(DynamicCollection));
    dc->offsets = calloc(1, sizeof(long));
    dc->keys = calloc(1, sizeof(int));
    dc->records = NULL;
    dc->offsetsSize = 1;
    dc->keysSize = 1;
    dc->recordsCount = 0;
    dc->maxRecords = N;
    dc->mutex = PTHREAD_MUTEX_INITIALIZER;
    return dc;
}

void resizeArrays(DynamicCollection *dc) {
    long *newOffsets = mmap(NULL, dc->offsetsSize * GROW_FACTOR, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0);
    int *newKeys = mmap(NULL, dc->keysSize * GROW_FACTOR, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0);
    Record *newRecords = realloc(dc->records, (dc->recordsCount + N) * sizeof(Record));

    if (newOffsets == MAP_FAILED || newKeys == MAP_FAILED || newRecords == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    memcpy(newOffsets, dc->offsets, dc->offsetsSize * sizeof(long));
    memcpy(newKeys, dc->keys, dc->keysSize * sizeof(int));
    memcpy(newRecords + dc->recordsCount, dc->records, dc->recordsCount * sizeof(Record));

    free(dc->offsets);
    free(dc->keys);
    free(dc->records);

    dc->offsets = newOffsets;
    dc->keys = newKeys;
    dc->records = newRecords;
    dc->offsetsSize *= GROW_FACTOR;
    dc->keysSize *= GROW_FACTOR;
}

void saveState(DynamicCollection *dc) {
    if (dc->persistentFile == NULL || dc->recordsCount >= M) {
        return;
    }

    fseek(dc->persistentFile, 0, SEEK_SET);
    fwrite(dc->offsets, sizeof(long), dc->recordsCount + 1, dc->persistentFile);
    fwrite(dc->keys, sizeof(int), dc->recordsCount + 1, dc->persistentFile);
    fwrite(dc->records, sizeof(Record), dc->recordsCount, dc->persistentFile);
}

DynamicCollection* initWithData(DynamicCollection *dc, FILE *dataFile) {
    fseek(dataFile, 0, SEEK_SET);
    size_t offsetSize = 0;
    size_t keySize = 0;
    size_t recordSize = sizeof(Record);
    dc->persistentFile = dataFile;

    while (!feof(dataFile)) {
        if (dc->recordsCount >= dc->maxRecords) {
            resizeArrays(dc);
        }

        fread(&dc->offsets[offsetSize], sizeof(long), 1, dataFile);
        fread(&dc->keys[keySize], sizeof(int), 1, dataFile);
        fread(&dc->records[dc->recordsCount], recordSize, 1, dataFile);

        dc->records[dc->recordsCount].value = dc->keys[keySize];
        offsetSize++;
        keySize++;
        dc->recordsCount++;
    }

    return dc;
}
```

This code creates a `DynamicCollection` struct and implements the given requirements. The function to manage the dynamic collection is not provided, but the necessary elements for it are set up. The functions included handle initializing the data structures with external data, resizing arrays as needed based on usage, saving the state of records to disk after every M operations, and handling concurrent access using a mutex. Memory mapping is used for efficient memory utilization.']

