// Lock-free implementation of linked list for thread-safe access to records array:
struct ListNode {
    Record data;
    std::atomic<ListNode*> next;
};

std::atomic<ListNode*> head = nullptr;

void addToList(Record record) {
    ListNode* node = new ListNode{record};
    node->next.store(head, std::memory_order_relaxed);
    head.compare_exchange_strong(node, head, node, std::memory_order_acq_relaxed);
}

Record fetchFromList() {
    ListNode* current = head;

    while (current != nullptr) {
        auto temp = current->next.load(std::memory_order_relaxed);
        if (!temp) break; // List is empty from this point onwards.

        std::atomic_thread_fence(std::memory_order_acq_relaxed);
        current = temp;
    }

    auto value = current ? current->data : Record{};
    head.compare_exchange_strong(current, nullptr, nullptr, std::memory_order_release);
    delete current;

    return value;
}
```

