static long int keys[512];
static size_t current_record = 0;
static size_t memory_usage = 0;

bool allocate_record() {
    if (current_record >= sizeof(records) / sizeof(Record)) return false;

    Record *new_record = &records[current_record++];
    new_record->value = rand() % 1001;

    offsets[memory_usage] = (long int)new_record - (long int)&records[0];
    keys[memory_usage++] = current_record - 1;

    if (memory_usage > 65536) {
        // Free all allocated resources
        for (size_t i = 0; i < memory_usage; ++i) {
            memmove(&records[0] + keys[i], &records[keys[i]], sizeof(Record));
        }
        current_record -= memory_usage;
        memory_usage = 0;
        return false;
    }
    return true;
}

void free_allocated() {
    // Free all allocated resources
    for (size_t i = 0; i < current_record; ++i) {
        memmove(&records[0] + keys[i], &records[keys[i+1]], sizeof(Record));
    }
    current_record -= memory_usage;
    memory_usage = 0;
}
