namespace bs = boost::asio;
using DemoApiClient = class SandeshClient {
public:
    SandeshClient(bs::io_context& ioContext) : strand_(ioContext), pool_(ioContext) {}

    void makeRequest(const std::string& url, const long offset, const int key, record& record) {
        auto self = shared_from_this();
        auto request = std::make_shared<bs::http::request<void>>(bs::http::verb::get, url);
        request->set(bs::http::field::user_agent, "DemoApiClient/1.0");

        auto timeoutAdjuster = [this](const bs::system_error& e) {
            if (e.code() == boost::system::errc::timed_out)
                requestTimeOut_.restart();
        };

        request->set_option(bs::bind_adapter<bs::streambuf>(requestTimeOut_, timeoutAdjuster));

        pool_.get_next([self, request](auto error) {
            if (!error) {
                self->sendRequest(*request);
            } else {
                std::cout << "Error getting connection: " << error.message() << '\n';
            }
        });
    }

private:
    void sendRequest(bs::http::request<void> request) {
        auto self = shared_from_this();
        bs::io_context::strand strand;
        bs::streambuf requestBody;
        auto response = bs::http::response<void>();

        bs::async_connect(pool_.returned_connection(), [self, request, &requestBody](auto error) {
            if (!error) {
                self->sendRequestImpl(request, requestBody, response, strand);
            } else {
                std::cout << "Error connecting: " << error.message() << '\n';
            }
        });
    }

    void sendRequestImpl(bs::http::request<void> request, bs::streambuf& requestBody, bs::http::response<void>& response, bs::io_context::strand strand) {
        auto self = shared_from_this();
        bs::async_write(self->socket_, boost::asio::buffer(request.to_string()), [&](auto error, size_t bytesTransferred) {
            if (!error) {
                requestBody.data(bs::buffers_begin(request.body()));
                requestBody.commit(bs::buffers_size(request.body()));

                bs::async_read_until(self->socket_, response, "\r\n\r\n", strand, [&](auto error, size_t bytesTransferred) {
                    if (!error) {
                        self->handleResponse(request, response);
                    } else {
                        std::cout << "Error reading response: " << error.message() << '\n';
                    }
                });
            } else {
                std::cout << "Error sending request: " << error.message() << '\n';
            }
        });
    }

    void handleResponse(bs::http::request<void> request, bs::http::response<void> response) {
        int statusCode = static_cast<int>(response.result().code());
        if (statusCode >= 200 && statusCode < 300) {
            std::cout << "Successful request: " << request.target() << '\n';
            // Implement logic to parse response data and populate record structure
        } else {
            std::cout << "Failed request: " << request.target() << ", status code: " << statusCode << '\n';
        }

        ++numSuccessfulRequests_;
    }

    bs::io_context& ioContext_;
    bs::steady_timer requestTimeOut_;
    bs::io_context::strand strand_;
    bs::io_context::work work_;
    bs::io_service pool_;
