#include <pthread.h>
#include <stdlib.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>

typedef struct Record {
    int key;
    long offset;
} Record;

struct MemoryBlock {
    size_t capacity; // Total number of Records this block can hold
    Record* records;  // Pointer to the records in this memory block
};

struct MemoryPool {
    struct MemoryBlock* blocks;
    size_t num_blocks;
    pthread_mutex_t lock;
};

void* create_memory_block(struct MemoryPool* pool) {
    void *addr;
    struct MemoryBlock* block = mmap(0, sizeof(Record) * POOL_CAPACITY, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (block == MAP_FAILED) {
        return NULL;
    }

    struct MemoryBlock* new_block = malloc(sizeof(struct MemoryBlock));
    if (!new_block) {
        munmap(block, sizeof(Record) * POOL_CAPACITY);
        return NULL;
    }

    new_block->capacity = POOL_CAPACITY;
    new_block->records = block;
    pool->blocks = realloc(pool->blocks, sizeof(struct MemoryBlock) * (++pool->num_blocks));
    if (!pool->blocks) {
        free(new_block);
        munmap(block, sizeof(Record) * POOL_CAPACITY);
        return NULL;
    }

    pool->blocks[pool->num_blocks - 1] = new_block;
    return block;
}

struct RecordPool* create_record_pool(size_t max_records, size_t pool_capacity) {
    struct MemoryPool* pool = malloc(sizeof(struct MemoryPool));
    if (!pool) {
        return NULL;
    }

    pool->blocks = calloc(1, sizeof(struct MemoryBlock));
    if (!pool->blocks) {
        free(pool);
        return NULL;
    }

    pool_capacity = (pool_capacity > max_records / POOL_CAPACITY) ? max_records / POOL_CAPACITY : pool_capacity;
    pool->num_blocks = 1;
    pool->lock = PTHREAD_MUTEX_INITIALIZER;

    pthread_t thread;
    if (pthread_create(&thread, NULL, create_memory_block, pool) != 0) {
        free(pool);
        return NULL;
    }

    // Wait for the memory block creation to complete before continuing
    void* block = pthread_join(thread, NULL);

    if (!block) {
        free(pool);
        return NULL;
    }

    struct RecordPool* record_pool = malloc(sizeof(struct RecordPool));
    if (!record_pool) {
        free(pool);
        munmap(block, sizeof(Record) * POOL_CAPACITY);
        return NULL;
    }

    record_pool->pool = pool;
    record_pool->num_records = 0;
    record_pool->max_records = max_records;
    record_pool->records = block;

    return record_pool;
}

