typedef struct Packet {
    unsigned long ID;
    unsigned int sequence_number;
    unsigned int payload_length;
    void* payload;
    pthread_mutex_t id_mutex;
} Packet;

// Function to initialize a new packet with given ID, sequence number and payload length.
Packet* create_packet(unsigned long id, unsigned int seq_num, unsigned int len) {
    Packet* packet = (Packet*) malloc(sizeof(Packet));
    if (!packet) {
        perror("Memory allocation failed");
        return NULL;
    }

    packet->ID = id;
    packet->sequence_number = seq_num;
    packet->payload_length = len;
    packet->payload = malloc(len);
    if (!packet->payload) {
        free(packet);
        perror("Memory allocation for payload failed");
        return NULL;
    }

    pthread_mutex_init(&packet->id_mutex, NULL);
    return packet;
}

// Function to validate the uniqueness of a given ID in the array.
bool validate_id(Packet** packets, unsigned long id, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (packets[i]->ID == id) {
            return false;
        }
    }
    return true;
}

// Function to manage dynamic memory allocation and initialization of an array of packets.
Packet** allocate_packet_array(size_t* packet_count, size_t capacity) {
    Packet** packets = (Packet**) malloc(capacity * sizeof(Packet*));
    if (!packets) {
        perror("Memory allocation failed");
        return NULL;
    }

    for (size_t i = 0; i < capacity; ++i) {
        packets[i] = NULL;
    }

    *packet_count = 0;
    return packets;
}

// Function to add a packet to the array, handling duplicate IDs gracefully.
bool add_packet(Packet** packets, Packet* new_packet) {
    for (size_t i = 0; i < *packets; ++i) {
        if (!validate_id(packets, new_packet->ID, *packets)) {
            free(new_packet);
            return false;
        }
    }

    packets[*packets] = new_packet;
    (*packets)++;
    return true;
}
