    size_t size;
    struct memory_block* next;
};

struct memory_pool {
    struct memory_block* head;
    struct memory_block* tail;
};

// Implement hash table with dynamic resizing and thread-safe operations.
typedef struct hash_table {
    size_t capacity; // Current number of buckets in the hash table.
    size_t threshold; // Trigger for automatic resizing.
    size_t load_factor; // Load factor for determining when to resize.
    void** table; // The actual hash table.
    pthread_mutex_t lock;
} HashTable;

HashTable* create_hash_table(size_t initial_capacity, size_t threshold, float load_factor) {
    // Initialize the hash table.
    HashTable* ht = malloc(sizeof(HashTable));
    ht->capacity = initial_capacity;
    ht->threshold = threshold;
    ht->load_factor = load_factor;
    ht->table = calloc(ht->capacity, sizeof(void*));
    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

size_t hash_function(int key) {
    // Implement your own hash function here.
    return key % ht->capacity;
}

void resize_hash_table(HashTable* ht) {
    size_t new_capacity = ht->capacity * 2;
    void** new_table = realloc(ht->table, new_capacity * sizeof(void*));

    if (!new_table) return;
    ht->table = new_table;
    ht->capacity = new_capacity;
}

// Implement other necessary functions for managing the hash table, such as insertion, lookup, and deletion.

struct memory_pool* create_memory_pool(size_t initial_size) {
    // Initialize the memory pool.
    struct memory_pool* mp = malloc(sizeof(struct memory_pool));
    mp->head = mp->tail = NULL;
    size_t block_size = 4096; // Adjust this value as needed.
    mp->next = calloc(initial_size, sizeof(struct memory_block));
    return mp;
}

void* mem_alloc(struct memory_pool* mp, size_t size) {
    if (!mp->head) { // If the pool is empty, allocate a new block.
        void* new_block = mmap(NULL, size + sizeof(struct memory_block), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        struct memory_block* b = (struct memory_block*)new_block;
        b->size = size;
        b->next = NULL;
        mp->head = b;
        mp->tail = b;
    } else { // If the pool is not empty, get a block from the head of the free list.
        struct memory_block* b = mp->head;
        if (b->size >= size + sizeof(struct memory_block)) {
            void* mem = (char*)b + sizeof(struct memory_block);
            b->size -= size + sizeof(struct memory_block);
            return mem;
        } else { // If the block is too small, merge adjacent blocks and try again.
            if (b->next && b->next->size > sizeof(struct memory_block)) {
                void* merged_block = (char*)b + b->size;
                size_t new_size = b->next->size - sizeof(struct memory_block);
                memcpy(merged_block, b->next, new_size);
                mp->head->size += new_size + sizeof(struct memory_block);
                free(b->next);
            } else { // If there are no suitable adjacent blocks, allocate a new one.
                void* new_block = mmap(NULL, size + sizeof(struct memory_block), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
                struct memory_block* b2 = (struct memory_block*)new_block;
                b2->size = size;
                b2->next = NULL;
                mp->head->next = b2;
                mp->tail = b2;
            }
        }
    }
    return (char*)mp->head + sizeof(struct memory_block);
}

void mem_free(struct memory_pool* mp, void* ptr) {
    if (!ptr) return;
    struct memory_block* b = (struct memory_block*)((char*)ptr - sizeof(struct memory_block));
    b->next = mp->head;
    mp->head = b;
}

// Implement other necessary functions for managing the memory pool, such as printing statistics.

void init_data_structures(HashTable* ht, struct memory_pool* mp, size_t num_records, long offsets[], int keys[], int range) {
    pthread_mutex_lock(&ht->lock);
    for (size_t i = 0; i < num_records; ++i) {
        // Allocate memory for a record using the memory pool.
        record* r = mem_alloc(mp, sizeof(record));

        // Initialize the random value within the specified range.
        r->value = rand() % range;

        // Insert the record into the hash table using the key.
        int key_index = hash_function(keys[i]);
        void** bucket = &ht->table[key_index];
        while (*bucket != NULL) {
            if ((record*)(*bucket)->value == keys[i]) {
                // Handle duplicate keys if necessary.
                break;
            }
            bucket = (void**)&((char*)*bucket + offsets[*((int*)(*bucket)->value).key]);
        }
        *bucket = r;
    }
    pthread_mutex_unlock(&ht->lock);
}
