int is_unique_id(const Packets *packets, size_t start_index, int id) {
    for (size_t i = start_index; i < packets->count; ++i) {
        if (packets->packets[i].id == id)
            return 0;
    }
    return 1;
}

void populate_payloads(Packets *packets, size_t count, size_t min_length, size_t max_length) {
    for (size_t i = 0; i < count; ++i) {
        packets->packets[i].payload_length = rand() % (max_length - min_length + 1) + min_length;
    }
}

int is_expired(const Packet *packet, time_t timeout) {
    return packet->timestamp + timeout < time(NULL);
}

void remove_expired(Packets *packets, time_t timeout) {
    size_t new_count = 0;

    for (size_t i = 0; i < packets->count; ++i) {
        if (!is_expired(&packets->packets[i], timeout)) {
            packets->packets[new_count] = packets->packets[i];
            new_count++;
        }
    }

    packets->count = new_count;
}

void serialize(Packets *packets, FILE *file) {
    fwrite(&packets->capacity, sizeof(size_t), 1, file);
    fwrite(&packets->count, sizeof(size_t), 1, file);

    for (size_t i = 0; i < packets->count; ++i) {
        fwrite(&packets->packets[i].id, sizeof(int), 1, file);
        fwrite(&packets->packets[i].sequence_number, sizeof(int), 1, file);
        fwrite(&packets->packets[i].payload_length, sizeof(size_t), 1, file);
        fwrite(&packets->packets[i].timestamp, sizeof(time_t), 1, file);
    }
}

void deserialize(Packets *packets, FILE *file) {
    fread(&packets->capacity, sizeof(size_t), 1, file);
    fread(&packets->count, sizeof(size_t), 1, file);

    packets->packets = (Packet *) realloc(packets->packets, packets->capacity * sizeof(Packet));

    for (size_t i = 0; i < packets->count; ++i) {
        fread(&packets->packets[i].id, sizeof(int), 1, file);
        fread(&packets->packets[i].sequence_number, sizeof(int), 1, file);
        fread(&packets->packets[i].payload_length, sizeof(size_t), 1, file);
        fread(&packets->packets[i].timestamp, sizeof(time_t), 1, file);
    }
}
