            for (int i = 0; i < MAX_RECORDS; i++) {
                long offset = START_OFFSET + (i / RECORD_SIZE) * RECORD_SIZE;
                int key = fileKeys[rand.nextInt(fileKeys.length)];
                records[i] = new Record(offset, rand.nextInt((int) ((END_OFFSET - START_OFFSET) / MAX_RECORDS)));
            }

            // Ensure total memory usage does not exceed the specified limit
            long currentMemoryUsage = MemoryManager.getCurrentMemoryUsage();
            if (currentMemoryUsage > MEMORY_LIMIT) {
                System.out.println("Memory limit exceeded. Freeing allocated memory.");
                Arrays.fill(fileOffsets, 0L);
                Arrays.fill(fileKeys, 0);
                for (Record record : records) {
                    record = null;
                }
                throw new OutOfMemoryError("Out of memory");
            }

            // Implement concurrent processing strategy and thread safety
