    int cmp = value - root->item.value;
    Node* node_ptr = (cmp > 0) ? root->right : root->left;
    return find(node_ptr, value);
}

void update_description(Node* node, const char* new_desc) {
    free(node->item.description);
    node->item.description = strdup(new_desc);
}

int add_item(BST* bst, Item item) {
    if (bst->root) bst->root = bst_insert(bst->root, item);
    else bst->root = create_node(item);
    return 0; // success
}

int update_item(BST* bst, float value, const char* new_desc) {
    Item* item_ptr = find(bst->root, value);
    if (!item_ptr) return -1; // not found
    pthread_mutex_lock(&item_ptr->lock);
    update_description(item_ptr, new_desc);
    pthread_mutex_unlock(&item_ptr->lock);
    return 0; // success
}

int delete_item(BST* bst, float value) {
    Node** node_ptr = &bst->root;
    while (*node_ptr) {
        int cmp = value - (*node_ptr)->item.value;
        if (cmp < 0) node_ptr = &(*node_ptr)->left;
        else if (cmp > 0) node_ptr = &(*node_ptr)->right;
        else break;
    }
    if (!*node_ptr) return -1; // not found
    Node* temp = *node_ptr;
    if (!temp->left) *node_ptr = temp->right;
    else if (!temp->right) *node_ptr = temp->left;
    else {
        Node* min_node = find_min(temp->right);
        temp->item = min_node->item;
        *node_ptr = min_node;
    }
    free(temp);
    return 0; // success
}

