typedef struct Event {
    int id;
    long offset;
    int timestamp;
    int data_int;
    char status;
    char* description;
    char* timestamp_str;
} Event;

typedef struct Node {
    Event record;
    struct Node *next;
} Node;

const int MAX_RECORDS = 10000;
const int MIN_DATA_INT = 1, MAX_DATA_INT = 100;
const char* DATE_FORMAT = "%Y-%m-%d %H:%M:%S";

int add_record(Node** head, Event* record) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -1; // Memory allocation error

    new_node->record = *record;
    new_node->next = *head;
    *head = new_node;

    // Format and validate timestamp
    char timestamp_str[32];
    strftime(timestamp_str, sizeof(timestamp_str), DATE_FORMAT, localtime(&(new_node->record.timestamp)));
    strcpy(new_node->record.timestamp_str, timestamp_str);

    // Set random data_int value
    new_node->record.data_int = rand() % (MAX_DATA_INT - MIN_DATA_INT + 1) + MIN_DATA_INT;

    return 0; // Successfully added record
}

int remove_by_key(Node** head, int key) {
    Node* current = *head;
    Node* previous = NULL;

    while (current != NULL && current->record.id == key) {
        previous = current;
        current = current->next;
        free(previous->record.description);
        free(previous->record.timestamp_str);
        free(previous);
        *head = current;
    }

    if (current == NULL) return -1; // Record not found

    // Move previous to the next node and free the current node's memory
    previous->next = current->next;
    free(current->record.description);
    free(current->record.timestamp_str);
    free(current);

    return 0; // Successfully removed record
}

Event* get_by_key(Node* head, int key) {
    Node* current = head;

    while (current != NULL && current->record.id != key) {
        current = current->next;
    }

    if (current == NULL) return NULL; // Record not found

    return &current->record; // Return the record pointer
}

Event* get_by_timestamp(Node* head, char* timestamp_str) {
    Node* current = head;

    while (current != NULL) {
        if (strcmp(current->record.timestamp_str, timestamp_str) == 0) {
            return &current->record; // Return the record pointer
        }
        current = current->next;
    }

    return NULL; // Record not found
}

int update_status(Node** head, int key, char status) {
    Node* current = *head;

    while (current != NULL && current->record.id != key) {
        current = current->next;
    }

    if (current == NULL) return -1; // Record not found

    current->record.status = status;

    return 0; // Successfully updated status
}

void prune_list(Node** head, int max_records) {
    Node* current = *head;
    Node* temp;

    while (current != NULL && (*head)->next != NULL && ((*head)->next->next) != NULL) {
        if (((*head)->next)->record.timestamp < current->record.timestamp) {
            temp = current;
            current = current->next;
            free(temp->record.description);
            free(temp->record.timestamp_str);
            free(temp);
        } else {
            break;
        }
    }

    *head = (*head)->next; // Move head to the next node after pruning
}
```

