} Node;

#define MAX_RECORDS 1000000
Node *head = NULL;

unsigned long total_memory = 0;
unsigned long fragmentation = 0;
double avg_ttl = 0.0;
pthread_mutex_t memory_mutex = PTHREAD_MUTEX_INITIALIZER;

void init_record(Record *record) {
    record->value = rand() % 100 + 1;
    record->status_flag = 'N';
    record->data = malloc(rand() % 100 + 1);
    memset(record->data, '\0', rand() % 100 + 1);
    record->priority = rand() % 5 + 1;
    record->timestamp = malloc(sizeof(struct timespec));
}

void init_list() {
    long offset = 0;
    int key = 2;
    for (int i = 0; i < MAX_RECORDS / 2 + 1; ++i) {
        Node *node = malloc(sizeof(Node));
        node->offset = offset++;
        node->key = key;
        node->record = malloc(sizeof(Record));
        init_record(node->record);
        node->next = head;
        head = node;
        if (i < (MAX_RECORDS / 2)) {
            key += getPrimeNumber(key);
        }
    }
}

long getFibonacci(int n) {
    long a = 0, b = 1;
    while (n > 0) {
        long temp = a + b;
        a = b;
        b = temp;
        --n;
    }
    return a;
}

int getPrimeNumber(int n) {
    for (int i = n + 2; ; ++i) {
        int is_prime = 1;
        for (int j = 2; j * j <= i; ++j) {
            if (i % j == 0) {
                is_prime = 0;
                break;
            }
        }
        if (is_prime) {
            return i;
        }
    }
}

Node* find(int key) {
    Node *current = head;
    while (current != NULL) {
        if (current->key == key) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

void add(Record *record) {
    Node *new_node = malloc(sizeof(Node));
    new_node->offset = getFibonacci(head->offset + 1);
    new_node->key = getPrimeNumber(new_node->offset);
    new_node->record = record;
    new_node->next = NULL;

    Node *current = head;
    while (current->next != NULL) {
        if (current->next->offset > new_node->offset) {
            new_node->next = current->next;
            current->next = new_node;
            return;
        }
        current = current->next;
    }
    current->next = new_node;
}

void remove(int key) {
    Node *current = head;
    Node *prev = NULL;

    while (current != NULL) {
        if (current->key == key) {
            if (prev != NULL) {
                prev->next = current->next;
            } else {
                head = current->next;
            }
            free(current->record);
            free(current->timestamp);
            free(current);
            return;
        }
        prev = current;
        current = current->next;
    }
}

void update(int key, Record *new_record) {
    Node *node = find(key);
    if (node != NULL) {
        free(node->record->data);
        node->record->data = malloc(rand() % 100 + 1);
        memset(node->record->data, '\0', rand() % 100 + 1);
        memcpy(node->record, new_record, sizeof(Record));
    }
}

void search(int key) {
    Node *node = find(key);
    if (node != NULL) {
        printf("Record found with key: %d\n", key);
        printf("Value: %d\n", node->record->value);
        printf("Status flag: %c\n", node->record->status_flag);
        printf("Data: %s\n", node->record->data);
        printf("Priority: %d\n", node->record->priority);
        printf("Timestamp: %.9lf seconds\n", node->record->timestamp->tv_sec + node->record->timestamp->tv_nsec / 1000000000.0);
    } else {
        printf("Record not found with key: %d\n", key);
    }
}

void calculate_avg_ttl() {
    pthread_mutex_lock(&memory_mutex);
    int count = 0;
    double total_time = 0.0;
    Node *current = head;
    while (current != NULL) {
        if (current->record->timestamp != NULL) {
            count++;
            total_time += current->record->timestamp->tv_sec + current->record->timestamp->tv_nsec / 1000000000.0;
        }
        current = current->next;
    }
    avg_ttl = total_time / count;
    pthread_mutex_unlock(&memory_mutex);
}

void report_memory() {
    pthread_mutex_lock(&memory_mutex);
    fragmentation = (total_memory - MAX_RECORDS * sizeof(Node) - MAX_RECORDS * sizeof(Record)) / (double)getpagesize();
    printf("Total memory usage: %.2f%%\n", total_memory * 100.0 / getpagesize());
    printf("Fragmentation: %.2f%%\n", fragmentation * 100.0);
    pthread_mutex_unlock(&memory_mutex);
}

void* update_data(void *arg) {
    while (1) {
        // Connect to external data source and fetch updates here
        calculate_avg_ttl();
        report_memory();
        sleep(60);
    }
}

int main() {
    init_list();
    Record record;
    add(&record);
    update(1, &record);
    search(1);
    remove(1);
    pthread_t update_thread;
    pthread_create(&update_thread, NULL, update_data, NULL);

    // Continue with other program logic here
}
