#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#define MAX_FILES 2000
static pthread_mutex_t cache_mutex = PTHREAD_MUTEX_INITIALIZER;
static int num_files = 0;
static char *cache[MAX_FILES] = {0}; // simple cache for previously generated filenames
static size_t cache_size = MAX_FILES;

// Helper function to generate a unique random string of 7 uppercase letters
char *generate_random_string(void) {
    static char alpha[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    static char str[8]; // 8-length buffer for safety
    size_t timestamp = time(NULL);
    size_t i, j;

    // Combine a timestamp and a cryptographically secure pseudo-random number generator (arc4random)
    for (i = 0; i < 7; ++i) {
        str[i] = alpha[(timestamp % 36) + (arc4random() / (RAND_MAX / 36))];

        // Search for duplicates, replace if found
        for (j = i - 1; j >= 0 && str[i] == str[j]; --j) {
            str[j] = str[i];
        }
    }

    return strdup(str);
}

// Function to process batched file requests concurrently
void process_files(char **filenames, size_t count) {
    size_t i;
    pthread_t threads[count];
    char *new_filename = 0;

    for (i = 0; i < count; ++i) {
        new_filename = filename_processor(filenames[i]);

        if (!new_filename || strcmp(new_filename, filenames[i])) { // handle edge cases and potential collisions
            free(new_filename);
            continue;
        }

        pthread_create(&threads[i], NULL, filename_processor_thread, (void*) new_filename);
    }

    for (i = 0; i < count; ++i) {
        pthread_join(threads[i], NULL);
    }
}

// Thread-safe cache management functions
char *get_cached_filename(const char *original_filename) {
    char *result = 0;
    size_t i;

    pthread_mutex_lock(&cache_mutex);
    for (i = 0; i < num_files && cache[i] != original_filename; ++i) {}
    if (i < num_files) {
        result = cache[i];
    }
    pthread_mutex_unlock(&cache_mutex);

    return result;
}

void put_cached_filename(const char *original_filename, const char *new_filename) {
    size_t i;

    pthread_mutex_lock(&cache_mutex);
    for (i = 0; i < num_files && cache[i] != original_filename; ++i) {}
    if (i >= num_files) { // eviction strategy, adjust cache size dynamically based on system metrics
        if (num_files == cache_size) {
            free(cache[0]);
            memmove(cache, cache + 1, --cache_size * sizeof(char*));
            --num_files;
        }
    }
    cache[num_files++] = new_filename;
    pthread_mutex_unlock(&cache_mutex);
}

// Main function to process filename
char *filename_processor(const char *original_filename) {
    size_t original_length = strlen(original_filename);
    size_t digits = 0;
    int current_char;

    for (size_t i = 0; i < original_length && digits < 10; ++i) {
        current_char = (unsigned char) original_filename[i];
        if (current_char >= '0' && current_char <= '9') {
            ++digits;
        }
    }

    // Generate unique random string and replace extension as required
    char *random_string = generate_random_string();
    char new_filename[260] = {0};

    snprintf(new_filename, sizeof(new_filename), "%.*s.modified.%u.%s.%s", digits, original_filename, digits, random_string, get_file_extension(original_filename));

    char *cached_filename = get_cached_filename(original_filename);
    if (!cached_filename || strcmp(cached_filename, new_filename)) { // ensure uniqueness across sessions and handle potential collisions
        put_cached_filename(original_filename, new_filename);
    }

    free(random_string);
    return cached_filename || new_filename;
}

// Helper function to extract the file extension from a given filename
const char *get_file_extension(const char *filename) {
    const size_t length = strlen(filename);
    size_t i;

    for (i = length - 1; i >= 0 && filename[i] != '.'; --i) {}

    if (i == length || i + 4 > length) {
        return filename + i;
    }

    return filename + i + 1;
}
