            optimize_asset(filePath, outDir, pFormatCtx->streams[stStreamIndex], qualityThreshold, resolutionTarget);
    }

    // Save the optimized asset to the specified directory
    if (avformat_write_header(&pFormatCtx, outFormat, NULL, NULL) < 0) {
        fprintf(stderr, "Couldn't save output file: %s\n", outDir);
        return filePath;
    }
    char *outFilePath = av_strdup_printf("%s/%s", outDir, pFormatCtx->filename);

    // Save the optimized asset to disk and close I/O resources
    if (avio_closep(&pFormatCtx->pb) < 0 || av_write_frame(pFormatCtx, NULL) < 0) {
        fprintf(stderr, "Error while saving output file: %s\n", outFilePath);
        free(outFilePath);
        return filePath;
    }

    // Return the optimized asset's new file path
    return outFilePath;
