#include <openssl/aes.h>
#include <openssl/sha.h>
#include <pthread.h>

typedef struct Record {
    int key;
    long offset;
} Record;

// Dynamically allocate and initialize arrays for keys and offsets
Record* init_arrays(size_t capacity) {
    Record *keys = (Record *)malloc(capacity * sizeof(Record));
    long *offsets = (long *)calloc(capacity, sizeof(long));
    if (!keys || !offsets) {
        free(keys);
        free(offsets);
        return NULL;
    }
    return keys;
}

// Generate random number within a specified range
int rand_in_range(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Initialize AES-256-CBC cipher with given password and return the initialized EVP_CIPHER_CTX structure
EVP_CIPHER_CTX *init_aes256cbc(const char *password) {
    const EVP_CIPHER *cipher = EVP_aes_256_cbc();
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int rc;

#if OPENSSL_VERSION_NUMBER >= 0x10100000L
    // Use SHA-256 for key derivation instead of SHA-1 (OpenSSL version 1.1.0 and later)
    uint8_t sha256_key[EVP_MAX_MD_SIZE];
    SHA256(password, strlen(password), sha256_key);
    rc = EVP_EncryptInit_ex(ctx, cipher, NULL, sha256_key, NULL);
#else
    // Use PKCS5/PKCS7 padding scheme (OpenSSL version 1.0.2 and earlier)
    uint8_t pkcs5_key[32];
    RC4(password, strlen(password), pkcs5_key);
    rc = EVP_EncryptInit_ex(ctx, cipher, NULL, pkcs5_key, NULL);
#endif

    if (rc != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

// Function to clean up and disable the cipher when it is no longer in use
void aes256cbc_cleanup(EVP_CIPHER_CTX *ctx) {
    EVP_CIPHER_CTX_free(ctx);
}

// Ensure thread safety by using pthread mutex for concurrent access
pthread_mutex_t lock;

void init_mutex() {
    pthread_mutexattr_t attr;
    int rc = pthread_mutexattr_init(&attr);
    if (rc != 0) return;

#if defined(_POSIX_C_SOURCE) && _POSIX_C_SOURCE >= 200809L
    rc = pthread_mutexattr_setrobust(attr, PTHREAD_MUTEX_ROBUST);
#endif
    if (rc != 0) return;

    rc = pthread_mutex_init(&lock, &attr);
    pthread_mutexattr_destroy(&attr);
    if (rc != 0) return;
}

// Implement a thread-safe version of appending a record to the arrays
void append_record(Record **keys, long *offsets, size_t *capacity, int key, long offset) {
    pthread_mutex_lock(&lock);
    if (*capacity >= ARRAY_SIZE) {
        // Reallocate memory when the capacity is reached
        Record *new_keys = (Record *)realloc(*keys, 2 * *capacity * sizeof(Record));
        long *new_offsets = (long *)realloc(offsets, 2 * *capacity * sizeof(long));
        if (!new_keys || !new_offsets) {
            pthread_mutex_unlock(&lock);
            return;
        }
        *keys = new_keys;
        offsets = new_offsets;
        *capacity *= 2;
    }
    (*keys)[*offsets] = (Record){key, offset};
    (*offsets)++;
    pthread_mutex_unlock(&lock);
}

// Main function to populate the record arrays with random values and initialize the AES-256-CBC cipher
void populate(size_t capacity, const char *password) {
    Record *keys = init_arrays(capacity);
    long *offsets = NULL;
    if (!keys) return;

    offsets = (long *)calloc(capacity, sizeof(long));
    if (!offsets) {
        free(keys);
        return;
    }

    init_mutex();

    // Populate the arrays with random values within a specified range and initialize the AES-256-CBC cipher
    EVP_CIPHER_CTX *ctx = init_aes256cbc(password);
    if (!ctx) {
        free(keys);
        free(offsets);
        return;
    }

    srand(time(NULL));
    for (size_t i = 0; i < capacity; ++i) {
        append_record(&keys, offsets, &capacity, rand_in_range(1, INT_MAX), i);
    }

    // Clean up the cipher when it is no longer in use
    aes256cbc_cleanup(ctx);

    free(keys);
    free(offsets);
}
```

This code provides a function `populate()` that populates an array of records with random values, ensuring thread safety by using a pthread mutex. The function also initializes the AES-256-CBC cipher with the given password and derives the encryption key from it using SHA-256. Memory allocation is handled dynamically to minimize overhead during initialization.']

