```c
#include <sys/stat.h>
#include <unistd.h>
#include <pwd.h>
#include <grp.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int createDirectoryWithPermissions(char *path, mode_t permissions, uid_t owner, gid_t group) {
    struct stat st;
    if (stat(path, &st) == -1) { // Check if directory exists
        return 0;
    }

    if (!(S_ISDIR(st.st_mode))) { // Check if it's a directory
        perror("Path is not a directory");
        return 0;
    }

    if (st.st_uid != owner || st.st_gid != group) { // Check ownership
        perror("Directory does not have the correct ownership");
        return 0;
    }

    if (!(S_ISUID(st.st_mode) && S_ISGID(st.st_mode))) { // Check setuid and setgid bits
        if (chmod(path, permissions | (S_ISUID(st.st_mode) ? ~S_ISUID : 0) | (S_ISGID(st.st_mode) ? ~S_ISGID : 0)) == -1) {
            perror("Failed to adjust permissions");
            return 0;
        }
    }

    if (chown(path, owner, group) == -1) { // Change ownership
        perror("Failed to change ownership");
        return 0;
    }

    if (mkdir(path, permissions & ~umask(0)) == -1 && errno != EEXIST) { // Create directory with new permissions
        perror("Failed to create directory");
        return 0;
    }

    return 1;
}
