#include <string.h>

int monitorDiskSpace(char *path, size_t threshold) {
    struct statvfs st;
    if (statvfs(path, &st) == -1) {
        perror("Failed to get disk usage stats");
        return 0;
    }

    long long available = st.f_bavail * st.f_frsize;
    long long total = st.f_blocks * st.f_frsize;

    if (available < threshold) { // Check if disk space is below the threshold
        printf("Disk space usage exceeded!\n");
        return 1;
    }

    return 0;
}
