    task->identifier = ++task_mempool.next_index;
    task->description = (char*) mempool_malloc((strlen(description) + 1) * sizeof(char));
    strcpy(task->description, description);
    task->priority = priority;
    task->status = status;

    Task* existing = find_task(task->identifier, -1);
    if (existing) {
