    Task* task = find_task(id, -1);
    if (!task) return false; // Handle non-existent tasks here, e.g., by returning an error code

    pthread_mutex_lock(&tasks_mutex);
    strcpy(task->description, description);
    task->priority = priority;
    task->status = status;
    pthread_mutex_unlock(&tasks_mutex);

    return true;
}

// Function to delete a task by its identifier from the collection
bool delete_task(int id) {
    Task* task = find_task(id, -1);
    if (!task) return false; // Handle non-existent tasks here, e.g., by returning an error code

    pthread_mutex_lock(&tasks_mutex);
    for (size_t i = id; i < task_mempool.next_index; ++i) {
        if (!task_mempool.tasks[i]) continue;
        Task* next_task = task_mempool.tasks[i + 1];
        mempool_free(task_mempool.tasks[i]->description);
        mempool_free(task_mempool.tasks[i]);
        task_mempool.tasks[i] = next_task;
    }
    --task_mempool.next_index;
    pthread_mutex_unlock(&tasks_mutex);

    return true;
}

