#include <boost/intrusive_ptr.hpp>
#include <boost/circular_buffer.hpp>
#include <boost/functional/hash.hpp>
#include <boost/container/redblack_tree.hpp>
#define private public // for testing purposes

struct Record {
    long offset;
    int key;
    std::string description;
};

class Item {
public:
    float value;
    char priority;
    boost::intrusive_ptr<Record> record;
};

typedef boost::container::redblack_tree<std::pair<int, Item>,
        boost::identity<Item>, std::less<>> BST;

class Collection {
private:
    BST bst;
    std::deque<Record> records; // thread-safe doubly linked list
    mutex mtx;

public:
    void insert(const Item& item, const Record& record) {
        auto new_item = make_intrusive<Item>(item);
        new_item->record = boost::intrusive_ptr<Record>(new Record(record));
        bst.insert({new_item->key, *new_item});
        lock_guard<mutex> guard(mtx);
        records.push_back(record);
    }

    void remove(int key) {
        lock_guard<mutex> guard(mtx);
        auto it = std::find_if(records.begin(), records.end(), [key](const Record& r) { return r.key == key; });
        if (it != records.end()) {
            bst.erase({key, *new Item()}); // Erase dummy item to ensure BST erasure and rebalancing
            it = records.erase(it);
            if (!it) {
                std::cerr << "Record not found for key: " << key << std::endl;
            }
        }
    }

    // Other methods for updating, querying by key or timestamp range, statistical insights, etc.
};
```

