        // Process directory of files
        boost::filesystem::path directoryPath = vm["directory"].as<std::string>();
        processDirectory(processor, logger, communicator, directoryPath);
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return 1;
    }

    return 0;
}

void processDirectory(FileProcessor& processor, Logger& logger, ServerCommunicator& communicator, const boost::filesystem::path& directoryPath) {
    // Initialize data structures and begin processing files concurrently
    Offsets offsets;
    Keys keys;
    Records records;

    std::vector<boost::shared_ptr<FileProcessor>> fileProcessors;

    for (auto const& entry : boost::make_iterator_range(boost::filesystem::recursive_directory_iterator(directoryPath), {})) {
        if (!boost::filesystem::is_regular_file(entry)) continue; // Skip non-files

        try {
            fileProcessors.emplace_back(processor.openFile(entry));
        } catch (const std::exception& e) {
            logger.logError("Failed to open file: " + entry.string() + ", error: " + e.what());
            continue;
        }
    }

    // Process each file in parallel, updating data structures and sending processed data to the server
    for (auto& fileProcessor : fileProcessors) {
        fileProcessor->run();
        records.insert(records.end(), fileProcessor->getRecords().begin(), fileProcessor->getRecords().end());
        keys.insert(keys.end(), fileProcessor->getKeys().begin(), fileProcessor->getKeys().end());
    }

    // Sort and allocate memory for arrays
    sort(records.begin(), records.end());
    offsets.resize(records.size());
    std::partial_sum(records.begin(), records.end(), offsets.begin());

    // Send processed data to the server asynchronously, using a queuing system
    communicator.sendData(records, keys, offsets);
}
```

