class Vertex {
public:
    explicit Vertex(const int key) : id_(key), connections_(std::list<int>()) {}

    const int id() const { return id_; }
    std::list<int>& connections() { return connections_; }
    void add_connection(int vertex_id) { connections_.push_back(vertex_id); }
    void update_metadata(const std::function<void(Vertex&)>& func) { func(*this); }

private:
    int id_;
    std::list<int> connections_;
};

class Graph {
public:
    std::shared_ptr<Vertex> add_vertex(const int key) {
        std::unique_lock<std::mutex> lock(mtx_);
        auto it = vertices_.find(key);
        if (it != vertices_.end()) return it->second;

        auto vertex = std::make_shared<Vertex>(key);
        vertices_[key] = vertex;
        return vertex;
    }

    void add_edge(int from, int to) {
        std::unique_lock<std::mutex> lock(mtx_);
        auto from_vertex = vertices_.find(from);
        auto to_vertex = vertices_.find(to);

        if (from_vertex == vertices_.end() || to_vertex == vertices_.end()) {
            std::cerr << "Error: Invalid vertex key" << std::endl;
            return;
        }

        from_vertex->second->add_connection(to);
        to_vertex->second->add_connection(from);
    }

    void update_vertex_metadata(const int key, const std::function<void(Vertex&)>& func) {
        std::unique_lock<std::mutex> lock(mtx_);
        auto vertex = vertices_.find(key);
        if (vertex != vertices_.end()) vertex->second->update_metadata(func);
    }

private:
    std::unordered_map<int, std::shared_ptr<Vertex>> vertices_;
    mutable std::mutex mtx_;
};
```
