[' ```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <time.h>

typedef struct {
    long *offset;
    int value;
} record;

void seed_rnd() {
    time_t t = time(NULL);
    srand((unsigned)t);
}

long *allocate_offsets(long start, long end, long max_count, size_t chunk_size) {
    long *offsets = NULL;
    size_t total_count = (end - start) / chunk_size + 1;

    if (total_count > max_count)
        total_count = max_count;

    offsets = malloc(total_count * sizeof(long));

    for (size_t i = 0; i < total_count; ++i) {
        offsets[i] = start + (i * chunk_size);
    }

    return offsets;
}

int *get_hashed_keys(char *input, size_t *num_keys) {
    int *keys = NULL;
    unsigned long hash;
    size_t key_count = 0;

    if (!input || !*input)
        return NULL;

    for (char *token = strtok(input, ","); token; token = strtok(NULL, ",")) {
        char *trimmed_token = trim_whitespace(token);
        hash = hash_string(trimmed_token);

        int found = 0;
        for (size_t i = 0; i < key_count; ++i) {
            if (hash == keys[i]) {
                found = 1;
                break;
            }
        }

        if (!found) {
            keys = realloc(keys, ++key_count * sizeof(int));
            keys[key_count - 1] = hash;
        }
    }

    *num_keys = key_count;
    return keys;
}

char* trim_whitespace(const char *str) {
    const size_t len = strlen(str);
    char *result = malloc(len + 1); // extra space for '\0'

    size_t start = 0;
    while (isspace(str[start]))
        ++start;

    size_t end = start;
    while (end < len) {
        if (!isspace(str[end]))
            break;
        ++end;
    }

    memcpy(result, str + start, end - start);
    result[end - start] = '\0';

    return result;
}

unsigned long hash_string(const char *str) {
    unsigned long hash = 5381;
    int c;

    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

    return hash % MAX_MEMORY_LIMIT;
}

record* allocate_records(int num_keys, size_t record_count, size_t offset_size, size_t value_size) {
    record *records = NULL;

    if (!num_keys || !record_count)
        return NULL;

    records = calloc(record_count, sizeof(record));

    for (size_t i = 0; i < record_count; ++i) {
        records[i].offset = &offsets[num_keys * i % num_keys];
        records[i].value = rand() % MAX_VALUE + MIN_VALUE;
    }

    return records;
}

int manage_memory(size_t **ptr, size_t old_size, size_t new_size) {
    if (new_size > MAX_MEMORY_LIMIT) {
        free(*ptr);
        *ptr = NULL;
        return MEMORY_ERROR;
    }

    if (old_size >= new_size)
        return SUCCESS;

    size_t *temp = realloc(*ptr, new_size);
    if (!temp) {
        free(*ptr);
        *ptr = NULL;
        return MEMORY_ERROR;
    }

    *ptr = temp;
    return SUCCESS;
}

int manage_records(record **records, size_t record_count, size_t *ptr) {
    if (!ptr || !*ptr)
        return INVALID_INPUT;

    if (*ptr >= MAX_MEMORY_LIMIT)
        return MEMORY_ERROR;

    if (record_count > *ptr)
        return RECORDS_COUNT_ERROR;

    size_t temp = *ptr - record_count;
    manage_memory(&temp, record_count, 0);

    if (temp) {
        *records = realloc(*records, temp * sizeof(record));
        memset(*records + record_count, 0, temp * sizeof(record));
    }

    return SUCCESS;
}

int main_func(long start, long end, long max_count, size_t chunk_size, size_t record_count, char *input) {
    seed_rnd();

    size_t num_keys = 0;
    int *keys = get_hashed_keys(input, &num_keys);
    if (!keys)
        return INVALID_INPUT;

    long *offsets = allocate_offsets(start, end, max_count, chunk_size);
    if (!offsets) {
        free(keys);
        return MEMORY_ERROR;
    }

    size_t memory_limit = MAX_MEMORY_LIMIT / 2;
    record *records = NULL;

    int status = manage_records(&records, num_keys, &memory_limit);
    if (status != SUCCESS) {
        free(offsets);
        free(keys);
        return status;
    }

    size_t *record_ptr = &memory_limit - record_count;
    status = manage_records(&records, record_count, record_ptr);
    if (status != SUCCESS) {
        free(offsets);
        free(keys);
        return status;
    }

    size_t records_size = memory_limit - *record_ptr;
    record *allocated_records = realloc(records, records_size * sizeof(record));

    if (!allocated_records) {
        free(keys);
        free(offsets);
        return MEMORY_ERROR;
    }

    allocated_records += *record_ptr;

    size_t *record_count_ptr = record_ptr + record_count;
    status = manage_memory(record_count_ptr, 1, records_size - *record_ptr);
    if (status != SUCCESS) {
        free(allocated_records);
        free(keys);
        free(offsets);
        return status;
    }

    record *records = allocated_records + *record_count_ptr;

    record *final_records = allocate_records(num_keys, record_count, sizeof(long), sizeof(int));
    if (!final_records) {
        free(allocated_records);
        free(keys);
        free(offsets);
        return MEMORY_ERROR;
    }

    for (size_t i = 0; i < record_count; ++i) {
        final_records[i].offset = offsets[i];
        final_records[i].value = records[i].value;
    }

    free(keys);
    free(offsets);
    free(records);

    printf("Successfully allocated %zu records.\n", record_count);
    return SUCCESS;
}
```
