```cpp
#include <atomic>
#include <vector>
#include <memory>
#include <cstdlib>
#include <cstring>
#include <random>
#include <boost/circular_buffer.hpp>
#include <iostream>
#include <fstream>
#include <chrono>
#include <cryptopp/sha.h>

struct Record {
    long offset;
    int key;
    int value;
    char status;
    std::unique_ptr<char[]> str;
};

class ThreadSafeCollection {
private:
    using Node = std::pair<Record, std::atomic<Node*>>;
    using List = std::vector<Node>;
    List data;
    boost::circular_buffer<Record> cache;
    int minOffset = 0;
    int maxOffset = -1;
    std::atomic<int> size{0};
    constexpr static int maxStrLength = 256;

    void reset() {
        data.clear();
        size = 0;
        minOffset = 0;
        maxOffset = -1;
    }

    std::unique_ptr<char[]> allocateString(const int len) {
        if (len > maxStrLength) {
            throw std::runtime_error("String length exceeds maximum allowed");
        }
        auto str = std::make_unique<char[]>(len + 1);
        memset(str.get(), 0, len + 1);
        return str;
    }

public:
    ThreadSafeCollection(int minKey, int maxKey, int rangeSize) {
        reset();
        std::mt19937 gen{std::random_device{}()};
        std::uniform_int_distribution<> dis(minKey, maxKey + rangeSize);

        for (auto i = 0; i < rangeSize * 2; ++i) { // Ensure at least half of the records are initialized
            int key = dis(gen);
            if (key >= minKey && key <= maxKey && key != size) {
                Record r{minOffset + size, key, rand() % 100, 'N', allocateString(maxStrLength)};
                data.emplace_back(r, nullptr);
                ++size;
            }
        }
    }

    void insert(const Record& r) {
        if (r.key < minKey || r.key > maxKey || r.key == size) {
            throw std::runtime_error("Attempting to insert record with invalid key");
        }

        auto node = std::make_pair(r, nullptr);
        Record* prevNode = &data[size - 1];
        Record* currentNode = &prevNode->second;

        // Lock and iterate through the list to find the correct position for the new node
        while (currentNode != nullptr && currentNode->first.key < r.key) {
            prevNode = currentNode;
            currentNode = currentNode->second.load();
        }

        if (prevNode == data.end()) {
            node.second.store(data.begin());
        } else if (currentNode == nullptr) {
            prevNode->second.store(&node);
        } else {
            prevNode->second.store(&node);
            currentNode->second.store(currentNode->first.key < r.key ? &node : currentNode->second.load());
        }

        ++size;
        if (minOffset >= 0 && minOffset > r.offset) {
            minOffset = r.offset;
        }
        if (r.offset > maxOffset) {
            maxOffset = r.offset;
        }
    }

    Record get(int key) const {
        for (const auto& node : data) {
            if (node.first.key == key) {
                return node.first;
            }
        }
        throw std::runtime_error("Record not found");
    }

    void exportData(const std::string& filePath, const int blockSize = 1000) const {
        std::ofstream outFile(filePath);
        if (!outFile.is_open()) {
            throw std::runtime_error("Failed to open output file");
        }

        CryptoPP::SHA256 hash;
        int blocksExported = 0;
        Record block[blockSize];

        for (size_t i = 0, j = 0; i < data.size(); ++i) {
            if (data[i].first.key >= block[j].key) {
                block[j] = data[i].first;
                if (++j == blockSize) {
                    hash.Reset();
                    hash.Update((const byte*)block, sizeof(Record) * blockSize);
                    outFile << std::hex << hash.GetDigest().ToString() << "\n";
                    outFile.write((const char*)block, sizeof(Record) * blockSize);
                    blocksExported++;
                    j = 0;
                }
            }
        }

        if (j > 0) {
            hash.Reset();
            hash.Update((const byte*)block, sizeof(Record) * j);
            outFile << std::hex << hash.GetDigest().ToString() << "\n";
            outFile.write((const char*)block, sizeof(Record) * j);
            blocksExported++;
        }

        outFile.close();
    }
};
```

