typedef struct {
    int priority;
    char* description;
} Task;

struct task_list {
    size_t size;
    size_t capacity;
    Task** tasks;
    pthread_mutex_t mutex;
};

void init_task_list(struct task_list* list) {
    list->size = 0;
    list->capacity = 0;
    list->tasks = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

void destroy_task_list(struct task_list* list) {
    for (size_t i = 0; i < list->size; ++i) {
        free(list->tasks[i]->description);
        free(list->tasks[i]);
    }
    free(list->tasks);
    pthread_mutex_destroy(&list->mutex);
}

void resize_task_list(struct task_list* list) {
    if (list->size == list->capacity) {
        list->capacity *= 2;
        Task** new_tasks = realloc(list->tasks, list->capacity * sizeof(Task*));
        if (!new_tasks) {
            fprintf(stderr, "Failed to allocate memory\n");
            exit(EXIT_FAILURE);
        }
        list->tasks = new_tasks;
    }
}

void add_task(struct task_list* list, int priority, const char* description) {
    pthread_mutex_lock(&list->mutex);
    resize_task_list(list);
    list->tasks[list->size] = malloc(sizeof(Task));
    if (!list->tasks[list->size]) {
        fprintf(stderr, "Failed to allocate memory\n");
        pthread_mutex_unlock(&list->mutex);
        exit(EXIT_FAILURE);
    }
    list->tasks[list->size]->priority = priority;
    list->tasks[list->size]->description = strdup(description);
    if (!list->tasks[list->size]->description) {
        fprintf(stderr, "Failed to allocate memory\n");
        free(list->tasks[list->size]);
        pthread_mutex_unlock(&list->mutex);
        exit(EXIT_FAILURE);
    }
    list->size++;
    pthread_mutex_unlock(&list->mutex);
}

void update_task(struct task_list* list, size_t index, const char* new_description) {
    if (index >= list->size) return;
    pthread_mutex_lock(&list->mutex);
    free(list->tasks[index]->description);
    list->tasks[index]->description = strdup(new_description);
    pthread_mutex_unlock(&list->mutex);
}

void handle_external_api(struct task_list* list) {
    // Integrate with the external API here.
    // Ensure minimal latency during peak usage periods.
    // Handle memory allocation failures gracefully.
}

int main() {
    struct task_list tasks;
    init_task_list(&tasks);

    add_task(&tasks, 1, "Task 1");
    add_task(&tasks, 2, "Task 2");
    update_task(&tasks, 0, "Updated Task 1");
    handle_external_api(&tasks);
    destroy_task_list(&tasks);

    return 0;
}
