public class ResourceScheduler
{
    private BigInteger _availableResources = BigInteger.Parse("9223372036854775807"); // Large but finite value for available resources
    private BigInteger _maxResourceLimit = BigInteger.Parse("18446744073709551615"); // Maximum resource limit
    private PriorityQueue<Task> _tasks;
    private readonly Dictionary<int, DateTime> _lastUseTime = new Dictionary<int, DateTime>();
    private MLContext _mlContext;

    public ResourceScheduler()
    {
        _tasks = new PriorityQueue<Task>(CompareByUrgency);
        _mlContext = new MLContext();
    }

    private int CompareByUrgency(Task x, Task y) => x.UrgencyLevel.CompareTo(y.UrgencyLevel);

    public void RequestResource(int quantity)
    {
        if (_availableResources + BigInteger.Parse(quantity.ToString()) > _maxResourceLimit)
            throw new InvalidOperationException("Requested resource count exceeds the maximum limit.");

        _availableResources += BigInteger.Parse(quantity.ToString());
        HandleExternalProviderDelayOrFailure();
        UpdateLastUseTime(quantity);
    }

    public void ReleaseResource(int quantity)
    {
        if (_availableResources - BigInteger.Parse(quantity.ToString()) < BigInteger.Zero)
            throw new InvalidOperationException("Requested resource count is greater than the available resources.");

        _availableResources -= BigInteger.Parse(quantity.ToString());
        HandleExternalProviderDelayOrFailure();
        UpdateLastUseTime(-1 * quantity);
    }

    private void UpdateLastUseTime(int quantity)
    {
        for (var i = 0; i < quantity; i++)
            if (_lastUseTime.ContainsKey(_availableResources))
                _lastUseTime[_availableResources] = DateTime.UtcNow;
            else
                _lastUseTime.Add(_availableResources, DateTime.UtcNow);
    }

