typedef struct Record {
    long offset;
    int key;
    int value;
} Record;

typedef struct record_set {
    size_t capacity, size;
    Record *data;
    pthread_mutex_t mutex;
    // Cache for previously generated filenames
    struct {
        char *key;
        char value[256];
        pthread_mutex_t lock;
        size_t size, capacity;
    } cache;
} RecordSet;

RecordSet record_set_init(size_t initial_capacity) {
    RecordSet rs = {.capacity = initial_capacity, .size = 0, .data = nullptr, .mutex = PTHREAD_MUTEX_INITIALIZER};
    rs.cache.lock = PTHREAD_MUTEX_INITIALIZER;
    rs.cache.size = rs.cache.capacity = 128;
    rs.cache.key = (char *)calloc(rs.cache.size, sizeof(char));
    return rs;
}

void record_set_compact(RecordSet *record_set) {
    if ((float)record_set->size / record_set->capacity > 0.75f) {
        size_t new_capacity = record_set->size ? (2 * record_set->size + 1) : 64;
        Record *new_data = (Record *)mmap(nullptr, new_capacity * sizeof(Record), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

        pthread_mutex_lock(&record_set->mutex);
        {
            Record *src = record_set->data;
            Record *dst = new_data;
            size_t i = 0;
            for (; i < record_set->size && i < record_set->capacity; ++i) {
                *dst++ = *src++;
            }
        }
        pthread_mutex_unlock(&record_set->mutex);

        if (record_set->data) {
            free(record_set->data);
        }
        record_set->data = new_data;
        record_set->capacity = new_capacity;
    }
}

