    for (size_t i = 0; i < record_set->cache.size; ++i) {
        if (!record_set->cache.key[i]) {
            strcpy(record_set->cache.value, "");
            record_set->cache.key[i] = true;
            break;
        }
    }
    pthread_mutex_unlock(&record_set->cache.lock);
    return record_set->cache.value;
}

void record_set_insert_cached_filename(RecordSet *record_set, const char *key, const char *value) {
