using System;
using System.Collections.Generic;
using System.Linq;
using System.Numerics;
using System.Runtime.InteropServices;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using System.Timers;
using static System.Math;

public class WebRecord
{
    public long Offset { get; set; }
    public int Key { get; set; }
    public Record Data { get; set; }
    public DateTime Timestamp { get; set; }
}

[StructLayout(LayoutKind.Sequential)]
public struct Record
{
    public int Value { get; set; }
    public char StatusFlag { get; set; }
    [MarshalAs(UnmanagedType.ByValArray, SizeConst = 100)]
    public char[] String1 { get; set; }
    public int Integer { get; set; }
    public char StatusFlag2 { get; set; }
    [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 100)]
    public string String2 { get; set; }
    public IntPtr TimestampPtr { get; set; }
    public int Priority { get; set; }
}

public class WebRecordList
{
    private readonly List<WebRecord> _records = new();
    private readonly object _lock = new();
    private const int MaxRecords = 1_000_000;
    private const int MinLength = 1;
    private const int MaxLength = 100;
    private Timer _memoryMonitor;
    private double _averageTTL { get; set; }

    public WebRecordList()
    {
        Initialize();
    }

    private void Initialize()
    {
        var offsets = Enumerable.Range(0, MaxRecords).Select((i) => FibonacciSequence(i)).ToArray();
        var keys = EnumeratePrimes().TakeWhile((prime) => _records.Count < MaxRecords).ToArray();

        for (int i = 0; i < MaxRecords && _records.Count < MaxRecords; ++i)
            AddRecord(offsets[i], keys[i], GenerateRandomRecord());

        _memoryMonitor = new Timer(60000);
        _memoryMonitor.Elapsed += (sender, e) => CheckMemoryUsage();
        _memoryMonitor.Start();
    }

    private long FibonacciSequence(int n)
    {
        if (n <= 1) return n;
        return FibonacciSequence(n - 1) + FibonacciSequence(n - 2);
    }

    private IEnumerable<int> EnumeratePrimes()
    {
        yield return 2;
        for (int i = 3, root = (int)Sqrt(MaxRecords); i <= root; i += 2)
        {
            if (IsPrime(i))
                foreach (var prime in EnumeratePrimes().Where(n => n * i > MaxRecords))
                    yield return prime * i;
        }
    }

    private bool IsPrime(int number)
    {
        if (number <= 1) return false;
        for (int i = 2; i * i <= number; ++i)
            if (number % i == 0) return false;
        return true;
    }

    private Record GenerateRandomRecord()
    {
        return new Record
        {
            Value = new Random().Next(int.MinValue / 10, int.MaxValue),
            StatusFlag = (char)(new Random().Next(2) == 0 ? 'A' : 'B'),
            String1 = GenerateRandomString(),
            Integer = new Random().Next(int.MinValue / 10, int.MaxValue),
            StatusFlag2 = (char)(new Random().Next(2) == 0 ? 'A' : 'B'),
            String2 = GenerateRandomString(),
            TimestampPtr = IntPtr.Zero,
            Priority = new Random().Next(int.MinValue / 10, int.MaxValue),
