#include <time.h>
#include <sys/mman.h>

typedef struct Record {
    long offset;
    int key;
    int field;
    char status;
    char* str;
} Record;

typedef struct Node {
    Record* data;
    struct Node* next;
} Node;

typedef struct HashTable {
    size_t size;
    Node** nodes;
    pthread_mutex_t lock;
} HashTable;

void init_hash(HashTable* table, size_t size) {
    table->size = size;
    table->nodes = calloc(table->size, sizeof(Node*));
    pthread_mutex_init(&table->lock, NULL);
}

Node* create_node(Record* data) {
    Node* node = malloc(sizeof(Node));
    node->data = data;
    node->next = NULL;
    return node;
}

void insert(HashTable* table, Record* record) {
    int key = record->key;
    size_t hash = key % table->size;
    pthread_mutex_lock(&table->lock);
    Node* current = table->nodes[hash];
    Node* new_node = create_node(record);
    if (!current) {
        table->nodes[hash] = new_node;
    } else {
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    pthread_mutex_unlock(&table->lock);
}

Record* search(HashTable* table, int key) {
    size_t hash = key % table->size;
    Record* record = NULL;
    pthread_mutex_lock(&table->lock);
    Node* current = table->nodes[hash];
    while (current != NULL) {
        if (current->data->key == key) {
            record = current->data;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&table->lock);
    return record;
}

void delete(HashTable* table, int key) {
    size_t hash = key % table->size;
    Record* record = NULL;
    Node* previous = NULL;
    Node* current = table->nodes[hash];
    pthread_mutex_lock(&table->lock);
    while (current != NULL) {
        if (current->data->key == key) {
            record = current->data;
            if (previous == NULL) {
                table->nodes[hash] = current->next;
            } else {
                previous->next = current->next;
            }
            free(record);
            break;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&table->lock);
}

void* generate_record(void* arg) {
    static long offset_counter = 0;
    static int key_counter = 0;
    static int min_field = 0;
    static int max_field = 100;

    Record* record = malloc(sizeof(Record));
    record->offset = offset_counter++;
    record->key = key_counter++;
    record->field = rand() % (max_field - min_field + 1) + min_field;
    record->status = 'A';
    asprintf(&record->str, "Sample string");

    return record;
}

void manage_records(HashTable* table, int num_threads, int num_records) {
    pthread_t threads[num_threads];
    Record** records = malloc(num_records * sizeof(Record*));

    for (int i = 0; i < num_records; ++i) {
        records[i] = generate_record(NULL);
        insert(table, records[i]);
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_create(&threads[i], NULL, generate_record, NULL);
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Implement logging and memory management functions here

    free(records);
}
