async function filterAndCollectLogs(logs, pattern) {
    if (!pattern) return logs;

    const regex = new RegExp(pattern);
    const results = [];
    const stack = [];

    stack.push(logs);

    async function processLevel() {
        stack.shift().forEach((log) => {
            if (!regex.test(log)) return;

            results.push(log);

            // Implement asynchronous, recursive traversal using promises or async/await
            // Collect matches in chunks to manage memory usage effectively

            log.split('[').forEach((part) => {
                if (part.startsWith('[')) stack.push(JSON.parse(part));
            });
        });

        if (stack.length > 0) await processLevel();
    }

    await processLevel();

    return results;
}
