} Record;

typedef struct Config {
    int max_digits;
    int max_length;
    int num_extensions;
    char** extensions;
    char* filetype;
} Config;

int initList(Config config, Record** head) {
    *head = NULL;
    if (config.max_length <= 0 || config.num_extensions < 1 || config.num_extensions > 4)
        return -1;

    // Initialize the linked list with predefined pattern
    for (int i = 0; i < config.max_length / 2; ++i) {
        Record* current = malloc(sizeof(Record));
        if (!current)
            return -1;
        current->offset = i * 2 + 1;
        current->key = i * 2;
        current->next = *head;
        *head = current;
    }

    srand(time(NULL));

    for (Record* current = *head; current != NULL; current = current->next) {
        current->value = rand() % config.max_digits * 10;
    }

    return 0;
}

int searchKey(Config config, Record* head, int key) {
    for (Record* current = head; current != NULL; current = current->next) {
        if (current->key == key)
            return 1;
    }
    return -1;
}

int insertKey(Config config, Record** head, int key, int value, char status_flag, char* string) {
    if (searchKey(config, *head, key))
        return -1;

    Record* new_record = malloc(sizeof(Record));
    if (!new_record)
        return -1;

    new_record->key = key;
    new_record->value = value;
    new_record->status_flag = status_flag;
    asprintf(&(new_record->string), "%s", string);
    if (!new_record->string) {
        free(new_record);
        return -1;
    }

    new_record->offset = 0; // Assign offset later, when inserting into the list.
    Record* current = *head;

    while (current->next != NULL && current->next->key < key) {
        current = current->next;
    }

    new_record->next = current->next;
    current->next = new_record;
    return 0;
}

int deleteKey(Config config, Record** head, int key) {
    if (!head || !*head)
        return -1;

    if ((*head)->key == key) {
        Record* temp = *head;
        *head = (*head)->next;
        free(temp);
        return 0;
    }

    Record* current = *head;

    while (current->next != NULL && current->next->key < key) {
        current = current->next;
    }

    if (!current->next)
        return -1;

    Record* temp = current->next;
    current->next = current->next->next;
    free(temp);
    return 0;
}

char* modifyFilename(Config config, char* filename) {
    int digit_count = 0;
    for (size_t i = 0; filename[i] != '\0'; ++i) {
        if (isdigit(filename[i]))
            ++digit_count;
    }

    char* new_extension = NULL;
    int extension_count = 0;
    for (int i = strlen(filename) - 1; i >= 0 && extension_count < config.num_extensions; i--) {
        if (strchr(config.extensions[extension_count], filename[i])) {
            ++extension_count;
        }
    }

    asprintf(&new_extension, "%.*s.%d.%s", digit_count, "", rand() % config.num_extensions, config.filetype);
    char* new_filename = malloc(strlen(new_extension) + strlen(filename) + 10); // Allow for worst-case scenario
    sprintf(new_filename, "%s%s", filename, new_extension);

    free(new_extension);

    if (strlen(new_filename) > config.max_length) {
        free(new_filename);
        return NULL;
    }

    return new_filename;
}
