using StackExchange.Redis;

public class EventData
{
    public string Metadata { get; set; }
    public byte[] Hash { get; set; }
}

public void ProcessLogFile(string filePath)
{
    var redis = ConnectionMultiplexer.Connect("localhost");
    var db = redis.GetDatabase();

    using (var reader = new StreamReader(filePath))
    {
        string line;
        while ((line = reader.ReadLine()) != null)
        {
            var data = JsonConvert.DeserializeObject<dynamic>(line);

            var hash = ComputeSHA256Hash(data);
            db.HashSet("eventData", hash, data);
        }
    }
}

private byte[] ComputeSHA256Hash(JObject data)
{
    using (var sha256 = SHA256.Create())
    {
        return sha256.ComputeHash(Encoding.UTF8.GetBytes(data.ToString()));
    }
}
