    return pool;
}

record* allocate_record(struct memory_pool* pool) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->count < pool->capacity) {
        record* rec = &pool->array[pool->count];
        pool->count++;
        pthread_mutex_unlock(&pool->mutex);
        return rec;
    }
    pthread_mutex_unlock(&pool->mutex);
    return realloc(pool->array, (pool->capacity + 100) * sizeof(record));
}

void free_record(struct memory_pool* pool, record* record) {
    if (pool->count > 0) {
        pool->array[record - pool->array] = (record_t){0};
        pool->count--;
        pthread_mutex_unlock(&pool->mutex);
    } else {
        free(pool->array);
        free(pool);
    }
}

