#define HASH_TABLE_MAX 10000
#define LOAD_FACTOR 0.75

typedef struct Record {
    long offset;
    int key;
    double timestamp;
    struct Record *next;
} Record;

typedef struct HashTable {
    Record **buckets;
    size_t size;
    size_t count;
} HashTable;

Record* create_record() {
    Record *rec = (Record*)malloc(sizeof(Record));
    if (!rec) return NULL;
    rec->next = NULL;
    rec->offset = rand() % 1000000 + 1;
    rec->key = rand() % INT_MAX;
    rec->timestamp = time(NULL);
    return rec;
}

size_t hash(HashTable *ht, int key) {
    return (key % ht->size);
}

void resize_hash_table(HashTable *ht) {
    size_t new_size = ht->size * 2 + 1;
    Record **new_buckets = malloc((new_size) * sizeof(Record*));
    if (!new_buckets) return;

    for (size_t i = 0; i < new_size; ++i) {
        new_buckets[i] = NULL;
    }

    ht->size = new_size;
    size_t old_count = ht->count;

    for (size_t i = 0; i < ht->size; ++i) {
        Record *rec = ht->buckets[i];
        while (rec != NULL) {
            Record *next = rec->next;
            size_t index = hash(ht, rec->key);
            if (index == i) {
                rec->next = new_buckets[index];
                new_buckets[index] = rec;
            } else {
                Record *temp = new_buckets[index];
                new_buckets[index] = rec;
                rec->next = temp;
            }
            rec = next;
        }
    }

    ht->count += old_count;
}

HashTable* create_hash_table(size_t initial_size) {
    if (initial_size > HASH_TABLE_MAX) return NULL;
    HashTable *ht = malloc(sizeof(HashTable));
    if (!ht) return NULL;

    ht->buckets = malloc((initial_size) * sizeof(Record*));
    if (!ht->buckets) {
        free(ht);
        return NULL;
    }

    for (size_t i = 0; i < initial_size; ++i) {
        ht->buckets[i] = NULL;
    }

    ht->size = initial_size;
    ht->count = 0;

    return ht;
}

void cleanup(HashTable *ht) {
    for (size_t i = 0; i < ht->size; ++i) {
        Record *rec = ht->buckets[i];
        while (rec != NULL) {
            Record *next = rec->next;
            free(rec);
            rec = next;
        }
    }

    free(ht->buckets);
    free(ht);
}

HashTable* create_dynamic_memory_hash_table() {
    HashTable *ht = create_hash_table(10);
    if (!ht) return NULL;

    while (ht->count / (double)ht->size >= LOAD_FACTOR) {
        resize_hash_table(ht);
    }

    Record *rec = create_record();
    if (!rec) {
        cleanup(ht);
        return NULL;
    }

    size_t index = hash(ht, rec->key);
    rec->next = ht->buckets[index];
    ht->buckets[index] = rec;
    ht->count++;

    return ht;
}
```
