struct AbilityRecord {
    int cooldown;
};

std::vector<long> offsets;
std::vector<int> keys;
std::vector<AbilityRecord> abilities;

const int NUM_ABILITIES = 2;
const int COOLDOWN_MAX = 10;

std::mutex mtx;
std::condition_variable cv;
bool isInit = false;

void initAbilities() {
    if (isInit) return;
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> distr(0, COOLDOWN_MAX);

    for (int i = 0; i < NUM_ABILITIES; ++i) {
        abilities.emplace_back(AbilityRecord{distr(gen)});
    }

    isInit = true;
}

void manageCharacterAbilities() {
    initAbilities();

    while (true) {
        std::unique_lock<std::mutex> lk(mtx);
        cv.wait(lk, [this](){ return isInit && abilities[0].cooldown <= 0; });

        int selectedAbility = rand() % NUM_ABILITIES;
        std::cout << "Selected ability: " << keys[selectedAbility] << std std::endl;

        auto start = std::chrono::system_clock::now();
        auto end = start + std::chrono::seconds(abilities[selectedAbility].cooldown);
        auto waitDuration = end - start;
        cv.wait_for(lk, waitDuration);

        {
            std::lock_guard<std::mutex> lock(mtx);
            abilities[selectedAbility].cooldown = rand() % (COOLDOWN_MAX + 1);
        }
    }
}

int main() {
    offsets.reserve(NUM_ABILITIES);
    keys.reserve(NUM_ABILITIES);

    // Initialize offsets and keys here...

    std::thread abilityThread(manageCharacterAbilities);

    // Main game loop goes here...

    abilityThread.join();
}
