#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <sys/mman.h>

typedef struct {
    TX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc;
} record;

struct memory_pool {
    void *base;
    size_t size;
    size_t used;
};

void *memory_pool_alloc(struct memory_pool *mp, size_t alignment, size_t size) {
    void *result = mmap((void *)((uintptr_t)(mp->base) + mp->used), size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (result == MAP_FAILED) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }
    mp->used += size;
    return align_pointer(result, alignment);
}

void *align_pointer(void *ptr, size_t alignment) {
    void *aligned = (void *)((uintptr_t)(ptr + alignment - 1) & ~(alignment - 1));
    if (aligned != ptr) {
        memset(aligned, 0, alignment);
    }
    return aligned;
}

record *get_next_entry(struct memory_pool *mp) {
    record *result = mp->base;
    mp->used -= sizeof(record);
    return result;
}

