} Record;

// Custom hash function, adjustable parameters for trade-offs between resizing strategies and performance
unsigned int custom_hash(const void *key) {
    const Record *r = (const Record *)key;
    unsigned long a = r->key;
    unsigned long b = r->offset;
    unsigned long c = time(NULL); // current timestamp in seconds since the epoch
    unsigned long seed = a + b + c;
    return (seed % 10497) % HASH_TABLE_SIZE;
}

typedef struct HashNode {
    Record record;
    struct HashNode *next;
} HashNode;

// Circular buffer for logging operations and timestamps
