// Function to initialize the hash table and circular buffer
HashNode* init_hash(unsigned int initial_size) {
    if (initial_size > 10000 || initial_size < 10) {
        return NULL;
    }

    HashNode *table = malloc(initial_size * sizeof(HashNode));
    if (!table) {
        return NULL;
    }

    for (unsigned int i = 0; i < initial_size; ++i) {
        table[i].next = NULL;
    }

    return table;
}

// Function to handle dynamic memory allocation and insertion of a record into the hash table
HashNode* insert(HashNode *table, const Record *record) {
    unsigned int index = custom_hash(record) % table->size;
    HashNode *current = table[index];

    while (current != NULL) {
        if (memcmp(current, record, sizeof(Record)) == 0) {
            return current; // Record already exists, do nothing
        }
        current = current->next;
    }

    HashNode *new_node = malloc(sizeof(HashNode));
    if (!new_node) {
        return NULL; // Memory allocation failed, handle error appropriately
    }

    memcpy(&new_node->record, record, sizeof(Record));
    new_node->next = table[index];
    table[index] = new_node;

    return new_node;
}

