    public void ProcessMessages(IEnumerable<Tuple<string, string>> messages)
    {
        var tasks = messages.Select(ProcessMessage).ToList();
        if (_isAsync)
            Task.WhenAll(tasks);
        else
            tasks.ForEach(t => t.Item2);
    }

    private Tuple<string, string> ProcessMessage((string iv, string base64EncodedData) message)
    {
        var decryptedData = Decrypt(message.iv, message.base64EncodedData);
        var hmac = CalculateHMAC(decryptedData);

        if (ValidateHMAC(hmac))
        {
            string cachedData;
            if (_cache.TryGetValue(decryptedData, out cachedData))
                return Tuple.Create(cachedData, decryptedData); // Cache hit, return from cache

            var metadata = FetchMetadata(decryptedData);
            cachedData = DecryptAndCache(decryptedData, metadata);

            return Tuple.Create(cachedData, decryptedData);
        }

        return Tuple.Create($"Invalid HMAC for message: {message.iv}", null); // Return invalid message
    }

    private string Decrypt(string iv, string base64EncodedData)
    {
        var data = Base64Decode(base64EncodedData);
        var decryptor = TripleDESCryptoServiceProvider.Create();
        decryptor.Key = _key.ToCharArray();
        using (var ms = new MemoryStream(data))
        {
            using (var cs = new CryptoStream(ms, decryptor.CreateDecryptor(), CryptoStreamMode.Read))
            {
                using (var reader = new BinaryReader(cs))
                    return Encoding.UTF8.GetString(reader.ReadBytes((int)ms.Length));
            }
        }
    }

    private byte[] CalculateHMAC(string data) => SHA256.Create().ComputeHash(Encoding.UTF8.GetBytes($"{data}:{_hmacKey}"));

    private bool ValidateHMAC(byte[] hmac) => hmac.SequenceEqual(CalculateHMAC(Decrypt(_iv, _base64EncodedData)));

    private string FetchMetadata(string decryptedData)
    {
        var request = new RestRequest($"https://api.example.com/metadata/{decryptedData}");
        request.AddHeader("Authorization", $"Bearer {AccessToken()}");
        _apiClient.ExecuteAsync(request, response =>
        {
            if (response.IsSuccessful)
                return JsonConvert.DeserializeObject<dynamic>(response.Content);

            RetryIfTransientError(response);
        });

        // Synchronous implementation would be placed here
        return null; // Placeholder for asynchronous implementation
    }

    private string DecryptAndCache(string decryptedData, dynamic metadata)
    {
        var cachedData = _cache.GetOrAdd(decryptedData, decryptedData);

        if (cachedData != decryptedData) // Cache update occurred during processing, return updated cache value
            return cachedData;

        if (!metadata.NeedRefreshToken)
            return cachedData;

        var newToken = RefreshAccessToken();
        cachedData = DecryptAndCache(decryptedData, metadata); // Recursively call with new token until no need for refresh

        return cachedData;
    }

    private string Base64Decode(string base64EncodedData) => Convert.FromBase64String(base64EncodedData);

    private AccessTokenResponse AccessToken() => // Implement token retrieval and caching here

    private void RetryIfTransientError(IRestResponse response)
    {
        if (response.ErrorException != null && ShouldRetry(response.ErrorException))
            Task.Delay(_retryBackoff).ContinueWith(t => FetchMetadata(decryptedData)); // Implement exponential backoff retry mechanism here
    }

    private bool ShouldRetry(Exception exception) => exception is RestClientException || exception is WebException;
}
