#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    long session_id;
    char *username;
    int last_activity;
    bool is_active;
    char *session_token;
} Session;

typedef struct Node {
    Session session;
    struct Node *next;
} Node;

Node *head = NULL;
Node **sessions;
pthread_mutex_t sessions_lock;
size_t num_sessions = 0;

char token_pattern[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";

long generate_token() {
    long token = 0;
    for (int i = 0; i < 10; ++i)
        token = (token * 36 + token_pattern[rand() % 62]) & ((1LL << 62) - 1);
    return token;
}

void init_session(const char *username) {
    Session session = {.last_activity = time(NULL), .is_active = true, .session_token = generate_token()};
    session.username = strdup(username);

    Node *new_node = malloc(sizeof(Node));
    if (!new_node) return;
    new_node->session = session;
    new_node->next = NULL;

    pthread_mutex_lock(&sessions_lock);
    if (head == NULL) {
        head = new_node;
    } else {
        Node *last = head;
        while (last->next != NULL) last = last->next;
        last->next = new_node;
    }
    sessions[session.session_id] = &head->session;
    pthread_mutex_unlock(&sessions_lock);
}

int authenticate(const char *username, const char *token) {
    pthread_mutex_lock(&sessions_lock);
    for (Node *node = head; node != NULL; node = node->next) {
        if (strcmp(node->session.username, username) == 0 && strcmp(node->session.session_token, token) == 0 && node->session.is_active) {
            pthread_mutex_unlock(&sessions_lock);
            return node->session.session_id;
        }
    }
    pthread_mutex_unlock(&sessions_lock);
    return -1;
}

void deactivate(long session_id) {
    if (sessions[session_id] == NULL) return;
    Session *session = &sessions[session_id]->session;
    session->is_active = false;
}

Session get_session(long session_id) {
    if (sessions[session_id] == NULL) return (Session){0};
    return sessions[session_id]->session;
}

void serialize(const char *filename) {
    FILE *file = fopen(filename, "w");
    if (!file) return;

    pthread_mutex_lock(&sessions_lock);
    for (Node *node = head; node != NULL; node = node->next) {
        fprintf(file, "%ld %s %d %d %s\n", node->session.session_id, node->session.username, node->session.last_activity, node->session.is_active, node->session.session_token);
    }
    pthread_mutex_unlock(&sessions_lock);

    fclose(file);
}

void deserialize(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) return;

    // Clear the current session collection
    Node *node, *next;
    pthread_mutex_lock(&sessions_lock);
    for (Node *iter = head; iter != NULL; iter = next) {
        next = iter->next;
        free(iter->session.username);
        free(iter);
    }
    head = NULL;
    sessions = calloc(MAX_SESSIONS, sizeof(Session*));
    num_sessions = 0;
    pthread_mutex_unlock(&sessions_lock);

    Session session;
    while (fscanf(file, "%ld %s %d %d %s\n", &session.session_id, session.username, &session.last_activity, &session.is_active, session.session_token) == 5) {
        session.session_token[10] = '\0'; // Ensure the token is 10 characters long
        init_session(session.username);
        sessions[session.session_id]->last_activity = session.last_activity;
        sessions[session.session_id]->is_active = session.is_active;
    }

    fclose(file);
}
```

