#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    float value;
} record;

record* create_records(unsigned int offsetCount, unsigned int keyCount, unsigned int recordCount,
                        long minOffset, long maxOffset, int minKey, int maxKey, float minValue, float maxValue) {
    if (offsetCount == 0 || keyCount == 0 || recordCount == 0)
        return NULL;

    srand((unsigned int)time(NULL));

    long* offsets = malloc(sizeof(long) * offsetCount);
    if (!offsets) {
        perror("Error allocating memory for offsets");
        return NULL;
    }

    int* keys = malloc(sizeof(int) * keyCount);
    if (!keys) {
        perror("Error allocating memory for keys");
        free(offsets);
        return NULL;
    }

    record** records = malloc(sizeof(record*) * recordCount);
    if (!records) {
        perror("Error allocating memory for records");
        free(keys);
        free(offsets);
        return NULL;
    }

    // Allocate a single block for all records to minimize memory fragmentation
    size_t recordSize = sizeof(record) * recordCount;
    record* recordBuffer = malloc(recordSize);
    if (!recordBuffer) {
        perror("Error allocating memory for record buffer");
        free(records);
        free(keys);
        free(offsets);
        return NULL;
    }

    // Initialize offsets and keys
    for (unsigned int i = 0; i < offsetCount; ++i) {
        offsets[i] = minOffset + rand() % ((maxOffset - minOffset) + 1);
    }
    for (unsigned int i = 0; i < keyCount; ++i) {
        keys[i] = minKey + rand() % ((maxKey - minKey) + 1);
    }

    // Initialize records using the allocated buffer
    for (unsigned int i = 0; i < recordCount; ++i) {
        record* currentRecord = &recordBuffer[i];
        currentRecord->offset = offsets[rand() % offsetCount];
        currentRecord->key = keys[rand() % keyCount];
        currentRecord->value = minValue + (rand() % ((maxValue - minValue) + 1)) / RAND_MAX * (maxValue - minValue);
        records[i] = currentRecord;
    }

    return records;
}
