// Function prototype with error handling and logging support
void* init_data_structures(size_t long_size, size_t int_size, size_t record_size, int min_range, int max_range, const char* character_set, size_t string_length, FILE* log_file);

// Function to generate a random string with given length and character set
char* generate_random_string(size_t length, const char* character_set);

void* init_data_structures(size_t long_size, size_t int_size, size_t record_size, int min_range, int max_range, const char* character_set, size_t string_length, FILE* log_file) {
    // Log the initial operation for debugging purposes
    if (log_file) {
        fprintf(log_file, "Initializing data structures...\n");
    }

    long* offsets = NULL;
    int* keys = NULL;
    record* records = NULL;

    // Memory allocation and error handling for each data structure
    if (!(offsets = (long*)malloc(long_size * sizeof(long)))) {
        perror("Error allocating memory for offsets array");
        goto cleanup;
    }
    if (!(keys = (int*)malloc(int_size * sizeof(int)))) {
        perror("Error allocating memory for keys array");
        free(offsets);
        goto cleanup;
    }
    if (!(records = (record*)calloc(record_size, sizeof(record)))) {
        perror("Error allocating memory for records array");
        free(offsets);
        free(keys);
        goto cleanup;
    }

    // Random value generation and populating data structures
    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < long_size; ++i) {
        offsets[i] = rand() % ((max_range - min_range + 1) + min_range);
    }
    for (size_t i = 0; i < int_size; ++i) {
        keys[i] = rand() % max_range + min_range;
    }

    // Generate random strings and store their hashes in the records array
    char* random_strings = generate_random_string(record_size, character_set);
    for (size_t i = 0; i < record_size; ++i) {
        uint64_t hash = MurmurHash3_x86_128(random_strings + (i * string_length), string_length, 0);
        records[i].value = (int)hash;
    }

    // Log the successful operation for debugging purposes
    if (log_file) {
        fprintf(log_file, "Data structures initialized successfully.\n");
    }

    // Return function pointer, hashed password, and array of records
    void* result = (void*){offsets, keys, records};

cleanup:
    // Free dynamically allocated memory before returning
    if (random_strings) free(random_strings);

    return result;
}
