    List* list = malloc(sizeof(List));
    if (!list) return NULL;
    list->size = 0;
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    list->serialize = serialize_fn;
    list->deserialize = deserialize_fn;
    return list;
}

void list_destroy(List* list) {
    if (!list) return;
    while (list->size > 0) list_remove_at(list, 0);
    free(list);
}

bool list_insert(List* list, int key, size_t pos) {
    Node* node = malloc(sizeof(Node));
    if (!node) return false;
    node->key = key;
    node->prev = NULL;
    node->next = NULL;

    pthread_mutex_lock(&list->mutex);
    if (list->size == 0) {
        list->head = node;
        list->tail = node;
    } else {
        Node* current = list->head;
        for (size_t i = 0; i < pos && current != NULL; ++i)
            current = current->next;
        if (current == NULL) {
            free(node);
            pthread_mutex_unlock(&list->mutex);
            return false;
        }
        node->prev = current;
        node->next = current->next;
        if (current->next)
            current->next->prev = node;
        else
            list->tail = node;
        current->next = node;
    }
    ++(list->size);
    pthread_mutex_unlock(&list->mutex);
    return true;
}

void list_traverse(const List* list, bool reverse, void(*fn)(int)) {
    Node* current = list->head;
    for (size_t i = 0; i < list->size; ++i) {
        if (!current) break;
        fn(current->key);
        current = reverse ? current->prev : current->next;
    }
}
