typedef struct Task {
    char *name;
    int priority;
    struct Task *next;
    struct Task *dependent;
} Task;

// Function to compare two tasks based on their names
int task_compare(const void *a, const void *b) {
    return strcmp(((Task *) a)->name, ((Task *) b)->name);
}

// Function to add a new task at the specified priority level
Task* add_task(Task **head, char *name, int priority) {
    Task *new_task = (Task*) malloc(sizeof(Task));
    if (!new_task) return NULL; // Out of memory error
    new_task->name = strdup(name);
    new_task->priority = priority;
    new_task->next = NULL;
    new_task->dependent = NULL;

    Task *current = *head, *prev = NULL;
    while (current && current->priority > priority) {
        prev = current;
        current = current->next;
    }

    if (!prev) {
        new_task->next = *head;
        *head = new_task;
    } else {
        prev->next = new_task;
        new_task->next = current;
    }
    return new_task;
}

