    char status;
    char* content;
} Record;

typedef struct Node {
    Record data;
    struct Node *next;
} Node;

struct Collection {
    long* offsets;
    int* keys;
    Node** records;
    int size, capacity;
};

int rand_in_range(int min, int max) {
    return (rand() % ((max - min) + 1)) + min;
}

void init_collection(struct Collection* collection, int size, int record_size) {
    collection->capacity = size * 2;
    collection->offsets = malloc((size + 1) * sizeof(long));
    collection->keys = malloc(size * sizeof(int));
    collection->records = malloc(collection->capacity * sizeof(Node*));

    for (int i = 0; i < size; ++i) {
        collection->offsets[i] = i;
        collection->keys[i] = rand_in_range(1, INT32_MAX);
        collection->records[collection->offsets[i]] = malloc(sizeof(Node));
        collection->records[collection->offsets[i]]->data.key = rand_in_range(1, INT32_MAX);
        collection->records[collection->offsets[i]]->next = NULL;
    }
}

void free_collection(struct Collection* collection) {
    for (int i = 0; i < collection->capacity; ++i) {
        if (collection->records[i]) {
            free(collection->records[i]);
            collection->records[i] = NULL;
        }
    }
    free(collection->offsets);
    free(collection->keys);
    free(collection->records);
}

int add_record(struct Collection* collection, Record data) {
    int i = 0;
