        if (!collection->records[i]) {
            collection->offsets[data.key] = i;
            collection->keys[i] = data.key;
            collection->records[i] = malloc(sizeof(Node));
            collection->records[i]->data = data;
            collection->records[i]->next = NULL;
            break;
