            memmove(collection->offsets + tmp + 1, collection->offsets + tmp, (collection->offsets[tmp] - tmp) * sizeof(long));
            memmove(collection->keys + tmp + 1, collection->keys + tmp, (collection->keys[tmp] - tmp) * sizeof(int));
            collection->offsets[data.key] = tmp;
            collection->keys[tmp] = data.key;
            collection->records[i]->next = malloc(sizeof(Node));
            collection->records[i + 1] = collection->records[i]->next;
            collection->records[i + 1]->data = data;
            collection->records[i + 1]->next = NULL;
            break;
        }
    }

    if (i == collection->capacity) {
        printf("Out of memory\n");
        return -1;
    }

    return 0;
}

Record get_record(struct Collection* collection, int key) {
    for (int i = 0; i < collection->capacity; ++i) {
        if (collection->records[i] && collection->records[i]->data.key == key) {
            return collection->records[i]->data;
        }
    }

    printf("Record not found\n");
}

int del_record(struct Collection* collection, int key) {
    for (int i = 0; i < collection->capacity; ++i) {
        if (!collection->records[i]) continue;

        if (collection->records[i]->data.key == key) {
            long* offset_to_fill = NULL;
            int j = i;

            do {
                if (!collection->records[j + 1]) {
                    if (offset_to_fill) {
                        collection->offsets[offset_to_fill] = collection->offsets[j];
                        collection->keys[offset_to_fill] = collection->keys[j];
                    }
                    break;
                }

                if (collection->records[j + 1]->data.key < collection->records[i]->data.key) {
                    offset_to_fill = collection->offsets[j + 1];
                }

                j++;
            } while (j < collection->capacity);

            free(collection->records[i]);
            collection->records[i] = NULL;
        }
    }

    return 0;
}
```

This code defines a simple collection data structure and provides functions to add, remove, and retrieve records. It uses a custom linked list (Node) for each record in the collection. The initialization function takes care of allocating memory for the collections' arrays, initializing some fields within them, and seeding the random number generator for record key generation.

The `add_record`, `get_record`, and `del_record` functions manage the operations on the collection, while the `init_collection` function is responsible for initializing it, and `free_collection` cleans up memory when needed.']

