std::queue<std::string> fileQueue;
int maxFilesPerSecond = 10000;
int maxThreads = 100;
int thresholdSizeMB = 100; // User-defined threshold in MB

void processFile(const std::string& filePath) {
    boost::filesystem::ifstream ifs(filePath, boost::filesystem::ios_base::binary);
    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    uint8_t buffer[1024];
    while (ifs.read(reinterpret_cast<char*>(buffer), sizeof(buffer))) {
        SHA256_Update(&ctx, buffer, sizeof(buffer));
    }
