    log4cxx::LoggerPtr logger = log4cxx::Logger::getLogger("FileProcessor");
    log4cxx::BasicConfigurator::configure();
    log4cxx::TODO("Log detailed information about the file");
}

void worker() {
    while (true) {
        if (!fileQueue.empty()) {
            std::string filePath = fileQueue.front();
            fileQueue.pop();
            processFile(filePath);
        }
        // Sleep for a short period to allow for throttling
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
    }
}

void processDirectory(const std::string& dirPath) {
    boost::filesystem::directory_iterator end;
    for (boost::filesystem::directory_iterator it(dirPath); it != end; ++it) {
        if (it->is_regular_file() && it->size() <= static_cast<unsigned long>(thresholdSizeMB * 1024 * 1024)) {
            fileQueue.push(it->path().string());
        }
    }

    std::vector<std::thread> threads;
    for (int i = 0; i < maxThreads && !fileQueue.empty(); ++i) {
        threads.emplace_back(worker);
    }

    // Wait for all worker threads to finish
    for (auto& thread : threads) {
        thread.join();
    }
}
