};

static struct GeometricObject *collection = NULL;
static size_t collection_size = 0;
static size_t cache_size = 1024;
static char *cache = NULL;
static size_t cache_index = 0;
static sem_t cache_mutex = SEM_INITIALIZER_NP;
static pthread_mutex_t collection_lock = PTHREAD_MUTEX_INITIALIZER;

void fetch_data() {
    // Fetch data from API and validate/clean it here
