void *parse_json(const char *json_str) {
    struct json_object *root = json_tokener_parse(json_str);
    if (IS_ERROR(root)) {
        fprintf(stderr, "Error parsing JSON: %s\n", json_get_error(root));
        return NULL;
    }

    struct json_object *point_obj = json_object_object_get(root, "point");
    if (!point_obj) {
        fprintf(stderr, "Missing 'point' field in JSON\n");
        json_object_put(root);
        return NULL;
    }

    struct json_object *x_obj = json_object_object_get(point_obj, "x");
    struct json_object *y_obj = json_object_object_get(point_obj, "y");
    struct json_object *measurement_obj = json_object_object_get(point_obj, "measurement");
    struct json_object *metadata_obj = json_object_object_get(point_obj, "metadata");

    if (!x_obj || !y_obj || !measurement_obj || !metadata_obj) {
        fprintf(stderr, "Missing required field in 'point' object\n");
        json_object_put(root);
        return NULL;
    }

    Point* point = (Point*)malloc(sizeof(Point));
    point->x = json_object_get_float(x_obj);
    point->y = json_object_get_float(y_obj);
    point->measurement = json_object_get_double(measurement_obj);
    strncpy(point->metadata, json_object_get_string(metadata_obj), sizeof(point->metadata));

    json_object_put(root);
    return point;
}

void add_to_collection(Point *point) {
    pthread_mutex_lock(&collection_lock);
    if (collection_size == collection_size) {
        size_t new_collection_size = collection_size ? collection_size * 2 : cache_size;
        struct GeometricObject *new_collection = realloc(collection, new_collection_size * sizeof(struct GeometricObject));
        if (!new_collection) {
            fprintf(stderr, "Failed to resize collection\n");
            pthread_mutex_unlock(&collection_lock);
            return;
        }
        collection = new_collection;
    }

    sem_init(&collection[collection_size].lock, 0, 1);
    collection[collection_size].point = point;
    collection_size++;
    pthread_mutex_unlock(&collection_lock);
}

void *worker(void *arg) {
    char *json_data = mmap(NULL, cache_size, PROT_READ, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (json_data == MAP_FAILED) {
        fprintf(stderr, "Failed to allocate memory for cache\n");
        pthread_exit(NULL);
    }

    sem_wait(&cache_mutex);
    size_t copy_size = cache_index < cache_size ? cache_index : cache_size;
    memcpy(json_data, cache, copy_size);
    cache_index = 0;
    sem_post(&cache_mutex);

    struct json_tokener *tok = json_tokener_new();
    json_object *root = NULL;
    char *iter = json_data;
    while (iter < json_data + copy_size) {
        root = json_tokener_parse_ex(tok, iter, json_data + copy_size - iter);
        if (!IS_ERROR(root)) {
            Point* point = parse_json(json_object_to_json_string(root));
            if (point) {
                add_to_collection(point);
            }
        }
        json_tokener_clear(tok);
        iter += json_object_get_length(root) + 1;
    }
    json_tokener_free(tok);
    munmap(json_data, cache_size);

    pthread_exit(NULL);
}

void update_collection() {
    sem_wait(&cache_mutex);
    if (cache_index < cache_size) {
        fetch_data();
        char *json_str = json_object_to_json_string(root);
        memcpy(cache + cache_index, json_str, strlen(json_str) + 1);
        cache_index++;
    }
    sem_post(&cache_mutex);
}
```

