```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Record {
    int value;
    char status;
    char* str;
} Record;

typedef struct Node {
    long offset;
    int key;
    Record record;
    struct Node *next;
} Node;

#define ALLOWED_GAP 1000
Node** data = NULL;
size_t size = 0;
size_t capacity = 0;

int insert(long offset, int key, Record record) {
    if (capacity == size) {
        capacity *= 2;
        Node **new_data = realloc(data, sizeof(Node*) * capacity);
        if (!new_data) return -1; // Memory allocation failure
        data = new_data;
    }

    int index = key / ALLOWED_GAP;
    if (index >= size) {
        for (size_t i = size; i < index; ++i) {
            data[i] = malloc(sizeof(Node));
            if (!data[i]) return -1; // Memory allocation failure
            data[i]->offset = 0;
            data[i]->key = 0;
            data[i]->next = NULL;
        }
    }

    Node *node = malloc(sizeof(Node));
    if (!node) return -1; // Memory allocation failure
    node->offset = offset;
    node->key = key;
    node->record = record;
    node->next = data[index];
    data[index] = node;
    return 0;
}

int delete(long offset) {
    for (size_t i = 0; i < size; ++i) {
        if (data[i]->offset == offset) {
            Node *temp = data[i];
            data[i] = data[i]->next;
            free(temp);
            return 0;
        }
    }
    return -1; // Record not found
}

Node* search(int key) {
    for (size_t i = 0; i < size; ++i) {
        if (data[i]->key == key) return data[i];
    }
    return NULL; // Key not found
}

void update(int* keys, int* values, int n) {
    for (int i = 0; i < n; ++i) {
        Node *node = search(keys[i]);
        if (!node) continue; // Skip if record not found
        node->record.value = values[i];
    }
}

void dump(const char* filename) {
    FILE *fp = fopen(filename, "w");
    if (!fp) return; // File creation failure

    for (size_t i = 0; i < size; ++i) {
        fprintf(fp, "%ld %d %d %c \"%s\"\n", data[i]->offset, data[i]->key, data[i]->record.value, data[i]->record.status, data[i]->record.str);
    }
    fclose(fp);
}
```

