#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_RECORDS 10000
#define KEY_RANGE 1000
#define CACHE_SIZE 100

typedef struct Record {
    int value;
    char status;
    char *str;
    double *timestamp;
    struct Record *next;
} Record;

typedef struct CacheEntry {
    Record *record;
    struct CacheEntry *next;
} CacheEntry;

int db_init() {
    Record *records = malloc(MAX_RECORDS * sizeof(Record));
    if (!records) return 1; // Memory allocation error

    int keys[MAX_RECORDS];
    int offsets[MAX_RECORDS] = {0};

    for (int i = 0; i < MAX_RECORDS; ++i) {
        keys[i] = i * KEY_RANGE / MAX_RECORDS;
        records[i].next = &records[i + 1];
    }

    CacheEntry *cache = malloc(CACHE_SIZE * sizeof(CacheEntry));
    if (!cache) {
        free(records);
        return 2; // Memory allocation error
    }

    for (int i = 0; i < CACHE_SIZE; ++i)
        cache[i].next = &cache[i + 1];

    srand(time(NULL));

    return 0;
}

Record *get_record_by_key(int key) {
    int offset = 0;
    for (int i = 0; i < MAX_RECORDS; ++i) {
        if (keys[i] == key)
            return &records[offset + i];
        if (++offset >= keys[i])
            offset = 0;
    }
    return NULL; // Record not found
}

int add_record(Record *r) {
    int *new_keys = realloc(keys, sizeof(int) * (MAX_RECORDS + 1));
    if (!new_keys) return 1; // Memory allocation error
    keys = new_keys;

    Record **new_records = realloc(records, sizeof(Record) * (MAX_RECORDS + 1));
    if (!new_records) {
        free(new_keys);
        return 2; // Memory allocation error
    }
    records = new_records;

    int new_key = MAX_RECORDS * KEY_RANGE;
    for (int i = 0; i < MAX_RECORDS; ++i) {
        if (keys[i] > new_key) {
            keys[i + 1] = new_key;
            records[i + 1] = r;
            offsets[i + 1] = offsets[i];
            break;
        }
        offsets[i + 1] = offsets[i] + (records[offsets[i]+i].next - &records[offsets[i]+i]);
    }

    return 0;
}

int del_record(int key) {
    Record *r = get_record_by_key(key);
    if (!r) return 1; // Record not found

    int *new_keys = realloc(keys, sizeof(int) * (MAX_RECORDS - 1));
    if (!new_keys) return 2; // Memory allocation error
    keys = new_keys;

    for (int i = 0; i < MAX_RECORDS; ++i) {
        if (keys[i] == key) {
            for (Record *curr = records + offsets[i]; curr->next != r; curr = curr->next)
                ; // Skip over the record to be deleted
            Record *temp = curr->next;
            curr->next = r->next;
            free(r);
            break;
        }
    }

    return 0;
}

int upd_record(int key, const char *str) {
    Record *r = get_record_by_key(key);
    if (!r) return 1; // Record not found

    free(r->str);
    r->str = strdup(str);
    if (!r->str) return 2; // Memory allocation error

    return 0;
}

// API functions for interacting with the database
int add_new_record(const int value, const char *status, const char *str) {
    Record *new_rec = malloc(sizeof(Record));
    if (!new_rec) return 1; // Memory allocation error
    new_rec->value = value + rand() % KEY_RANGE;
    new_rec->status = *status;
    new_rec->str = strdup(str);
    if (!new_rec->str) {
        free(new_rec);
        return 2; // Memory allocation error
    }
    new_rec->timestamp = NULL;
    new_rec->next = NULL;

    int ret = add_record(new_rec);
    if (ret == 0) {
        upd_record(new_rec->value, str); // Update the key field in the record structure
    } else {
        free(new_rec);
    }

    return ret;
}

int remove_record(const int key) {
    return del_record(key);
}

int update_record(const int key, const char *str) {
    return upd_record(key, str);
}

int reset() {
    for (int i = 0; i < CACHE_SIZE; ++i)
        cache[i].next = &cache[0]; // Clear the cache

    // Free all dynamically allocated memory
    free(records);
    records = NULL;
    free(keys);
    keys = NULL;
    return 0;
}
