[' ```c
#include <pthread.h>
#include <semaphore.h>
#include <sys/mman.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <log_service.h> // External logging service library

typedef struct {
    char key[32];
    off_t offset;
    int data;
    char status;
    char *path;
    file_info *file_info;
} record;

typedef struct {
    size_t size;
    void *pool;
} mem_pool;

struct collection {
    mem_pool record_pool;
    sem_t lock;
    record *records;
    size_t capacity;
    size_t count;
};

void *record_alloc(mem_pool *pool) {
    void *res = mmap(NULL, pool->size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (res == MAP_FAILED) {
        // Handle error
    }
    return res;
}

void record_free(mem_pool *pool, void *ptr) {
    munmap(ptr, pool->size);
}

void collection_init(struct collection *col, size_t capacity) {
    col->record_pool.size = sizeof(record);
    col->record_pool.pool = malloc(capacity * col->record_pool.size);
    col->records = (record *)col->record_pool.pool;
    col->capacity = capacity;
    col->count = 0;
    sem_init(&col->lock, 0, 1);
}

void *collection_get(struct collection *col) {
    void *res;
    if (col->count == col->capacity) {
        res = realloc(col->record_pool.pool, (col->capacity + col->record_pool.size) * sizeof(record));
        if (res == NULL) {
            // Handle error
        }
        col->records = res;
        col->capacity += col->record_pool.size;
    } else {
        res = col->records + col->count++;
    }
    return res;
}

void collection_put(struct collection *col, void *ptr) {
    if (ptr >= col->records && ptr < (void *)((char *)col->records + col->record_pool.size * col->capacity)) {
        memset(ptr, 0, sizeof(record));
    }
}

int collection_add(struct collection *col, const char *key, off_t offset, int data, char status, const char *path, file_info *file_info) {
    record *rec = (record *)collection_get(col);
    sem_wait(&col->lock);

    strncpy(rec->key, key, sizeof(rec->key));
    rec->offset = offset;
    rec->data = data;
    rec->status = status;
    rec->path = strdup(path);
    rec->file_info = file_info;

    sem_post(&col->lock);

    // Integrate with logging service here

    return 0;
}

int collection_remove(struct collection *col, const char *key) {
    record **it = (record **)(col->records + col->count - 1);
    int found = 0;

    sem_wait(&col->lock);
    for (size_t i = 0; i < col->count && !found; ++i) {
        if (!strcmp(it[-i]->key, key)) {
            memmove(it - i, it - i + 1, sizeof(record *) * (col->count - i - 1));
            found = 1;
        }
    }
    free((*it)->path);
    collection_put(col, it);
    sem_post(&col->lock);

    --col->count;

    // Integrate with logging service here

    return 0;
}

record *collection_search(struct collection *col, const char *key) {
    record **it = col->records;
    for (size_t i = 0; i < col->count; ++i) {
        if (!strcmp(it[i]->key, key)) {
            return it[i];
        }
    }
    return NULL;
}

int collection_update(struct collection *col, const char *key, file_info *new_file_info) {
    record *rec = collection_search(col, key);
    if (rec != NULL) {
        rec->file_info = new_file_info;
        // Integrate with logging service here
    }
    return 0;
}
```

