[' ```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct UserProfile {
    char *name;
    char *email;
    int age;
    bool subscription_status;
    pthread_mutex_t lock;
} UserProfile;

typedef struct Node {
    UserProfile *user;
    struct Node *next;
} Node;

typedef struct HashTable {
    unsigned int size;
    Node **buckets;
    unsigned int num_profiles;
} HashTable;

HashTable create_hash_table(unsigned int size) {
    HashTable table = {size, NULL, 0};
    table.buckets = calloc(size, sizeof(Node*));
    return table;
}

int hash_function(const char *key, unsigned int size) {
    unsigned long hash = 5381;
    int c;

    while ((c = *key++))
        hash = (hash << 5) + hash + c; /* hash * 33 + c */

    return hash % size;
}

void insert_profile(HashTable *table, UserProfile *user) {
    Node **bucket = &table->buckets[hash_function((user->name), table->size)];
    Node *new_node = malloc(sizeof(Node));

    new_node->user = user;
    new_node->next = *bucket;
    *bucket = new_node;
    ++table->num_profiles;
}

UserProfile* find_profile_by_id(HashTable *table, unsigned int id) {
    Node **bucket = &table->buckets[id % table->size];
    for (Node *current = *bucket; current != NULL; current = current->next) {
        if (current->user->age == id)
            return current->user;
    }
    return NULL;
}

void update_profile(HashTable *table, UserProfile *new_data, unsigned int id) {
    UserProfile *user = find_profile_by_id(table, id);
    if (user) {
        pthread_mutex_lock(&user->lock);
            memcpy(user, new_data, sizeof(UserProfile));
        pthread_mutex_unlock(&user->lock);
    }
}

void delete_profile(HashTable *table, unsigned int id) {
    Node **bucket = &table->buckets[id % table->size];
    for (Node **current = bucket; *current != NULL; current = &(*current)->next) {
        if ((*current)->user->age == id) {
            Node *temp = *current;
            *current = (*current)->next;
            free(temp);
            --table->num_profiles;
            break;
        }
    }
}

void iterate_over_profiles(HashTable table, void(*func)(UserProfile*)) {
    for (unsigned int i = 0; i < table.size; ++i) {
        Node *current = table.buckets[i];
        while (current != NULL) {
            func(current->user);
            current = current->next;
        }
    }
}

// Initialize UserProfile mutexes
void init_mutexes(UserProfile *users, unsigned int count) {
    for (unsigned int i = 0; i < count; ++i)
        pthread_mutex_init(&users[i].lock, NULL);
}

// Cleanup UserProfile mutexes
void cleanup_mutexes(UserProfile *users, unsigned int count) {
    for (unsigned int i = 0; i < count; ++i)
        pthread_mutex_destroy(&users[i].lock);
}
```

