#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

typedef struct Record {
    int key;
    long offset;
} Record;

Record* create_records(int max_keys, int min_value, int max_value, int *num_records) {
    const int MAX_KEYS = 50;
    if (max_keys > MAX_KEYS) max_keys = MAX_KEYS;

    Record* records = NULL;
    long* offsets = calloc(max_keys * (*num_records), sizeof(long));
    if (!offsets) return NULL;

    int unique_keys[MAX_KEYS] = {0};
    int used_keys = 0;
    srand(time(NULL));

    for (int i = 0; i < *num_records; ++i) {
        int key = min_value + rand() % ((max_value - min_value) + 1);
        if (unique_keys[key] >= MAX_KEYS) continue;
        unique_keys[key]++;
        records = realloc(records, ++used_keys * sizeof(Record));
        if (!records) {
            free(offsets);
            return NULL;
        }
        records[i - 1].key = key;
        records[i - 1].offset = offsets[used_keys - 1];
        offsets[unique_keys[key]] = offsets[used_keys - 1] + 1;
    }

    *num_records = used_keys;
    return records;
}

void free_records(Record* records, int num_records) {
    free(records);
    free(records[0].offset); // Free offset array dynamically allocated in create_records()
}
```

This code provides a `create_records()` function to manage memory for a variable number of records with an integer key and a long offset value. It dynamically allocates memory for these records, ensures no more than 50 unique keys are used, and generates random keys within the specified range. Upon completion, it returns a pointer to the allocated records and updates the `num_records` parameter accordingly. The code also includes a corresponding `free_records()` function to efficiently clean up all dynamically allocated memory before exiting.']

