#include <stdlib.h>
#include <stdio.h>
#include <time.h>  // For random number generation
#include <pthread.h> // For handling potential concurrent access by multiple threads

typedef struct Record {
    long offset;
    int key;
    float timestamp;
} Record;

Record* init_records(size_t num_records, long seed) {
    Record *data = NULL;
    size_t i;

    // Initialize pthread_mutex_t for data access synchronization
    pthread_mutex_t mtx;
    pthread_mutex_init(&mtx, NULL);

    // Allocate memory for the array of records and seed the random number generator
    data = (Record *)malloc(num_records * sizeof(Record));
    if (!data) {
        perror("Memory allocation failure");
        return NULL;
    }

    srand(seed);

    // Lock mutex before modifying shared data and unlock it afterward
    pthread_mutex_lock(&mtx);

    for (i = 0; i < num_records; ++i) {
        // Generate random values for each Record structure field
        data[i].offset = rand();
        data[i].key = rand() % INT_MAX;
        data[i].timestamp = ((float)rand()) / RAND_MAX;
    }

    pthread_mutex_unlock(&mtx);

    // Validate the initialized data against predefined constraints
    for (i = 0; i < num_records; ++i) {
        if (data[i].offset < 0 || data[i].key < 0 || data[i].timestamp <= 0.0) {
            fprintf(stderr, "Invalid data detected: %ld, %d, %.3f\n",
                    data[i].offset, data[i].key, data[i].timestamp);
            free(data);
            return NULL;
        }
    }

    pthread_mutex_destroy(&mtx);
    return data;
}
```
