const static double LOAD_FACTOR = 0.75;
static HashTableNode table[TABLE_SIZE];
static size_t num_profiles = 0;
static pthread_mutex_t hash_table_lock;

void init_hash_table() {
    pthread_mutex_init(&hash_table_lock, NULL);
}

size_t hash(const char* email) {
    size_t hash = 0;
    for (int i = 0; email[i]; ++i)
        hash = (hash * 31 + email[i]) % TABLE_SIZE;
    return hash;
}

void rehash() {
    // Implement the rehashing logic here, such as creating a new table and moving profiles from the old one
}

bool add_profile(const char* name, int age, const char* email) {
    size_t index = hash(email);
    pthread_mutex_lock(&hash_table_lock);
    // Check for duplicate entries and memory allocation failures
    if (num_profiles >= TABLE_SIZE || find_profile(email)) {
        pthread_mutex_unlock(&hash_table_lock);
        return false;
    }
    // Create a new node and add it to the hash table
    HashTableNode* node = malloc(sizeof(HashTableNode));
    if (!node) {
        pthread_mutex_unlock(&hash_table_lock);
        return false;
    }
    memcpy(node->profile.name, name, sizeof(name));
    node->profile.age = age;
    node->next = table[index].next;
    table[index] = *node;
    pthread_mutex_unlock(&hash_table_lock);

    ++num_profiles;
    if (num_profiles * 1.0 / TABLE_SIZE > LOAD_FACTOR)
        rehash();

    return true;
}

bool remove_profile(const char* email) {
    size_t index = hash(email);
    pthread_mutex_lock(&hash_table_lock);
    // Find the node containing the profile and remove it from the hash table
    if (!find_profile(email)) {
        pthread_mutex_unlock(&hash_table_lock);
        return false;
    }

    HashTableNode* prev = NULL, *current = &table[index];
    while (current->next != TABLE_SIZE) {
        if (!strcmp(current->profile.email, email)) {
            if (prev == NULL) {
                table[index] = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            --num_profiles;
            pthread_mutex_unlock(&hash_table_lock);
            return true;
        }
        prev = current;
        current = &table[current->next];
    }
    pthread_mutex_unlock(&hash_table_lock);
    return false;
}

Profile* find_profile(const char* email) {
    size_t index = hash(email);
    Profile* profile = malloc(sizeof(Profile));
    memset(profile, 0, sizeof(Profile));

    pthread_mutex_lock(&hash_table_lock);
    HashTableNode* current = &table[index];
    while (current->next != TABLE_SIZE) {
        if (!strcmp(current->profile.email, email)) {
            memcpy(profile, &current->profile, sizeof(Profile));
            pthread_mutex_unlock(&hash_table_lock);
            return profile;
        }
        current = &table[current->next];
    }
    pthread_mutex_unlock(&hash_table_lock);
    free(profile);
    return NULL;
}
