// External library interface for random number generation
extern void rand_init(unsigned long seed);
extern int rand_int(int min, int max);

typedef struct Record {
    int key;
    long value;
};

// Function to dynamically allocate and initialize the data structure.
void init_data(Record** offsets, Record** keys, size_t capacity, int min_key, int max_key) {
    if (!offsets || !keys) return;

    *offsets = malloc(capacity * sizeof(Record));
    *keys = calloc(capacity, sizeof(Record));

    if (!*offsets || !*keys) {
        perror("Memory allocation failure");
        exit(EXIT_FAILURE);
    }

    srand((unsigned int)time(NULL)); // Seed random number generator with current time

    for (size_t i = 0; i < capacity; ++i) {
        int key = rand_int(min_key, max_key);
        bool found = false;

        for (int j = 0; j <= KEY_CONSECUTIVE_SLOTS && !found; ++j) {
            if (i + j >= capacity) break; // Check if we've gone beyond the array bounds
            if (keys[i + j].key == key) found = true; // Found duplicate, move on to next slot
        }

        if (!found) {
            (*offsets)[i].key = key;
            (*offsets)[i].value = rand_int(MIN_VALUE, MAX_VALUE);
            (*keys)[i].key = key;
        } else {
            --i; // Rescan from the current index if a duplicate was found
        }
    }
}

// Function to free allocated memory when exiting.
void deallocate_data(Record* offsets, Record* keys) {
    if (offsets && keys) {
        free(offsets);
        free(keys);
    }
}
