    const Record* rec_b = (const Record*) b;
    return strcmp(rec_a->string, rec_b->string);
}

// The dynamic collection of records using a hash table
typedef struct {
    void** data; // Pointer to the actual data stored in the bucket
    size_t size;  // Number of elements currently stored in the bucket
    size_t capacity; // Total capacity of the bucket
    size_t (*hash_fn)(const char*); // Hash function used for this table
    int (*compare)(const void*, const void*); // Comparator function
} HashMap;

// Create a new hash map with given capacity and hashing/comparing functions
HashMap* create_hash_map(size_t capacity, size_t (*hash_fn)(const char*), int (*compare)(const void*, const void*)) {
    // Initialize the hash table with the specified parameters.
    // ...
}

// Insert a new record into the hash map if it does not already exist (ensuring no duplicates)
int insert_record(HashMap* map, Record* rec) {
    size_t idx = hash(rec->string) % map->capacity;
    for (size_t i = 0; i < map->size; ++i) {
        if (map->data[idx + i] == NULL || strcmp(((Record*)map->data[idx + i])->string, rec->string)) {
            map->data[idx + i] = rec;
            map->size++;
            return 0; // Success
        }
    }
    fprintf(stderr, "Error: Tried to insert duplicate record\n");
    return -1; // Failure due to duplicate record
}

// Retrieve a record from the hash map by its string value, or NULL if not found
Record* find_record(HashMap* map, const char* string) {
    size_t idx = hash(string) % map->capacity;
    for (size_t i = 0; i < map->size; ++i) {
        if (map->data[idx + i] && strcmp(((Record*)map->data[idx + i])->string, string) == 0) {
            return (Record*) map->data[idx + i]; // Found the record, return a pointer to it
        }
    }
    return NULL; // Not found
}

// Delete a record from the hash map by its string value, or do nothing if not found
void delete_record(HashMap* map, const char* string) {
    size_t idx = hash(string) % map->capacity;
    for (size_t i = 0; i < map->size; ++i) {
        if (map->data[idx + i] && strcmp(((Record*)map->data[idx + i])->string, string) == 0) {
            map->data[idx + i] = NULL; // Mark the record as deleted
            map->size--;
            break;
        }
    }
}

// Deallocate all memory used by a hash map and its records when exiting the function
void free_hash_map(HashMap* map) {
    for (size_t i = 0; i < map->capacity; ++i) {
        if (map->data[i]) { // Deallocate individual record memory
            free(((Record*) map->data[i])->string);
            free(map->data[i]);
        }
    }
    free(map->data); // Free the array of pointers
}
