struct cache *init_cache(double capacity) {
    struct cache *c = malloc(sizeof(struct cache));
    c->capacity = capacity;
    c->max_records = (unsigned long)((1 - capacity) * pow(2, 32));
    c->cache_array = calloc((size_t)pow(2, 30), sizeof(linked_list_node*));
    pthread_mutex_init(&c->lock, NULL);
    pthread_cond_init(&c->not_full, NULL);
    return c;
}

void cache_insert(struct cache *cache, linked_list_node *node) {
    unsigned long index = hash_function(node->record_ptr->value);

    pthread_mutex_lock(&cache->lock);
    while (index >= (unsigned long)pow(2, 30)) index -= pow(2, 30);

    if (cache->cache_array[index] != NULL && cache->capacity > get_cache_ratio(cache)) {
        cache->cache_array[index] = node;
        pthread_cond_signal(&cache->not_full);
    } else {
        unsigned long i;
        for (i = index + 1; i < pow(2, 30); ++i) {
            if (cache->cache_array[i] == NULL) {
                cache->cache_array[i] = node;
                pthread_cond_signal(&cache->not_full);
                break;
