#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct Preference {
    char* preference;
    struct Preference *next;
} Preference;

typedef struct UserProfile {
    char* name;
    char* email;
    Preference* preferences;
    pthread_mutex_t lock;
    struct UserProfile *next;
} UserProfile;

typedef struct HashTableNode {
    UserProfile* profile;
    struct HashTableNode *next;
} HashTableNode;

typedef struct HashTable {
    int size;
    HashTableNode** table;
    pthread_mutex_t lock;
} HashTable;

// Function to create a new UserProfile
UserProfile* createUserProfile(char* name, char* email) {
    UserProfile* profile = (UserProfile*)malloc(sizeof(UserProfile));
    if (!profile) return NULL;

    profile->name = strdup(name);
    profile->email = strdup(email);
    profile->preferences = NULL;
    profile->next = NULL;
    pthread_mutex_init(&profile->lock, NULL);
    return profile;
}

// Function to create a new preference
Preference* createPreference(char* preference) {
    Preference* preference_node = (Preference*)malloc(sizeof(Preference));
    if (!preference_node) return NULL;

    preference_node->preference = strdup(preference);
    preference_node->next = NULL;
    return preference_node;
}

// Function to insert a new UserProfile into the hash table
void insertProfile(HashTable* hash_table, UserProfile* profile) {
    int index = hash(profile->email, hash_table->size);
    HashTableNode* current = hash_table->table[index];

    while (current != NULL) {
        if (strcmp(current->profile->email, profile->email) == 0) {
            updateProfile(current->profile, profile);
            return;
        }
        current = current->next;
    }

    hash_table->table[index] = malloc(sizeof(HashTableNode));
    if (!hash_table->table[index]) return;

    hash_table->table[index]->profile = profile;
    hash_table->table[index]->next = current;
}

// Function to update an existing UserProfile with new preferences
void updateProfile(UserProfile* old_profile, UserProfile* new_profile) {
    pthread_mutex_lock(&old_profile->lock);

    Preference *current = old_profile->preferences;
    while (current != NULL) {
        free(current->preference);
        Preference *temp = current;
        current = current->next;
        free(temp);
    }

    old_profile->preferences = new_profile->preferences;

    pthread_mutex_unlock(&old_profile->lock);
}

// Function to remove a UserProfile from the hash table by email
void removeProfileByEmail(HashTable* hash_table, char* email) {
    int index = hash(email, hash_table->size);
    HashTableNode* current = hash_table->table[index];
    HashTableNode* previous = NULL;

    while (current != NULL) {
        if (strcmp(current->profile->email, email) == 0) {
            if (previous == NULL) {
                hash_table->table[index] = current->next;
            } else {
                previous->next = current->next;
            }

            freeUserProfile(current->profile);
            free(current);
            return;
        }
        previous = current;
        current = current->next;
    }
}

// Function to retrieve a UserProfile by email
UserProfile* getProfileByEmail(HashTable* hash_table, char* email) {
    int index = hash(email, hash_table->size);
    HashTableNode* current = hash_table->table[index];

    while (current != NULL) {
        if (strcmp(current->profile->email, email) == 0) {
            return current->profile;
        }
        current = current->next;
    }

    return NULL;
}

// Function to free all dynamically allocated memory in a UserProfile
void freeUserProfile(UserProfile* profile) {
    pthread_mutex_destroy(&profile->lock);
    free(profile->name);
    free(profile->email);
    Preference *current = profile->preferences;
    while (current != NULL) {
        Preference *temp = current;
        current = current->next;
        free(temp->preference);
        free(temp);
    }
    free(profile);
}

// Function to hash an email for use in the hash table
int hash(char* key, int table_size) {
    uint32_t hash = 5381;
    int c;

    while ((c = *key++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }

    return hash % table_size;
}
```
