    public byte[] Metadata { get; set; }
}

public class MediaLibrary
{
    private ConcurrentQueue<MediaItem> _queue = new ConcurrentQueue<MediaItem>();
    private ConcurrentDictionary<string, MediaItem> _items = new ConcurrentDictionary<string, MediaItem>();

    public void Enqueue(MediaItem item) => _queue.Enqueue(item);

    public MediaItem Dequeue() => _queue.TryDequeue(out var item) ? item : default;

    public MediaItem GetItem(string key) => _items.GetOrAdd(key, _ => new MediaItem { FilePath = key });
}

