#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>
#include <jansson.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <unistd.h>

typedef struct {
    char *name;
    int value;
} item;

struct list_cache {
    void *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
};

struct list {
    item **items;
    size_t size;
    size_t capacity;
    struct list_cache cache;
    int threshold;
};

void destroy_item(item *item) {
    free(item->name);
    free(item);
}

void* load_file(const char *path, struct list_cache *cache) {
    void *mmaped = mmap(NULL, sizeof(json_t), PROT_READ, MAP_PRIVATE, open(path, O_RDONLY), 0);
    if (mmaped == MAP_FAILED) return NULL;

    json_t *root = json_loads(mmaped, 0, NULL);
    void *data = malloc(json_size(root));
    memcpy(data, json_text(root), json_size(root));

    if (cache->capacity > 0) {
        if (cache->size + json_array_length(root) <= cache->capacity) {
            memcpy((char *)cache->data + cache->size, data, json_size(root));
            cache->size += json_size(root);
        } else {
            munmap(mmaped, sizeof(json_t));
            return NULL;
        }
    } else {
        free(data);
        data = malloc(json_size(root));
        memcpy(data, json_text(root), json_size(root));
    }

    return data;
}

void init_list(struct list *list, const char *const paths[], size_t path_count, int threshold) {
    pthread_mutex_init(&list->cache.lock, NULL);
    list->threshold = threshold;

    for (size_t i = 0; i < path_count; ++i) {
        struct list_cache *cache = &list->cache;
        char *data = load_file(paths[i], cache);
        if (!data) return;

        json_t *root = json_loads(data, 0, NULL);
        json_array_foreach(root, item, i) {
            item *new_item = malloc(sizeof(item));
            new_item->name = strdup(json_string_value(json_object_get(item, "name")));
            new_item->value = json_integer_value(json_object_get(item, "value"));

            pthread_mutex_lock(&list->cache.lock);
            if (list->capacity > list->size) {
                list->items[list->size] = new_item;
                list->size++;
            } else {
                free(new_item);
                pthread_mutex_unlock(&list->cache.lock);
                destroy_item(list->items[list->size - 1]);
                list->size--;
                pthread_mutex_lock(&list->cache.lock);
            }
            pthread_mutex_unlock(&list->cache.lock);
        }
    }

    qsort(list->items, list->size, sizeof(item *), (int (*)(const void *, const void *))compare_item_ptrs);

    size_t new_capacity = list->size;
    while (new_capacity > 1 && list->items[new_capacity - 1]->value > threshold) {
        destroy_item(list->items[--new_capacity]);
    }
    list->capacity = new_capacity;
}

int calculate_sum(const struct list *list) {
    int sum = 0;
    for (size_t i = 0; i < list->size; ++i) {
        sum += list->items[i]->value;
    }
    return sum;
}

int compare_item_ptrs(const void *a, const void *b) {
    return (*(item **)a)->value - *(*(item **)b)->value;
}
```

