typedef struct Entry {
    char* key;
    size_t value;
} Entry;

static size_t entry_count = 0;
static size_t capacity = 0;
static Entry* entries = NULL;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void init_entries(size_t initial_capacity) {
    if (initial_capacity > capacity) {
        Entry* new_entries = realloc(entries, initial_capacity * sizeof(Entry));
        if (!new_entries) {
            fprintf(stderr, "Memory allocation failure\n");
            exit(EXIT_FAILURE);
        }
        entries = new_entries;
        capacity = initial_capacity;
    }
}

void entry_push(const char* key, size_t value) {
    pthread_mutex_lock(&mutex);

    if (entry_count == capacity) {
        init_entries(capacity * 2);
    }

    Entry* entry = &entries[entry_count];
    entry->key = strdup(key);
    entry->value = value;
    entry_count++;

    pthread_mutex_unlock(&mutex);
}

size_t entry_count() {
    return entry_count;
}

void print_entries() {
    pthread_mutex_lock(&mutex);

    printf("Entries:\n");
    for (size_t i = 0; i < entry_count; ++i) {
        printf("%zu: key=\"%s\", value=%zu\n", i, entries[i].key, entries[i].value);
    }

    pthread_mutex_unlock(&mutex);
}

// This implementation assumes that the provided functions for initializing and accessing the 'entries' array are thread-safe.
