#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
    size_t offset;
} record;

typedef struct memory_block {
    record* data;
    size_t capacity;
    size_t used;
    struct memory_block* next;
} memory_block;

static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
static const char* LOG_PREFIX = "[RECORD_POOL] ";

memory_block* memory_pool = NULL;
size_t max_records = 1000000; // Predefined maximum limit for records

void log(const char* message) {
    pthread_mutex_lock(&log_mutex);
    printf("%s%s\n", LOG_PREFIX, message);
    pthread_mutex_unlock(&log_mutex);
}

record* record_pool_alloc() {
    if (!memory_pool) {
        memory_block* new_block = malloc(sizeof(memory_block));
        new_block->data = NULL;
        new_block->capacity = 0;
        new_block->used = 0;
        new_block->next = memory_pool;
        memory_pool = new_block;
    }

    memory_block* current = memory_pool;
    while (current->next && current->next->capacity == 0) {
        current = current->next;
    }

    if (!current->next || current->next->used == current->next->capacity) {
        // Allocate a new block if the current one is full or there's no next one.
        memory_block* new_block = malloc(sizeof(memory_block));
        new_block->data = malloc(current->next ? current->next->capacity * sizeof(record) : INITIAL_CAPACITY * sizeof(record));
        new_block->capacity = current->next ? current->next->capacity * 2 : INITIAL_CAPACITY;
        new_block->used = 0;
        new_block->next = current->next;
        current->next = new_block;
    }

    return current->next->data + current->next->used++;
}

void record_pool_init(record** key_array, size_t num_records, const void* offset_array, size_t array_size) {
    if (num_records > max_records) {
        log("Error: Invalid number of records exceeds the predefined maximum limit.");
        return;
    }

    for (size_t i = 0; i < num_records; ++i) {
        record* new_record = record_pool_alloc();
        if (!new_record) {
            log("Error: Out of memory during record allocation.");
            return;
        }

        new_record->value = rand() % 100 + 1; // Generate random value between 1 and 100.
        new_record->offset = *(const size_t*)(offset_array + i);
        key_array[i] = new_record;
    }
}
```

