struct MemoryPool* create_memory_pool(size_t capacity) {
    struct MemoryPool* pool = malloc(sizeof(struct MemoryPool));
    if (!pool) return NULL;

    pool->capacity = capacity;
    pool->used = 0;
    pool->memory = malloc(capacity * sizeof(struct Record));
    if (!pool->memory) {
        free(pool);
        return NULL;
