[' C# Function: FindFirstElement (XPath parser using LinqToXml)

```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Xml.Linq;
using System.Xml.XPath;

public static XElement FindFirstElement(XDocument xmlDoc, string elementName, IDictionary<string, string> attributes = null)
{
    var caseInsensitiveComparer = StringComparer.OrdinalIgnoreCase;

    if (attributes == null)
        return xmlDoc.Root.XPathSelectElement(elementName);

    Func<XElement, bool> predicate = e =>
    {
        if (!e.Name.LocalName.Equals(elementName, caseInsensitiveComparer))
            return false;

        foreach (var attribute in attributes)
        {
            if (!e.Attribute(attribute.Key).Value.Equals(attribute.Value, caseInsensitiveComparer))
                return false;
        }

        return true;
    };

    var elements = xmlDoc.Root.Elements().Where(predicate);
    return elements.FirstOrDefault();
}
```

