JsonPair *parseAndValidateJSON(const char *json) {
    json_t *root = NULL;
    json_error_t error;

    root = json_loads(json, 0, &error);

    if (!root || !json_is_object(root)) {
        fprintf(stderr, "Error parsing JSON: %s\n", error.text);
        json_decref(root);
        return NULL;
    }

    size_t count = 0;
    JsonPair *pairs = malloc(sizeof(JsonPair) * json_object_size(root));

    json_object_foreach(root, key, value) {
        pairs[count].key = strdup(json_string_value(key));
        pairs[count].value = strdup(json_string_value(value));
        count++;
    }

    json_decref(root);

    JsonPair *result = malloc(sizeof(JsonPair) * count);
    memcpy(result, pairs, sizeof(JsonPair) * count);
    free(pairs);

    return result;
}

pid_t executeInBackground(const char *command) {
