typedef struct {
    char str[256];
    int value;
    struct timespec ts;
} entry;

entry* create_entry(const char* str, int value) {
    entry* new_entry = (entry*) malloc(sizeof(entry));
    if (!new_entry) {
        fprintf(stderr, "Error: Out of memory\n");
        return NULL;
    }

    strncpy(new_entry->str, str, 256);
    new_entry->value = value;
    time_t now;
    struct timespec* ts = &new_entry->ts;
    clock_gettime(CLOCK_REALTIME, ts);
    return new_entry;
}

void destroy_entry(entry* entry) {
    if (!entry) return;
    free(entry);
}

typedef struct {
    size_t capacity;
    size_t size;
    entry** entries;
} entry_array;

entry_array* create_entry_array(size_t initial_capacity) {
    if (initial_capacity == 0) return NULL;

    entry_array* array = (entry_array*) malloc(sizeof(entry_array));
    if (!array) {
        fprintf(stderr, "Error: Out of memory\n");
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    array->entries = (entry**) malloc(initial_capacity * sizeof(entry*));
    if (!array->entries) {
        fprintf(stderr, "Error: Out of memory\n");
        free(array);
        return NULL;
    }

    memset(array->entries, 0, initial_capacity * sizeof(entry*));
    return array;
}

void resize_entry_array(entry_array* array) {
    size_t new_capacity = (array->capacity * 2 > 100000) ? 100000 : array->capacity * 2;
    entry** new_entries = realloc(array->entries, new_capacity * sizeof(entry*));

    if (!new_entries) {
        fprintf(stderr, "Error: Out of memory\n");
        return;
    }

    array->entries = new_entries;
    array->capacity = new_capacity;
}

void add_entry(entry_array* array, entry* new_entry) {
    if (array->size == array->capacity) resize_entry_array(array);

    array->entries[array->size] = new_entry;
    array->size++;
}

void destroy_entry_array(entry_array* array) {
    for (size_t i = 0; i < array->size; ++i) {
        destroy_entry(array->entries[i]);
    }
    free(array->entries);
    free(array);
}
