```javascript
function getElementMatches(selector, parent = document) {
    const results = [];
    let depthLimit = 10; // Limit the traversal depth to avoid excessive memory consumption

    const traverse = (node, currentDepth) => {
        if (!node || currentDepth > depthLimit) return;

        if (node.matches && node.matches(selector)) {
            results.push(node);
        }

        Array.from(node.children).forEach((childNode, index) => {
            traverse(childNode, currentDepth + 1);
        });
    };

    traverse(parent.querySelector(selector));
    return results;
}
