        perror("fork failed");
        exit(EXIT_FAILURE);
    } else if (pid == 0) { // child process
        execl("/bin/bash", "/bin/bash", "-c", command, NULL);
        perror("execl failed");
        exit(EXIT_FAILURE);
    }
    return pid;
}

void handleCommand(pid_t pid) {
    int status = 0;
    waitpid(pid, &status, WNOHANG);
    if (!WIFEXITED(status)) return; // command is still running or encountered an error
