    time_t timestamp;
} reading_t;

struct storage {
    size_t capacity;
    size_t count;
    void* data; // dynamically allocated array of char bytes (for flexibility)
    reading_t** readings; // dynamically allocated array for storing readings (with a circular buffer implementation)
    pthread_cond_t full_cond;
    pthread_cond_t empty_cond;
};

void storage_init(struct storage* storage, size_t capacity) {
    storage->capacity = capacity;
    storage->count = 0;
    storage->data = malloc(capacity * sizeof(char));
    if (storage->data == NULL) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    storage->readings = malloc(sizeof(reading_t*) * capacity);
    if (storage->readings == NULL) {
        perror("malloc");
        free(storage->data);
        exit(EXIT_FAILURE);
    }
    memset(storage->readings, 0, sizeof(reading_t*) * capacity);
    pthread_cond_init(&storage->full_cond, NULL);
    pthread_cond_init(&storage->empty_cond, NULL);
}

void storage_deinit(struct storage* storage) {
    free(storage->data);
    free(storage->readings);
    pthread_cond_destroy(&storage->full_cond);
    pthread_cond_destroy(&storage->empty_cond);
}

size_t storage_count(const struct storage* storage) {
    return storage->count;
}

void* storage_reading_at(const struct storage* storage, size_t index) {
    return &((const reading_t*)storage->readings[(index + storage->capacity - 1) % storage->capacity])[0];
}

void storage_push(struct storage* storage, const void* data, const size_t size) {
    if (size > sizeof(reading_t)) {
        fprintf(stderr, "Invalid data size.\n");
        return;
    }

    reading_t* reading = (reading_t*)((char*)storage->data + storage->count * size);
    memcpy(reading, data, size);

    if (!pthread_cond_signal(&storage->empty_cond)) {
        perror("pthread_cond_signal");
    }
}

int main() {
    // Initialize the storage with a capacity of 1000 readings.
    struct storage storage;
    storage_init(&storage, 1000);

