typedef struct Node {
    char *str;
    size_t len;
    unsigned int count;
    struct Node *next;
} Node;

typedef struct HashTable {
    unsigned long capacity;
    unsigned long size;
    Node **table;
} HashTable;

Node* create_node(char *str) {
    Node *new_node = (Node*) malloc(sizeof(Node));
    new_node->str = strdup(str);
    new_node->len = strlen(new_node->str);
    new_node->count = 1;
    new_node->next = NULL;
    return new_node;
}

HashTable* create_hash_table(unsigned long capacity) {
    HashTable *ht = (HashTable*) malloc(sizeof(HashTable));
    ht->capacity = capacity;
    ht->size = 0;
    ht->table = calloc(capacity, sizeof(Node*));
    return ht;
}

unsigned long hash(char *str, unsigned long capacity) {
    unsigned long hash = 5381;
    int c;
    while ((c = *(str++)))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    return hash % capacity;
}

void resize_array(char **arr, size_t *size, size_t new_size) {
    char *new_arr = (char*) mmap(NULL, new_size * sizeof(char), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    memcpy(new_arr, arr[0], *size * sizeof(char));
    free(arr);
    arr = new_arr;
    *size = new_size;
}

void add_string(char **arr, size_t *size, Node **list, HashTable *ht, char *str) {
    if (*size == capacity) resize_array(arr, size, *size * 2);
    arr[*size] = str;
    (*size)++;

    Node *new_node = create_node(str);
    unsigned long index = hash(str, ht->capacity);
    if (!ht->table[index]) ht->table[index] = new_node;
    else {
        Node *current = ht->table[index];
        while (current->next) current = current->next;
        current->next = new_node;
    }

    ht->size++;
}

Node* find_longest(HashTable *ht) {
    Node *max_length_node = NULL;
    unsigned long max_len = 0;
    for (unsigned long i = 0; i < ht->capacity; ++i) {
        if (!ht->table[i]) continue;
        Node *current = ht->table[i];
        while (current) {
            if (current->len > max_len) {
                max_length_node = current;
                max_len = current->len;
            }
            current = current->next;
        }
    }
    return max_length_node;
}

