        Queue<Path> fileQueue = new LinkedBlockingQueue<>(THREAD_COUNT * 2);
        ExecutorService executor = Executors.newFixedThreadPool(THREAD_COUNT);
        Files.walkFileTree(rootDir, new SimpleFileVisitor<>() {
