const int MAX_STRING_LENGTH = 100;
const int MIN_KEY = 0, MAX_KEY = 10000;
const int MIN_INT_VALUE = -10000, MAX_INT_VALUE = 10000;
std::random_device rd;
std::mt19937 gen(rd());
std::uniform_int_distribution<> disKey(MIN_KEY, MAX_KEY);
std::uniform_int_distribution<> disInt(MIN_INT_VALUE, MAX_INT_VALUE);

struct Record {
    long offset;
    int key;
    int value;
    char status;
    std::string data;
};

class Collection {
private:
    std::list<std::unique_ptr<Record>> records;
    std::mutex mtx;
public:
    void insert(const Record& record) {
        std::lock_guard<std::mutex> lock(mtx);
        // Trim and ensure null terminator for data string
        auto trimmedData = record.data.substr(0, MAX_STRING_LENGTH);
        if (trimmedData.length() > 0) {
            trimmedData += '\0';
        }
        record.data = std::move(trimmedData);

        // Set random value for int field
        record.value = disInt(gen);

        records.push_back(std::make_unique<Record>(record));
    }

    const Record* find(int key) const {
        std::lock_guard<std::mutex> lock(mtx);
        for (const auto& record : records) {
            if (record->key == key) {
                return record.get();
            }
        }
        return nullptr;
    }

    void erase(int key) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = records.begin();
        while (it != records.end()) {
            if ((*it)->key == key) {
                it = records.erase(it);
                break;
            }
            ++it;
        }
    }

    // Provide methods to iterate over all records and other needed operations
};
