    pthread_mutex_lock(&list_mutex);
    while (temp->next != NULL && temp->next->record.key != key) temp = temp->next;
    if (temp->next == NULL) return;

    struct Node *to_free = temp->next;
    temp->next = to_free->next;
    free(to_free->record.string);
    free(to_free);
    pthread_mutex_unlock(&list_mutex);
}

// Function to search for a record by key in the linked list.
struct Record* findRecordByKey(struct Node *head, int key) {
    struct Node *temp = head;
    while (temp->next != NULL && temp->next->record.key != key) temp = temp->next;
    return temp->next->record.key == key ? &temp->next->record : NULL;
