    if (!new_record) return -1; // Memory allocation failure

    new_record->offset = offset;
    new_record->key = key;
    new_record->record_data.value = rand() % 100 + 1;
    new_record->record_data.status = status;
    asprintf(&new_record->record_data.filename, "%s", filename);
    new_record->next = collection->head;
    collection->head = new_record;
    ++collection->size;
    return 0;
}

int delete_record(Collection *collection, int key) {
    pthread_mutex_lock(&collection->mutex);
    struct Record *current = collection->head;
    struct Record *prev = NULL;

    while (current != NULL && current->key != key) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&collection->mutex);
        return -1; // Key not found
    }

    if (prev == NULL) {
        collection->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current->record_data.filename);
    free(current);
    --collection->size;
    pthread_mutex_unlock(&collection->mutex);
    return 0;
}

struct Record *find_record(Collection *collection, int key) {
    pthread_mutex_lock(&collection->mutex);
    struct Record *current = collection->head;

    while (current != NULL && current->key != key) {
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&collection->mutex);
        return NULL; // Key not found
    }

    pthread_mutex_unlock(&collection->mutex);
    return current;
}

void iterate_records(Collection *collection, void (*callback)(struct Record *)) {
    pthread_mutex_lock(&collection->mutex);
    struct Record *current = collection->head;

    while (current != NULL) {
        struct Record *temp = current;
        current = current->next;

        callback(temp);

        temp->next = collection->head;
        collection->head = temp;
    }

    pthread_mutex_unlock(&collection->mutex);
}
