typedef struct Record {
    int value;
    char status;
    char* string;
} Record;

typedef struct HashEntry {
    Record* record;
    struct HashEntry* next;
} HashEntry;

struct CustomHashTable {
    unsigned int size;
    HashEntry** table;
};

CustomHashTable create_hash_table(unsigned int size) {
    CustomHashTable table = {size, NULL};
    table.table = malloc(sizeof(HashEntry*) * size);
    memset(table.table, 0, sizeof(HashEntry*) * size);
    return table;
}

void insert_record(CustomHashTable* table, Record* record) {
    unsigned int index = hash(record->value);
    HashEntry** entry = &table->table[index];
    while (*entry != NULL) {
        if ((*entry)->record->value == record->value) return;
        entry = &((*entry)->next);
    }
    *entry = malloc(sizeof(HashEntry));
    (*entry)->record = record;
    (*entry)->next = NULL;
}

Record* find_record(CustomHashTable* table, int key) {
    unsigned int index = hash(key);
    HashEntry** entry = &table->table[index];
    while (*entry != NULL) {
        if ((*entry)->record->value == key) return (*entry)->record;
        entry = &((*entry)->next);
    }
    return NULL;
}

unsigned int hash(int key) {
    unsigned long a = 61;
    unsigned long b = 37;
    unsigned long result = 1;
    while (key) {
        result = (result * a + key % a) * b;
        key /= a;
    }
    return result % table->size;
}

// Function to implement other required features such as sorting, logging, backup, etc.
