typedef struct {
    double avg_value;
    size_t total_length;
} summary;

struct hash_table {
    size_t size;
    void **keys;
    pthread_mutex_t lock;
};

void init_hash_table(struct hash_table *ht, size_t size) {
    ht->size = size;
    ht->keys = malloc(sizeof(void *) * size);
    memset(ht->keys, 0, sizeof(void *) * size);
    pthread_mutex_init(&ht->lock, NULL);
}

uint64_t fast_hash(const char *key, size_t len) {
    uint64_t hash = 131;
    for (size_t i = 0; i < len; ++i) {
        hash = (hash * 33 + key[i]) & ((1LL << 64) - 1);
    }
    return hash % ULLONG_MAX;
}

size_t find_empty(struct hash_table *ht, uint64_t hash) {
    for (size_t i = hash; i < ht->size; ++i) {
        if (!ht->keys[i]) {
            return i;
        }
    }
    for (size_t i = 0; i <= hash; ++i) {
        if (!ht->keys[i]) {
            return i;
        }
    }
    return 0; // Table is full, should handle this case gracefully.
}

void *create_entry(double min_value, double max_value, size_t *key_len) {
    char *key = malloc(*key_len + 1);
    key[*key_len] = '\0';
    // Code for handling various data formats and sizes.
    // ...

    entry *entry_ptr = malloc(sizeof(entry));
    entry_ptr->key = key;
    entry_ptr->length = *key_len;
    entry_ptr->value = (min_value + rand() % ((int)max_value - (int)min_value + 1));

    return entry_ptr;
}

void destroy_entry(void *entry_ptr) {
    free(((entry *)entry_ptr)->key);
    free(entry_ptr);
}

void process_entry(int key, double value, void (*callback)(int, double)) {
    callback(key, value);
}

struct summary *find_or_create_summary(struct hash_table *ht, const char *key, size_t key_len) {
    uint64_t hash = fast_hash(key, key_len);
    size_t index = find_empty(ht, hash);
    if (index == 0) {
        return NULL; // Table is full, should handle this case gracefully.
    }

    void *slot = &ht->keys[index];
    pthread_mutex_lock(&ht->lock);
    entry *entry = (entry *)slot;
    if (!entry) {
        entry = create_entry(MIN_VALUE, MAX_VALUE, &key_len);
        ht->keys[index] = entry;
    } else {
        // Check for uniqueness and retry with different random offsets if duplicates are detected.
        while (strcmp(entry->key, key) == 0) {
            entry->value += rand() % ((int)MAX_VALUE - (int)MIN_VALUE + 1);
            entry = (entry *)slot;
        }
    }

    summary *summary_ptr = malloc(sizeof(summary));
    summary_ptr->avg_value = entry->value;
    summary_ptr->total_length = entry->length;

    struct hash_table summaries[] = {
        { .size = NUM_KEYS, .keys = calloc(NUM_KEYS, sizeof(void *)) },
        // More hash tables for efficient mapping of sumaries.
        // ...
    };

    uint64_t summary_hash = fast_hash(key, key_len);
    size_t summary_index = find_empty(summaries, summary_hash);
    summaries[summary_index].keys[hash] = summary_ptr;

    pthread_mutex_unlock(&ht->lock);
    return summary_ptr;
}

void init_data(struct hash_table *ht, size_t num_entries) {
    // Code for handling external data sources, filtering criteria, and optional callback mechanism.
    // ...
}

int main() {
    struct hash_table ht;
    init_hash_table(&ht, NUM_BUCKETS);
    init_data(&ht, NUM_ENTRIES);
    // Initialize other data structures and resources as needed.
    // ...

    return 0;
}
```

