using System;
using System.IO;
using System.Linq;
using System.Numerics;
using System.Security.Cryptography;
using System.Text.Compression.GZip;
using System.Threading.Tasks;
using System.Collections.Generic;

namespace DataProcessing
{
    public class DataProcessor
    {
        private readonly string _filePath;
        private readonly Tuple<BigInteger, BigInteger> _range;
        private readonly int _seedValue;
        private readonly int _numConcurrentThreads;
        private readonly CompressionAlgorithmId _compressionAlgorithm;
        private readonly int _compressionLevel;
        private readonly TextWriter _logger;
        private long _processedBytes = 0;
        private long _totalChunkSize = 0;
        private bool _isProcessing = false;
        private SemaphoreSlim _semaphore;
        private Queue<Task> _tasksQueue;
        private byte[] _chunkData;
        private HashAlgorithm hashAlgorithm = SHA256.Create();

        public DataProcessor(string filePath, Tuple<BigInteger, BigInteger> range, int seedValue, int numConcurrentThreads, CompressionAlgorithmId compressionAlgorithm, int compressionLevel, TextWriter logger)
        {
            _filePath = filePath;
            _range = range;
            _seedValue = seedValue;
            _numConcurrentThreads = numConcurrentThreads;
            _compressionAlgorithm = compressionAlgorithm;
            _compressionLevel = compressionLevel;
            _logger = logger;
        }

        public void StartProcessing()
        {
            if (_isProcessing) throw new InvalidOperationException("Processing is already in progress.");
            _isProcessing = true;
            _tasksQueue = new Queue<Task>();
            _semaphore = new SemaphoreSlim(_numConcurrentThreads);
            ProcessFile();
        }

        public void ResetProcessingState()
        {
            _processedBytes = 0;
            _totalChunkSize = 0;
            _isProcessing = false;
        }

        private async void ProcessFile()
        {
            using (var fileStream = File.OpenRead(_filePath))
            {
                var bufferSize = 1024 * 1024; // 1MB chunk size
                _totalChunkSize += fileStream.Length;
                while (_processedBytes < fileStream.Length)
                {
                    await ReadAndProcessChunkAsync(fileStream, bufferSize);
                }
            }
        }

        private async Task ReadAndProcessChunkAsync(Stream fileStream, int chunkSize = -1)
        {
            if (chunkSize < 0) chunkSize = _totalChunkSize / _numConcurrentThreads;

            var currentChunkSize = fileStream.ReadByteArray(_semaphore, chunkSize);

            if (currentChunkSize == 0) return;

            _processedBytes += currentChunkSize;

            var hash = hashAlgorithm.ComputeHash(currentChunkSize > 0 ? new MemoryStream(currentChunkSize > 0 ? CompressData(currentChunkSize) : currentChunkSize) : null);
            var chunkHash = BitConverter.ToString(hash).Replace("-", "").ToLower();

            _logger.WriteLine($"Processed chunk {_processedBytes}: {chunkHash} ({currentChunkSize} bytes)", LogLevel.INFO);
        }

        private byte[] CompressData(byte[] data)
        {
            using (var ms = new MemoryStream(data))
            using (var gz = new GZipStream(ms, CompressionMode.Compress, _compressionLevel))
                return gz.ToArray();
        }

        private byte[] DecompressData(byte[] data)
        {
            using (var ms = new MemoryStream(data))
            using (var gz = new GZipStream(ms, CompressionMode.Decompress))
                return gz.ToArray();
        }

        public int RandomInt(bool isInclusive = true) => System.Random(_seedValue).Next((int)_range.Item1, (int)(isInclusive ? _range.Item2 : _range.Item2 + 1));
        public float RandomFloat(bool isInclusive = true) => (float)System.Random(_seedValue).NextDouble() * (_range.Item2 - _range.Item1) + (isInclusive ? _range.Item1 : 0);

        public override string ToString() => $"Range: [{_range.Item1}, {_range.Item2}] Seed: {_seedValue}";
    }
}
```
