using System;
using System.Data.SqlClient;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;
using Dapper;
using StackExchange.Redis;
using StackExchange.Redis.Util;

public class DatabaseQueryService
{
    private readonly IConnectionMultiplexer _redis;
    private readonly IDbConnection _dbConnection;
    private readonly ILogger<DatabaseQueryService> _logger;
    private readonly int _maxCacheSize;
    private readonly TimeSpan _exponentialBackoffFactor;
    private readonly IDatabase _cacheDb;

    public DatabaseQueryService(IConfiguration configuration, ILogger<DatabaseQueryService> logger)
    {
        _redis = ConnectionMultiplexer.Connect(configuration["RedisConnectionString"]);
        _dbConnection = new SqlConnection(configuration["DatabaseConnectionString"]);
        _logger = logger;
        _maxCacheSize = int.Parse(configuration["MaxCacheSize"]);
        _exponentialBackoffFactor = TimeSpan.FromSeconds(double.Parse(configuration["ExponentialBackoffFactor"]));
        _cacheDb = _redis.GetDatabase();
    }

    public async Task<IDataReader> ExecuteDatabaseQuery(string sqlCommand, List<object> parameters)
    {
        var cacheKey = sqlCommand + string.Join(",", parameters.Select(x => x.ToString()));
        IDataReader result;

        // Check if the query is in the cache
        if (_cacheDb.KeyExists(cacheKey))
        {
            _logger.LogInformation($"Executing cached query: {sqlCommand}");
            result = _cacheDb.ListRangeByKey<IDataReader>(cacheKey);
        }
        else
        {
            // Execute the query asynchronously and cache the result for future use
            using var connection = _dbConnection.OpenAsync().Result;
            using var multi = await connection.CreateCommandMultiplexerAsync(sqlCommand, parameters.ToArray());

            // Configure the background worker service to handle long-running queries
            var bgWorker = new BackgroundWorker();
            bgWorker.RunWorkerAsync(() => HandleLongRunningQuery(multi));

            result = await multi.ExecuteReaderAsync();

            if (!result.HasRows) return result;

            // Cache the query result for future use, with a weight based on the number of rows processed
            var cacheEntry = new RedisValue[result.FieldCount];
            for (var i = 0; i < result.FieldCount; i++)
                cacheEntry[i] = result.GetName(i);
            _cacheDb.HashTagsWithTimetoliveAdd(cacheKey, cacheEntry, TimeSpan.FromSeconds(double.Parse(configuration["CacheExpiration"])), result.GetEnumerator());
        }

        // Log the number of rows processed and return the result set
        _logger.LogInformation($"Processed {result.FieldCount} rows for query: {sqlCommand}");
        return result;
    }

    private async void HandleLongRunningQuery(IDbCommandMultiplexer multi)
    {
        try
        {
            await multi.ExecuteNonQueryAsync();
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, $"Error executing query: {multi.CommandText}");
        }
    }
}
