import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.slf4j.*;
import com.google.gson.*;

public class SessionCounter {
    private static final Logger LOGGER = LogManager.getLogger(SessionCounter.class);
    private final ConcurrentSkipListMap<Long, Interval> sessions;
    private final ScheduledExecutorService executor;
    private final long cleanUpIntervalSeconds;
    private final Gson gson;

    public SessionCounter(long cleanUpIntervalSeconds) {
        this.sessions = new ConcurrentSkipListMap<>();
        this.executor = Executors.newScheduledThreadPool(1);
        this.cleanUpIntervalSeconds = cleanUpIntervalSeconds;
        this.gson = new Gson();
    }

    public void processSessionEvent(String event) {
        Session session = gson.fromJson(event, Session.class);
        processSession(session.startTime, session.userId, session.endTime);
    }

    private void processSession(long startTime, long userId, Long endTime) {
        Interval interval = sessions.floorEntry(startTime).getValue();
        if (interval != null && interval.contains(startTime)) {
            // Handle overlapping session
        } else {
            Interval newInterval = new Interval(startTime, userId);
            sessions.tailMapBefore(startTime).values().stream()
                    .filter(i -> i.endTime == null)
                    .forEach(i -> i.mergeWith(newInterval));
            sessions.putIfAbsent(startTime, newInterval);
        }

        if (endTime != null && sessions.containsKey(endTime)) {
            Interval endInterval = sessions.get(endTime);
            if (endInterval.userId == userId) {
                // Handle potential gaps in timestamp reporting
                sessions.remove(endTime);
                endInterval.setEndTime(endTime);
            } else {
                LOGGER.warn("Received out-of-order session event for user: {}, skipping", userId);
            }
        }
    }

    private class Interval {
        private long startTime;
        private Long endTime;
        private long userId;

        public Interval(long startTime, long userId) {
            this.startTime = startTime;
            this.userId = userId;
        }

        public void setEndTime(Long endTime) {
            this.endTime = endTime;
        }

        public boolean contains(long time) {
            return (startTime <= time && time <= endTime);
        }

        public void mergeWith(Interval other) {
            if (other.startTime < startTime) {
                startTime = other.startTime;
                userId = other.userId;
            }
            if (endTime != null && other.endTime != null) {
                endTime = Math.max(endTime, other.endTime);
            } else if (other.endTime != null) {
                endTime = other.endTime;
            }
        }
    }

    public void start() {
        executor.scheduleAtFixedRate(() -> cleanUp(), cleanUpIntervalSeconds, cleanUpIntervalSeconds, TimeUnit.SECONDS);
    }

    private void cleanUp() {
        long currentTime = Instant.now().toEpochMilli();
        sessions.keySet().stream()
                .filter(time -> time + cleanUpIntervalSeconds * 1000 < currentTime)
                .forEach(time -> sessions.remove(time));
    }
}

public class Session {
    private long userId;
    private long startTime;
    private Long endTime;

    // constructor, getters and setters
}
```

This code provides a basic implementation for the given task using a ConcurrentSkipListMap to store session intervals and a ScheduledExecutorService to handle periodic cleanup of expired sessions. The SessionCounter class also includes methods to process session events (Session.class), log processing times, and handle edge cases such as overlapping sessions, missing end timestamps, and out-of-order events.

The code is designed for scalability under load and can be extended with additional session metrics or integration with existing logging infrastructure.']

