// Function prototype for createDirectoryWithPermissions
int createDirectoryWithPermissions(const char *path, mode_t mode);

int createDirectoryWithPermissions(const char *path, mode_t mode) {
    struct stat st;

    if (stat(path, &st) == -1 && errno != ENOENT) {  // Check for existence and handle errors
        perror("stat");
        return -1;
    }

    if (S_ISDIR(st.st_mode)) {  // Check if it's a directory
        return chmod(path, mode);  // Update permissions if it exists and is a directory
    } else if (errno != ENOENT) {  // Handle errors other than ENOENT
        perror("stat");
        return -1;
    }

    if (mkdir(path, mode) == -1) {  // Create directory
        perror("mkdir");
        return -1;
    }

    return 0;  // Success
}
