2. Python Code (`batchFileProcessor.py`)

```python
import os
import threading
import queue
import time

def process_file(queue, out_queue, func):
    while True:
        file = queue.get()
        if not file:
            break
        result = func(file)
        out_queue.put((file, result))

def batchFileProcessor(files, func, num_threads=os.cpu_count()*2):
    q, oq = queue.Queue(), queue.Queue()
    threads = [threading.Thread(target=process_file, args=(q, oq, func)) for _ in range(num_threads)]

    for thread in threads:
        thread.start()

    for file in files:
        q.put(file)

    for thread in threads:
        thread.join()

    return {file: result for file, result in zip(files, oq.queue)}
```

