#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <pthread.h>
#include <stdbool.h>
#include <unistd.h>
#include <limits.h>
#include <semaphore.h>

typedef struct _file_t {
    char *path;
    long size;
    struct _file_t *next;
} file_t;

sem_t list_mutex;

void process_file(file_t *file) {
    // Read file size and populate 'size' field
    struct stat st;
    if (stat(file->path, &st) < 0) return;
    file->size = st.st_size;

    // Allocate and initialize char buffer for file name
    size_t len = strlen(file->path);
    char *buf = malloc(len + 1);
    strcpy(buf, file->path);
    free(file->path);
    file->path = buf;
}

void push_front(file_t **head, file_t *new) {
    new->next = *head;
    *head = new;
}

file_t* pop_front(file_t **head) {
    if (*head == NULL) return NULL;
    file_t *temp = *head;
    *head = temp->next;
    return temp;
}

void list_free(file_t *list) {
    while (list != NULL) {
        file_t *temp = list;
        list = list->next;
        free(temp->path);
        free(temp);
    }
}

int main() {
    sem_init(&list_mutex, 0, 1);
    file_t *head = NULL;
    pthread_t threads[10]; // Adjustable thread count

    while (true) {
        char path[PATH_MAX];
        if (fgets(path, sizeof(path), stdin) == NULL) break;

        file_t *file = malloc(sizeof(file_t));
        if (!file) {
            perror("Memory allocation failure");
            continue;
        }
        file->path = strdup(path);
        file->size = 0;
        file->next = NULL;

        sem_wait(&list_mutex);
        push_front(&head, file);
        sem_post(&list_mutex);

        pthread_create(&threads[pthread_count], NULL, process_file, file);
    }

    while (pthread_count > 0) pthread_join(threads[--pthread_count], NULL);

    sem_destroy(&list_mutex);

    file_t *max_size = head;
    long max_size_val = LONG_MIN;

    sem_wait(&list_mutex);
    for (file_t *cur = head; cur != NULL; cur = cur->next) {
        if (cur->size > max_size_val) {
            max_size = cur;
            max_size_val = cur->size;
        }
    }
    sem_post(&list_mutex);

    printf("%s\n", max_size->path);
    list_free(head);
    return 0;
}
```
