unsigned long hash(const char *key, unsigned long length) {
    unsigned long hash = 5381;
    int c;

    while ((c = *key++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

    return hash % length;
}

void insert_endpoint(HashTable *ht, Endpoint *ep) {
    unsigned long index = hash(ep->ip, strlen(ep->ip));
    HashTableNode **node_ptr = &ht->table[index];
    HashTableNode *new_node = malloc(sizeof(HashTableNode));

    pthread_mutex_lock(&ht->mutex);
    new_node->endpoint = ep;
    new_node->next = *node_ptr;
    *node_ptr = new_node;
    pthread_mutex_unlock(&ht->mutex);
}

