struct ResourcePool {
    std::vector<Resource> resources;
    std::map<unsigned long long, std::shared_ptr<Resource>> pool; // resource map using ids as keys
    size_t capacity;
    size_t size;

    mutex mtx;
    condition_variable cv;
};

void schedule(ResourcePool& pool, const Resource& resource) {
    std::unique_lock<std::mutex> lock(pool.mtx);
    // Check if the resource is already in the pool
    auto it = pool.pool.find(resource.id);
    if (it != pool.pool.end()) {
        // Extend reservation or handle overlapping cases as needed
    } else {
        // Schedule new resource, ensuring proper memory management
        if (pool.size == pool.capacity) {
            // Handle the case when the pool is full
        }
        pool.resources.push_back(resource);
        pool.pool[resource.id] = std::make_shared<Resource>(resource);
        ++pool.size;
    }
    lock.unlock();
    pool.cv.notify_one(); // Notify any waiting threads if there were any
}

void extend_reservation(ResourcePool& pool, unsigned long long id) {
    // Extend reservation time for the given resource in a similar fashion as schedule()
}

void release_resource(ResourcePool& pool, unsigned long long id) {
    std::unique_lock<std::mutex> lock(pool.mtx);
    auto it = pool.pool.find(id);
    if (it == pool.pool.end()) {
        throw std::runtime_error("Resource not found");
    }
    // Release resource, ensuring proper memory management
    it->second.reset();
    pool.resources.erase(std::remove_if(pool.resources.begin(), pool.resources.end(),
                          [id](const Resource& res) { return res.id == id; }), pool.resources.end());
    --pool.size;
    lock.unlock();
    pool.cv.notify_one(); // Notify any waiting threads if there were any
}

void serialize(ResourcePool& pool, std::ostream& out) {
    boost::archive::text_oarchive oa(out);
    oa & boost::serialization::make_nvp("pool", pool);
}

void deserialize(ResourcePool& pool, std::istream& in) {
    boost::archive::text_iarchive ia(in);
    ia & boost::serialization::make_nvp("pool", pool);
}
