typedef struct sensor_data {
    double *temperature;
    int timestamp;
    bool validity;
} sensor_data;

void custom_free(void **ptr) {
    if (*ptr != NULL) {
        free(*ptr);
        *ptr = NULL;
    }
}

int init_sensor_network(double sampling_interval, const char *input_ids, size_t memory_limit, void (**memory_manager)(void **), sensor_data **sensor_data_ptr) {
    // Handle error cases for invalid input
    if (sampling_interval <= 0 || !input_ids || !*memory_manager || !sensor_data_ptr) {
        return -1;
    }

    size_t num_sensors = 0;
    char **ids = NULL;
    sensor_data *sensor_data_arr = NULL;
    double *temp_arr = NULL;
    size_t max_sensors = memory_limit / (sizeof(sensor_data) + sizeof(double));

    // Validate and store the input IDs
    ids = malloc((strlen(input_ids) + 1) * sizeof(char*));
    char *token = strtok(const_cast<char*>(input_ids), ",");
    size_t i = 0;
    while (token != NULL && num_sensors < max_sensors) {
        // Handle duplicates and alphanumeric format validation
        bool is_valid = true;
        for (size_t j = 0; j < i; ++j) {
            if (!strcmp(token, ids[j])) {
                is_valid = false;
                break;
            }
        }
        if (!is_valid || strlen(token) > 32 || !isalnum(*token)) {
            continue;
        }

        ids[i] = strdup(token);
        ++num_sensors;
        token = strtok(NULL, ",");
    }

    if (num_sensors == 0) {
        // Free memory and return failure
        for (size_t i = 0; i < num_sensors; ++i) {
            custom_free((void**)&ids[i]);
        }
        free(ids);
        return -1;
    }

    // Allocate memory for the temperature readings, considering validity and sampling period
    temp_arr = calloc(num_sensors * (1 / sampling_interval), sizeof(double));
    if (!temp_arr) {
        // Free memory and return failure
        for (size_t i = 0; i < num_sensors; ++i) {
            custom_free((void**)&ids[i]);
        }
        free(ids);
        return -1;
    }

    // Initialize sensor data, considering input parameters and data quality
    sensor_data_arr = malloc(num_sensors * sizeof(sensor_data));
    if (!sensor_data_arr) {
        // Free memory and return failure
        custom_free((void**)&temp_arr);
        for (size_t i = 0; i < num_sensors; ++i) {
            custom_free((void**)&ids[i]);
        }
        free(ids);
        return -1;
    }

    // Assign temperature readings and initialize sensor data structures
    double temp_range = 100.0;
    for (size_t i = 0; i < num_sensors; ++i) {
        sensor_data *sd = &sensor_data_arr[i];
        sd->temperature = &temp_arr[(i * (1 / sampling_interval))];
        sd->timestamp = -1;
        sd->validity = true;

        // Adjust temperature values to reflect data quality and source accuracy
        *sd->temperature = ((rand() % temp_range * 2) - temp_range + temp_range / 2) / 100.0;
    }

    // Initialize the custom memory manager for further memory operations
    (*memory_manager)((void**)&ids);
    (*memory_manager)((void**)&temp_arr);
    (*memory_manager)((void**)&sensor_data_arr);

    *sensor_data_ptr = sensor_data_arr;
    return num_sensors;
}
