#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#ifdef _WIN32
#define aligned_malloc(sz, al) _aligned_malloc(sz, al)
#define aligned_free(ptr) _aligned_free(ptr)
#else
#define aligned_malloc(sz, al) aligned_alloc(al, sz)
#define aligned_free(ptr) free(ptr)
#endif

// Max memory limit
#define MAX_MEMORY 10485760 // 10MB (feel free to adjust this value as needed)

typedef struct offset_record {
    long offset;
    int key;
    char* data;
} offset_record;

typedef struct record {
    int value;
    size_t length; // length of associated 'data' array
    char* data;
} record;

// Thread-safe random number generator
pthread_mutex_t rand_mutex = PTHREAD_MUTEX_INITIALIZER;

int thread_safe_rand(int min, int max) {
    pthread_mutex_lock(&rand_mutex);
    int range = (max - min) + 1;
    int r = rand() % range;
    pthread_mutex_unlock(&rand_mutex);
    return min + r;
}

// Memory pool for 'offset_record' structures
struct offset_pool {
    size_t capacity;
    size_t count;
    offset_record* records;
};

void init_offset_pool(struct offset_pool* pool, size_t initial_capacity) {
    pool->records = aligned_malloc(sizeof(offset_record) * initial_capacity, 16); // Align allocations for better cache performance
    pool->capacity = initial_capacity;
    pool->count = 0;
}

void free_offset_pool(struct offset_pool* pool) {
    if (pool->records) {
        aligned_free(pool->records);
        pool->capacity = 0;
        pool->count = 0;
    }
}

offset_record* get_offset_record(struct offset_pool* pool) {
    if (pool->count >= pool->capacity) {
        size_t new_capacity = pool->capacity * 2; // Double the capacity when it's full
        void* new_records = aligned_realloc(pool->records, sizeof(offset_record) * new_capacity, 16);
        if (new_records == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for offset records.\n");
            return NULL;
        }
        pool->records = new_records;
        pool->capacity = new_capacity;
    }
    offset_record* record = &pool->records[pool->count++];
    return record;
}

// Memory pool for 'record' structures
struct record_pool {
    size_t capacity;
    size_t count;
    record* records;
};

void init_record_pool(struct record_pool* pool, size_t initial_capacity) {
    pool->records = aligned_malloc(sizeof(record) * initial_capacity, 16); // Align allocations for better cache performance
    pool->capacity = initial_capacity;
    pool->count = 0;
}

void free_record_pool(struct record_pool* pool) {
    if (pool->records) {
        aligned_free(pool->records);
        pool->capacity = 0;
        pool->count = 0;
    }
}

record* get_record(struct record_pool* pool) {
    if (pool->count >= pool->capacity) {
        size_t new_capacity = pool->capacity * 2; // Double the capacity when it's full
        void* new_records = aligned_realloc(pool->records, sizeof(record) * new_capacity, 16);
        if (new_records == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for record structures.\n");
            return NULL;
        }
        pool->records = new_records;
        pool->capacity = new_capacity;
    }
    record* record = &pool->records[pool->count++];
    return record;
}

// Function to initialize the data structures with the given parameters
void init_data_structures(size_t offset_size, size_t offset_array_size, size_t record_array_size, int min_value, int max_value) {
    struct offset_pool offset_pool;
    struct record_pool record_pool;

    init_offset_pool(&offset_pool, 16); // Start with a small number of offset records to minimize memory usage
    init_record_pool(&record_pool, min((size_t)MAX_MEMORY / (sizeof(offset_record) + sizeof(record)), record_array_size));

    for (size_t i = 0; i < offset_array_size; ++i) {
        offset_record* record = get_offset_record(&offset_pool);
        if (!record) break; // Exit loop if memory allocation fails
        record->offset = i * offset_size;
        record->key = i;

        size_t data_length = (record->offset > 0) ? record->offset : 1;
        record->data = aligned_malloc(data_length, 16); // Align allocations for better cache performance
    }

    for (size_t i = 0; i < record_array_size; ++i) {
        record* record = get_record(&record_pool);
        if (!record) break; // Exit loop if memory allocation fails
        record->value = thread_safe_rand(min_value, max_value);
        record->length = 1 + (record->value % data_length);
        record->data = aligned_malloc((size_t)(record->length), 16); // Align allocations for better cache performance
    }
}

// Function to clean up the allocated memory when necessary
void cleanup_memory(struct offset_pool* offset_pool, struct record_pool* record_pool) {
    if (offset_pool->count > 16) free_offset_pool(offset_pool); // Free memory if the number of allocated offset records exceeds 16
    if (record_pool->count > 16) free_record_pool(record_pool); // Free memory if the number of allocated record structures exceeds 16
}
```

This function initializes two memory pools for `offset_record` and `record` structures, allowing dynamic allocation based on user-provided parameters. It also ensures thread safety during random number generation, optimizes memory utilization, and provides mechanisms for efficient memory deallocation.

It should be noted that this code is just a starting point, and additional error handling, optimization, and function extension mechanisms will depend on the specific requirements of your project.']

