```c
#include "memory_manager.h"

void initialize_memory(struct MemoryManager *mm, const char *csv_filename, const size_t max_records) {
    mm->offsets = calloc(max_records, sizeof(long));
    mm->keys = calloc(max_records, sizeof(int));
    mm->indices = calloc(sizeof(size_t), 1);
    mm->num_indices = 0;
    mm->num_records = 0;
    mm->records = NULL;

    FILE *file = fopen(csv_filename, "r");
    if (!file) {
        perror("Error opening file");
        return;
    }
    read_csv(mm, file);
}

void read_csv(struct MemoryManager *mm, FILE *file) {
    char line[1024];
    int i = 0;

    while (fgets(line, sizeof(line), file)) {
        if (i >= mm->num_indices) {
            resize_indices(mm);
        }
        sscanf(line, "%ld,%d\n", &mm->offsets[mm->indices[i]], &mm->keys[i]);
        i++;
    }
    rewind(file);

    mm->num_records = i;
    if (mm->num_records >= mm->num_indices) {
        resize_records(mm, mm->num_records);
    }
}

void set_random_values(struct MemoryManager *mm) {
    srand(time(NULL));
    for (size_t i = 0; i < mm->num_records; i++) {
        mm->records[i].value = rand() % 100 + 1;
    }
}

Record *resize_records(struct MemoryManager *mm, size_t new_size) {
    Record *new_arr = realloc(mm->records, new_size * sizeof(Record));
    if (!new_arr) {
        perror("Error allocating memory");
        return NULL;
    }
    mm->records = new_arr;
    return mm->records;
}

void resize_indices(struct MemoryManager *mm) {
    size_t *tmp = realloc(mm->indices, sizeof(size_t) * (mm->num_indices + 1));
    if (!tmp) {
        perror("Error allocating memory");
        return;
    }
    mm->indices = tmp;
    mm->indices[mm->num_indices] = mm->num_records;
}

void serialize(const struct MemoryManager *mm, const char *output_filename, z_stream *strm) {
    gzFile outfile = gzopen(output_filename, "wb");

    if (!outfile || !compress2(strm, Z_FILTER_DEFLATE, mm)) {
        perror("Error opening file or compressing data");
        return;
    }

    for (size_t i = 0; i < mm->num_indices; i++) {
        fwrite(&mm->offsets[mm->indices[i]], sizeof(long), 1, outfile);
        fwrite(&mm->keys[i], sizeof(int), 1, outfile);
    }

    for (size_t i = 0; i < mm->num_records; i++) {
        fwrite(&mm->records[i].value, sizeof(Record), 1, outfile);
    }

    gzclose(outfile);
}

void deserialize(struct MemoryManager *mm, const char *input_filename, z_stream *strm) {
    gzFile infile = gzopen(input_filename, "rb");

    if (!infile || !inflateInit2(strm, Z_DEFLATED, 15 + 32, -MAX_WBITS, Z_DEFAULT_STRATEGY, Z_DEFAULT_WINDOW_BITS) ||
        !inflate(strm, Z_FINISH) || (strm->avail_in != 0)) {
        perror("Error opening file or decompressing data");
        return;
    }

    size_t offset, key;
    for (size_t i = 0; i < mm->num_indices; i++) {
        fread(&offset, sizeof(long), 1, infile);
        fread(&key, sizeof(int), 1, infile);

        mm->offsets[i] = offset;
        mm->keys[i] = key;
    }

    size_t record_size = sizeof(Record) * mm->num_records;
    Record *tmp = malloc(record_size);
    fread(tmp, record_size, 1, infile);

    for (size_t i = 0; i < mm->num_records; i++) {
        mm->records[i] = tmp[i];
    }

    inflateEnd(strm);
    gzclose(infile);
}

void free_memory(struct MemoryManager *mm) {
    if (mm->offsets) free(mm->offsets);
    if (mm->keys) free(mm->keys);
    if (mm->indices) free(mm->indices);
    if (mm->records) free(mm->records);
}
```

