2. Concurrent Record Collection (Java using synchronized blocks and Atomic classes):

```java
public class RecordCollection {
    private Map<Long, Record> records = new ConcurrentHashMap<>();

    public void add(Record record) {
        synchronized (records) {
            records.putIfAbsent(record.getId(), record);
        }
    }

    public void update(Record record) {
        AtomicReference<Record> current = new AtomicReference<>(null);
        boolean updated = false;
        while (!updated) {
            Record existing = records.get(record.getId());
            if (existing != null && existing.equals(record)) {
                updated = true;
            } else {
                current.set(existing);
                try {
                    Thread.sleep(10);
                } catch (InterruptedException e) {
                    e.printStackTrace();
                }
            }
        }
        records.putIfAbsent(record.getId(), record);
    }

    // Getters and setters for the collection
}
```

