['1. C Function for Dynamic Log Collection (log_collection.c)

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <pthread.h>
#include <pthread_rwlock_t.h>
#include <atomic>
#include <unordered_map>

struct LogEntry {
    std::atomic<uint64_t> id;
    time_t timestamp;
    char* message;
};

std::unordered_map<uint64_t, struct LogEntry*> log_map;
pthread_rwlock_t rwlock;

void init_log_collection() {
    pthread_rwlock_init(&rwlock, nullptr);
}

struct LogEntry* create_log_entry() {
    struct LogEntry* new_entry = (struct LogEntry*) malloc(sizeof(struct LogEntry));
    if (!new_entry) {
        return nullptr;
    }
    new_entry->id.store(0, std::memory_order_relaxed);
    new_entry->timestamp = time(nullptr);
    new_entry->message = nullptr;
    return new_entry;
}

void free_log_entry(struct LogEntry* entry) {
    if (entry && entry->message) {
        free(entry->message);
    }
    free(entry);
}

void add_or_update_log_entry(uint64_t id, const char* message) {
    pthread_rwlock_wrlock(&rwlock);

    if (log_map.find(id) != log_map.end()) {
        // Conflict resolution strategy here
    }

    struct LogEntry* new_entry = create_log_entry();
    if (!new_entry) {
        pthread_rwlock_unlock(&rwlock);
        return;
    }

    new_entry->id.store(id, std::memory_order_relaxed);
    new_entry->message = strdup(message);
    if (!new_entry->message) {
        free_log_entry(new_entry);
        pthread_rwlock_unlock(&rwlock);
        return;
    }

    log_map[id] = new_entry;

    pthread_rwlock_unlock(&rwlock);
}

struct LogEntry* get_log_entry(uint64_t id) {
    pthread_rwlock_rdlock(&rwlock);

    auto it = log_map.find(id);
    if (it != log_map.end()) {
        return it->second;
    }

    pthread_rwlock_unlock(&rwlock);
    return nullptr;
}
```

