#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

typedef struct Record {
    int key;
    bool status;
    char* str;
} Record;

typedef struct Node {
    Record data;
    struct Node* next;
} Node;

typedef struct HashTable {
    unsigned long capacity;
    unsigned long size;
    Node** table;
} HashTable;

unsigned long hash(int key, unsigned long capacity) {
    return key % capacity;
}

void rehash(HashTable* ht) {
    unsigned long old_capacity = ht->capacity;
    ht->capacity *= 2;
    Node** new_table = malloc(sizeof(Node*) * ht->capacity);
    for (unsigned long i = 0; i < old_capacity; ++i) {
        if (!new_table[i]) new_table[i] = NULL;
        Node* n = ht->table[i];
        while (n != NULL) {
            Node* temp = n;
            n = n->next;
            insert(temp, ht);
        }
    }
    free(ht->table);
    ht->table = new_table;
}

void insert(Record data, HashTable* ht) {
    unsigned long index = hash(data.key, ht->capacity);
    if (!ht->table[index]) ht->table[index] = malloc(sizeof(Node));
    Node* n = ht->table[index];
    while (n != NULL && n->data.key < data.key) n = n->next;
    data.str = malloc(strlen(data.str) + 1);
    memcpy(data.str, data.str, strlen(data.str) + 1);
    if (!n) {
        ht->table[index] = malloc(sizeof(Node));
        n = ht->table[index];
    }
    n->data = data;
    n->next = malloc(sizeof(Node));
    n = n->next;
}

void delete_key(int key, HashTable* ht) {
    unsigned long index = hash(key, ht->capacity);
    Node** current = &ht->table[index];
    while (*current != NULL && (*current)->data.key < key) current = &((*current)->next);
    if (!(*current)) return;

    Node* temp = *current;
    if ((*current)->data.key == key) {
        *current = (*current)->next;
        free(temp->str);
        free(temp);
    } else {
        while ((*current)->next && (*current)->next->data.key < key) current = &((*current)->next);
        if (!(*current)->next || (*current)->next->data.key != key) return;
        temp = (*current)->next;
        (*current)->next = temp->next;
        free(temp->str);
        free(temp);
    }
}

Record* find_key(int key, HashTable* ht) {
    unsigned long index = hash(key, ht->capacity);
    Node** current = &ht->table[index];
    while (*current != NULL && (*current)->data.key < key) current = &((*current)->next);
    if (!(*current)) return NULL;
    if ((*current)->data.key == key) return &((*current)->data);
    while ((*current)->next && (*current)->next->data.key != key) current = &((*current)->next);
    return (*current)->next ? &((*current)->next->data) : NULL;
}

// Filter and sort functions using appropriate data structures and algorithms

void free_record(Record* record) {
    free(record->str);
    free(record);
}

void free_hash_table(HashTable* ht) {
    for (unsigned long i = 0; i < ht->capacity; ++i) {
        Node* n = ht->table[i];
        while (n != NULL) {
            Node* temp = n;
            n = n->next;
            free_record(temp);
        }
    }
    free(ht->table);
}
```

