[' I will provide a simplified C++ solution using the `std::unordered_map` for fast lookup of sessions and `boost::intrusive_ptr` for efficient memory management. For thread-safety, we'll use the `boost::lockfree::queue` for session addition and removal, which supports high concurrency with minimal lock contention.

```cpp
#include <iostream>
#include <chrono>
#include <unordered_map>
#include <string>
#include <boost/date_time/posix_time/ptime.hpp>
#include <boost/lockfree/spsc_queue.hpp>
#include <boost/intrusive/counted_ptr.hpp>

struct Session {
    std::string id;
    std::string ip;
    boost::posix_time::ptime lastActivity;
    std::unordered_set<std::string> activeFeatures; // Replace with your custom feature data structure
};

using SessionPtr = boost::intrusive::counted_ptr<Session>;
using SessionQueueType = boost::lockfree::spsc_queue<SessionPtr>;
using SessionMapType = std::unordered_map<std::string, SessionPtr>;

class SessionManager {
public:
    SessionManager() : m_sessionQueue(SessionQueueType::max_size()), m_inactiveTime(std::chrono::seconds(30)) {}

    SessionPtr addSession(const std::string& id, const std::string& ip) {
        auto session = SessionPtr(new Session{id, ip, boost::posix_time::second_clock::local_time(), {}});
        if (m_sessionQueue.push(session)) {
            return session;
        } else {
            throw std::runtime_error("Failed to push session into queue");
        }
    }

    void updateSessionActivity(const SessionPtr& session) {
        session->lastActivity = boost::posix_time::second_clock::local_time();
    }

    bool isSessionActive(const std::string& id, const std::string& feature) const {
        const auto it = m_sessionMap.find(id);
        if (it != m_sessionMap.end()) {
            return it->second->activeFeatures.count(feature) > 0;
        }
        return false;
    }

    void removeInactiveSessions() {
        std::chrono::time_point<std::chrono::system_clock> now = std::chrono::system_clock::now();
        while (!m_sessionQueue.empty()) {
            SessionPtr session = m_sessionQueue.pop();
            if (std::chrono::duration_cast<std::chrono::seconds>(now - session->lastActivity).get<std::chrono::seconds>() >= m_inactiveTime.get<std::chrono::seconds>()) {
                session->reset(); // Call your custom destructor for proper cleanup here
            } else {
                auto it = m_sessionMap.find(session->id);
                if (it != m_sessionMap.end()) {
                    it->second = session;
                } else {
                    std::cout << "Session not found in map: " << session->id << std::endl;
                }
            }
        }
    }

private:
    SessionQueueType m_sessionQueue;
    SessionMapType m_sessionMap;
    std::chrono::seconds m_inactiveTime;
};
```

This code assumes that you have the necessary Boost libraries installed, and it provides a basic structure for managing sessions. It is important to replace the `Session` struct with your actual custom data structure representing user sessions, and adapt the `removeInactiveSessions()` function according to your specific requirements. Additionally, you might need to implement mechanisms for periodic or asynchronous removal of inactive sessions based on your application's concurrency and resource management constraints.']

