```csharp
using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using System.Globalization;

public class FileInitializer
{
    private const int MaxFileSize = 1024 * 1024 * 1024; // 1 GB
    private readonly ConcurrentDictionary<long, int> _offsetsAndKeys;
    private readonly object _lockObject = new Object();
    private readonly LocalizationManager _localizationManager;

    public FileInitializer(LocalizationManager localizationManager)
    {
        _offsetsAndKeys = new ConcurrentDictionary<long, int>();
        _localizationManager = localizationManager;
    }

    public void InitializeFiles(long minOffset, long maxOffset, int keyCount, int metadataSize)
    {
        for (long i = minOffset; i <= maxOffset; i += metadataSize + 1)
        {
            var key = GenerateKey(keyCount);
            var offset = i;
            Parallel.ForEach(Enumerable.Range(0, metadataSize), () => new Tuple<int, string>(-1, null), (state, index) =>
            {
                state.Item1++;
                if (state.Item1 < metadataSize)
                {
                    state.Item2 = _localizationManager.GetLocalizedString(index, CultureInfo.CreateSpecificCulture("en-US"));
                }

                lock (_lockObject)
                {
                    _offsetsAndKeys.TryAdd(offset + (long)state.Item1, key);
                }

                return state;
            });
        }
    }

    private int GenerateKey(int maxKey) => new Random().Next(maxKey);
}
```

