config_priority = ["primary", "secondary"]

class ConfigUpdater:
    def __init__(self):
        self._configs = {}
        self._cache = LFUCache(maxsize=1000, ttl=60)
        self.logger = logging.getLogger(__name__)

    def load_config(self, filename):
        with open(filename, 'r') as file:
            config = yaml.safe_load(file)
        return config

    def update_config(self, config, placeholders):
        for key, value in placeholders.items():
            pattern = rf'{{{key}}}'
            config[key] = value
            for placeholder in re.finditer(pattern, config):
                start, end = placeholder.span()
                config = f"{config[:start]}{value}{config[end:]}"
        return config

    def get_config(self, filename):
        if filename not in self._cache:
            for priority in config_priority:
                filepath = os.path.join(os.getcwd(), filename)
                if os.path.exists(filepath):
                    break
            else:
                raise FileNotFoundError(f"No valid configuration files found.")
            self._cache[filename] = self.load_config(filename)
        return self._cache[filename]

    def get_placeholder_values(self):
