#include <openssl/aes.h>
#include <openssl/rsa.h>
#include <openssl/hmac.h>
#include <openssl/err.h>

struct EVP_CIPHER *create_cipher(int keySize, int mode, const EVP_MD_CTX* hmacCtx) {
    AES_KEY aesKey;
    RSA* rsa = nullptr;
    unsigned char* iv = nullptr;

    // Generate AES key and IV
    if (AES_set_encrypt_key(reinterpret_cast<const uint8_t*>(keySize), 128, &aesKey) <= 0) {
        throw std::runtime_error("Error generating AES key");
    }

    iv = static_cast<unsigned char*>(OPENSSL_malloc(AES_block_size()));
    if (iv == nullptr) {
        throw std::runtime_error("Error allocating memory for IV");
    }

    // Initialize RSA key pair
    rsa = RSA_new();
    if (RSA_generate_key_ex(rsa, keySize / 8, NULL, NULL) <= 0) {
        throw std::runtime_error("Error generating RSA key");
    }

    // Create EVP_CIPHER context
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        throw std::runtime_error("Error allocating memory for cipher context");
    }

    // Set encryption mode and key/IV
    if (1 == mode) {  // ECB
        EVP_EncryptInit_ex(ctx, EVP_aes_128_cbc(), &aesKey, nullptr, iv);
    } else if (2 == mode) {  // CBC
        EVP_EncryptInit_ex(ctx, EVP_aes_128_cbc(), &aesKey, rsa->get0_rptr()->d, iv);
    } else {
        throw std::runtime_error("Invalid encryption mode");
    }

    // Set HMAC context for message integrity check
    EVP_MD_CTX_copy(ctx, hmacCtx);

    // Return the cipher structure
    return ctx;
}
