#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>
#include <time.h>
#include <evp.h>

typedef struct {
    long offset;
    int key;
    double value;
    char status;
} Record;

struct cipher_data {
    Record* offsets;
    int* keys;
    void** data;
    size_t capacity;
    size_t count;
    CURL* api_handle;
    CURLcode last_response;
};

struct cipher_data* init_cipher(size_t capacity) {
    struct cipher_data* cd = malloc(sizeof(struct cipher_data));
    if (!cd) return NULL;

    cd->capacity = capacity;
    cd->count = 0;
    cd->offsets = calloc(capacity, sizeof(Record));
    if (!cd->offsets) {
        free(cd);
        return NULL;
    }
    cd->keys = calloc(capacity, sizeof(int));
    if (!cd->keys) {
        free(cd->offsets);
        free(cd);
        return NULL;
    }
    cd->data = calloc(capacity, sizeof(void*));
    if (!cd->data) {
        free(cd->keys);
        free(cd->offsets);
        free(cd);
        return NULL;
    }

    cd->api_handle = curl_easy_init();

    return cd;
}

void destroy_cipher(struct cipher_data* cd) {
    if (cd->api_handle) curl_easy_cleanup(cd->api_handle);
    free(cd->offsets);
    free(cd->keys);
    free(cd->data);
    free(cd);
}

CURLcode fetch_data(struct cipher_data* cd, const char* url) {
    CURLcode res;
    if (cd->last_response == CURLE_OK) return CURLE_OK; // already fetched recently

    curl_easy_reset(cd->api_handle);
    curl_easy_setopt(cd->api_handle, CURLOPT_URL, url);
    curl_easy_setopt(cd->api_handle, CURLOPT_WRITEFUNCTION, NULL); // ignore data for now

    res = curl_easy_perform(cd->api_handle);

    if (res != CURLE_OK) {
        printf("Error fetching data: %s\n", curl_easy_strerror(res));
        return res;
    }

    cd->last_response = res;
    return CURLE_OK;
}

void parse_and_fill(struct cipher_data* cd, const char* data, size_t index) {
    // Assuming the parsed struct looks like: { "offset": offset, "key": key, "value": value, "status": status }
    json_object* obj = json_tokener_parse(data);
    if (!obj) return;

    Record* record = &cd->offsets[index];
    json_object* offset_obj = json_object_object_get(obj, "offset");
    json_object_object_get_ex(offset_obj, const char*, &record->offset);

    json_object* key_obj = json_object_object_get(obj, "key");
    json_object_object_get_ex(key_obj, const char*, &record->key);

    record->value = json_object_get_double(json_object_object_get(obj, "value"));
    record->status = json_object_get_string(json_object_object_get(obj, "status"))[0];

    cd->data[index] = malloc(sizeof(struct { double value; char status; }));
    memcpy(cd->data[index], &record->value, sizeof(double));
    cd->data[index][sizeof(double)] = record->status;
}

void fill_cipher(struct cipher_data* cd) {
    if (cd->count == cd->capacity) return;

    for (size_t i = cd->count; i < cd->capacity; ++i) {
        CURLcode res = fetch_data(cd, "https://example-api.com/fetch?index=*");
        if (res != CURLE_OK) continue;

        size_t count = 0;
        while (count < 10) {
            char data[4096];
            res = curl_easy_getinfo(cd->api_handle, CURLINFO_RESPONSE_CODE, &res);
            if (res != CURLE_OK) break;

            if (res == 200 || res == 201) { // Successful response
                size_t nread = curl_easy_getinfo(cd->api_handle, CURLINFO_RECV_SIZE_TOTAL, &count);
                if (nread > 4095) continue; // Too large, retry later

                res = curl_easy_read(cd->api_handle, data, nread + 1);
                if (res != CURLE_OK || res > 0) break; // Error or EOF
            } else {
                continue; // Non-2xx response, retry later
            }

            parse_and_fill(cd, data, i);
        }
    }

    cd->count = cd->capacity;
}

void validate_cipher(struct cipher_data* cd) {
    for (size_t i = 0; i < cd->count; ++i) {
        if (cd->offsets[i].key != cd->keys[i] || !cd->data[i]) {
            fprintf(stderr, "Invalid data record: index=%zu\n", i);
            return;
        }
    }
}

EVP_CIPHER* get_cipher() {
    static struct cipher_data cd = {0}; // Singleton instance

    fill_cipher(&cd);
    validate_cipher(&cd);

    return &cd.data[0]->value;
}
```']

