        if (it != sessions.end()) {
            // Remove node from tree here, e.g., tree.erase(it->first);
            return true;
        }
        return false;
    }

    bool isSessionValid(const std::string& id) const {
        auto it = sessions.find(id);
        if (it != sessions.end()) {
            if (std::time(nullptr) > it->second->expiration) {
                return false;
            }
        }
        return true;
    }

    StorageType& getSessions() { return sessions; }

private:
    boost::circular_buffer<SessionMetadata> logBuffer;
    RedBlackTree<Session, &SessionStorage::compareSession> tree; // Use a Red-Black Tree for efficient lookups and updates.
