#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct Record {
    int value;
    char status;
    char* str;
} Record;

typedef struct Node {
    Record data;
    struct Node* next;
} Node;

struct System {
    size_t offsetsSize;
    size_t keysSize;
    Node** records;
    pthread_mutex_t mutex;
    size_t cacheSize;
    Node* cacheHead;
    size_t cacheCount;
};

int initSystem(struct System* sys, size_t offsetsSize, size_t keysSize) {
    sys->offsetsSize = offsetsSize;
    sys->keysSize = keysSize;
    sys->records = calloc(keysSize, sizeof(Node*));
    if (!sys->records) return -1; // Memory allocation failure

    for (size_t i = 0; i < offsetsSize; ++i)
        sys->offsets[i] = i * keysSize;

    for (size_t i = 0; i < keysSize; ++i)
        sys->keys[i] = i;

    pthread_mutex_init(&sys->mutex, NULL);
    return 0;
}

Record* createRecord() {
    Record* rec = malloc(sizeof(Record));
    if (!rec) return NULL; // Memory allocation failure

    rec->value = rand() % 100;
    rec->status = 'N';
    rec->str = calloc(1, sizeof(char));
    if (!rec->str) {
        free(rec);
        return NULL; // Memory allocation failure
    }

    return rec;
}

Node* createNode(Record* data) {
    Node* node = malloc(sizeof(Node));
    if (!node) return NULL; // Memory allocation failure

    node->data = *data;
    node->next = NULL;
    return node;
}

int addRecord(struct System* sys, int key, const char* str) {
    pthread_mutex_lock(&sys->mutex);

    Record* rec = createRecord();
    if (!rec) {
        pthread_mutex_unlock(&sys->mutex);
        return -1; // Memory allocation failure
    }

    strncpy(rec->str, str, sizeof(rec->str));
    Node** nodePtr = &sys->records[key];
    Node* node = createNode(rec);
    if (!node) {
        free(rec->str);
        free(rec);
        pthread_mutex_unlock(&sys->mutex);
        return -1; // Memory allocation failure
    }

    Node* temp = *nodePtr;
    *nodePtr = node;
    while (temp != NULL) {
        node = temp;
        temp = temp->next;
        node->next = nodePtr;
        *nodePtr = node;
    }

    pthread_mutex_unlock(&sys->mutex);
    return 0;
}

// Implement search, remove, and other operations here...

void freeRecord(Record* rec) {
    free(rec->str);
    free(rec);
}

void freeNode(Node* node) {
    freeRecord(&node->data);
    free(node);
}

void garbageCollect(struct System* sys) {
    pthread_mutex_lock(&sys->mutex);

    Node* temp = NULL;
    Node* current = sys->cacheHead;
    while (current != NULL) {
        temp = current;
        current = current->next;
        freeNode(temp);
    }

    sys->cacheCount = 0;
    sys->cacheHead = NULL;

    pthread_mutex_unlock(&sys->mutex);
}

void periodicallyGarbageCollect(struct System* sys, time_t interval) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    while (1) {
        clock_gettime(CLOCK_REALTIME, &ts);
        if ((ts.tv_sec - lastCollectTime) >= interval) {
            garbageCollect(sys);
            lastCollectTime = ts.tv_sec;
        }
        sleep(1);
    }
}
```

