    char* str;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

void push(Record record) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        perror("Memory allocation failure");
        return;
    }
    new_node->record = record;
    new_node->next = head;
    pthread_mutex_lock(&list_mutex);
    head = new_node;
    pthread_mutex_unlock(&list_mutex);
}

Record* pop() {
    Record* result = NULL;
    if (head) {
        result = &head->record;
        Node* temp = head;
        pthread_mutex_lock(&list_mutex);
        head = head->next;
        free(temp);
        pthread_mutex_unlock(&list_mutex);
    }
    return result;
}

void* worker(void* arg) {
    while (true) {
        Record* record = pop();
        // Process the record in a batch
