        return EXIT_FAILURE;
    }
    for (int i = 0; i < range_min; ++i) {
        offsets[i] = i * 10;
    }

    int* keys = calloc(range_max - range_min + 1, sizeof(int));
    if (!keys) {
        perror("Memory allocation failure");
        free(offsets);
        return EXIT_FAILURE;
    }
    for (int i = range_min; i < range_max + 1; ++i) {
        keys[i - range_min] = i;
    }

    pthread_t worker_id;
    pthread_create(&worker_id, NULL, worker, NULL);

    int num;
    while (read_and_validate(&num, 10, 50)) { // Validate and read integers from standard input
        Record record = { .value = num, .status = 'N', .str = NULL };
        push(record);
    }

    pthread_join(worker_id, NULL);

    free(offsets);
    free(keys);
    return EXIT_SUCCESS;
}
