```cpp
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <sys/mman.h>
#include <semaphore.h>

typedef struct Record {
    int key;
} Record;

int batch_size = 10000;
int max_range = 1000000;
double log_frequency = 0.01; // Logging frequency as a decimal (e.g., 0.01 means once per 100 iterations)
sem_t memory_threshold_sem, system_stability_sem;
extern void logMemoryUsage(size_t used_memory);

void* processDataset(void* arg) {
    pthread_t self = pthread_self();
    Record* records = (Record*) malloc(batch_size * sizeof(Record));
    long* offsets = (long*) malloc((batch_size + 1) * sizeof(long));
    int* keys = (int*) malloc(batch_size * sizeof(int));

    for (int i = 0; i < batch_size; ++i) {
        keys[i] = rand() % max_range;
    }

    offsets[0] = 0;
    sem_wait(&memory_threshold_sem); // Wait before allocating memory to monitor system resources

    for (int i = 0; i < batch_size; ++i) {
        records[i].key = keys[i];
        offsets[i + 1] = offsets[i] + (keys[i] > offsets[i]) ? 1 : 0;
    }

    sem_post(&system_stability_sem); // Notify system is ready to handle more memory allocation requests

    size_t used_memory = sizeof(Record) * batch_size + sizeof(long) * (batch_size + 1);
    logMemoryUsage(used_memory);

    int iterations = 0;
    while (iterations < batch_size) {
        if ((iterations % (int)(batch_size * log_frequency)) == 0) {
            printf("Thread[%lu] Iteration: %d, Key: %d\n", self, iterations, keys[iterations]);
        }
        ++iterations;
    }

    free(records);
    free(offsets);
    free(keys);

    return NULL;
}

void logMemoryUsage(size_t used_memory) {
    sem_wait(&system_stability_sem); // Wait before logging to monitor system resources

    static double last_log = 0.0;
    if (used_memory - last_log >= 1024 * 1024 || std::chrono::steady_clock::now().time_since_epoch().count() > std::chrono::seconds(10)) {
        printf("Memory usage: %.2f MB\n", used_memory / (1024.0 * 1024.0));
        last_log = used_memory;
    }

    sem_post(&memory_threshold_sem); // Notify system is ready to handle more memory allocation requests
}
