typedef struct Record {
    long offset;
    int key;
    void* metadata;
    size_t size;
    struct Record *next;
} Record;

Record* create_record(long offset, int key, void* metadata) {
    Record* new_record = (Record*) malloc(sizeof(Record));
    new_record->offset = offset;
    new_record->key = key;
    new_record->metadata = metadata;
    new_record->size = sizeof(long) + sizeof(int) + sizeof(void*); // size of fields
    if (metadata != NULL) {
        new_record->size += *((size_t*)metadata);
    }
    new_record->next = NULL;
    return new_record;
}

Record* dynamic_list_init(size_t num_records, long min_offset, long max_offset, int min_key, int max_key, size_t metadata_size) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    Record* head = NULL;
    Record* current = NULL;
    Record* new_record = NULL;
    for (size_t i = 0; i < num_records; ++i) {
        pthread_mutex_lock(&mutex);
        if (head == NULL) {
            head = current = create_record(min_offset + rand() % (max_offset - min_offset), min_key + rand() % (max_key - min_key), &metadata_size);
        } else {
            new_record = create_record(min_offset + rand() % (max_offset - min_offset), min_key + rand() % (max_key - min_key), &metadata_size);
            current->next = new_record;
            current = new_record;
        }
        pthread_mutex_unlock(&mutex);
    }

    // Implement a dynamic resizing mechanism here by calculating the total size of records and reallocating memory if needed

    return head;
}

void cleanup(Record* head) {
    Record *current, *next;
    for (current = head; current != NULL; current = next) {
        next = current->next;
        free(current);
    }
}
