#include <log_system.h> // External logging system header

typedef struct record {
    int64_t offset;
    int key;
    double value;
} Record;

#define THRESHOLD (100ULL * 1024 * 1024) // Set your own threshold in bytes

Record* create_dataset(size_t size) {
    if (!size) return NULL;

    size_t block_size = alignof(Record) + sizeof(Record);
    size_t total_size = size * block_size;

    // Check memory threshold before allocation
    if (total_size > THRESHOLD) {
        log_memory_error("Exceeded memory limit: %" PRIu64 " bytes requested", total_size);
        return NULL;
    }

    Record* data = mmap(NULL, total_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    if (data == MAP_FAILED) {
        perror("Error allocating memory");
        return NULL;
    }

    // Ensure proper alignment and padding for efficient access
    size_t i;
    for (i = total_size - block_size + 1; i < total_size; ++i) data[i] = {};

    return data;
}

void destroy_dataset(Record* data, size_t size) {
    if (!data || !size) return;

    munmap((void*)data, size * alignof(Record) + sizeof(Record) * size);
}
