class DynamicArray {
public:
    void insert(const std::string& data, int value) {
        if (!allocate()) return;

        Entry* entry = &dataArr_[index_];
        std::memcpy(entry->buffer, data.c_str(), data.length());
        entry->value = value;
        entry->timestamp = boost::posix_time::second_clock::local_time();
        index_++;
    }

private:
    bool allocate() {
        if (index_ == capacity_) {
            std::unique_ptr<Entry[]> newArr(new Entry[capacity_ * 2]);
            std::memcpy(newArr.get(), dataArr_.get(), index_ * sizeof(Entry));
            dataArr_ = std::move(newArr);
            capacity_ *= 2;
