Record popRecord(PoolNode **pool) {
    PoolNode *current = *pool;
    if (!current->next) return (Record){0};

    PoolNode *temp = current->next;
    Record record = temp->record;
    current->next = temp->next;

    free(temp);
    return record;
}

void pushRecord(PoolNode **pool, Record record) {
    PoolNode *current = *pool;
    while (current->next) {
        current = current->next;
    }
    current->next = malloc(sizeof(PoolNode));
    if (!current->next) return;

    current->next->record = record;
    current->next->next = NULL;
}

