// Custom allocator for efficient memory management
class MemPool {
public:
    static std::vector<char> pool;

    static void* allocate(size_t size, std::nothrow_t) {
        if (pool.empty()) {
            pool.resize(1024); // Reserve initial space for faster allocation
        }
        auto it = pool.begin();
        if (it != pool.end() && size <= std::distance(it, pool.end())) {
            auto data = it;
            pool.erase(it);
            return data;
        }
        return std::malloc(size);
    }

    static void deallocate(void* p, size_t) noexcept {
        if (p && pool.size() < 1024) {
            pool.push_back(*static_cast<char*>(p));
        } else {
            std::free(p);
        }
    }
};
std::vector<char> MemPool::pool;

