class DLinkedListNode {
public:
    DLinkedListNode* prev, *next;
    Event event;
};

class DLinkedList {
public:
    DLinkedList() : head(new DLinkedListNode()), tail(head) { head->prev = head; }

    ~DLinkedList() { clear(); }

    void push_back(const Event& event) {
        auto node = new DLinkedListNode{};
        node->event = event;
        node->next = head->next;
        node->prev = head;
        head->next->prev = node;
        head->next = node;
    }

    void remove(const Event& event) {
        auto current = head->next;
        while (current != head && current->event.id == event.id) {
            DLinkedListNode* temp = current;
            current = current->next;
            delete temp;
            --size;
        }
    }

    Event& find(const std::string& id) {
        auto current = head->next;
        while (current != head) {
            if (current->event.id == id)
                return current->event;
            current = current->next;
        }
        throw std::out_of_range("Event not found");
    }

    size_t size = 0;

private:
    DLinkedListNode* head, *tail;
};

class RLinkedListNode {
public:
    RLinkedListNode* next, *prev;
    Record record;
};

class RLinkedList {
public:
    RLinkedList() : head(new RLinkedListNode()), tail(head) { head->next = head; }

    ~RLinkedList() { clear(); }

    void push_back(const Record& record) {
        auto node = new RLinkedListNode{};
        std::copy(record.str.get(), record.str.get() + record.str->size(), node.record.str.getData());
        node->record = record;
        node->next = head->next;
        node->prev = head;
        head->next->prev = node;
        head->next = node;
    }

    void remove(const Record& record) {
        auto current = head->next;
        while (current != head && current->record.str.get() == record.str.get()) {
            RLinkedListNode* temp = current;
            current = current->next;
            delete temp;
            --size;
        }
    }

    Record& find(const char* id) {
        auto current = head->next;
        while (current != head) {
            if (strcmp(current->record.str.get(), id) == 0)
                return current->record;
            current = current->next;
        }
        throw std::out_of_range("Record not found");
    }

    size_t size = 0;

private:
    RLinkedListNode* head, *tail;
};

