public class NetworkConfigManager {
    private static final int MAX_SIZE = 1000;
    private static final long BASE = 10000;
    private Map<String, Record> configMap;
    private native long optimizeAndSynchronizeNetworkConfiguration(long[] networkSettings);

    public NetworkConfigManager() {
        this.configMap = new ConcurrentHashMap<>(MAX_SIZE);
    }

    public void addRecord(String filename, long offset, int key) {
        Record record = new Record(offset, key);
        String hashedFilename = hash(filename);
        while (configMap.get(hashedFilename + "-" + configMap.size()) != null) {
            configMap.put(hashedFilename + "-" + ++configMap.size(), record);
        }
        configMap.put(hashedFilename + "-" + configMap.size(), record);
    }

    public Record getRecord(String filename) {
        String hashedFilename = hash(filename);
        for (int i : configMap.keySet()) {
            if (configMap.get(hashedFilename + "-" + i).getFileName().equals(filename)) {
                return configMap.get(hashedFilename + "-" + i);
            }
        }
        return null;
    }

    private String hash(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] messageDigest = md.digest(input.getBytes("UTF-8"));
            BigInteger no = new BigInteger(1, messageDigest);
            String hashtext = no.toString(16);
            while (hashtext.length() < 32) {
                hashtext = "0" + hashtext;
            }
            return hashtext;
        } catch (UnsupportedEncodingException e) {
            throw new RuntimeException("Hash function failed", e);
        }
    }

    // JNI methods for C library interaction
    private static class NativeMethods {
        static {
            System.loadLibrary("NetworkConfigManager");
        }

        private native long optimizeAndSynchronizeNetworkConfiguration(long[] networkSettings);
    }
}

