    *records = calloc(element_count, sizeof(struct record));

    if (!*offsets || !*records) {
        printf("Memory allocation failed.\n");
        exit(1);
    }

    *elements = malloc(sizeof(Element*) * element_count);
    *events = malloc(sizeof(Event*) * event_count);

    if (!*elements || !*events) {
        printf("Memory allocation failed.\n");
        exit(1);
    }

    for (size_t i = 0; i < element_count; ++i) {
        (*elements)[i] = calloc(1, sizeof(Element));
