#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int count;
    char status;
    char *description;
} Record;

typedef struct Node {
    Record *record;
    struct Node *next;
    int key;
} Node;

Node *head = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void init_lists(size_t capacity) {
    head = malloc(capacity * sizeof(Node));
    if (!head) exit(1);

    for (size_t i = 0; i < capacity; ++i) {
        Node *node = &head[i];
        node->next = NULL;
        node->key = i + 1;
    }
}

Node* create_record(int count, char status, char *description) {
    Record *rec = malloc(sizeof(Record));
    if (!rec) exit(1);

    rec->count = count;
    rec->status = status;
    rec->description = strdup(description);
    return (Node*)rec;
}

void insert_record(int key, Node *record) {
    pthread_mutex_lock(&mutex);
    Node *current = head;

    for (; current && current->key < key; current = current->next);

    if (!current || current->key == key) {
        record->next = current;
        current = record;
    } else {
        Node *next_node = malloc(sizeof(Node));
        if (!next_node) exit(1);

        next_node->record = record;
        next_node->next = current;
    }

    pthread_mutex_unlock(&mutex);
}

Node* find_record(int key) {
    Node *current = head;
    for (; current && current->key < key; current = current->next);

    return current ? current->key == key ? current : NULL : NULL;
}

void remove_record(int key) {
    pthread_mutex_lock(&mutex);
    Node *current = head, *prev = NULL;

    for (; current && current->key < key; prev = current, current = current->next);

    if (!current || current->key != key) return;

    if (prev) prev->next = current->next;
    else head = current->next;

    free(current->record);
    free(current);

    pthread_mutex_unlock(&mutex);
}

int compute_average(const char *line, long *offsets, int *keys) {
    int len = strlen(line);
    if (len < 5 || line[len - 1] != ',') return 1;

    long num1 = strtol(&line[*offsets], NULL, 10);
    (*offsets) += strlen(to_string(num1)) + 2;
    int key = atoi(&line[*offsets]);
    (*offsets) += strlen(to_string(key)) + 2;
    long num2 = strtol(&line[*offsets], NULL, 10);

    return (long)(num1 + num2) / 2;
}

int process_file(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) return 1;

    size_t capacity = 100000;
    init_lists(capacity);

    long offsets[capacity];
    int keys[capacity];
    char c;

    for (int i = 0; i < capacity; ++i) {
        offsets[i] = keys[i] = -1;
    }

    Record *rec = NULL;
    long total_count = 0;

    while ((c = fgetc(fp)) != EOF) {
        if (c == '\n') {
            if (compute_average(&line[*offsets], offsets, keys) == 1) continue;
            int key = keys[--(*offsets)];
            insert_record(key, rec);
            rec = NULL;
            total_count++;
        } else {
            if (!rec) {
                rec = malloc(sizeof(Record));
                if (!rec) exit(1);
            }
            rec->description = realloc(rec->description, strlen(&line[*offsets]) + 2);
            strcpy(&rec->description[strlen(rec->description)], &c);
        }
    }
    free(rec->description);
    free(rec);

    fclose(fp);

    double avg = (double)total_count ? total_count / (double)head->next->key : 0;

    Node *current = head->next;
    while (current) {
        remove_record(current->key);
        current = current->next;
    }
    free(head);

    return 0;
}
