class ResourceAddress {
public:
    long address;
    std::chrono::steady_clock::time_point lastUsed;

    ResourceAddress(long addr) : address(addr), lastUsed(std::chrono::steady_clock::now()) {}
};

class Task {
public:
    enum class UrgencyLevel { LOW, MEDIUM, HIGH, CRITICAL };

    std::string name;
    UrgencyLevel urgency;

    Task(const std::string& n, UrgencyLevel u) : name(n), urgency(u) {}
};

class ResourceScheduler {
private:
    static constexpr long maxResources = 100000; // Maximum resource limit
    long resources{maxResources}; // Available resources
    long minThreshold{(resources * 90) / 100}; // Minimum resource threshold
    std::vector<ResourceAddress> resourceOffsets;
    std::priority_queue<std::shared_ptr<Task>> tasksQueue;
    std::unordered_map<long, int64_t> availableResourcesCache; // Cache for available resources
    std::deque<std::shared_ptr<Task>> pendingTasks; // Tasks to be displayed when ToString() is called
    long lastResourceUpdate{0};

public:
    ResourceScheduler(long resourceQuantity = 0) : resources(resourceQuantity ? resourceQuantity : maxResources / 10) {
        std::transform(std::begin(resourceOffsets), std::end(resourceOffsets), resourceOffsets.begin(), [](ResourceAddress addr) { return ResourceAddress(addr.address + resourceQuantity); });
    }

    void RequestResource(long quantity) {
        long requestedResources = std::min<long>(resources, quantity);
        if (requestedResources > 0) {
            resources -= requestedResources;
            for (auto& addr : resourceOffsets)
                addr.lastUsed = std::chrono::steady_clock::now();
        }
    }

    void ReleaseResource(long quantity) {
        if (quantity > resources)
            quantity = resources;
        resources += quantity;
        if (resources > minThreshold)
            resources = minThreshold;
    }

    long GetAvailableResources() const {
        if (auto it = availableResourcesCache.find(std::chrono::steady_clock::now().time_since_epoch().count()); it != availableResourcesCache.end())
            return it->second;
        auto available = resources - std::accumulate(resourceOffsets.cbegin(), resourceOffsets.cend(), 0, [](long a, const ResourceAddress& b) { return a + (b.address >= resources ? 0 : 1); });
        availableResourcesCache[std::chrono::steady_clock::now().time_since_epoch().count()] = available;
        return available;
    }

    void ScheduleTask(const std::shared_ptr<Task>& task) {
        tasksQueue.push(task);
    }

    void ToString() const {
