            if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;
            if (entry->d_type == DT_DIR) { // Recurse for directories
                if (chdir(path) != 0) {
                    syslog(LOG_ERR, "Failed to change directory to %s", path);
                    return 1;
                }
                process_directory(args.delimiter, args.filter_regex);
                if (chdir("..") != 0) {
                    syslog(LOG_ERR, "Failed to change back to parent directory.");
                    return 1;
                }
            } else { // Process a file
                Args thread_args = args;
                strcpy(thread_args.input, path);
                pthread_create(&threads[num_threads++], NULL, count_lines, &thread_args);
            }
        }
        closedir(dir);
    } else { // Process stdin
        Args args = args;
        pthread_create(&threads[num_threads++], NULL, count_lines, &args);
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
```

