void insert_record(Node** head, Record data) {
    Node* new_node = create_node(data);
    if (*head == NULL) {
        *head = new_node;
    } else {
        Node* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
}

Record find_record(Node* head, int key) {
    Record found_record = {0, '\0', NULL, 0, -1};
    Node* current = head;
    while (current != NULL) {
        if (current->data.key == key) {
            found_record = current->data;
            break;
        }
        current = current->next;
    }
    return found_record;
}

void remove_record(Node** head, int key) {
    if (*head == NULL) {
        return;
    }
    if ((*head)->data.key == key) {
        Node* temp = *head;
        *head = (*head)->next;
        free(temp->data.description);
        free(temp);
        return;
    }
    Node* current = *head;
    while (current->next != NULL && (current->next->data.key != key)) {
        current = current->next;
    }
    if (current->next == NULL) {
        return;
    }
    Node* temp = current->next;
    current->next = current->next->next;
    free(temp->data.description);
    free(temp);
}

