#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#define MAX_BINARY_SIZE 1024

typedef struct {
    char* data;
    size_t length;
    int timestamp;
} Object;

typedef struct Node {
    Object obj;
    struct Node* next;
} Node;

Node* create_node(const char* data, size_t length, int timestamp) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;

    new_node->obj.data = malloc(length);
    if (!new_node->obj.data) {
        free(new_node);
        return NULL;
    }
    memcpy(new_node->obj.data, data, length);
    new_node->obj.length = length;
    new_node->obj.timestamp = timestamp;
    new_node->next = NULL;

    return new_node;
}

void delete_node(Node** head, Node* node) {
    if (*head == node) *head = node->next;
    else {
        Node* current = *head;
        while (current && current->next != node) current = current->next;
        if (current) current->next = node->next;
        else printf("Node not found\n");
    }

    free(node->obj.data);
    free(node);
}

void merge_nodes(Node** head1, Node* head2) {
    if (!*head1) *head1 = head2;
    else {
        Node* current = *head1;
        while (current->next) current = current->next;
        current->next = head2;
    }
}

void filter_list(Node** head, int start_timestamp, int end_timestamp) {
    Node* current = *head;
    Node* temp_head = NULL;
    Node* temp = NULL;

    while (current) {
        if (current->obj.timestamp >= start_timestamp && current->obj.timestamp <= end_timestamp) {
            if (!temp_head) temp_head = temp = current;
            else {
                temp->next = current;
                temp = current;
            }
        }
        current = current->next;
    }

    *head = temp_head;
}
