        if (sscanf(line, "%d", &fields) != 1) break;
        for (int i = 0; i < fields; ++i) {
            int value;
            if (sscanf(strchr(line, ' ') + 1, "%d", &value) != 1) continue;
            ((*record)->values)[(*offsets)++] = value;
