                if (current_record) destroy_record(current_record);
                current_record = create_record(offsets[i]);
            }
            read_record(file, &current_record, offsets + i, keys_count + i);
        }
        // Perform average calculation on last two fields of each record
        // ...
    }
    if (current_record) destroy_record(current_record);
}

