typedef struct Event {
    time_t timestamp;
    char ip[256];
    enum ProtocolType { TCP, UDP, ICMP } protocol;
    size_t payload_size;
    char* payload;
    char* error;
    pthread_mutex_t mutex;
} Event;

typedef struct HashNode {
    Event event;
    size_t hash;
    struct HashNode *next;
} HashNode;

typedef struct HashTable {
    size_t size;
    HashNode** nodes;
    pthread_mutex_t mutex;
} HashTable;

HashTable* create_hash_table(size_t size) {
    HashTable *table = malloc(sizeof(HashTable));
    table->size = size;
    table->nodes = calloc(size, sizeof(HashNode*));
    table->mutex = PTHREAD_MUTEX_INITIALIZER;
    return table;
}

Event* create_event() {
    Event *event = malloc(sizeof(Event));
    event->payload = malloc(RANDOM_PAYLOAD_SIZE);
    event->error = malloc(MAX_ERROR_LENGTH);
    memset(event->payload, 0, RANDOM_PAYLOAD_SIZE);
    memset(event->error, 0, MAX_ERROR_LENGTH);
    pthread_mutex_init(&event->mutex, NULL);
    return event;
}

void insert_event(HashTable *table, Event *event) {
    size_t index = event->timestamp % table->size;
    pthread_mutex_lock(&table->mutex);
    HashNode* node = table->nodes[index];
    if (!node) {
        table->nodes[index] = malloc(sizeof(HashNode));
        node = table->nodes[index];
        node->event = *event;
        node->hash = event->timestamp % table->size;
        node->next = NULL;
    } else {
        HashNode* current = node;
        while (current != NULL) {
            if (current->event.timestamp == event->timestamp) {
                free(event);
                pthread_mutex_unlock(&table->mutex);
                break;
            }
            current = current->next;
        }
        if (!current) {
            node->next = malloc(sizeof(HashNode));
            current = node->next;
            current->event = *event;
            current->hash = event->timestamp % table->size;
            current->next = NULL;
        }
    }
    pthread_mutex_unlock(&table->table->mutex);
}

