#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdbool.h>
#include <inttypes.h>

typedef struct record {
    int64_t offset;
    int key;
    double precision;
} record;

struct cache {
    size_t size;
    size_t capacity;
    record *data;
    size_t mru;
};

struct cache cache_init(size_t initial_capacity) {
    if (initial_capacity > 10000)
        initial_capacity = 10000;
    struct cache c = {.capacity = initial_capacity, .data = calloc(initial_capacity, sizeof(record))};
    c.size = 0;
    c.mru = -1;
    return c;
}

struct cache cache_grow(struct cache *c) {
    if (c->size == c->capacity) {
        c->capacity *= 2;
        c->data = realloc(c->data, c->capacity * sizeof(record));
    }
    return *c;
}

record* mru_record(struct cache *c) {
    if (c->size == 0 || c->mru < 0)
        return NULL;
    record *r = &c->data[c->mru];
    return r;
}

int64_t unique_offset(struct cache *c, size_t start, size_t end) {
    for (size_t i = start; i < c->size; ++i) {
        if (c->data[i].offset >= start && c->data[i].offset < end)
            return start + rand() % (end - start);
    }
    return start + rand() % (end - start);
}

struct record init_record(int64_t offset, int key, double precision) {
    struct record r = {.offset = offset, .key = key, .precision = precision};
    return r;
}

void insert_record(struct cache *c, const struct record *r) {
    while (true) {
        r->offset = unique_offset(c, 0, 10000);
        size_t i = 0;
        for (; i < c->size && c->data[i].offset != r->offset; ++i);
        if (i == c->size) {
            c = &cache_grow(c);
            memcpy(&c->data[c->size], r, sizeof(record));
            c->size++;
            break;
        }
    }
    if (c->mru != SIZE_MAX && c->data[c->mru].offset > r->offset)
        c->mru = (int64_t)SIZE_MAX;
    else if (c->mru != -1)
        c->mru = (int64_t)(c->mru % c->size);
    c->mru = (int64_t)(&c->data[c->mru] - c->data);
}

struct record *lookup_record(struct cache *c, int key) {
    for (size_t i = 0; i < c->size; ++i) {
        if (c->data[i].key == key)
            return &c->data[i];
    }
