    struct stat st;
    if (stat(user, &st) == -1) {
        app->logError("Unable to stat user file");
        sem_destroy(&readLock);
        SSL_CTX_free(ctx);
        EVP_PKEY_free(pkey);
        return;
    }

    unsigned char buffer[4096];
    SHA256_Init(&context);
    off_t offset = 0;
    size_t numRead;

    while ((numRead = read(user, buffer, sizeof(buffer))) > 0) {
        SHA256_Update(&context, buffer, numRead);
        offset += numRead;
    }

    SHA256_Final(hash, &context);

