using System;
using System.Collections.Concurrent;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;
using System.Diagnostics;
using Microsoft.Extensions.Logging;

public class AsyncNetworkService
{
    private readonly HttpClient _httpClient;
    private readonly string _baseUrl;
    private readonly int _maxConcurrentRequests;
    private readonly RetrySettings _retrySettings;
    private readonly ILogger<AsyncNetworkService> _logger;
    private SemaphoreSlim _semaphore;
    private ConcurrentQueue<RequestParameter> _requestsQueue;
    private CancellationTokenSource _cancellationTokenSource;

    public AsyncNetworkService(HttpClient httpClient, string baseUrl, int maxConcurrentRequests, RetrySettings retrySettings, ILogger<AsyncNetworkService> logger)
    {
        _httpClient = httpClient;
        _baseUrl = baseUrl;
        _maxConcurrentRequests = maxConcurrentRequests;
        _retrySettings = retrySettings;
        _logger = logger;
        _semaphore = new SemaphoreSlim(_maxConcurrentRequests);
        _requestsQueue = new ConcurrentQueue<RequestParameter>();
        _cancellationTokenSource = new CancellationTokenSource();
    }

    public void AddRequest(RequestParameter request)
    {
        _requestsQueue.Enqueue(request);
        _semaphore.Release();
    }

    public async Task ProcessRequestsAsync()
    {
        var stopWatch = Stopwatch.StartNew();

        var loggerSettings = new LoggerFactory().CreateLogger<ProcessRequestsAsync>();

        while (_cancellationTokenSource.IsCancellationRequested == false)
        {
            await _semaphore.WaitAsync(_cancellationTokenSource.Token);

            if (_requestsQueue.TryDequeue(out var request))
            {
                try
                {
                    var stopWatchRequest = Stopwatch.StartNew();

                    HttpResponseMessage response;
                    var requestUri = new Uri($"{_baseUrl}{request.Uri}");

                    loggerSettings.LogInformation($"Request started: {requestUri}");

                    for (var attempt = 0; attempt <= _retrySettings.MaxRetries; attempt++)
                    {
                        try
                        {
                            response = await _httpClient.SendAsync(request.BuildHttpRequestMessage(), HttpCompletionOption.ResponseHeadersRead);
                        }
                        catch (Exception ex)
                        {
                            if (attempt >= _retrySettings.MaxRetries)
                            {
                                throw new Exception($"Failed to process request after {_retrySettings.MaxRetries} attempts", ex);
                            }

                            await Task.Delay(_retrySettings.GetDelay(attempt), _cancellationTokenSource.Token);
                        }

                        if (response.IsSuccessStatusCode)
                        {
                            request.HandleResponse(response);
                            loggerSettings.LogInformation($"Request success: {requestUri}");
                            break;
                        }
                        else
                        {
                            _logger.LogError($"Request failed: {requestUri}, status code: {response.StatusCode}, message: {response.ReasonPhrase}");
                        }
                    }

                    stopWatchRequest.Stop();

                    loggerSettings.LogInformation($"Request duration: {stopWatchRequest.ElapsedMilliseconds} ms");
                }
                catch (Exception ex)
                {
                    _logger.LogError($"Failed to process request: {request.Uri}", ex);
                }
            }
        }

        stopWatch.Stop();
        _logger.LogInformation($"ProcessRequestsAsync completed in {stopWatch.ElapsedMilliseconds} ms");
    }

    public void Dispose()
    {
        _cancellationTokenSource?.Dispose();
    }
}

public class RequestParameter
{
    protected HttpMethod _method;
    protected Uri _uri;
    protected Func<HttpRequestMessage> _requestBuilder;
