using System;
using System.Collections.Generic;
using System.IO;
using System.Numerics;
using System.Threading.Tasks;
using UnityAtoms;
using UnityEngine;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
using static UnityEngine.Application;
using static UnityEngine.Screen;

public class GameSettingsLoader : MonoBehaviour
{
    public PhysicsEngine physicsEngine;
    public Transform playerTransform;
    public Material customShaderMaterial;

    private Dictionary<string, object> _settings;

    private void Awake()
    {
        LoadSettingsAsync().Forget();
    }

    private async Task LoadSettingsAsync()
    {
        string configFilePath = Path.Combine(dataPath, "config.json");

        try
        {
            using StreamReader reader = new StreamReader(configFilePath);
            var json = await reader.ReadToEndAsync();
            _settings = JsonConvert.DeserializeObject<Dictionary<string, object>>(json);

            InitializeGameSettings(_settings);
        }
        catch (Exception ex)
        {
            Debug.LogError($"Failed to load settings: {ex.Message}");
        }
    }

    private void InitializeGameSettings(Dictionary<string, object> settings)
    {
        int screenWidth = Screen.currentResolution.x;
        int screenHeight = Screen.currentResolution.y;

        SetDisplayResolution(Mathf.Max((float)screenWidth / 2, 800f), Mathf.Max((float)screenHeight / 2, 600f));

        var gameSettings = settings["gameSettings"] as JObject;

        var playerSettings = gameSettings["playerSettings"] as JObject;
        playerTransform.localScale = new Vector3((float)playerSettings["scale"], (float)playerSettings["scale"], 1);
        playerTransform.position = new Vector3(0, 0, 0);

        var physicsSettings = gameSettings["physicsSettings"] as JObject;
        physicsEngine.Setup(
            (float)physicsSettings["gravity"],
            (Vector2)physicsSettings["wind"],
            (float)physicsSettings["elasticity"]);

        var shaderSettings = gameSettings["shaderSettings"] as JObject;
        customShaderMaterial = Resources.Load<Material>(shaderSettings["name"]);
    }

    private void SetDisplayResolution(float width, float height)
    {
        var aspectRatio = (float)Screen.currentResolution.width / Screen.currentResolution.height;
        height = width / aspectRatio;
        SetResolution(Mathf.RoundToInt(width), Mathf.RoundToInt(height));
    }
}
```

