        $this->db = $db;
        $this->redis = $rateLimiter = $redis;
        $this->encryptionLib = $encryptionLib;
        $this->lock = new Lock($redis);
    }

    public function processUserRequests($payload) {
        if (!$this->lock->acquire()) return ['error' => 'Too many concurrent requests, please try again later.'];

        $userData = [
            'name' => $payload['name'],
            'email' => $payload['email'],
            'password' => $this->encryptionLib->encrypt($payload['password']),
            'preferences' => json_encode($payload['preferences'])
        ];

        $subAction = $payload['sub_action'];
        $id = isset($payload['id']) ? (int)$payload['id'] : null;

        $this->validateUserData($userData);
        $this->rateLimitCheck();

        try {
            $this->db->beginTransaction();

            if (!$id) {
                // Create new user
                $userId = $this->createUser($userData);
            } else {
                switch ($subAction) {
                    case 'update':
                        $this->updateUser($userId, $userData);
                        break;
                    case 'delete':
                        $this->deleteUser($userId);
                        break;
                    default:
                        // Handle unexpected sub_action
                }
            }

            $this->db->commit();
