class DataAggregator {
  constructor(compressionAlgorithms = ['zlib', 'brotli'], maxMemoryUsage, logLevel, bufferOnInterruption) {
    this.compressionAlgorithms = compressionAlgorithms;
    this.maxMemoryUsage = maxMemoryUsage;
    this.logLevel = logLevel;
    this.bufferOnInterruption = bufferOnInterruption;
    this.currentDataSize = 0;
    this.aggregatedDataBuffer = Buffer.alloc(0);
    this.compressedDataBuffer = Buffer.alloc(0);
    this.threadPool = new WorkerThreadPool(); // Assuming you have a WorkerThreadPool library for handling concurrent access
  }

  addChunk(chunk) {
    if (this.isValidRange(chunk)) {
      this.currentDataSize += chunk.length;

      const worker = this.threadPool.getWorker();
      worker.postMessage({ action: 'compress', data: chunk });

      if (this.shouldLog()) {
        this.log(`Received chunk of size ${chunk.length}`);
        this.log(`Currently processing ${this.currentDataSize} bytes`);
      }
    } else {
      throw new Error('Invalid range provided');
    }
  }

  processWorkerMessage(message) {
    const { action, data } = message;

    switch (action) {
      case 'compress':
        this.aggregatedDataBuffer = Buffer.concat([this.aggregatedDataBuffer, data]);

        if (this.compressedDataBuffer.length + this.aggregatedDataBuffer.length > this.maxMemoryUsage) {
          this.compressedDataBuffer = this.compressData(this.aggregatedDataBuffer); // Compress the data and update aggregated data buffer accordingly
          this.aggregatedDataBuffer = Buffer.alloc(0);
        } else if (this.shouldLog()) {
          this.log(`Buffering ${data.length} bytes due to memory constraints`);
        }
        break;
      // Add other supported worker messages here, such as 'compressWithLevel' for specifying compression level, etc.
    }
  }

  compressData(buffer) {
    let compressedBuffer = Buffer.alloc(0);

    for (let algorithm of this.compressionAlgorithms) {
      const result = zlib.gzipSync(buffer, { level: 9 }); // Adjust compression level based on user preferences

      if (result.length < buffer.length) {
        compressedBuffer = result;
        break;
      }
    }

    return compressedBuffer;
  }

  shouldLog() {
    return this.logLevel !== 'silent';
  }

  isValidRange(chunk) {
    // Implement a check to ensure the range of data in the chunk is valid and within acceptable bounds
  }

  log(message) {
    if (this.logLevel === 'verbose') {
      console.log(`${new Date().toISOString()} ${message}`);
    } else if (this.logLevel === 'info') {
      console.info(`${message}`);
    }
  }
}
