    Record* record = (Record*) malloc(sizeof(Record));
    if (!record) return NULL;
    record->id = 0;
    record->timestamp = 0;
    record->status = 0;
    record->comments = NULL;
    return record;
}

// Function to dynamically resize the array of records
Record** resize_record_array(Record** records, size_t new_size) {
    Record** new_records = (Record**) realloc(records, new_size * sizeof(Record*));
    if (!new_records) return NULL;
    memset(new_records + sizeof(Record*) * old_size, 0, (new_size - old_size) * sizeof(Record*));
    return new_records;
}

// Function to process a large text file and store records in a dynamic array
int processFileAndStoreRecords(const char* filename, Record*** records, size_t* records_count, size_t max_records) {
    FILE *file = fopen(filename, "r");
    if (!file) return -1; // Error: Could not open file

    size_t buffer_size = 256;
    char* buffer = (char*) malloc(buffer_size);
    if (!buffer) {
        fclose(file);
        return -2; // Error: Out of memory
    }

    size_t lines_read = 0;
    size_t records_processed = 0;

    Record** records_array = *records;

    while ((lines_read = getline(&buffer, &buffer_size, file)) != -1) {
        // Parse the line and create a new record
        Record* record = parse_record(buffer);
        if (!record) continue; // Skip invalid records

        // Check if we need to resize the array of records
        if (records_processed == max_records) {
            records_array = resize_record_array(records_array, max_records * 2);
            if (!records_array) {
                free_record(record);
                fclose(file);
                free(buffer);
                return -3; // Error: Out of memory
            }
        }

        records_array[records_processed++] = record;
    }

    fclose(file);
    free(buffer);

    *records = records_array;
    *records_count = records_processed;

    return 0; // Success
}

