import requests
from collections import defaultdict
import json
import random
import time

def get_weather_data(city_names, api_key):
    data = defaultdict(lambda: {'temperature': None, 'humidity': None})
    for city in city_names:
        url = f'http://api.openweathermap.org/data/2.5/weather?q={city}&appid={api_key}'
        try:
            response = requests.get(url)
            response.raise_for_status()
            weather_data = response.json()
            temperature = weather_data['main']['temp'] - 273.15  # Convert from Kelvin to Celsius
            humidity = weather_data['main']['humidity']
            data[city] = {'temperature': temperature, 'humidity': humidity}
        except Exception as e:
            print(f"Error fetching data for {city}: {e}")
    return data
```

