use std::env;
use std::fs::File;
use std::io::{BufReader, BufWriter, Write};
use std::path::PathBuf;
use std::sync::mpsc::{channel, Sender};
use tokio::task::spawn;
use tokio::sync::{RwLock, Semaphore};
use tokio::fs::File as AsyncFile;
use log::{debug, error, info};
use regex::Regex;

const CSV_DELIMITER: char = ',';

struct Config {
    input_path: PathBuf,
    output_path: PathBuf,
    pattern: Regex,
}

async fn process_log(config: &Config, sender: Sender<String>) {
    let mut reader = BufReader::new(AsyncFile::open(config.input_path).await.unwrap());
    let mut line = String::new();

    loop {
        match reader.read_line(&mut line) {
            Ok(_) => {
                if config.pattern.is_match(&line.trim()) {
                    sender.send(format!("{}\n", line)).unwrap();
                }
                line.clear()
            },
            Err(e) => {
                error!("Error reading log file: {}", e);
                break;
            },
        }
    }
}

async fn write_to_csv(sender: Sender<String>, output_path: PathBuf) {
    let mut writer = BufWriter::new(File::create(output_path).unwrap());

    while let Ok(line) = sender.recv().await {
        writer.write_all(line.as_bytes()).unwrap();
        writer.flush().unwrap();
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error> {
    env_logger::init();

    let args: Vec<String> = env::args().collect();
    if args.len() < 5 {
        eprintln!("Usage: LogProcessor input_path output_path pattern semaphore");
        std::process::exit(1);
    }

    let input_path = PathBuf::from(args[1]);
    let output_path = PathBuf::from(args[2]);
    let pattern = Regex::new(&args[3]).unwrap();
    let semaphore = Semaphore::new(args[4].parse::<usize>().unwrap());

    let (tx, rx) = channel(std::env::current_exe()?.args().len());

    spawn(async move { process_log(&Config { input_path, output_path.clone(), pattern }, tx.clone()) })
        .in_current_span();

    spawn(async move { write_to_csv(tx, output_path) })
        .in_current_span();

    loop {
        semaphore.acquire_owned().await;

        if let Ok(line) = rx.recv().await {
            // process the log line here
        }
    }
}
