using System;
using System.Collections.Concurrent;
using System.Threading;

namespace LogProcessor.Utilities
{
    public class DynamicRangeGenerator
    {
        private readonly SemaphoreSlim _semaphore;
        private readonly ConcurrentDictionary<string, int> _frequency = new();
        private readonly (double min, double max) _range;

        public DynamicRangeGenerator((double min, double max) range, int initialSemaphoreValue = 1)
        {
            _range = range;
            _semaphore = new SemaphoreSlim(initialSemaphoreValue);
        }

        public void GenerateFloatingPoint()
        {
            _semaphore.Wait();

            var rnd = new Random();
            var value = _range.min + (rnd.NextDouble() * (_range.max - _range.min));
            _frequency[$"{value:F6}"]++;

            _semaphore.Release();
        }

        public void GenerateInteger()
        {
            _semaphore.Wait();

            var rnd = new Random();
            var value = (int)(_range.min + (rnd.NextDouble() * (_range.max - _range.min)));
            _frequency[$"{value}"]++;

            _semaphore.Release();
        }

        public void LogFrequency()
        {
            foreach (var item in _frequency)
            {
                Console.WriteLine($"Value: {item.Key}, Frequency: {item.Value}");
            }
        }
    }
}
