const asyncReduce = (array, reducer, initialValue, options) => {
  const { maxParallelism = 4, maxNestingLevel = 5, concurrencyQueue = [] } = options || {};

  let accumulator = initialValue;
  const processItem = async (item, index) => {
    try {
      console.log(`Processing item ${index}:`, typeof item);
      accumulator = await reducer(accumulator, item, index, array);
      concurrencyQueue.shift()();
    } catch (error) {
      console.error(`Error processing item ${index}:`, error);
    }
  };

  const processChunk = async () => {
    if (!array.length || concurrencyQueue.length === maxParallelism) return;

    const chunkSize = Math.min(array.length, maxParallelism);
    const chunk = array.slice(0, chunkSize);
    array.splice(0, chunkSize);

    for (let i = 0; i < chunkSize; i++) {
      concurrencyQueue.push(processItem.bind(null, chunk[i], i));
    }

    await Promise.all(concurrencyQueue);
    if (array.length) processChunk();
  };

  processChunk();
  return accumulator;
};

// Example usage:
const myReducer = (acc, value, index, array) => {
  if (typeof value === 'object' && value !== null && Object.keys(value).length > maxNestingLevel) {
    console.log(`Serialized object with depth greater than ${maxNestingLevel}`);
    return JSON.parse(JSON.stringify(acc));
  }
  return acc + value;
};

const data = [1, 'hello', { a: { b: { c: 3 } } }, null, true, [{ x: 4 }, { y: 5 }]];
