[' ```c
#include <csignal>
#include <ctime>
#include <jansson/jansson.h>
#include <pthread.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    pthread_mutex_t mutex;
    size_t allocated;
    size_t used;
} Arena;

Arena *arena_create(size_t initial_size) {
    Arena *a = (Arena *)malloc(sizeof(Arena));
    a->allocated = initial_size;
    a->used = 0;
    pthread_mutex_init(&a->mutex, NULL);
    return a;
}

void *arena_realloc(void *ptr, size_t new_size) {
    Arena *a = (Arena *)((char *)ptr - offsetof(Arena, allocated));
    void *new_ptr = realloc(a->allocated ? a : ptr, new_size);
    if (new_ptr != NULL) {
        if (!a->allocated) {
            a = (Arena *)new_ptr;
            a->allocated = new_size;
            a->used = 0;
            pthread_mutex_init(&a->mutex, NULL);
        }
    }
    return new_ptr;
}

void *arena_malloc(Arena *a, size_t size) {
    pthread_mutex_lock(&a->mutex);
    void *ptr = a->allocated ? ((char *)a + a->used) : NULL;
    if (!ptr && a->allocated < a->used + size) {
        size_t new_size = (a->allocated == 0) ? size : a->allocated * 2;
        ptr = arena_realloc(a, new_size);
    }
    if (ptr) {
        a->used += size;
    }
    pthread_mutex_unlock(&a->mutex);
    return ptr;
}

void arena_free(Arena *a, void *ptr) {
    pthread_mutex_lock(&a->mutex);
    if (ptr >= a && ptr < ((char *)a + a->used)) {
        memmove(((char *)a + a->used), ptr, a->used - ((char *)ptr - (char *)a));
        a->used -= sizeof(void *);
    }
    pthread_mutex_unlock(&a->mutex);
}

