        public FileProcessor(Config config)
        {
            _config = config;
            _rateLimiter = new SemaphoreSlim(config.MaxFilesPerSecond, config.MaxFilesPerSecond);
        }

        public async Task<IEnumerable<T>> ProcessDirectoryAsync<T>(string directoryPath)
        {
