            var files = Directory.GetFiles(directoryPath, "*.*", SearchOption.AllDirectories)
                .Where(f => _config.SupportedExtensions.Any(ext => Path.GetExtension(f).Equals(ext, StringComparison.OrdinalIgnoreCase)));

            var tasks = files.Select(FileProcessor.CreateTask);

            await Task.WhenAll(tasks);

