import java.io.*;
import java.lang.ClassLoader;
import java.lang.reflect.InvocationTargetException;
import java.util.concurrent.ConcurrentMap;
import java.util.concurrent.LinkedHashMap;
import java.util.concurrent.TimeUnit;
import java.util.logging.Level;
import java.util.logging.Logger;

public class SerializationUtils {
    private static final Logger LOGGER = Logger.getLogger(SerializationUtils.class.getName());
    private static final int MAX_CACHE_SIZE = 1000;
    private static final long CACHE_ACCESS_TIME_MILLIS = TimeUnit.MINUTES.toMillis(5);
    private static final ConcurrentMap<byte[], Object> cache = new LinkedHashMap<>(MAX_CACHE_SIZE, 0.75f, true) {
        private static final long serialVersionUID = -349682471157662313L;

        protected boolean removeEldestEntry(Map.Entry<byte[], Object> eldest) {
            return size() > MAX_CACHE_SIZE;
        }
    };

    public static <T> T deserialize(byte[] data, Class<T> clazz) {
        if (cache.containsKey(data)) {
            LOGGER.log(Level.INFO, "Deserialized from cache: {0}", clazz.getSimpleName());
            return (T) cache.get(data);
        }

        synchronized (this) {
            if (!cache.containsKey(data)) {
                ObjectInputStream ois = null;
                try {
                    ois = new ObjectInputStream(new ByteArrayInputStream(data));
                    T obj = clazz.getDeclaredConstructor().newInstance();
                    ois.defaultReadObject();
                    if (!cache.putIfAbsent(data, obj)) {
                        ois.close();
                        LOGGER.log(Level.INFO, "Cached deserialized object: {0}", clazz.getSimpleName());
                    } else {
                        ois.close();
                    }
                    return obj;
                } catch (InstantiationException | IllegalAccessException | ClassNotFoundException e) {
                    LOGGER.log(Level.SEVERE, "Failed to deserialize object: {0}", clazz.getSimpleName(), e);
                    if (!cache.replace(data, createDefaultInstance(clazz))) {
                        throw new RuntimeException("Cache replacement failed", e);
                    }
                } catch (IOException e) {
                    LOGGER.log(Level.SEVERE, "Failed to deserialize object: {0}", clazz.getSimpleName(), e);
                    if (!cache.replace(data, createDefaultInstance(clazz))) {
                        throw new RuntimeException("Cache replacement failed", e);
                    }
                } finally {
                    if (ois != null) {
                        try {
                            ois.close();
                        } catch (IOException ex) {
                            LOGGER.log(Level.WARNING, "Failed to close ObjectInputStream: {0}", clazz.getSimpleName(), ex);
                        }
                    }
                }
            }
        }
        return cache.get(data);
    }

    private static <T> T createDefaultInstance(Class<T> clazz) {
        try {
            Constructor<?> constructor = clazz.getDeclaredConstructors()[0];
            constructor.setAccessible(true);
            return constructor.newInstance();
        } catch (InstantiationException | IllegalAccessException | InvocationTargetException ex) {
            LOGGER.log(Level.WARNING, "Failed to create default instance of class: {0}", clazz.getName(), ex);
            throw new RuntimeException("Failed to create default instance", ex);
        }
    }
}
