import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedList;
import java.util.Locale;
import java.util.Map;
import java.util.Queue;
import java.util.concurrent.Executors;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;

public class TransactionProcessor {

    private static final int MAX_THREADS = 1000;
    private static final int MEMORY_LIMIT = 100 * (1024 * 1024); // 100MB
    private static final NumberFormat NUMBER_FORMAT = NumberFormat.getNumberInstance();
    static {
        NUMBER_FORMAT.setMaximumIntegerDigits(18);
        NUMBER_FORMAT.setMaximumFractionDigits(2);
    }

    public String processAndGenerateReportFromCSV(String csvFile, long memoryLimit) throws DataProcessingException {
        // Validate CSV file format and create a queue to manage concurrent processing
        ThreadPoolExecutor executor = (ThreadPoolExecutor) Executors.newFixedThreadPool(MAX_THREADS);
        Queue<String> transactionQueue = new LinkedList<>();
        try (BufferedReader br = new BufferedReader(new FileReader(csvFile))) {
            String line;
            while ((line = br.readLine()) != null) {
                transactionQueue.add(line);
            }
        } catch (Exception e) {
            throw new DataProcessingException("Invalid CSV file format", e);
        }

        // Process transactions in parallel and generate summary report
        Map<String, TransactionRecord> transactionMap = new HashMap<>();
        long processedRecords = 0;
        BigDecimal totalAmount = BigDecimal.ZERO;
        while (!transactionQueue.isEmpty() && processedRecords < 1_000_000) { // Adjust the limit based on available resources
            executor.execute(() -> processTransaction(transactionQueue, transactionMap, memoryLimit));
        }
        executor.shutdown();
        try {
            executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
        } catch (InterruptedException e) {
            throw new DataProcessingException("Thread pool termination interrupted", e);
        }

        // Generate summary report and compute SHA-256 hash
        StringBuilder report = new StringBuilder();
        report.append("Transaction Summary:\n");
        report.append("------------------\n");
        for (Map.Entry<String, TransactionRecord> entry : transactionMap.entrySet()) {
            report.append(entry.getValue().toString()).append("\n");
        }
        report.append("Total Transactions: ").append(transactionMap.size()).append("\n");
        report.append("Total Amount: ").append(NUMBER_FORMAT.format(totalAmount)).append("\n");
        report.append("SHA-256 Hash: ");
        try {
            MessageDigest sha256 = MessageDigest.getInstance("SHA-256");
            byte[] hash = sha256.digest((transactionMap.values() + "\n").getBytes(StandardCharsets.UTF_8));
            String hexHash = bytesToHex(hash);
            report.append(hexHash);
        } catch (Exception e) {
            throw new DataProcessingException("Error computing SHA-256 hash", e);
        }
        return report.toString();
    }

    private void processTransaction(Queue<String> transactionQueue, Map<String, TransactionRecord> transactionMap, long memoryLimit) {
        // Extract transaction data and validate business rules
        String line = transactionQueue.poll();
        if (line == null || line.isBlank()) {
            return;
        }
        String[] columns = line.split(",");
        if (columns.length < 4) {
            throw new DataProcessingException("Invalid CSV record format", new IllegalArgumentException());
        }
        String userId = columns[0];
        BigDecimal amount = NUMBER_FORMAT.parse(columns[2]).setScale(2, RoundingMode.HALF_UP);
        if (transactionMap.containsKey(userId)) {
            throw new DataProcessingException("Duplicate user ID found: " + userId);
        }
        Instant timestamp = Instant.ofEpochMilli(Long.parseLong(columns[3]));
        // Store transaction data and update running totals
        transactionMap.put(userId, new TransactionRecord(amount, timestamp));
        totalAmount = totalAmount.add(amount);
    }

    private static String bytesToHex(byte[] hash) {
        StringBuilder hexString = new StringBuilder();
        for (byte b : hash) {
            String hex = Integer.toHexString(0xFF & b);
            if (hex.length == 1) {
                hexString.append('0');
            }
            hexString.append(hex);
        }
        return hexString.toString();
    }
}

class TransactionRecord {
    private final BigDecimal amount;
    private final Instant timestamp;
    private String status = "Pending";

    public TransactionRecord(BigDecimal amount, Instant timestamp) {
        this.amount = amount;
        this.timestamp = timestamp;
    }

    @Override
    public String toString() {
        return "Transaction[ID=" + Thread.currentThread().getId() + ", Amount=" + NUMBER_FORMAT.format(amount) + ", Timestamp=" + timestamp + ", Status=" + status + "]";
    }
}
```

