    pthread_mutex_lock(&buckets[hash_value].lock);

    ListNode *new_node = malloc(sizeof(ListNode));
    memcpy(&new_node->session, &Session{session_id, user_ip, last_activity, is_authenticated}, sizeof(Session));
    new_node->next = buckets[hash_value].head;
    buckets[hash_value].head = new_node;

    pthread_mutex_unlock(&buckets[hash_value].lock);
}

void update_session(const char *session_id, time_t last_activity) {
    size_t hash_value = hash(session_id, strlen(session_id));

    pthread_mutex_lock(&buckets[hash_value].lock);

    ListNode *current = buckets[hash_value].head;
    while (current != NULL) {
        if (strcmp(current->session.session_id, session_id) == 0) {
            current->session.last_activity = last_activity;
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&buckets[hash_value].lock);
}

void remove_expired_sessions() {
    time_t now = time(NULL);
    for (size_t i = 0; i < NUM_BUCKETS; ++i) {
        pthread_mutex_lock(&buckets[i].lock);

        ListNode *current = buckets[i].head;
        ListNode *prev = NULL;

        while (current != NULL) {
            if (difftime(now, current->session.last_activity) > INACTIVITY_TIMEOUT) {
                if (prev == NULL) {
                    buckets[i].head = current->next;
                } else {
                    prev->next = current->next;
                }
                free(current);
            } else {
                prev = current;
            }
            current = prev ? prev->next : buckets[i].head;
        }

        pthread_mutex_unlock(&buckets[i].lock);
    }
}
