    std::cout << "Deallocated: " << size << " bytes\n";
    ::operator delete(ptr);
}

std::mutex mtx;

bool isUnique(int value) {
    std::lock_guard<std::mutex> lock(mtx);
    auto it = std::find(records.begin(), records.end(), value);
    return it == records.end();
}

void initDataArrays(size_t n) {
    offsets.resize(n + 1, 0);
    keys.reserve(n);
    labels.resize(n);
    std::mt19937 gen(std::chrono::high_resolution_clock::now().time_since_epoch().count());
    auto minValue = 1000;
    auto maxValue = 2000;

    records.reserve(n);
    std::uniform_int_distribution<> dis(minValue, maxValue);

    for (size_t i = 0; i < n; ++i) {
        int key = 0;
        while (!isUnique(key)) {
            key = dis(gen);
        }
        keys.push_back(key);
        records.emplace_back(key);
    }

    // Sort and assign labels, offsets, and update keys for efficient lookup
    std::sort(records.begin(), records.end());

    auto it = records.begin();
    size_t labelCounter = 0;
    for (size_t i = 0; i < n; ++i) {
        labels[i] = static_cast<char>('A' + labelCounter);
        offsets[keys[it - records.begin()] + 1] = i + 1;
        it++;
        labelCounter += (it == records.end()) ? 0 : (it->value - it[-1]->value) > 1;
    }
}
