#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    int value;
    char status;
    char* str;
    long offset;
    int key;
    pthread_mutex_t mutex;
} Record;

typedef struct Node {
    Record data;
    struct Node* next;
    pthread_mutex_t node_lock;
} Node;

Node** hash_table;
int capacity = 10000000;
long total_allocated = 0;
pthread_mutex_t log_lock;

void init_log(const char* file) {
    FILE* log_file = fopen(file, "w");
    if (!log_file) {
        perror("Failed to open log file");
    }
}

void log_event(const char* message) {
    pthread_mutex_lock(&log_lock);
    FILE* log_file = fopen("log.txt", "a");
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    } else {
        perror("Failed to open log file");
    }
    pthread_mutex_unlock(&log_lock);
}

long hash(int key) {
    return key % capacity;
}

Node* create_node(Record data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        log_event("Memory allocation failure");
        return NULL;
    }
    new_node->data = data;
    new_node->next = NULL;
    pthread_mutex_init(&new_node->node_lock, NULL);
    return new_node;
}

void insert(int key, Record data) {
    Node** node_ptr = &hash_table[hash(key)];
    Node* current = *node_ptr;
    while (current != NULL) {
        if (current->data.key == key) {
            pthread_mutex_lock(&current->data.mutex);
            current->data = data;
            current->data.offset++;
            pthread_mutex_unlock(&current->data.mutex);
            return;
        }
        current = current->next;
    }

    Node* new_node = create_node(data);
    if (!new_node) {
        log_event("Memory allocation failure");
        return;
    }

    pthread_mutex_lock(&new_node->data.mutex);
    new_node->data.key = key;
    new_node->data.offset = 1;
    new_node->data.status = 'N'; // Not processed
    pthread_mutex_unlock(&new_node->data.mutex);

    pthread_mutex_lock(node_ptr);
    new_node->next = *node_ptr;
    *node_ptr = new_node;
    pthread_mutex_unlock(node_ptr);

    total_allocated++;
}

Record* search(int key) {
    Node** node_ptr = &hash_table[hash(key)];
    Node* current = *node_ptr;
    while (current != NULL) {
        if (current->data.key == key) {
            return &current->data;
        }
        current = current->next;
    }
    return NULL;
}

void delete(int key) {
    Node** node_ptr = &hash_table[hash(key)];
    Node* current = *node_ptr;
    if (current == NULL) {
        return;
    }

    if (current->data.key == key) {
        pthread_mutex_lock(&current->data.mutex);
        total_allocated--;
        Record* data = &current->data;
        *node_ptr = current->next;
        free(current);
        pthread_mutex_unlock(&current->data.mutex);
        return;
    }

    while (current != NULL && current->next != NULL) {
        if (current->next->data.key == key) {
            Node* temp = current->next;
            pthread_mutex_lock(&temp->data.mutex);
            total_allocated--;
            *node_ptr = temp->next;
            free(temp);
            pthread_mutex_unlock(&temp->data.mutex);
            break;
        }
        current = current->next;
    }
}

void process_range(int min_val, int max_val) {
    for (int i = min_val; i <= max_val; ++i) {
        Record* record = search(i);
        if (record != NULL && record->status == 'N') {
            pthread_mutex_lock(&record->mutex);
            record->status = 'P'; // Processed
            // Perform processing logic here
            pthread_mutex_unlock(&record->mutex);
        }
    }
}
