#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct record {
    int value;
} Record;

struct node {
    Record data;
    int key;
    struct node* next;
    struct node* prev;
};

struct manager {
    struct node** offsets;
    int* keys;
    struct node** records;
    size_t capacity;
    size_t current_size;
    size_t max_key;
    pthread_mutex_t mutex;
};

struct manager* create_manager(size_t initial_capacity, size_t memory_limit, size_t max_key) {
    struct manager* manager = malloc(sizeof(struct manager));
    if (!manager) {
        perror("Memory allocation failed");
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->max_key = max_key;
    manager->current_size = 0;
    manager->keys = calloc(initial_capacity, sizeof(int));
    if (!manager->keys) {
        perror("Memory allocation failed");
        free(manager);
        return NULL;
    }

    manager->offsets = malloc(sizeof(struct node*) * initial_capacity);
    if (!manager->offsets) {
        perror("Memory allocation failed");
        free(manager->keys);
        free(manager);
        return NULL;
    }

    manager->records = calloc(initial_capacity, sizeof(struct node*));
    if (!manager->records) {
        perror("Memory allocation failed");
        free(manager->offsets);
        free(manager->keys);
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->mutex, NULL);

    return manager;
}

void destroy_manager(struct manager* manager) {
    if (manager) {
        for (size_t i = 0; i < manager->capacity; ++i) {
            struct node* current = manager->offsets[i];
            while (current != NULL) {
                struct node* temp = current;
                current = current->next;
                free(temp);
            }
        }

        free(manager->keys);
        free(manager->offsets);
        free(manager->records);
        pthread_mutex_destroy(&manager->mutex);
        free(manager);
    }
}

struct node* create_node(int key, Record data) {
    struct node* new_node = malloc(sizeof(struct node));
    if (!new_node) {
        perror("Memory allocation failed");
        return NULL;
    }

    new_node->data = data;
    new_node->key = key;
    new_node->next = NULL;
    new_node->prev = NULL;

    return new_node;
}

bool insert(struct manager* manager, Record data) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->current_size >= manager->capacity) {
        printf("Memory limit exceeded\n");
        pthread_mutex_unlock(&manager->mutex);
        return false;
    }

    int key = rand() % manager->max_key;
    for (size_t i = 0; i < manager->current_size; ++i) {
        if (manager->keys[i] == key) {
            pthread_mutex_unlock(&manager->mutex);
            return false;
        }
    }

    manager->keys[manager->current_size] = key;
    struct node* new_node = create_node(key, data);
    if (!new_node) {
        pthread_mutex_unlock(&manager->mutex);
        return false;
    }

    if (manager->current_size == 0) {
        manager->offsets[0] = new_node;
        manager->records[0] = &new_node->data;
        continue;
    }

    struct node* current = manager->offsets[manager->current_size - 1];
    if (current->key > key) {
        for (size_t i = manager->current_size; i != 0; --i) {
            manager->records[i] = manager->records[i - 1];
            manager->offsets[i] = manager->offsets[i - 1];
        }
        manager->records[0] = &new_node->data;
        manager->offsets[0] = new_node;
    } else {
        while (current->next != NULL && current->next->key < key) {
            current = current->next;
        }
        struct node* temp = new_node;
        temp->prev = current;
        temp->next = current->next;
        if (current->next == NULL) {
            manager->offsets[manager->current_size] = new_node;
        } else {
            current->next->prev = temp;
        }
        current->next = temp;
        temp->prev = current;
    }

    ++manager->current_size;

    pthread_mutex_unlock(&manager->mutex);

    return true;
}

bool delete(struct manager* manager, int key) {
    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->current_size; ++i) {
        if (manager->keys[i] == key) {
            struct node* current = manager->offsets[i];
            if (current->prev != NULL) {
                current->prev->next = current->next;
            } else {
                manager->offsets[0] = current->next;
            }

            if (current->next != NULL) {
                current->next->prev = current->prev;
            } else {
                manager->offsets[manager->current_size - 1] = current->prev;
            }

            free(current);

            --manager->current_size;
            for (size_t j = i; j < manager->current_size; ++j) {
                manager->keys[j] = manager->keys[j + 1];
                manager->records[j] = manager->records[j + 1];
            }

            pthread_mutex_unlock(&manager->mutex);

            return true;
        }
    }

    pthread_mutex_unlock(&manager->mutex);
    return false;
}
```

