    *keys = (int*) malloc(m * sizeof(int));
    if(!*keys) {
        free(*offsets);
        free(*keys);
        return -2;
    }
    // Initialize keys with random values and ensure uniqueness
    for(size_t i=0; i<m; ++i) {
        int key = 1 + (rand() % (m - i));
        size_t j;
        for(j=0; j<i; ++j) {
            if((*keys)[j] == key) break;
        }
        if(j == i) (*keys)[i] = key;
    }

    // Allocate memory for records array and initialize each record with a random value between -100 and 100
    *records = (record*) malloc(p * sizeof(record));
