#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <sys/mman.h>

typedef struct Record {
    int key;
    int value;
    struct Record* next;
} Record;

struct DataStruct {
    long* offsets;
    int* keys;
    Record** records;
    size_t size;
    size_t capacity;
    size_t limit;
    pthread_mutex_t mutex;
};

void init_data_struct(struct DataStruct* ds, size_t limit) {
    ds->limit = limit;
    ds->capacity = 0;
    ds->size = 0;
    ds->offsets = mmap(NULL, sizeof(long), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    ds->keys = calloc(ds->capacity, sizeof(int));
    ds->records = calloc(ds->capacity, sizeof(Record*));
    pthread_mutex_init(&ds->mutex, NULL);
}

void destroy_data_struct(struct DataStruct* ds) {
    for (size_t i = 0; i < ds->capacity; ++i) {
        if (ds->records[i]) free(ds->records[i]);
    }
    free(ds->keys);
    free(ds->records);
    munmap(ds->offsets, sizeof(long));
    pthread_mutex_destroy(&ds->mutex);
}

int get_next_key(struct DataStruct* ds) {
    if (ds->size == ds->capacity) {
        if (expand_data_struct(ds)) return -1; // Return error code on failure
    }

    int key = ds->keys[ds->size];
    for (size_t i = ds->size; i > 0; --i) {
        if (ds->keys[i] == key + 1) {
            ds->keys[i] = key;
            return key + 1;
        }
    }

    // If no suitable key is found, assign a new one within the range.
    for (int k = ds->size + 1; k <= ds->capacity; ++k) {
        if (!ds->keys[k]) {
            ds->keys[k] = key + 1;
            return key + 1;
        }
    }

    // If no suitable key is found even within the specified range, an error has occurred.
    return -1;
}

void insert_record(struct DataStruct* ds, int value) {
    pthread_mutex_lock(&ds->mutex);

    Record* new_rec = malloc(sizeof(Record));
    if (!new_rec) { // Return error code on failure
        pthread_mutex_unlock(&ds->mutex);
        return;
    }

    int key = get_next_key(ds);
    if (key == -1) { // Return error code on failure
        free(new_rec);
        pthread_mutex_unlock(&ds->mutex);
        return;
    }

    new_rec->key = key;
    new_rec->value = value;
    new_rec->next = ds->records[ds->offsets[ds->size]];
    ds->records[ds->offsets[ds->size]] = new_rec;
    ds->offsets[++ds->size] = ds->offsets[ds->size - 1];

    pthread_mutex_unlock(&ds->mutex);
}

Record* find_record(struct DataStruct* ds, int key) {
    Record* cur = ds->records[0];
    size_t offset = 0;

    pthread_mutex_lock(&ds->mutex);
    while (cur && cur->key <= key) {
        if (cur->key == key) {
            Record* res = cur;
            cur = cur->next;
            pthread_mutex_unlock(&ds->mutex);
            return res;
        }
        offset = ds->offsets[++ds->size];
        cur = ds->records[offset];
    }
    pthread_mutex_unlock(&ds->mutex);
    return NULL;
}

void delete_record(struct DataStruct* ds, int key) {
    Record* del_rec = find_record(ds, key);
    if (!del_rec) return; // Exit function on failure

    pthread_mutex_lock(&ds->mutex);
    if (del_rec->next) {
        ds->records[ds->offsets[ds->size - 1]] = del_rec->next;
        ds->offsets[--ds->size] = del_rec->offset;
    } else {
        for (size_t i = ds->size; i > 0; --i) {
            if (!ds->records[ds->offsets[i - 1]]) {
                ds->records[ds->offsets[i - 1]] = NULL;
                break;
            }
        }
    }
    free(del_rec);
    pthread_mutex_unlock(&ds->mutex);
}
