void init_cache(struct cache *cache, size_t capacity) {
    cache->capacity = capacity;
    cache->size = 0;
    cache->records = calloc(capacity, sizeof(struct node*));
}

void free_cache(struct cache *cache) {
    for (size_t i = 0; i < cache->capacity; ++i) {
        if (cache->records[i]) free(cache->records[i]);
    }
    free(cache->records);
}

struct node* find_node(struct cache *cache, int key) {
    size_t hash = key % cache->capacity;
    struct node *current = cache->records[hash];

    while (current != NULL) {
        if (current->data.key == key) return current;
        current = current->next;
    }

    return NULL;
}

