**Python Solution:**

```python
import os
import hashlib
import concurrent.futures

def file_hashes(directory, concurrency=os.cpu_count()):
    hashed = {}
    threshold = 1024 * 1024 * 5
    files = [f"{directory}/{}" for f in os.listdir(directory) if os.path.isfile(f)]
    with concurrent.futures.ThreadPoolExecutor(max_workers=concurrency) as executor:
        futures = {executor.submit(hash_file, file): file for file in files}
        for future in concurrent.futures.as_completed(futures):
            file, hash_obj = future.result()
            if os.path.getsize(file) > threshold:
                continue
            hashed[file] = hash_obj.hexdigest()
    return hashed

def hash_file(file):
    with open(file, 'rb') as f:
        return hashlib.md5(f.read()).cast(bytes)

```
