#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <sys/mman.h>

typedef struct {
    char name[100];
    char email[100];
    struct tm dob;
    int key;
    long offset;
} Record;

struct hash_table {
    int capacity;
    int size;
    Record **data;
    pthread_mutex_t lock;
};

int create_user_profiles(struct hash_table *ht, int n, int min_val, int max_val) {
    ht->capacity = 1024; // initial capacity
    ht->size = 0;
    ht->data = mmap(NULL, sizeof(Record*) * ht->capacity, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0);
    if (ht->data == MAP_FAILED) {
        perror("mmap failed");
        return -1;
    }

    pthread_mutex_init(&ht->lock, NULL);

    for (int i = 0; i < ht->capacity; ++i) {
        ht->data[i] = NULL;
    }

    int success_count = 0;
    srand(time(NULL));

    for (int i = 0; i < n; ++i) {
        Record *record = malloc(sizeof(Record));
        if (!record) {
            perror("malloc failed");
            break;
        }

        memset(record, 0, sizeof(Record));

        strncpy(record->name, "User", sizeof(record->name));
        record->dob = *(localtime(&time(NULL))); // current date and time
        sprintf(record->email, "user%d@example.com", i);

        record->key = min_val + rand() % (max_val - min_val + 1);

        pthread_mutex_lock(&ht->lock);
        int hash = hash(record->email);
        while (ht->data[hash] || ht->data[hash]->key == record->key) {
            ++hash %= ht->capacity;
        }
        ht->data[hash] = record;
        pthread_mutex_unlock(&ht->lock);

        record->offset = i + 1;

        success_count++;
    }

    mprotect(ht->data, sizeof(Record*) * ht->capacity, PROT_READ);
    msync(ht->data, sizeof(Record*) * ht->capacity, MS_SYNC);

    return success_count;
}

int hash(const char *key) {
    uint32_t hash = 5381;
    int c;

    while ((c = *key++)) {
        hash = (hash << 5) + hash + c; /* hash * 33 + c */
    }

    return hash % ht->capacity;
}

