#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    char *key;
    enum { INT, DOUBLE, STRING } type;
    union {
        int i;
        double d;
        char *s;
    } value;
    void *default_value;
} setting;

typedef struct {
    time_t timestamp;
    const setting *setting;
    char action[10];
} log_entry;

typedef struct hash_node {
    size_t key_hash;
    setting setting;
    struct hash_node* next;
} hash_node;

typedef struct {
    size_t capacity, count, threshold;
    hash_node **table;
} hash_map;

void hash_init(hash_map *map, size_t capacity, size_t threshold) {
    map->capacity = capacity;
    map->threshold = threshold;
    map->count = 0;
    map->table = calloc(capacity, sizeof(hash_node*));
}

size_t hash(const char *key, size_t capacity) {
    size_t hash = 0, i;
    for (i = 0; key[i]; ++i) hash = (hash << 5) + hash + key[i];
    return hash % capacity;
}

void hash_insert(hash_map *map, setting *setting) {
    size_t index = hash(setting->key, map->capacity);
    hash_node **head = &map->table[index];
    while (*head && strcmp((*head)->setting.key, setting->key)) head = &(*head)->next;

    if (!*head) {
        *head = malloc(sizeof(hash_node));
        (*head)->key_hash = hash(setting->key, map->capacity);
        (*head)->setting = *setting;
        (*head)->next = NULL;
    } else {
        setting->default_value = (*head)->setting.default_value;
        (*head)->setting = *setting;
    }
}

void log_entry_init(log_entry *entry, const setting *setting, const char *action) {
    entry->timestamp = time(NULL);
    entry->setting = setting;
    strcpy(entry->action, action);
}

void* malloc_or_realloc(void **ptr, size_t old_capacity, size_t new_capacity) {
    if (new_capacity > old_capacity) {
        void *new_ptr = realloc(*ptr, new_capacity * sizeof(**ptr));
        if (!new_ptr) {
            fprintf(stderr, "Out of memory!\n");
            exit(EXIT_FAILURE);
        }
        *ptr = new_ptr;
    }
    return *ptr;
}

int main() {
    // Initialize dynamic structures with given initial capacities and thresholds.
    hash_map settings;
    hash_init(&settings, 10, 5);

    // Predefine settings, populate the settings array, and insert each into the hash table.
    setting predefined_settings[] = {
        {"INT_KEY", INT, {.i = 42}},
        {"DOUBLE_KEY", DOUBLE, {.d = 3.14}},
        {"STRING_KEY", STRING, {.s = strdup("Hello, world!")}},
    };
    size_t i;
    for (i = 0; i < sizeof(predefined_settings) / sizeof(setting); ++i) {
        settings.table[hash(&predefined_settings[i].key, settings.capacity)] = malloc(sizeof(hash_node));
        *settings.table[hash(&predefined_settings[i].key, settings.capacity)] = (hash_node){
            .key_hash = hash(&predefined_settings[i].key, settings.capacity),
            .setting = predefined_settings[i]
        };
    }

    // Generate a linked list of log entries within a specified time range.
    log_entry *log = malloc(10 * sizeof(log_entry));
    for (i = 0; i < 10; ++i) {
        log_entry_init(&log[i], settings.table[hash("INT_KEY", settings.capacity)]->setting, "updated");
        log[i].timestamp += i * 60; // Generated timestamp within a 1-hour range.
    }

    // Simulate actions on the settings randomly, logging each action in the linked list of log entries.
    for (int j = 0; j < 100; ++j) {
        size_t setting_index = rand() % settings.count;
        const setting *setting = settings.table[settings.table[setting_index]->key_hash]->setting;
        if (rand() % 3 == 0) { // Update action with probability 1/3.
            setting->value.i += rand() % 10;
            log_entry *log_entry = malloc(sizeof(log_entry));
            log_entry_init(log_entry, setting, "updated");
            log_entry->timestamp += j * 60; // Generated timestamp within a 1-hour range.
            log_entry->setting = setting;
            log = malloc_or_realloc(&log, 10, sizeof(log_entry) * (j + 2));
            log[j + 1] = *log_entry;
        } else if (rand() % 3 == 1) { // Delete action with probability 1/6.
            setting->default_value = malloc(sizeof(setting->type == INT ? int : double));
            memcpy(setting->default_value, &setting->value, sizeof(setting->type == INT ? int : double));
            log_entry *log_entry = malloc(sizeof(log_entry));
            log_entry_init(log_entry, setting, "deleted");
            log_entry->timestamp += j * 60; // Generated timestamp within a 1-hour range.
            log_entry->setting = setting;
            log = malloc_or_realloc(&log, 10, sizeof(log_entry) * (j + 2));
            log[j + 1] = *log_entry;
        } else { // Load action with probability 1/6.
            setting->value = *(setting->default_value);
            log_entry *log_entry = malloc(sizeof(log_entry));
            log_entry_init(log_entry, setting, "loaded");
            log_entry->timestamp += j * 60; // Generated timestamp within a 1-hour range.
            log_entry->setting = setting;
            log = malloc_or_realloc(&log, 10, sizeof(log_entry) * (j + 2));
            log[j + 1] = *log_entry;
        }
    }

    // Ensure all pointers and references are correctly set before returning.
    return 0;
}
