#include <random>
#include <cstdlib>

class DataStreamHandler {
public:
    // Constructor initializes a high-quality random number generator and sets maximum key range and buffer size.
    explicit DataStreamHandler(unsigned int maxKeyRange, unsigned int bufferSize)
        : maxKeyRange_(maxKeyRange), bufferSize_(bufferSize), gen_(std::random_device{}()), dist_(gen_) {
        freqTable_.reserve(maxKeyRange_);
        recordBuffer_.reserve(bufferSize);
    }

    // Destructor releases all allocated resources.
    ~DataStreamHandler() {
        // TODO: Implement memory deallocation here.
    }

    // Insert a new record into the data stream, handling potential memory allocation failures.
    void insertRecord(long offset, int key, int value) {
        // Handle memory allocation failure gracefully.
        if (!addRecordToBuffer(offset, key, value)) {
            std::cout << "Memory allocation failure. Skipping record.\n";
            return;
        }

        // Update the frequency table and maintain low-contention points for concurrent access.
        std::unique_lock<std::shared_mutex> lock(freqTableMutex_);
        freqTable_[key]++;
    }

    // Retrieve the most frequently occurring records based on their keys, balancing memory usage and speed.
    void getMostFrequentRecords(unsigned int numRecords) {
        std::unique_lock<std::shared_mutex> lock(freqTableMutex_);

        auto it = std::rbegin(freqTable_);
        std::vector<std::pair<int, int>> topRecords;
        topRecords.reserve(numRecords);

        for (unsigned int i = 0; i < numRecords && it != freqTable_.end(); ++it) {
            if ((*it).second > 0) {
                topRecords.emplace_back((*it).first, (*it).second);
            }
            --it;
        }

        // Sort the records based on frequency in descending order.
        std::sort(topRecords.begin(), topRecords.end(), [](const auto& a, const auto& b) { return a.second > b.second; });
    }

private:
    // Helper function to add a record to the buffer and linked list.
    bool addRecordToBuffer(long offset, int key, int value) {
        if (!recordBuffer_.empty()) {
            auto last = std::prev(std::end(recordBuffer_));
            last->offset = offset;
            last->key = key;
            last->value = value;
            return true;
        }

        // Allocate a new record when the buffer is empty.
        recordBuffer_.emplace_back();
        auto& newRecord = recordBuffer_.back();
        newRecord.offset = offset;
        newRecord.key = key;
        newRecord.value = generateRandomValue(valueRange_);
        return true;
    }

    // Implement efficient random number generation.
    int generateRandomValue(unsigned int valueRange) {
        std::uniform_int_distribution<> dist(0, valueRange - 1);
        return dist(gen_);
    }

    // Internal data structures and mutex for concurrent access.
    unsigned int maxKeyRange_;
    unsigned int bufferSize_;
    unsigned int valueRange_{100}; // Initialize the value range to a reasonable default value.
    std::mt19937 gen_; // Mersenne Twister 19937 random number generator.
    std::deque<DataRecord> recordBuffer_; // Deque for efficient insertions and deletions at both ends.
    std::unordered_map<int, unsigned int, std::hash<int>> freqTable_; // Unordered map for fast key-based lookups.
    std::shared_mutex freqTableMutex_; // Shared mutex for concurrent access to the frequency table.
};

struct DataRecord {
    long offset;
    int key;
    int value;
};
```

