typedef struct {
    float num;
    char* cat;
    time_t ts;
} DataRecord;

typedef struct Node {
    DataRecord record;
    struct Node* next;
} Node;

tbb::concurrent_hash_map<char*, Node*> hashTable; // Custom hash table for efficient data access
pthread_mutex_t hashTableMutex; // Mutex for concurrent access

Node* buffer;
size_t bufferSize = 1024;
size_t bufferIndex = 0;

void* deserialize(void* socket) {
    char buf[4096];
    ssize_t len;

    while ((len = recv(socket, buf, sizeof(buf), MSG_DONTWAIT)) > 0) {
        json_t* root = json_loads(buf, JSON_DECREF | JSON_ERROR_ON_INVALID);

        if (!root) continue; // Ignore invalid JSON objects

        DataRecord record;
        json_unreference(json_object_get(root, "num")); // Extract numerical value
        record.num = (float)json_integer_value(json_object_get(root, "num"));
        record.cat = strdup(json_string_value(json_object_get(root, "cat")));
        record.ts = time(NULL);

        // Store the DataRecord in the buffer
        Node* node = malloc(sizeof(Node));
        node->record = record;
        node->next = buffer[(bufferIndex + 1) % bufferSize];
        buffer[(bufferIndex++) % bufferSize] = node;
    }
}

void moving_average(float* arr, size_t len, float* ma, size_t windowSize) {
    float sum = 0.0f;

    for (size_t i = 0; i < windowSize; ++i) {
        sum += arr[i];
    }

    *ma = sum / windowSize;

    for (size_t i = windowSize; i < len; ++i) {
        sum -= arr[i - windowSize];
        sum += arr[i];
        *ma = sum / windowSize;
    }
}

float mean(Node* head, size_t count) {
    float sum = 0.0f;

    for (size_t i = 0; i < count; ++i) {
        sum += head->record.num;
        head = head->next;
    }

    return sum / count;
}

float median(Node* head, size_t count) {
    qsort(head, count, sizeof(DataRecord), compare);

    if (count % 2 == 0) {
        return (head[count / 2 - 1].num + head[count / 2].num) / 2;
    } else {
        return head[count / 2].num;
    }
}

int compare(const void* a, const void* b) {
    return ( *(static_cast<const DataRecord*>(a)->ts) - *(static_cast<const DataRecord*>(b)->ts) );
}

// ... Implement the rest of the functions as specified in the task description
