// Allocate and initialize product memory based on user-provided sizes, validating input and preventing overflow
Product* allocate_products(size_t size) {
    if (size == 0) return NULL;

    Product *products = malloc(sizeof(Product) * size);
    if (!products) return NULL;

    for (size_t i = 0; i < size; ++i) {
        products[i].id = i + 1;
        products[i].price = 0.0f;
        products[i].name = NULL;
    }

    return products;
}

// Set product prices from an external data source, handling errors and implementing a retry mechanism for transient issues
void set_product_prices(Product *products, size_t size, int (*get_price)(int id)) {
    pthread_t threads[size];
    Product *product_data = malloc(sizeof(Product) * size);

    if (!product_data) {
        perror("Failed to allocate memory for product data");
        exit(IO_ERROR);
    }

    for (size_t i = 0; i < size; ++i)
        product_data[i] = products[i];

    for (size_t i = 0; i < size; ++i) {
        product_data[i].price = get_price(product_data[i].id);

        if (pthread_create(&threads[i], NULL, &load_price, &product_data[i])) {
            perror("Failed to create thread");
            exit(THREAD_ERROR);
        }
    }

    for (size_t i = 0; i < size; ++i)
        pthread_join(threads[i], NULL);

    free(product_data);
}

// Load product price in a separate thread, handling errors and retrying on transient issues
void* load_price(void *arg) {
    Product *product = (Product *) arg;
    int tries = 0;

    while (true) {
        int result = get_price(product->id);
        if (result != SUCCESS) {
            if (tries >= MAX_TRIES) {
                perror("Failed to load price");
                pthread_exit(IO_ERROR);
            } else {
                ++tries;
                usleep(RETRY_DELAY);
            }
        } else {
            product->price = result;
            pthread_exit(SUCCESS);
        }
    }
}

// Calculate average price and variance of the product prices using efficient algorithms that can handle large datasets without excessive memory usage
void calculate_stats(const Product *products, size_t size, float *avg_price, float *variance) {
    float sum = 0.0f;
    float sum_of_squares = 0.0f;

    for (size_t i = 0; i < size; ++i) {
        sum += products[i].price;
        sum_of_squares += pow(products[i].price, 2);
    }

    *avg_price = sum / size;
    *variance = (sum_of_squares / size - pow(*avg_price, 2)) / (size - 1);
}

// Implement the main function to manage and process product data for a retail management system
int process_products(size_t id_size, size_t price_size, size_t name_size, int (*get_price)(int id), void *(*library_function)()) {
