[" ```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    struct Record record;
    struct Node *next;
} Node;

typedef struct Record {
    int value;
    char status;
    char *str;
} Record;

Node *head = NULL;
size_t capacity = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void init(size_t size, long min_offset, long max_offset, int min_key, int max_key) {
    // Memory allocation and management
    capacity = size;
    Node *nodes = malloc(capacity * sizeof(Node));
    if (!nodes) return;

    head = nodes;
    for (size_t i = 1; i < capacity; ++i)
        nodes[i].next = &nodes[i + 1];
    nodes[capacity - 1].next = NULL;

    // Data Initialization
    srand(time(NULL));
    for (size_t i = 0; i < capacity; ++i) {
        head[i].offset = min_offset + i;
        head[i].key = rand() % (max_key - min_key + 1) + min_key;
        head[i].record.value = rand() % 100;
        head[i].record.status = '\0';
        head[i].record.str = malloc(1);
        if (!head[i].record.str) return;
        *head[i].record.str = '\0';
    }
}

void insert(int key, Record r) {
    pthread_mutex_lock(&mutex);
    Node *node = head;
    for (size_t i = 0; i < capacity; ++i) {
        if (node[i].key == key) {
            node[i].record = r;
            pthread_mutex_unlock(&mutex);
            return;
        }
        node = &node[1];
    }
    Node *new_node = &head[capacity - 1];
    new_node->key = key;
    new_node->record = r;
    new_node->offset = capacity++;
    node->next = new_node;
    pthread_mutex_unlock(&mutex);
}

Record *find(int key) {
    Node *node = head;
    for (size_t i = 0; i < capacity; ++i) {
        if (node[i].key == key) return &node[i].record;
        node = &node[1];
    }
    return NULL;
}

void remove(int key) {
    pthread_mutex_lock(&mutex);
    Node *node = head, *prev = NULL;
    for (size_t i = 0; i < capacity; ++i) {
        if (node[i].key == key) {
            if (prev) prev->next = &node[i + 1];
            else head = &node[i + 1];
            free(node[i].record.str);
            --capacity;
            pthread_mutex_unlock(&mutex);
            return;
        }
        prev = &node[0];
        node = &node[1];
    }
    pthread_mutex_unlock(&mutex);
}

