    struct data_node* prev;
    struct data_node* next;
} data_node;

// Initialize doubly-linked list
data_node* head = NULL;
data_node* tail = NULL;
HashMap* hash_table = NULL; // Assuming you have a pre-implemented hash map structure (e.g., TBB's tbb/tbb_hash_map)
pthread_mutex_t mutex; // For synchronization during concurrent read and write operations

// Insert node into the linked list based on the specified criterion
void insert_node(double value) {
    if (hash_table->find(value)) {
        printf("Error: Duplicate values are not allowed.\n");
        return;
    }

    data_node* new_node = malloc(sizeof(data_node));
    if (!new_node) {
        perror("Memory allocation error.");
        exit(EXIT_FAILURE);
    }

    new_node->value = value;
    new_node->prev = NULL;
    new_node->next = NULL;

    pthread_mutex_lock(&mutex);
    if (!head) {
        head = tail = new_node;
    } else {
        tail->next = new_node;
        new_node->prev = tail;
        tail = new_node;
    }
    hash_table->insert(value, new_node); // Store the node's address in the hash table for fast lookup
    pthread_mutex_unlock(&mutex);
}

// Remove nodes based on a specific threshold
void remove_nodes_below(double threshold) {
    pthread_mutex_lock(&mutex);
    data_node* current = head;

    while (current != NULL) {
        if (current->value <= threshold) {
            data_node* temp = current;
            current = current->next;

            if (temp == head) {
                head = head->next;
                free(temp);
            } else if (temp == tail) {
                tail = tail->prev;
                free(temp);
            } else {
                temp->prev->next = temp->next;
                temp->next->prev = temp->prev;
                free(temp);
            }

            hash_table->erase(temp->value); // Remove the deleted node from the hash table
        } else {
            current = current->next;
        }
    }

    pthread_mutex_unlock(&mutex);
}
```

