    bool removeRecord(int key) {
        std::unique_lock<std::mutex> lock(mtx);
        auto it = nodes.begin();
        while (it != nodes.end()) {
            if ((*it)->key == key) {
                it = nodes.erase(it);
                return true;
            }
            ++it;
        }
        return false;
    }

    Node* findRecord(int key) const {
        std::unique_lock<std::mutex> lock(mtx);
        for (const auto& node : nodes) {
            if ((*node)->key == key) {
                return *node;
            }
        }
        return nullptr;
    }
};
