typedef struct Record {
    int key;
    int value;
    struct Record *next;
} Record;

Record* create_record(int key, int value) {
    Record *new_record = (Record*) malloc(sizeof(Record));
    new_record->key = key;
    new_record->value = value;
    new_record->next = NULL;
    return new_record;
}

void fill_records(Record **head, int *keys, int *offsets, int len) {
    for (int i = 0; i < len; ++i) {
        Record *temp = *head;
        bool found = false;
        for (int j = 0; temp && j < i; ++j) {
            if (temp->key == keys[i]) {
                found = true;
                break;
            }
            temp = temp->next;
        }

        if (!found) {
            if (temp) {
                temp->next = create_record(keys[i], offsets[i]);
            } else {
                *head = create_record(keys[i], offsets[i]);
                *head = *head->next;
            }
        }
    }
}

void traverse_list(Record *head, int order) {
    Record *current = head;
    if (!current) return;

    printf("Key\tValue\n");
    while (current) {
        if (order == 1) {
            printf("%d\t%d\n", current->key, current->value);
        } else if (order == -1) {
            printf("%d\t%d\n", current->key, current->value);
            current = current->next;
            while (current && current->key < current->next->key) {
                current = current->next;
            }
        }
        current = current->next;
    }
}

void free_memory(Record **head) {
    Record *temp;
    while (*head) {
        temp = *head;
        *head = (*head)->next;
        free(temp);
    }
}

