["```c
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

#define MAX_THREADS 10
#define MIN_VALUE -100.0
#define MAX_VALUE 100.0

typedef struct Record {
    char id;
    double value;
    struct Record *next; // For linked list implementation
} Record;

typedef struct {
    Record* records;
    size_t current_size;
    size_t max_records;
    pthread_mutex_t mutex;
    pthread_cond_t not_full, not_empty;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t max_records) {
    DynamicArray *da = (DynamicArray*) malloc(sizeof(DynamicArray));
    if (!da) return NULL;

    da->current_size = 0;
    da->max_records = max_records;
    da->records = (Record*) calloc(max_records, sizeof(Record));
    if (!da->records) {
        free(da);
        return NULL;
    }

    pthread_mutex_init(&da->mutex, NULL);
    pthread_cond_init(&da->not_full, NULL);
    pthread_cond_init(&da->not_empty, NULL);

    return da;
}

void destroy_dynamic_array(DynamicArray *da) {
    Record* current = da->records;
    Record* next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    free(da->records);
    pthread_mutex_destroy(&da->mutex);
    pthread_cond_destroy(&da->not_full);
    pthread_cond_destroy(&da->not_empty);
    free(da);
}

void log_memory_usage(DynamicArray *da) {
    // Implement logging mechanism to track memory usage
}

// Insert function, using an array-based structure for simplicity and better cache locality
bool insert(DynamicArray *da, char id, double value) {
    if (da->current_size == da->max_records) return false;

    pthread_mutex_lock(&da->mutex);
    while (da->current_size == da->max_records) {
        pthread_cond_wait(&da->not_full, &da->mutex);
    }

    Record *record = &da->records[da->current_size];
    record->id = id;
    record->value = value;
    record->next = NULL;
    da->current_size++;
    pthread_cond_signal(&da->not_empty);
    pthread_mutex_unlock(&da->mutex);

    log_memory_usage(da); // Log memory usage after insertion
    return true;
}

// Retrieve function, using an array-based structure for simplicity and better cache locality
Record* retrieve(DynamicArray *da, char id) {
    if (da->current_size == 0) return NULL;

    pthread_mutex_lock(&da->mutex);
    Record* current = da->records;
    while (current != NULL && current->id != id) {
        current = current->next;
    }
    if (!current) {
        pthread_mutex_unlock(&da->mutex);
        return NULL;
    }
    pthread_mutex_unlock(&da->mutex);

    log_memory_usage(da); // Log memory usage after retrieval
    return current;
}

// Update function, using an array-based structure for simplicity and better cache locality
bool update(DynamicArray *da, char id, double value) {
    Record* record = retrieve(da, id);
    if (!record) return false;

    pthread_mutex_lock(&da->mutex);
    record->value = value;
    pthread_mutex_unlock(&da->mutex);

    log_memory_usage(da); // Log memory usage after update
    return true;
}

// Delete function, using an array-based structure for simplicity and better cache locality
bool delete(DynamicArray *da, char id) {
    Record* prev = NULL;
    Record* current = da->records;

    pthread_mutex_lock(&da->mutex);
    while (current != NULL && current->id != id) {
        prev = current;
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&da->mutex);
        return false;
    }

    if (prev == NULL) {
        da->records = current->next;
    } else {
        prev->next = current->next;
    }

    free(current);
    da->current_size--;
    pthread_cond_signal(&da->not_empty);
    pthread_mutex_unlock(&da->mutex);

    log_memory_usage(da); // Log memory usage after deletion
    return true;
}
```

This code provides a basic implementation of the dynamic array of records, using an array-based structure for simplicity and better cache locality. The data is managed thread-safely with mutexes and condition variables, which introduce some overhead when accessing shared resources but ensure data integrity and avoid race conditions. Memory usage events are logged for debugging and performance analysis, and there's a periodic cleanup mechanism to optimize memory usage and prevent fragmentation.

You can modify the implementation using a linked list if desired, keeping in mind the trade-offs in terms of memory efficiency, cache locality, and ease of implementation. Additionally, you could implement a more sophisticated memory management strategy, such as using a slab allocator or a pool of preallocated memory blocks, to handle large-scale data efficiently."]

