Next, we'll use a custom memory allocator that validates the total memory usage and manages block allocation efficiently:

```cpp
#include <new>

template<typename T>
class Allocator final : public std::allocator<T> {
public:
    using value_type = T;
    using size_type = std::size_t;

    Allocator() {}

    Allocator(const Allocator&) = delete;
    Allocator& operator=(const Allocator&) = delete;

    Allocator(Allocator&& other) noexcept {
        this->hard_capacity_ = other.hard_capacity_;
        this->soft_capacity_ = other.soft_capacity_;
    }

    Allocator& operator=(Allocator&& other) noexcept {
        if (this != &other) {
            hard_capacity_ = other.hard_capacity_;
            soft_capacity_ = other.soft_capacity_;
        }
        return *this;
    }

    value_type* allocate(size_type n) {
        auto* result = static_cast<value_type*>(::operator new(n * sizeof(T)));
        if (!result || this->hard_capacity_ <= this->soft_capacity_ + n)
            throw std::bad_alloc();
        hard_capacity_ += n;
        soft_capacity_ += n;
        return result;
    }

    void deallocate(value_type* p, size_type) noexcept {
        if (p) {
            auto* end = static_cast<value_type*>(std::distance(p, std::addressof(*static_cast<const Allocator&>(*(reinterpret_cast<const std::allocator<T>*>(&other))))));
            if (end <= p + hard_capacity_) {
                soft_capacity_ -= static_cast<size_type>(std::distance(p, end));
                hard_capacity_ -= static_cast<size_type>(std::distance(p, end));
            }
            ::operator delete(p);
        }
    }

private:
    size_type hard_capacity_ = 0;
    size_type soft_capacity_ = 0;
};
```

