                MD5_Final(reinterpret_cast<unsigned char*>(md5Hash.data()), &md5Context);

                std::lock_guard<std::mutex> lock(mtx);
                memUsage += (sizeof(Record) + md5Hash.size() + sizeof(char[MD5_DIGEST_LENGTH])) * recordAllocator.allocate((size_t)(1 + md5Hash.size()));
                auto* currentData = recordAllocator.data();
                std::copy_n_backward(currentData, memUsage, currentData + memUsage);

                std::copy(cbegin(md5Hash), cend(md5Hash), currentData);
                ++currentData;
                queue.push(p);
            }
        } else if (!is_directory(p)) {
            // Do nothing, skipping directories and data files that exceed maxFileThreshold
        } else {
            forEachRecursive(p, [&](const path& p) { addToQueue(p); });
        }
    };

    path root(rootPath);
    addToQueue(root);

    while (!queue.empty()) {
        auto p = queue.front();
        queue.pop();

        futures.emplace_back([p, &recordAllocator]() mutable {
            if (p.extension() != ".dat") {
                // Create and manage a connection here for reading the file
                // ... calculate MD5 hash for the file using OpenSSL's MD5 implementation
                // ... store the calculated MD5 hash in the Record structure
                // ... deallocate memory when done with the Record
            }
        });
    }

    for (auto& f : futures) {
        f.wait();
    }

    std::unordered_map<std::string, std::string> result;
    std::lock_guard<std::mutex> lock(mtx);
    auto* currentData = recordAllocator.data();
    for (auto i = 0; i < memUsage; ++i) {
        if (*currentData == '\0') {
            // A null-terminated MD5 hash string is stored at this position in the array
            result[std::string(reinterpret_cast<const char*>(currentData))] = std::string(static_cast<size_t>(2 * MD5_DIGEST_LENGTH), '\0');
        }
        ++currentData;
    }

    return result;
}
