typedef struct Record {
    int value;
} Record;

// Global variables for memory management
size_t total_allocated = 0;
size_t max_memory;
void* memory_pool = NULL;
pthread_mutex_t memory_mutex = PTHREAD_MUTEX_INITIALIZER;

Record* create_record() {
    Record* new_record = (Record*) malloc(sizeof(Record));
    if (!new_record) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }
    new_record->value = rand() % (max_value - min_value + 1) + min_value;
    return new_record;
}

long* allocate_offsets(size_t size) {
    void* allocated_memory = realloc(memory_pool, size * sizeof(long));
    if (!allocated_memory) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }
    memory_pool = allocated_memory;
    return (long*) memory_pool;
}

int* allocate_keys(size_t size) {
    void* allocated_memory = realloc(memory_pool, size * sizeof(int));
    if (!allocated_memory) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }
    memory_pool = allocated_memory;
    return (int*) memory_pool;
}

Record** allocate_records(size_t size) {
    void* allocated_memory = realloc(memory_pool, size * sizeof(Record*));
    if (!allocated_memory) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }
    memory_pool = allocated_memory;
    return (Record**) memory_pool;
}

void reset_memory() {
    pthread_mutex_lock(&memory_mutex);
    if (memory_pool) {
        free(memory_pool);
        memory_pool = NULL;
    }
    total_allocated = 0;
    pthread_mutex_unlock(&memory_mutex);
}

void* thread_function(void* arg) {
    Record** records = allocate_records((max_memory / sizeof(Record)) / 3);
    for (int i = 0; i < 3; ++i) {
        *(records + i) = allocate_records(rand() % ((max_memory - total_allocated) / sizeof(Record)));
        for (int j = 0; j < *(*(records + i) + total_allocated / 3); ++j) {
            *(*(records + i) + j) = create_record();
        }
    }
    return NULL;
}

void init_memory(size_t max_mem, size_t min_value, size_t max_value, unsigned int num_threads) {
    if (total_allocated + 3 * sizeof(long) + 6 * sizeof(int) + ((max_memory / sizeof(Record)) / 3 + 1) * sizeof(Record*) > max_mem) {
        fprintf(stderr, "Memory limit exceeded\n");
        exit(EXIT_FAILURE);
    }
    total_allocated += 3 * sizeof(long) + 6 * sizeof(int) + ((max_memory / sizeof(Record)) / 3 + 1) * sizeof(Record*);
    memory_pool = malloc(total_allocated);
    max_memory = max_mem;

    pthread_t threads[num_threads];
    for (int i = 0; i < num_threads; ++i) {
        pthread_create(&threads[i], NULL, thread_function, NULL);
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }
}
```

