typedef struct {
    char buffer[MAX_LENGTH];
    int key;
    double value;
} entry;

typedef enum { UNKNOWN, CSV, JSON } format;

int load_data(const char* file, entry** entries, int* num_entries, format* format, int max_length) {
    FILE *fp = fopen(file, "r");
    if (!fp) return 0;

    format = UNKNOWN;
    int lines = 0;
    entry* temp_entries = NULL;
    int *temp_status = NULL;
    int *status = NULL;

    // Dynamically allocate memory for status flags based on the number of entries in the file
    while (!feof(fp)) {
        lines++;
        if (lines == 1) {
            temp_entries = malloc(sizeof(entry));
            temp_status = malloc(sizeof(int));
        } else {
            entry *temp_next = malloc(sizeof(entry));
            int *temp_next_status = malloc(sizeof(int));
            if (!temp_entries) {
                free(temp_entries);
                temp_entries = malloc(lines * sizeof(entry));
            }
            if (!temp_status) {
                free(temp_status);
                temp_status = malloc(lines * sizeof(int));
            }
            memcpy(temp_next, temp_entries + lines - 1, sizeof(entry));
            memcpy(temp_next_status, temp_status + lines - 1, sizeof(int));
            temp_entries = realloc(temp_entries, (lines + 1) * sizeof(entry));
            temp_status = realloc(temp_status, (lines + 1) * sizeof(int));
            memcpy(temp_entries + lines - 1, temp_next, sizeof(entry));
            memcpy(temp_status + lines - 1, temp_next_status, sizeof(int));
        }

        char c;
        if (fscanf(fp, "%c", &c) != 1 || feof(fp)) break;

        switch (format) {
            case UNKNOWN:
                if (isspace(c)) continue;
                if (c == ',') format = CSV;
                else if (c == '{') format = JSON;
                break;
            case CSV:
                // Handle CSV input here
                break;
            case JSON:
                // Handle JSON input here using json-c library
                break;
        }
    }

    fclose(fp);

    *entries = malloc((*num_entries) * sizeof(entry));
    memcpy(*entries, temp_entries, lines * sizeof(entry));

    *num_entries = lines;
    status = malloc(*num_entries * sizeof(int));
    memcpy(status, temp_status, lines * sizeof(int));

    free(temp_entries);
    free(temp_status);

    return 1;
}
