#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <zlib.h>

typedef struct Record {
    int id;
    double value;
    char* string;
};

#define ARRAY_SIZE 10000
#define LONG_RANGE (2147483647LL - 1)
#define INT_RANGE 2147483647
#define DOUBLE_RANGE 10000.0
#define STRING_LENGTH 256

long long int long_values[ARRAY_SIZE];
int int_values[ARRAY_SIZE];
double double_values[ARRAY_SIZE];
Record records[ARRAY_SIZE];
char string_buffer[ARRAY_SIZE][STRING_LENGTH];

pthread_mutex_t mutex;
FILE* output_file = NULL;
gzFile gz_output_file = NULL;

void init_data() {
    for (size_t i = 0; i < ARRAY_SIZE; ++i) {
        long_values[i] = (rand() * INT_MAX);
        int_values[i] = rand() % INT_RANGE;
        double_values[i] = ((double)rand() / RAND_MAX) * DOUBLE_RANGE;
        records[i].id = i;
        records[i].value = double_values[i];
        strncpy(records[i].string, "Random String", STRING_LENGTH);
    }
}

void validate_data() {
    for (size_t i = 0; i < ARRAY_SIZE; ++i) {
        if (!((long_values[i] <= LONG_RANGE) && (int_values[i] <= INT_RANGE) && (double_values[i] <= DOUBLE_RANGE))) {
            fprintf(stderr, "Invalid data value at index %zu: long=%lld int=%d double=%f\n", i, long_values[i], int_values[i], double_values[i]);
        }
    }
}

void* serialize_chunk(void* arg) {
    size_t offset = (size_t)arg;
    char* buffer = NULL;
    size_t buffer_size = 0;

    pthread_mutex_lock(&mutex);
    gzwrite(gz_output_file, &long_values[offset], sizeof(long long int));
    gzwrite(gz_output_file, &int_values[offset], sizeof(int));
    gzwrite(gz_output_file, &double_values[offset], sizeof(double));
    memcpy(buffer, records[offset].string, STRING_LENGTH);
    buffer_size = strlen(buffer) + 1;
    gzwrite(gz_output_file, &buffer_size, sizeof(size_t));
    gzwrite(gz_output_file, buffer, buffer_size);
    free(buffer);
    pthread_mutex_unlock(&mutex);
}

void serialize() {
    char filepath[256];
    size_t chunk_size = ARRAY_SIZE / 10; // Adjust chunk size for concurrency control
    sprintf(filepath, "data.dat");

    output_file = fopen(filepath, "wb");
    if (!output_file) {
        perror("Failed to open file for writing");
        return;
    }

    gz_output_file = gzopen(filepath, "w" );
    if (!gz_output_file) {
        perror("Failed to open gzip file for writing");
        fclose(output_file);
        return;
    }

    pthread_mutex_init(&mutex, NULL);
    pthread_t threads[10];

    for (size_t i = 0; i < 10; ++i) {
        if (pthread_create(&threads[i], NULL, serialize_chunk, (void*)(i * chunk_size))) {
            perror("Failed to create thread");
            break;
        }
    }

    for (size_t i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }

    pthread_mutex_destroy(&mutex);
    gzclose(gz_output_file);
    fclose(output_file);
}

int main() {
    srand(time(NULL));

    init_data();
    validate_data();
    serialize();

    for (size_t i = 0; i < ARRAY_SIZE; ++i) {
        free(records[i].string);
    }

    return 0;
}
```

