typedef struct Record {
    int value;
    char status;
    char *str;
} Record;

typedef struct Node {
    Record *record;
    struct Node *next;
} Node;

typedef struct HashTable {
    unsigned long *offsets;
    int *keys;
    Node **records;
    unsigned size;
    unsigned capacity;
} HashTable;

void init_hash(HashTable *ht, unsigned size) {
    ht->size = 0;
    ht->capacity = size;
    ht->offsets = calloc(ht->capacity, sizeof(unsigned long));
    ht->keys = calloc(ht->capacity, sizeof(int));
    ht->records = calloc(ht->capacity, sizeof(Node*));
}

void resize_hash(HashTable *ht) {
    if (ht->size >= 2 * ht->capacity) {
        unsigned new_capacity = ht->capacity * 2;
        unsigned long *new_offsets = realloc(ht->offsets, new_capacity * sizeof(unsigned long));
        int *new_keys = realloc(ht->keys, new_capacity * sizeof(int));
        Node **new_records = realloc(ht->records, new_capacity * sizeof(Node*));

        if (new_offsets == NULL || new_keys == NULL || new_records == NULL) {
            fprintf(stderr, "Memory allocation failed.\n");
            exit(EXIT_FAILURE);
        }

        memmove(new_offsets, ht->offsets, ht->capacity * sizeof(unsigned long));
        memmove(new_keys, ht->keys, ht->capacity * sizeof(int));
        memmove(new_records, ht->records, ht->capacity * sizeof(Node*));

        free(ht->offsets);
        free(ht->keys);
        free(ht->records);

        ht->offsets = new_offsets;
        ht->keys = new_keys;
        ht->records = new_records;
        ht->capacity = new_capacity;
    }
}

unsigned long hash(HashTable *ht, int key) {
    return key % ht->capacity;
}

Node* create_node(Record *record) {
    Node *new_node = malloc(sizeof(Node));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    new_node->record = record;
    new_node->next = NULL;
    return new_node;
}

Record* create_record() {
    Record *new_record = malloc(sizeof(Record));
    if (new_record == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    new_record->value = rand() % 100;
    new_record->status = 'A';
    new_record->str = malloc(sizeof(char) * 20);
    strcpy(new_record->str, "Default value");
    return new_record;
}

void insert_record(HashTable *ht, int key, Record *record) {
    resize_hash(ht);
    unsigned long offset = ht->offsets[key];
    Node *node = ht->records[offset];

    if (node == NULL) {
        ht->records[offset] = create_node(record);
    } else {
        while (node->next != NULL) {
            node = node->next;
        }
        node->next = create_node(record);
    }
}

Record* find_record(HashTable *ht, int key) {
    unsigned long offset = ht->offsets[key];
    Node *node = ht->records[offset];

    while (node != NULL && node->record->keys != key) {
        node = node->next;
    }

    return node == NULL ? NULL : node->record;
}

void delete_record(HashTable *ht, int key) {
    unsigned long offset = ht->offsets[key];
    Node **prev = &ht->records[offset];
    Node *node = ht->records[offset];

    while (node != NULL && node->record->keys == key) {
        *prev = node->next;
        free(node->record->str);
        free(node->record);
        free(node);
        ht->size--;
        node = *prev;
    }
}

void print_largest(Record **records, int n) {
    int max_value = -1;
    Record *max_record = NULL;

    for (int i = 0; i < n; ++i) {
        if (records[i]->value > max_value) {
            max_value = records[i]->value;
            max_record = records[i];
        }
    }

    printf("The largest integer is: %d\n", max_record->value);
}

void main(int argc, char *argv[]) {
    srand(time(NULL));

    unsigned num_records = atoi(argv[1]);
    int seed = atoi(argv[2]);
    const char *output_format = argv[3];

    if (num_records <= 0 || seed < 0) {
        fprintf(stderr, "Invalid arguments.\n");
        return;
    }

    HashTable ht;
    init_hash(&ht, 10);

    Record **records = malloc(num_records * sizeof(Record*));
    for (int i = 0; i < num_records; ++i) {
        records[i] = create_record();
        insert_record(&ht, records[i]->keys, records[i]);
    }

    Record *largest = NULL;

    FILE *log_file = fopen("log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        return;
    }

    for (int i = 0; i < num_records; ++i) {
        Record *found_record = find_record(&ht, records[i]->keys);

        if (found_record == NULL) {
            fprintf(stderr, "Record not found.\n");
            return;
        }

        fprintf(log_file, "Record %d: size=%lu, value=%d\n", i + 1, sizeof(*records[i]), records[i]->value);

        if (largest == NULL || found_record->value > largest->value) {
            largest = found_record;
        }
    }

    fclose(log_file);
    print_largest(records, num_records);

    for (int i = 0; i < num_records; ++i) {
        delete_record(&ht, records[i]->keys);
        free(records[i]);
    }
    free(records);
}
