typedef struct {
    int key;
    long offset;
    char* data;
} record;

record* records;
long* offsets;
int* keys;
size_t buffer_factor;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
sem_t mem_sync;

// Function to initialize the shared data structures and allocate memory for each component.
void init(size_t size, size_t factor) {
    buffer_factor = factor;

    records = malloc(sizeof(record) * size);
    keys = calloc(size, sizeof(int));
    offsets = calloc(size, sizeof(long));

    sem_init(&mem_sync, 0, 1); // Initializing semaphore to 1
}

// Function to generate a random integer within a specified range.
int rand_in_range(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Function to generate a random character from a predefined alphabet.
char rand_char() {
    return 'a' + rand() % 26; // Predefined alphabet is lowercase letters a-z
}

// Function to create and initialize a single record.
record* create_record(size_t index) {
    record* new_record = calloc(1, sizeof(record));
    new_record->key = keys[index];
    new_record->offset = offsets[index];
    size_t data_size = new_record->offset * buffer_factor;
    new_record->data = mmap(NULL, data_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    pthread_mutex_lock(&mutex);
    sem_wait(&mem_sync); // Wait for memory synchronization before allocating buffer

    memset(new_record->data, rand_char(), data_size);
    new_record->data[data_size] = '\0';

    pthread_mutex_unlock(&mutex);
    return new_record;
}

// Function to create and initialize an array of records.
void* worker(void* arg) {
    for (size_t i = 0; i < *(size_t*)arg; ++i)
        create_record(i);
    return NULL;
}

int main(int argc, char** argv) {
    // Parse command-line arguments and configuration file to configure the buffer factor
    // Implement error handling for incorrect arguments and configuration file loading

    pthread_t threads[NUM_THREADS];
    size_t num_records = ...; // Determine number of records based on configuration

    init(num_records, buffer_factor);

    for (size_t i = 0; i < NUM_THREADS; ++i) {
        pthread_create(&threads[i], NULL, worker, &num_records / NUM_THREADS);
    }

    // Wait for all threads to finish and free shared memory

    free(keys);
    free(offsets);
    free(records);
    sem_destroy(&mem_sync);

    return 0;
}
