typedef struct {
    int value;
    void* (*init)(void* data);
} Record;

typedef struct Factory {
    pthread_mutex_t lock;
    int num_ids;
    int next_id;
    int max_ids;
    Record* records;
    void** factories;
} Factory;

void* mmap(void* addr, size_t length, int prot, int flags, int fd, off_t offset) {
    char *ret = mmap(addr, length, prot, MAP_PRIVATE|flags, fd, offset);
    if (ret == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    return ret;
}

void* memalign(size_t alignment, size_t size) {
    void *ret = nullptr;
    posix_memalign(&ret, alignment, size);
    if (ret == nullptr) {
        perror("posix_memalign");
        exit(EXIT_FAILURE);
    }
    return ret;
}

void munmap(void *addr, size_t length) {
    if (munmap(addr, length) != 0) {
        perror("munmap");
        exit(EXIT_FAILURE);
    }
}

Factory* factory = nullptr;

void init_factory() {
    factory = (Factory*)memalign(sizeof(Factory), sizeof(Factory));
    pthread_mutex_init(&factory->lock, nullptr);
    factory->num_ids = 0;
    factory->next_id = 0;
    factory->max_ids = 100;
    factory->records = (Record*)mmap(nullptr, sizeof(Record) * 100, PROT_READ | PROT_WRITE, MAP_ANONYMOUS | MAP_PRIVATE, -1, 0);
    factory->factories = memalign(sizeof(void*), sizeof(void*) * 100);
}

int register_factory(void* (*init)(void* data)) {
    pthread_mutex_lock(&factory->lock);
    if (factory->num_ids >= factory->max_ids) {
        pthread_mutex_unlock(&factory->lock);
        return -1;
    }
    Record* record = &factory->records[factory->next_id];
    void** factories = factory->factories;

    int id = factory->next_id++;
    record->init = init;
    factories[id] = init;

    pthread_mutex_unlock(&factory->lock);

    return id;
}

Record* create_record(int id) {
    if (id < 0 || id >= factory->num_ids) {
        fprintf(stderr, "Invalid ID: %d\n", id);
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(&factory->lock);
    Record* record = &factory->records[id];
    pthread_mutex_unlock(&factory->lock);

    void* data = factory->factories[id](record);
    if (data == nullptr) {
        fprintf(stderr, "Error creating record\n");
        exit(EXIT_FAILURE);
    }

    record->value = rand() % 100;

    return record;
}

